  str_item_3420136 = "三週年回憶協力箱",
  str_item_intro_3420136 = "在指定的5星光靈中選擇一位與你並肩作戰。可選角色包含：<color=#ffffff>多恩、波娜瑟、艾爾戈絲、彼亞塔曼、愛洛拉、花芸、阿桃&阿杏、梅、虹霞、塞提、珀蘭蒂、厘清、馬太、阿納托利、加晴、叭噗、三十三號、維吉爾</color>。",
  str_item_3420137 = "三週年特選召集箱",
  str_item_intro_3420137 = "在指定的6星光靈中選擇一位與你並肩作戰。可選角色包含：<color=#ffffff>提亞拉、辰霓、阿爾戈爾、伊斯塔萬·沓痕、璇極、麗蓓卡、丹棠、札莉雅、安頓、萊蕾、希南、約書亞、舒瓦茲·錚鳴、鶯歌、李奧、哈提、蒂娜、零恩、耶利亞、木月白、仲胥、維克、阿克希亞、莉莉卡、米洛斯、珀拉珂、傑諾、菲雅、卡蓮·煜魂、妮娜、巴頓·芒刃、賈爾斯、蓮、青瞳、瑤、雨森、凜音、芙洛琳、露比、希諾普、諾維亞、海蒂、貝菲爾、路克、普律瑪、克、雷文頓、斯莫奇、弗勞爾、拜里厄、緋、醒山、伊芙、烏列爾、卡蓮、希羅娜、沙利葉、拉斐爾、克娜莉、卡戎、艾希、維多利亞、約娜、娜席里絲、加百列、彌加德、米迦勒、貢露、伊倫汀、雷霆</color>。\n注意：三週年特選召集箱有期限，過期將轉化為3,000光珀，經由郵件發放給您。請記得在期限內使用：2024年8月16日17:00",
