  str_item_6001013 = "四亡騎",
  str_item_6001101 = "頁冊通曉",
  str_item_6001102 = "書卷之座",
  str_item_6001103 = "典籍入夢",
  str_item_6001201 = "茵苗終有",
  str_item_6001202 = "綠景暮色",
  str_item_6001203 = "魚獲一時",
  str_item_6001204 = "盛釣季節",
  str_item_6001205 = "樓台傍暨",
  str_item_6001206 = "閣廈櫛比",
  str_item_6001301 = "靜寂喚醒",
  str_item_6001302 = "舊日言約",
  str_item_6001400 = "大冒險王者！",
  str_item_6001401 = "記錄之眼",
  str_item_6001402 = "響徹歌頌",
  str_item_6001403 = "方向指引",
  str_item_6001404 = "心之蜜甜",
  str_item_6001405 = "繁花冠月之時",
  str_item_6001406 = "偵探的得力助手",
  str_item_6001407 = "憶響水晶",
  str_item_6001408 = "碎界鏡景",
  str_item_6001409 = "神女蝴蝶",
  str_item_6001410 = "啟光的傑出服務者",
  str_item_6002001 = "四翼天使",
  str_item_6002002 = "光輪武備",
  str_item_6002003 = "霜龍凜冽",
  str_item_6002004 = "自影孤鏡",
  str_item_6002005 = "羽毛筆與卷軸",
  str_item_6002006 = "鋼鐵升空",
  str_item_6002007 = "風馳電掣之器",
  str_item_6002008 = "陸行千里",
  str_item_6002009 = "戴冠者必受其重",
  str_item_6002010 = "戰爭之王",
  str_item_6002011 = "堅甲彼身",
  str_item_6002012 = "無內無外之瓶",
  str_item_6002013 = "一體兩面之環",
  str_item_6002014 = "瓶中窺世",
  str_item_6002015 = "萬事根基",
  str_item_6002016 = "雙豎琴波",
  str_item_6002017 = "棘輪戰車",
  str_item_6002018 = "巨獸要塞橫行",
  str_item_6002019 = "虛無之瞳系",
  str_item_6002020 = "漠海駿馬",
  str_item_6002021 = "棋局碎如往昔",
  str_item_6002022 = "歸亡視界",
  str_item_6002023 = "宣星塔",
  str_item_6002024 = "毒蟄猊獰",
  str_item_6002025 = "焰鬃驪火",
  str_item_6000620 = "引擎7號",
  str_item_6000621 = "城防炮塔",
  str_item_6001500 = "點翠",
  str_item_6001507 = "雪的過往",
  str_item_6001508 = "拍立得",
  str_item_6001510 = "花香尚在",
  str_item_6001511 = "熠火燭陰",
  str_item_6001512 = "牧羊人手杖",
  str_item_6001515 = "守護者·虛擬機器",
  str_item_6001516 = "糖人",
  str_item_6001517 = "科技手環",
  str_item_6001520 = "首領項鍊",
  str_item_6001521 = "戰友的胸牌",
  str_item_6001524 = "遊戲掌機",
  str_item_6001525 = "靈感點亮時刻",
  str_item_6001526 = "灼燃之章",
  str_item_6001529 = "血色邪典",
  str_item_6001530 = "摯友之證",
  str_item_6001531 = "愛之歌",
  str_item_6001532 = "這是你的星光",
  str_item_intro_6000001 = "偕行紀念章。日積月累，錢幣的數量已成驚人的數目，就連裝放它們的錢袋，也變得如同一棟房屋那般巨大。",
  str_item_intro_6000002 = "偕行紀念章。感覺已經無法計算這些財富的具體數目了，光是看著它們，什麼人都會覺得頭暈目眩，心馳嚮往，尤其是那些影鎮的商人。",
  str_item_intro_6000101 = "偕行紀念章。祝賀！雖然只是嘗試了幾次，但是未來不可限量。",
  str_item_intro_6000102 = "偕行紀念章。已經可以很靈活地駕駛巨像了！總感覺與螢盞們的連結也更加緊密呢～",
  str_item_intro_6000103 = "偕行紀念章。眼前是雲，周圍是雲，透過白色薄雲，巡瞰大地，也巡視雲在的藍天。",
  str_item_intro_6000104 = "偕行紀念章。當駕駛「臨空者號」進行長時間的旅行後，天空幾乎成為了導航員的後花園，任意遨遊。",
  str_item_intro_6000201 = "偕行紀念章。將看到的大陸印刻於心，揮手而去，便是一副平面上的世界圖景。",
  str_item_intro_6000202 = "偕行紀念章。已經這麼多時日，想必對大陸上的山川地形已經了然於胸吧？腦海中是不是立刻有了它們的樣子？",
  str_item_intro_6000301 = "偕行紀念章。可以想像得到，前方的路依舊漫長，那些形形色色的夥伴，都是可以信任的對象。",
  str_item_intro_6000302 = "偕行紀念章。想必現在已經遊歷了諸多地域，結識的夥伴也大大增加了許多，令人眼花繚亂了～",
  str_item_intro_6000303 = "偕行紀念章。無論去向何方，夥伴們都會圍繞在身邊，一起迎接各種挑戰，也分享他們的歡樂、痛苦與故事。",
  str_item_intro_6000401 = "偕行紀念章。每當一名夥伴覺醒了真正的力量後，天空中似乎也會出現奇妙的輝映，也許這就是名為「光」的力量的神祕連結吧～",
  str_item_intro_6000402 = "偕行紀念章。當他們掌握了名為「光」的力量後，那些曾經閃耀在天空之上的明亮，也在雙手之中了。",
  str_item_intro_6000403 = "偕行紀念章。那些擁有「光」之力量的夥伴，聚集他們的力量，交付於那特別的人，令其昭然生輝，無光者也可照耀四方。",
  str_item_intro_6000501 = "偕行紀念章。如果看到兩顆彼此閃耀的星，那就代表了他們的信任，宛如這兩顆星，彼此映照，不曾分離。",
  str_item_intro_6000502 = "偕行紀念章。星們在移動，路徑在交匯，也如同他們的心靈和所思，在名為「相信」的道路上交匯、相通、靈犀共鳴。",
  str_item_intro_6000503 = "偕行紀念章。夥伴宛如天空的群星，那份光芒不僅代表了絕對信任，更是代表了理念、意志上的聚合。",
  str_item_intro_6000601 = "偕行紀念章。雖然是第一次見面，然而默契早已種下，四隻手宛如一臂，指尖雀躍、心意連結。",
  str_item_intro_6000602 = "偕行紀念章。長年的埋沒，依舊無法令其忘記翱翔於天空的感覺，儘管是第一次，然而這已經足夠了。",
  str_item_intro_6000603 = "偕行紀念章。接近的腳步聲，不僅代表了危險，也代表了崩壞的來臨。",
  str_item_intro_6000604 = "偕行紀念章。面對無數的敵人，他選擇了用轟鳴之物與之「同歸於盡」。這並非無謀的犧牲，而是機智的戰術。",
  str_item_intro_6000605 = "偕行紀念章。那是族人的消息！不過，在那份細微的聲音之下，究竟有著怎樣的心聲，怎樣的過去？",
  str_item_intro_6000606 = "偕行紀念章。它，位於碧空；它，文明中心；它，永不墜落；它，象徵光明。",
  str_item_intro_6000607 = "偕行紀念章。「未來不屬於光，只屬於黑暗」這一瞬間，她的笑容猙獰無比。本為同族，就此走上了歧路。",
  str_item_intro_6000608 = "偕行紀念章。陰謀得逞，敵人得意，垂頭喪氣間，看到了偶爾飄過的蒲公英。未來，將會如何？亦或說，是否還有明日可言？",
  str_item_intro_6000609 = "偕行紀念章。艾斯特拉大陸俗語有云——「選擇大於努力」，很多人猶豫在那命運的路口，此時唯有相信內心，相信直覺，相信夥伴。",
  str_item_intro_6000610 = "偕行紀念章。以光束作為武器，恐怕只有那永不墜落之都才能做到。代價巨大，但是為了擊敗來敵，這一切都是值得的。",
  str_item_intro_6000611 = "偕行紀念章。黑色的巨像，已經變為一道黑色的灰煙，直落入遠方的山谷。然而，它與它的主人，並未死去......",
  str_item_intro_6000612 = "偕行紀念章。追求力量之人，必將會死於那份力量。當她投身於黑暗之時，葬身於黑暗之中就是她的結局。",
  str_item_intro_6000613 = "偕行紀念章。線條是數學語言來表示的「自然」，螺殼是承載價值的容器，連續並不一定是必須。",
  str_item_intro_6000614 = "偕行紀念章。源自過去的理念，為戰爭服務的二者，現在已經走上不同的道路。",
  str_item_intro_6000615 = "偕行紀念章。「和弦紐帶」之下，她陷入無盡的沉睡，一旦甦醒，勢必迸發那深潛於內的強大力量。",
  str_item_intro_6000616 = "偕行紀念章。在回歸塔下，空裔終於擁有了自己的家園。而它的再現，也改變了他的命運......",
  str_item_intro_6000617 = "偕行紀念章。面對永夜地帶的探索行動，白夜城的騎士與啟光聯邦的軍官也要聯手，因為那邊不是一般的兇險。",
  str_item_intro_6000618 = "偕行紀念章。將由多方勢力參與的軍事演練，其獎牌不啻為莫大的榮譽。",
  str_item_intro_6000619 = "偕行紀念章。地下城的最深之處，厚重的大門將阻擋一切入侵者，保護重要之物免於落入宵小匪類之手。",
  str_item_intro_6000701 = "偕行紀念章。這不僅是開始，更是展露頭角的時候，面對那些挑戰，屢屢先攻的勝者，將會是登頂的有力人選。",
  str_item_intro_6000702 = "偕行紀念章。不斷超越，不斷攀登，中途雖然有艱難險阻，進襲卻依舊如常，這就是覺醒之後的力量嗎？",
  str_item_intro_6000703 = "偕行紀念章。當達到這座高峰後，其成就足以俯瞰眾生，然而攀登者不會滿足，因為其那最終目標還未達成......",
  str_item_intro_6000704 = "偕行紀念章。到達這頂層時，攀登者已經勝過大多數挑戰的人們，然而那顆征服之心，卻不會滿足，腳步亦不會停留。",
  str_item_intro_6000705 = "偕行紀念章。高峰之巔上，歷經無數戰；\n高峰之巔上，何知其中難。\n高峰之巔上，坐擁而王據，\n高峰之巔上，俯瞰眾登攀。",
  str_item_intro_6000706 = "偕行紀念章。雖然是第一次，然而能踏入如此境地之人，實非尋常。僅此一點，便已不凡。",
  str_item_intro_6000801 = "偕行紀念章。意外的囚禁，意外的相逢；\n萬丈的牢籠之上，打碎鐐銬者，從不甘願困於其中。",
  str_item_intro_6000802 = "偕行紀念章。貓貓的渴求是什麼呢？除了最喜歡的罐頭，那就是......",
  str_item_intro_6000803 = "偕行紀念章。它是「假日」的家人，也令她明白了這座咖啡廳才是自己的棲身之所，是自己的家......",
  str_item_intro_6000804 = "偕行紀念章。冰雪之下，宮殿緊閉，然而當那仰望極光的瘦小身影到來時，也會為之敞開。",
  str_item_intro_6000901 = "偕行紀念章。地面上出現的諸多裂縫，它們密集如蜂巢，互相接連如蛛網，而從中湧出的不祥氣息表明，它沒有看起來那麼簡單......",
  str_item_intro_6000902 = "偕行紀念章。洞穴之中漆黑一片，唯有進入者自身的光源閃爍期間，然而這裡並不寂靜，因為有很多「土著」在歡迎到來者。",
  str_item_intro_6000903 = "偕行紀念章。它真的有盡頭嗎？探索多次，該想法就徘徊在腦海中，久久不曾散去。然而，堅定的探索者依舊會不畏危險，再次進入的吧。",
  str_item_intro_6001001 = "偕行紀念章。影像也是武器，虛假亦是利刃，有時候一雙眼睛比一對強壯的手臂要有用許多。",
  str_item_intro_6001002 = "偕行紀念章。燃燒吧！看著那熊熊的火焰，將毀滅一切褻瀆的敵人。",
  str_item_intro_6001003 = "偕行紀念章。高聲的呼喚，是在標記敵人的存在，而沉默則成為了它的死地，也是它的結局。",
  str_item_intro_6001004 = "偕行紀念章。是敵人可怕，還是虛空可怕？看來要征服這一存在，唯有將其永久封印，永久禁錮。",
  str_item_intro_6001005 = "偕行紀念章。沒有形體的身軀，唯有意識的漂浮。但是面對光之海嘯，也只能消逝。",
  str_item_intro_6001006 = "偕行紀念章。命運的不公會使人瘋狂，進而墮入黑暗。到了如此地步時，剩下的唯有槍與劍的征討。",
  str_item_intro_6001007 = "偕行紀念章。時刻承受無盡的痛苦，時刻陷入究極的狂暴，將這一切終結吧！那是最好的禮物。",
  str_item_intro_6001008 = "偕行紀念章。黎明前的一刻最為黑暗，只要苦熬下去，接下來的就是在第一抹晨光下的奔跑。",
  str_item_intro_6001009 = "偕行紀念章。不成體系的聲音，無法入耳的聲音，它們交匯於此，成為了敵人的苦與恨。",
  str_item_intro_6001010 = "偕行紀念章。無處可去的人，還能被放逐嗎？或許是可以的，只不過無人看到罷了。",
  str_item_intro_6001011 = "偕行紀念章。血色的石頭源於污濁的目標，在掙脫重重危險之籠後，卻誕生了最為美麗的寶石。",
  str_item_intro_6001012 = "偕行紀念章。凡人沒有任何價值，唯有靈魂諸神爭搶，將之放棄，便如敝屣。",
  str_item_intro_6001013 = "偕行紀念章。並非白夜城的騎士，而是那長年以來的敵手。偽裝已被打破，剩下唯有決一死戰。",
  str_item_intro_6001101 = "偕行紀念章。每翻動一頁，那悅耳之聲便進入腦海，那美妙文字承載的一切，便展現在眼前。",
  str_item_intro_6001102 = "偕行紀念章。將書卷坐於身下，並非不尊重它，而是因為書中記載之事，已了然於胸。",
  str_item_intro_6001103 = "偕行紀念章。以典籍為床、為枕，便在夢鄉中也進入了那典籍的寶庫，在浩瀚的知識中起起伏伏，肆意享受。",
  str_item_intro_6001201 = "偕行紀念章。每一株新苗都是親自培育，雙手雖沾滿泥土，然而看到它們終於成長為那些奇妙植物時，心中喜悅，自不必言。",
  str_item_intro_6001202 = "偕行紀念章。當那些奇妙植物紛繁蔓生，綴練而成一片自然之景後，空庭的暮色便與眾不同。",
  str_item_intro_6001203 = "偕行紀念章。這些稀有的魚類，足以證明，這是一名高手！",
  str_item_intro_6001204 = "偕行紀念章。這是垂釣者的盛大節日，並非因為時日已到，而是因為那名垂釣高手來了～",
  str_item_intro_6001205 = "偕行紀念章。不知不覺間已經知曉了如此多的建築之法，那處山谷間的空地，想必不會荒蕪了。",
  str_item_intro_6001206 = "偕行紀念章。掌握了如此多的建築，只要願意，就可以將空庭建設為一處繁榮小鎮，這便是空庭主人的實力。",
  str_item_intro_6001301 = "偕行紀念章。寂靜之地，往昔的傳說，喚醒那名沉睡已久的英雄後，他們，將有如何的羈絆？",
  str_item_intro_6001302 = "偕行紀念章。舊日的契約無可違逆，舊日的敵人依舊令人如芒在背。即便是口頭上的許諾，也不能斷絕他們的意圖，阻止他們的行動。",
  str_item_intro_6001400 = "偕行紀念章。遊戲亦如人生，掌上的冒險也同樣刺激。能夠在嚴苛條件下過關之人，想必在現實中也能有所斬獲。",
  str_item_intro_6001401 = "偕行紀念章。它是忠實的記錄者，從無偏袒，從無隱瞞；它是記憶的儲存者，舊日時光，任君調閱。",
  str_item_intro_6001402 = "偕行紀念章。漂泊於天空之上的舞台，響徹在大陸四方的歌頌。在夢境與願景之間，愛與治癒之弦。",
  str_item_intro_6001403 = "偕行紀念章。在一望無際之大洋上，它是必不可少的幫助，據說不僅能引導船隻走向正途，甚至還有指點命運之迷津的大用……",
  str_item_intro_6001404 = "偕行紀念章。既是禮物也是心意，更是言語。無需任何的表白，把它交予對方就足以代言。",
  str_item_intro_6001405 = "偕行紀念章。特別之日的花團，在特別之時盛開，芬芳彌漫，意醉情迷，享受這當下的好時光吧。",
  str_item_intro_6001406 = "偕行紀念章。它不會離開偵探，只要伸出手，就能獲得它的幫助。有了它，再細微的線索也能一一發現。",
  str_item_intro_6001407 = "偕行紀念章。家族之日的記憶，水晶之中的幻影。雖為在虛妄之界與虛妄之人、虛妄之物發生的虛妄之事，然而一切又那麼真實，猶如親歷。",
  str_item_intro_6001408 = "虛妄之界困住了真實的人們，若強行打碎，反而束滯其中，永遠無法逃離……",
  str_item_intro_6001409 = "偕行紀念章。德諾奧峽谷的隱士，翩翩起舞、鱗粉揮灑，光粒漫溢之間，令人迷醉……",
  str_item_intro_6001410 = "偕行紀念章。勝利不僅僅由戰爭帶來，而是更加依賴於平日的建設、發展與日益強盛。",
  str_item_intro_6002001 = "偕行紀念章。善良之人的守護，諸神的使者，真的存在？抑或只是凡人的幻想？",
  str_item_intro_6002002 = "偕行紀念章。光之輪，武之備。太陽升起，但永遠不要忘記黑暗的威脅；和平雖存，但永遠要警惕那些黑暗中的惡敵。",
  str_item_intro_6002003 = "偕行紀念章。北境的傳說，未知的古老巨物，只一息的噴吐，就足以令火焰成冰，小鎮封凍。",
  str_item_intro_6002004 = "偕行紀念章。世界上有那一種鏡子，只能找出來自己的倒影，然而那倒影也有生命、有生命，甚至有靈魂......",
  str_item_intro_6002005 = "偕行紀念章。它們原本都是尋常之物，只有握在擁有智慧之人的手中，才能獲得意識與靈魂，去完成它們的使命。",
  str_item_intro_6002006 = "偕行紀念章。鋼鐵比空氣重百倍，為何能升空？這不禁令人想到「鐵比水重，為何能用於造船？」有時候，知識與邏輯，是要勝過常識。",
  str_item_intro_6002007 = "偕行紀念章。令萬千沉重之鋼鐵飛馳如無形之聲音，恐怕只有神才能做到。",
  str_item_intro_6002008 = "偕行紀念章。沙漠漫天，戈壁接連，如此漫步為何，恐怕無人所知，也恐怕其行為的目的，便只是漫遊。",
  str_item_intro_6002009 = "偕行紀念章。沒有人可以只享受，而不用付出對等的代價。即便現在沒有，將來一定會有，而且付出的會是更多。",
  str_item_intro_6002010 = "偕行紀念章。恐怖的嚎叫，友軍的歡呼。戰爭的偉力不在於征服、計謀與勇敢，而是在名為「勝利」的祭壇上，人們不得不塑造的一位又一位「王者」。",
  str_item_intro_6002011 = "偕行紀念章。將普通人變為無堅不摧的戰士，只有鋼鐵的外殼是不夠的，更多的是協調、柔韌與堅持。",
  str_item_intro_6002012 = "偕行紀念章。有這樣的瓶子？沒有內外之分，也就沒有了空間，或許說它的空間是無限的。這種瓶子絕非凡間之物，唯有神才能理解，並造出它來。",
  str_item_intro_6002013 = "偕行紀念章。一條紙帶可以只擁有一個面？它「回答」了這個問題。關鍵之處在於絲帶上的接口，明白了這一點，就能明白某些「世界的接口」的道理......",
  str_item_intro_6002014 = "偕行紀念章。再小之處也可能存有萬物，凝視這瓶中的世界時，是否想過有某些存在，一樣地在某處凝視眼下的世界？",
  str_item_intro_6002015 = "偕行紀念章。在某些傳說中，萬物是在一顆樹上形成的，很多人嗤之以鼻。然而，當研究了某些生物的由來後，那些人卻又懷疑自己之前的說法了......",
  str_item_intro_6002016 = "偕行紀念章。單排琴弦就足以發出令人興奮的樂聲，如果是雙排的呢？然而演奏者恐怕也要擁有嫺熟的技術跟過人的體力吧。",
  str_item_intro_6002017 = "偕行紀念章。它的輪子就是它的身體，因此「碾壓」成為了它的主要攻擊方式，面對那滾滾而來的利刃，還是祈禱不要在戰場上直面它吧。",
  str_item_intro_6002018 = "偕行紀念章。如果有一天，要塞能像傳說中的巨獸一樣，橫行於大陸之上，恐怕不會碰上什麼對手。",
  str_item_intro_6002019 = "偕行紀念章。當凡人思考「虛無」之時，「虛無」已經化為實際存在，它無形無狀，它悄然進入這些凡人的眼中，滲入頭腦裡，形成另處虛無。",
  str_item_intro_6002020 = "偕行紀念章。不會勞累、沒有怨言，對於那些穿行於沙漠中的人，這就是他們的駿馬。",
  str_item_intro_6002021 = "偕行紀念章。世人熱衷棋局，身居高位者熱衷將世界作為棋局，然而棋子擁有自我意識，棋盤亦然。於是，棋局破碎，一如過往那無數次的重蹈覆轍。",
  str_item_intro_6002022 = "偕行紀念章。「沒入永遠的毀滅吧......再看一下眼前的世界，那是最後的回憶了。」那些來自黑暗的邪佞，對大陸生靈如是語。",
  str_item_intro_6002023 = "偕行紀念章。據說，天空中星辰的方位會代表凡人的命運，為此凡人曾建造高高的塔來觀察星辰的位置，宣讀未來。諷刺的是，這座塔卻無法知曉自己的結局。",
  str_item_intro_6002024 = "偕行紀念章。強壯的身軀、迅猛的動作，雖然外表為兇惡猛獸，然而真正令人畏懼的，則是那狡詐的頭腦與帶有劇毒的恐怖尾刺。",
  str_item_intro_6002025 = "偕行紀念章。仿佛來自地獄的使者，承載著生者的怒意，來到凡間。幽冥並不是它的歸宿，死而復生的輪回才是它的一切。",
  str_item_intro_6001500 = "偕行紀念章。\n音域寬博，海棠綻放；俯耳傾聽，若有迴響；遠風東來，盛開在即；雙榭生弦，灼華其上。",
  str_item_intro_6001507 = "偕行紀念章。\n北境中有些雪是最近剛下的，另一些卻是來自亙古之前。你手上拿著的雪是哪一種呢？",
  str_item_intro_6001508 = "偕行紀念章。\n一同經歷的冒險，都將被珍藏起來。",
  str_item_intro_6001510 = "未被毒液污染的花朵，那是如此純潔和美好。\n就像她一樣。",
  str_item_intro_6001511 = "偕行紀念章。\n過人的智慧，既可以被用來製造溝通大陸的航船，也可以被用來製造撒佈混亂的兵器，這時候，如何選擇就成了一種智慧。",
  str_item_intro_6000620 = "偕行紀念章。\n啟光打造出的巨型戰鬥機甲，擁有堅固外殼與強大火力，這種龐然大物的弱點往往不在外部……",
  str_item_intro_6000621 = "偕行紀念章。\n守衛最後防線的炮塔，消滅一切來犯之敵。",
  str_item_intro_6001512 = "偕行紀念章。\n人人都渴望獲得，卻非人人都能承擔。",
  str_item_intro_6001515 = "偕行紀念章。\n殘留著未知危險的機器，執行時間無法考證，總是在夜深人靜的時候發出詭異而駭人的滋滋聲。",
  str_item_intro_6001516 = "偕行紀念章。\n光靈與祟靈有何不同？兩者都會在春朔節的煙火下品嘗甘甜的糖人，一起歡慶這吉祥的節日。",
  str_item_intro_6001517 = "偕行紀念章。\n阿爾戈爾自行研發的科技手環，能即時監測心率、血壓、血氧度等健康資料，並根據佩戴者的運動數據制定健身計畫。",
  str_item_intro_6001520 = "偕行紀念章。\n「守護」是很沉重的詞，但是他們肯定了自己，把自己留在暴雪之中。",
  str_item_intro_6001521 = "偕行紀念章。\n犧牲，絕不是為了所謂榮譽。「你們是英雄，但也不僅僅是英雄。」",
  str_item_intro_6001524 = "偕行紀念章。\n「真有趣！二周目二周目！」",
  str_item_intro_6001525 = "偕行紀念章。\n腦海中的靈感瞬間點亮，化成記錄中值得紀念的時刻。",
  str_item_intro_6001526 = "偕行紀念章。\n「這份力量，不只屬於我一人。」",
  str_item_intro_6001529 = "偕行紀念章。\n「久違了，我的契約者。此行雖險，但通往真理。」",
  str_item_intro_6001530 = "偕行紀念章。\n王子的冒險雖然沒有迎來歸途，但為子民開闢了道路。他們的心隨時相連，他們的後裔，未來哪天也會在大陸重逢吧。",
  str_item_intro_6001531 = "偕行紀念章。\n她聽說，愛是人間的一場美夢。",
  str_item_intro_6001532 = "偕行紀念章。\n這是趟艱辛的旅途，結局卻似乎只是讓你目睹他人重逢的幸福。\n但對努力幫助星辰的你，有什麼理由不給予最深的感激？",
  str_item_6100001 = "偕行紀念板",
  str_item_6100002 = "偕行戰記板",
  str_item_6100003 = "偕行曜岩板",
  str_item_6100004 = "偕行機群板",
  str_item_intro_6100001 = "偕行紀念板。很適合放在空庭內的紀念板，可以讓夥伴們將偕行紀念章放於此處。",
  str_item_intro_6100002 = "偕行紀念板。雖然這面牆上的圖案頗具戰鬥的氣息，但是不妨礙大家將別的紀念章也放在上面的~",
  str_item_intro_6100003 = "偕行紀念板。黑色山岩頗具荒野氣息，究竟是誰把它搬來的？不管了，至少這面牆上的細小凹凸，能妥當地將那些紀念章穩穩擺好。",
  str_item_intro_6100004 = "偕行紀念板。這面背景是……好像來到了巨大的機械之中，彷彿置身於一座工廠間，讓人不由自主地將那些紀念章擺整齊。不過，隨意放置也是沒問題的，或許有一種別樣的錯落感？",
  str_item_6400001 = "稱號-對局先手",
