  str_item_9995018 = "耀光目鏡",
  str_item_4090334 = "片憶櫻雪",
  str_item_intro_1400851 = "影鎮的見證人，任何時候都保持中立。隨身的箱子裡存有數量龐大的紀錄，可以說是影鎮的行動檔案庫。",
  str_item_intro_3000220 = "行動點：活動中挑戰特定關卡時所需的行動點數，會隨時間恢復。",
  str_item_intro_3000221 = "少見的槲寄生果實，北境人認為它代表著希望與豐饒。用於在雪松市集兌換禮品。",
  str_item_intro_3000001 = "採用特殊工藝製造的光源載體，是進行各類探險的必需物資。",
  str_item_intro_3000002 = "白夜城發行的硬幣，純度高、數量多，是大陸各地普遍認可的貨幣。",
  str_item_intro_3000003 = "打磨耀晶後得到的寶石。\n用於召集光靈、兌換特召星標和召集星標，以及購買稜鏡。",
  str_item_intro_3000004 = "指揮各種作戰獲得的心得體驗。等級越高，與巨像的感應便越緊密，足以瞭解更多巨像的詳情。",
  str_item_intro_3000005 = "螢盞可以自動回復，其速度受光能儲艙影響，還能在冶煉坊中透過熔煉巨像肌材增加。\n它們是聽命於巨像控制者的微型構裝體，負責恢復巨像、日常維修等工作。",
  str_item_intro_3000006 = "「棱度計」顯示的數值，降低至零便表示必須離開，否則會有危險。",
  str_item_intro_3000007 = "祕境中發現的古老卷冊碎片，某些機構十分重視它們的價值，願意加以收購。",
  str_item_intro_3000008 = "完成各項日常任務給予的獎勵點數，累積至指定數值可獲得額外獎勵。",
  str_item_intro_3000009 = "成就的證明",
  str_item_intro_3000010 = "將與光靈變得更親密",
  str_item_intro_3000011 = "聖物色子",
  str_item_intro_3000012 = "於資源攜行室發現的特殊裝置，可為探索者收集各種物資。\n【連續掃蕩時使用，可消耗本次挑戰過關所需的稜鏡以立即獲得收益】",
  str_item_intro_3000013 = "巨像冶煉坊製作的特殊產物，據說是遠古科技的應用。利用它能夠改變某些物品的基本性質，令其變成新的物品。",
  str_item_intro_3000014 = "蘊含光能的天然水晶體。\n可使用耀晶在商店中購買禮包和光靈時裝，也可以將耀晶轉換為光珀，用於召集光靈和恢復稜鏡。",
  str_item_intro_3000015 = "與心之石一同被發現的透明寶石，擁有強烈的火彩，能在星鑽商店兌換貴重商品。",
  str_item_intro_3000016 = "更加稀有的星鑽，價值連城，可說是星鑽中的珍品，在輝耀商行相當受歡迎。",
  str_item_intro_3000017 = "維持巨像活動的必需物質，由光能儲艙分發，為巨像供應能源。",
  str_item_intro_3000018 = "從空庭各處發現的石片，應該是先前的殘留，具體作用不明。丘布們倒是很喜歡它，願意拿某些東西來交換。",
  str_item_intro_3000019 = "很稀有的星鑽，貴重到大部分人無法承擔其價格，只有去專門的奇璨商行才能交易。",
  str_item_intro_3000021 = "「臨空者號」艦橋與模擬器聯合製作的一種儲存片，可以讓導航員將自己的記憶輸入其中，從而在巨像的雲端硬碟中形成全像影像。",
  str_item_intro_3000022 = "一種珍貴木材，據說產自於某些奇異的植物，現在已經很少見。因稀有且天然圓潤而廣受社會名流的歡迎，影鎮中有專門的商會負責收購，在小範圍內作為等價物使用。",
  str_item_intro_3000025 = "據說它上面記載了「末逐之物」的言語，但由於現在還無法將其破譯，所以只是猜測。因其保持得相對完整，在某些追求真相的組織眼中具有一定的價值，願意收購。",
  str_item_intro_3000026 = "據說它上面記載了「末逐之物」的言語，但由於現在還無法將其破譯，所以只是猜測。由於破碎得有點厲害，感覺需要累積到一定的數量，才能引起收購者的興趣吧。",
  str_item_intro_3000029 = "遍閱特別事件簿的菁英可獲得的金色書籤。\n可以在【事件簿商店】兌換道具獎勵。",
  str_item_intro_3000030 = "通讀特別事件簿之人可獲得的書籤。\n可以在【事件簿商店】兌換道具獎勵。",
  str_item_intro_3000031 = "通讀特別事件簿之人可獲得的道具。\n可以在【事件簿商店】兌換普通時裝。",
  str_item_intro_3000032 = "通讀特別事件簿之人可獲得的道具。\n可以在【事件簿商店】兌換巨像家具。",
  str_item_intro_3501001 = "該道具可提升裝備的精煉等級。\n這種神祕物質能令某件物品與其持用者產生更強大的連結，但由於其具有轉眼即消散的性質，必須將其放入特製容器保存。",
  str_item_intro_3000100 = "能發射召集訊號的裝置。\n可在常規召集中獲得光靈。",
  str_item_intro_3000101 = "能發射特殊召集訊號的裝置。\n可在限時召集中獲得光靈。",
  str_item_intro_3000110 = "萬聖特典召集專屬道具，可在萬聖特典召集中發起十次召集。\n為限時道具，在【萬聖特典召集】結束後將轉化成3000光珀。",
  str_item_intro_3000112 = "聖誕特典召集專屬道具，可在聖誕特典召集中發起十次召集。\n此為限時道具，在【聖誕特典召集】結束後將轉化為3,000光珀。",
  str_item_intro_3000113 = "聯動限定召集的專屬道具，可以在聯動限定召集中進行10次召集。\n此道具是限時道具，請您在UTC +0時間2022年1月26日09:00之前使用，逾期則道具將消失，不另外轉換為其他內容。",
  str_item_intro_3000114 = "聯動限定召集的專屬道具，可以在聯動限定召集中進行10次召集。\n此道具是限時道具，請您在UTC +0時間2022年2月12日09:00之前使用，逾期則道具將消失，不另外轉換為其他內容。",
  str_item_intro_3000343 = "聯動限定召集的專屬道具，可以在聯動限定召集中進行10次召集。\n此道具是限時道具，請您在2023年11月7日17:00之前使用，逾期則道具將消失，不另外轉換為其他內容。",
  str_item_intro_3000115 = "狂歡特典召集專屬道具，可在狂歡特典召集中發起十次召集。\n此為限時道具，在【狂歡特典召集】結束後將轉化為3,000光珀。",
  str_item_intro_3000116 = "可在【啟明之光】限定召集中使用，進行一次召集。\n此道具是限時道具，請您在【啟明之光】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000117 = "可在【啟明之光】限定召集中使用，進行十次召集。\n此道具是限時道具，請您在【啟明之光】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000141 = "可在【啟明之光】限定召集或【孤勇闖客】推薦召集中使用，進行十次召集。\n此道具是限時道具，請您在【啟明之光】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_3000142 = "隙間特召星標",
  str_item_3000143 = "隙間十連召集靈",
  str_item_intro_3000142 = "可在【神蹟漸顯】限定召集或【霧鎖孤堡】限時召集中使用，進行一次召集。\n此道具是限時道具，請您在【神蹟漸顯】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000143 = "可在【神蹟漸顯】限定召集或【霧鎖孤堡】限時召集中使用，進行十次召集。\n此道具是限時道具，請您在【神蹟漸顯】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_3000145 = "鍊金術士十連召集靈",
  str_item_intro_3000145 = "可於【鍊金旅奇】聯動限定召集或【商略弦心】聯動限定召集中使用，召集十次。\n此為限時道具，請在上述召集結束前使用，逾期將消失，不轉化為其他物品。",
  str_item_intro_3000118 = "聯動限定召集的專屬道具，可以在聯動限定召集中進行10次召集。\n此道具是限時道具，請您在UTC+0時間2022年8月3日09:00之前使用，逾期則道具將消失，不另外轉換為其他內容。",
  str_item_intro_3000119 = "可在【北境女王】限定召集中使用，進行一次召集。\n此道具是限時道具，請您在【北境女王】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000120 = "可在【北境女王】限定召集中使用，進行十次召集。\n此道具是限時道具，請您在【北境女王】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000121 = "可在【夏風特典召集】中使用，進行十次召集。\n該道具是限時道具，在【夏風特典召集】結束後將轉化為3,000光珀。",
  str_item_3000146 = "破雪鳴鷹十連特典召集靈",
  str_item_intro_3000146 = "可在【破雪鳴鷹特典召集】中使用，進行10次召集。\n此為限時道具，【破雪鳴鷹特典召集】結束後，該道具會轉化成3,000光珀。",
  str_item_intro_3000122 = "可在【冬霰特典召集】中使用，進行十次召集。\n該道具是限時道具，在【冬霰特典召集】結束後將轉化為3,000光珀。",
  str_item_intro_3000123 = "可在本次【北境女王】限定召集中使用，進行一次召集。\n此道具是限時道具，請您在本次【北境女王】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_intro_3000124 = "這可不是一般的紀念冊，是附有歌爾蒂的簽名的！擁有它就能和這名偶像產生什麼奇妙的聯繫哦！\n可在本次【強運天星】該限定召集中使用，進行一次召集。\n此道具是限時道具，請您在本次【強運天星】限定召集結束之前使用，逾期則道具將消失，不額外轉化其他內容。",
  str_item_intro_3000125 = "可在【春朔特典召集】中使用，進行十次召集。\n該道具是限時道具，在【春朔特典召集】結束後道具會轉化成3,000光珀。",
  str_item_intro_3000126 = "可在【巡綽特典召集】中使用，進行十次召集。\n該道具是限時道具，在【巡綽特典召集】結束後，該道具會轉化成3,000光珀。",
  str_item_intro_3000127 = "可於【滌魂舊日】限定召集中使用，進行一次召集。\n此為限時道具，請在【滌魂舊日】限定召集結束前使用，逾期將消失，不轉化為其他物品。",
  str_item_intro_3000128 = "可於【滌魂舊日】限定召集中使用，召集十次。\n此為限時道具，請在【滌魂舊日】限定召集結束前使用，逾期將消失，不轉化為其他物品。",
  str_item_intro_3000129 = "可在【樂遊特典召集】中使用，進行十次召集。\n該道具是限時道具，在【樂遊特典召集】結束後道具會轉化成3000光珀。",
  str_item_intro_3000133 = "可在【暖冬頌歌特典召集】中使用，進行十次召集。\n此道具是限時道具，在【暖冬頌歌特典召集】結束後道具會轉化成3,000光珀。",
  str_item_intro_3000138 = "可在【狂歡特典召集】中使用，進行十次召集。\n該道具是限時道具，在【狂歡特典召集】結束後，該道具會轉化成3,000光珀。",
  str_item_intro_3000201 = "這是紅油扳手某些成員自己做的小徽章，由螺帽改造而來。在他們看來這代表「沙漠認可了你」，因此這種徽章只頒發給獲得紅油扳手認可的人。",
  str_item_intro_3000211 = "可以在夏潮飯店櫃檯兌換特別禮品的獎券，上面蓋的印章據說是飯店總經理的肖像。",
  str_item_intro_3000212 = "完成特別事件簿的任務，會獲得影鎮貢獻點，可用來解鎖對應的獎勵。影鎮不會虧待任何一位心懷夢想和慾望的冒險者。",
  str_item_intro_3000213 = "行動點：在活動內挑戰特定關卡所需的行動點數，會隨時間恢復。",
  str_item_intro_3000214 = "信使公會專用食品，用來補充工作所消耗的體力。口味成謎，也許有機會可以吃看看。",
  str_item_intro_3000215 = "重建進度（暫無詳情）",
  str_item_intro_3000217 = "軍功值：呈現軍人實際的戰績，代表對啟光聯邦貢獻的高低。",
  str_item_intro_3000219 = "揮灑汗水，忍受傷痛，用你的拳腳在地下格鬥賽中贏得聲望，讓你的威名響徹影鎮",
  str_item_intro_3000202 = "活動道具，可於湯屋達摩間抽獎，累積到一定數量更能解鎖緋的專屬劇情。\n雲山一大特產，是雲櫻飄落的花瓣，雲山的住民認為它會帶來好運。",
  str_item_intro_3000224 = "「白夜長明」活動道具，累積一定數量後可在名望階梯中領取獎勵。",
  str_item_intro_3000225 = "「龍女僕的假日」活動道具，可用於【朵露廚房】抽獎。\n熱騰騰的飯菜馬上就要上桌了，快點拿好餐盤就座吧！",
  str_item_intro_3000226 = "艾斯特拉不常見的飲料，喝了似乎可以提神醒腦。",
  str_item_intro_3000227 = "現代貨幣改造而成，舊舊的。",
  str_item_intro_3000229 = "探險者、冒險家的榮耀象徵，需要經過艱苦卓絕的努力或是跨越驚險萬分的困境才能獲得。",
  str_item_intro_3000236 = "完成挑戰後可獲得的積分。完成不同難度的挑戰所獲得的積分數量也有差異。",
  str_item_intro_3000238 = "在祭典的季節時，雲島人會在這種紙上寫上祝福的話語，希望在這一年中獲得幸福。",
  str_item_intro_3000239 = "遠東地區人們喜歡的干糧，不僅看起來很可愛，而且很容易攜帶，還有小配菜～",
  str_item_intro_3000240 = "「輕絲入夢」願鏡專屬道具，可在「輕絲入夢」願鏡中進行許願。\n該道具為限時道具，在【「輕絲入夢」願鏡】結束後道具會轉化成100光珀。",
  str_item_intro_3000241 = "該銀幣成色充足，是雲島上的主要流通貨幣。",
  str_item_intro_3000242 = "記錄賽事選手表現的卡片，上面有各個檢錄點人員的簽名。",
  str_item_intro_3000244 = "它的莫名力量，能讓深陷其中的人得以自由行動，甚至掙脫這裡的束縛......",
  str_item_intro_3000245 = "據說是某些靈魂碎片在異空間的「產物」，某些人對它們十分感興趣。",
  str_item_intro_3000246 = "將蒐集到的資料進行量化以及綜合測算後獲得的資訊，可以根據它來劃定範圍，開展搜尋行動。",
  str_item_intro_3000247 = "攜行探測器搜尋到的普通訊號",
  str_item_intro_3000248 = "攜行探測器搜尋到的特殊訊號",
  str_item_intro_3000253 = "原本勢力龐大的安德森商會發行的票據，如果能夠找到認可它的人，或許會換來一些東西。",
  str_item_intro_3000256 = "為攻打盜賊犯罪集團的藏身之處所需的點數。打敗潛入中遇到的敵人，向前前進吧。",
  str_item_intro_3000258 = "隨手記下的各種資訊、趣事、逸聞的紙條，如果要瞭解到事情的全貌，可以根據它們提供的線索來深入調查一番。",
  str_item_intro_3000259 = "每逢慶典時，好泊城會發給市民們的一種特殊硬幣，可以在慶典商街充當代金券。",
  str_item_intro_3000266 = "一座新開的水族館！無論是設備還是飼養的水生生物，都十分齊全，而且人很少！趕緊前往，不要錯過喔～\n水族館之遊專屬道具，可在水族館之遊中進行祈願。該道具為限時道具，在水族館之遊結束後會轉化為100光珀。",
  str_item_intro_3000267 = "攜行探測器搜尋到的普通訊號",
  str_item_intro_3000268 = "攜行探測器搜尋到的特殊訊號",
  str_item_intro_3000270 = "據魔術師說，這種牌雖然看起來很簡單，但是帶有神祕的力量，能夠讓他變成各種東西！\n活動期間消耗稜鏡過關獲得。",
  str_item_intro_3000271 = "尚可回收的空彈殼，可以在物資小站內用於一些物資的兌換。\n活動期間內消耗稜鏡過關獲得。",
  str_item_intro_3000275 = "據說只要擁有這張電影票，就能看那位「著名演員」的電影，甚至還能親自去採訪喔！\n聚光燈下專屬道具，可在聚光燈下中進行許願。該道具是限時道具，在聚光燈下結束後道具會轉化成100光珀。",
  str_item_intro_3000276 = "妮娜為增添鬼屋氛圍製作的錢幣道具，可以用來兌換景區紀念品",
  str_item_intro_3000278 = "散落在各處的零件，或許能派上用場！\n活動期間內消耗稜鏡過關獲得。",
  str_item_intro_3000280 = "復刻「輕絲入夢」願鏡專屬道具，可在復刻「輕絲入夢」願鏡中進行許願。\n該道具為限時道具，在【復刻「輕絲入夢」願鏡】結束後道具會轉化成100光珀。",
  str_item_intro_3000281 = "據說是某位天才導演的作品，有傳聞說他在試看自己拍攝的恐怖片時笑到岔氣死掉了。",
  str_item_intro_3000282 = "看起來是奇幻冒險劇情的劇本，這種劇本有時候浪漫而富有想像力，有時候卻套路古板令人讀著如同嚼蠟。",
  str_item_intro_3000283 = "劇本好像是根據真實故事改編的，但是故事原本的主角最終的下場沒有人知道，所以結尾都是經過藝術加工過的。",
  str_item_intro_3000284 = "狡木神祕地把這個劇本塞進你手裡，並稱事成之後會有高額回報。",
  str_item_intro_3000285 = "莉莉卡交給你的劇本，她似乎認為你有一些導演天賦，因此將廣告的拍攝工作交付給你。",
  str_item_intro_3000286 = "薇薇安交給你的劇本，據她所稱這是啟光在徵兵宣傳方面的一次新嘗試。",
  str_item_intro_3000288 = "伯利恆與你一起創作時所寫的筆記，蘊含著你們二人的思緒交織。\n綺色樂間專屬道具，可在綺色樂間中進行許願。該道具是限時道具，在綺色樂間結束後道具會轉化成100光珀。",
  str_item_intro_3000291 = "從旅途中找到的記錄，可以在歸來的這一段時間中，想起來許多重要資訊。",
  str_item_intro_3000292 = "全大陸最有人氣的偶像的週邊商品，怎麼能錯過呢！狂熱粉絲一定會收集它們的，自然而然就有想要從中賺上一筆的人來收購了……",
  str_item_intro_3000293 = "北境風俗之一。在冬日的節慶夜晚，孩子們將它掛在床頭，裡面寫上自己想要的禮物，據說那禮物就會在隔天早上出現在襪子裡！至於是誰放的，那就不知道啦~",
  str_item_intro_3000294 = "這種空白的卡片似乎擁有某種「魔力」，據說將願望寫在上面，就會實現。雖然可信度不高，但是誰會拒絕這種祝福滿滿的禮物呢？",
  str_item_intro_3000297 = "從匿名人士手中得到的劇本，看起來是包含驚險刺激與浪漫的故事，\n不過劇本中的故事似乎總有些眼熟……",
  str_item_intro_3000298 = "坊間流傳的故事改編成的劇本，危機四伏、江湖險惡盡顯於此。",
  str_item_intro_3000299 = "雲島時下最流行的話本之一，被神祕人士遠渡重洋交到了你的手中，\n乍看之下似乎是一個以刀劍打鬥和末世題材為賣點的故事……",
  str_item_intro_3000300 = "林家商會的票據，根據上面的金額，就能在碼頭小鋪那邊換東西哦！",
  str_item_intro_3000307 = "看起來很奇怪的石膏碎片，感覺是從雕像上掉下來的，或許有什麼線索吧……",
  str_item_intro_3000311 = "據說用這種高腳杯來與人對飲的話，會一直保持清醒~\n迷人之夜專屬道具，可在迷人之夜中進行許願。該道具是限時道具，在迷人之夜結束後道具會轉化成100光珀。",
  str_item_intro_3000313 = "啟光聯邦物資中心流通的貨幣，是運輸和調配補給品的唯一證明。",
  str_item_intro_3000321 = "似乎是什麼奇妙晶體的碎片，其中蘊含著更為奇妙的水滴……\n用途：在【占卜廳室】購買心儀的商品。\n取得途徑：完成消耗稜鏡的主線或資源整備關卡。",
  str_item_intro_3000326 = "做工精緻的硬幣，但總覺得有種危險的氣息……好吧，紅女士說它可以用來換些東西，應該沒問題吧……\n取得途徑：完成紅女士的委託任務。",
  str_item_intro_3000330 = "被荊棘所纏繞的花朵，是否綻放全憑自己，而非凡世之認為。\n黑荊白花的欲放活動專屬道具，可在黑荊白花的欲放活動中進行許願。該道具是限時道具，在黑荊白花的欲放活動結束后道具會轉化成100光珀。",
  str_item_intro_3000332 = "工作堆積如山，還要防備暗鬼的騷擾、偵查前方的動向……因此雷霆·傲骨只能在捉襟見肘的人力中進行適當安排，完成黃昏鎮一部分重建工作。",
  str_item_intro_3000334 = "巴頓對雷霆的權略認可度",
  str_item_intro_3000335 = "緋對雷霆的權略認可度",
  str_item_intro_3000336 = "薇薇安對雷霆的權略認可度",
  str_item_intro_3000337 = "希羅娜對雷霆的權略認可度",
  str_item_intro_3000353 = "心有所想，願望可期。",
  str_item_intro_3000354 = "累積「願望之繭」可在兌換中心兌換禮品。",
  str_item_intro_3000356 = "濟國人常用的香，外觀講究，香味淡雅。\n「燔木升煙、吿祭天地，阿霓明白這種文化。但每年總有那麼幾天，香火薰得阿霓睜不開眼睛……」",
  str_item_intro_3000361 = "因故障而紊亂的影像資料，光是收集整理就要費一番功夫。\n消耗後可以解鎖新的影像修復關卡。",
  str_item_intro_3000366 = "與特定光靈結下契約的必需品。",
  str_item_intro_3000367 = "出自影鎮的棒棒糖，味道隨機轉變，充滿驚喜。在物資匱乏的沙漠，寶貴如同貨幣。",
  str_item_intro_3000368 = "專為勤奮的導航員準備的補給箱。\n您的每一次努力和成長都會記錄下來，轉化為實實在在的回報。",
  str_item_intro_3000374 = "造型懷舊的遊戲代幣，據說高手玩家只要花一枚代幣就能玩個通宵。",
  str_item_intro_3000376 = "在迦南城換取日常生活物資的票券，對於啟光有特殊貢獻的人，還能用它申請定製有個人性質的物品。",
  str_item_intro_3000377 = "聽聞聖者的血不會白白流逝，而是永存，猶如琥珀。將之奉納給真理，就像將虔誠獻給主一樣。",
  str_item_intro_3000381 = "大夢初醒，那露水便凝在葉間，刹那消逝，好似美夢再尋不著。獻給夢中的蜃龍，或許能換得獎勵。",
  str_item_intro_3000383 = "來自空之山谷的彩紙，柔軟堅韌，既適合裝飾在窗邊，也可以結成彩偶。溫德嵐節的彩紙，不僅寄託往日的思念，更是前行的信心。",
  str_item_intro_3100001 = "可提升光靈等級，森系光靈效果提升50%。\n綠色的瑩玉，運用它進行冥想，便能恢復部分戰鬥記憶，獲得少許經驗。",
  str_item_intro_3100002 = "可提升光靈等級，森系光靈效果提升50%。\n較為珍貴的綠色瑩玉，運用它能回想起較多戰鬥時的感受，獲得較多經驗。",
  str_item_intro_3100003 = "可提升光靈等級，森系光靈效果提升50%。\n極為珍貴的綠色瑩玉，可以身歷其境感受到過往的戰鬥，獲得大量經驗。",
  str_item_intro_3100004 = "可提升光靈等級，水系光靈效果提升50%。\n藍色的瑩玉，運用它進行冥想，便能恢復部分戰鬥記憶，獲得少許經驗。",
  str_item_intro_3100005 = "可提升光靈等級，水系光靈效果提升50%。\n較為珍貴的藍色瑩玉，運用它能回想起較多戰鬥時的感受，獲得較多經驗。",
  str_item_intro_3100006 = "可提升光靈等級，水系光靈效果提升50%。\n極為珍貴的藍色瑩玉，可以身歷其境感受到過往的戰鬥，獲得大量經驗。",
  str_item_intro_3100007 = "可提升光靈等級，雷系光靈效果提升50%。\n黃色的瑩玉，運用它進行冥想，便能恢復部分戰鬥記憶，獲得少許經驗。",
  str_item_intro_3100008 = "可提升光靈等級，雷系光靈效果提升50%。\n較為珍貴的黃色瑩玉，運用它能回想起較多戰鬥時的感受，獲得較多經驗。",
  str_item_intro_3100009 = "可提升光靈等級，雷系光靈效果提升50%。\n極為珍貴之黃色瑩玉，會身歷其境感受到死去之戰鬥，獲得大量經驗。",
  str_item_intro_3100010 = "可提升光靈等級，火系光靈效果提升50%。\n紅色的瑩玉，運用它進行冥想，便能恢復部分戰鬥記憶，獲得少許經驗。",
  str_item_intro_3100011 = "可提升光靈等級，火系光靈效果提升50%。\n較為珍貴的紅色瑩玉，運用它能回想起較多戰鬥時的感受，獲得較多經驗。",
  str_item_intro_3100012 = "可提升光靈等級，火系光靈效果提升50%。\n極為珍貴的紅色瑩玉，可以身歷其境感受到過往的戰鬥，獲得大量經驗。",
  str_item_intro_3100013 = "可用於提升光靈等級。\n灰白色的瑩玉，擁有些許特殊能量，任何光靈都能透過它獲得少許經驗。",
  str_item_intro_3100014 = "可用於提升光靈等級。\n較為珍貴的灰白色瑩玉，任何光靈都能運用它重新想起戰鬥時的感覺，獲得一些經驗。",
  str_item_intro_3100015 = "可用於提升光靈等級。\n極為珍貴的灰白色瑩玉，任何光靈都能運用它感受到過往的戰鬥，獲得更多經驗。",
  str_item_intro_3210101 = "初級覺醒材料，用於白夜城勢力光靈的覺醒。\n白夜城黎明學院保存的物品，經過獨特的魔法體系增強，能夠提升光靈的力量。",
  str_item_intro_3210201 = "初級覺醒材料，用於影鎮勢力光靈的覺醒。\n影鎮流行的一種特殊烈酒，口感香醇，還能提升飲用者的力量。",
  str_item_intro_3210301 = "初級覺醒材料，用於北境勢力光靈的覺醒。\n松樹上凝集而成的晨露，經過北境特殊環境的影響，能夠讓北境人擁有強大的力量。",
  str_item_intro_3210401 = "初級覺醒材料，用於紅油扳手勢力光靈的覺醒。\n特殊的紅油，擁有強烈的刺激性氣味，唯有強力的紅油扳手成員才敢嘗試。",
  str_item_intro_3210501 = "初級覺醒材料，用於啟光聯邦勢力光靈的覺醒。\n啟光聯邦的實戰記錄，能夠提升閱讀者的戰鬥技巧。",
  str_item_intro_3210601 = "初級覺醒材料，用於真理結社勢力光靈覺醒。\n記載了些許古代知識的殘卷，真理結社的成員解讀後，能力將獲得提升。",
  str_item_intro_3210701 = "初級覺醒材料，用於無勢力者勢力光靈的覺醒。\n各色人等記錄的見聞，用語十分混亂。無勢力者閱讀後，能習得各種生存經驗。",
  str_item_intro_3210801 = "初級覺醒材料，用於龍洲勢力光靈的覺醒。\n龍洲藥房煉製的丹藥，純度佳，有助於增強體力，鞏固筋骨。",
  str_item_intro_3210102 = "中級覺醒材料，用於白夜城勢力光靈的覺醒。\n白夜城黎明學院保存的物品，據說自晨光汲取力量製成，能夠大幅提升光靈的力量。",
  str_item_intro_3210202 = "中級覺醒材料，用於影鎮勢力光靈的覺醒。\n命運香檳酒的珍品，口感大大提升，飲用者的力量也會大幅提升。",
  str_item_intro_3210302 = "中級覺醒材料，用於北境勢力光靈的覺醒。\n松樹上凝集而成的晨露，呈霜狀，較為少見，是北境人體內魔力的重要來源。",
  str_item_intro_3210402 = "中級覺醒材料，用於紅油扳手勢力光靈的覺醒。\n通常在紅油沙漠深處才能發現的紅油精華，足以讓紅油扳手成員提升戰鬥力。",
  str_item_intro_3210502 = "中級覺醒材料，用於啟光聯邦勢力光靈的覺醒。\n啟光聯邦處理了大量資料匯總而成的實戰記錄，能夠大幅提升閱讀者的戰鬥技巧。",
  str_item_intro_3210602 = "中級覺醒材料，用於真理結社勢力光靈的覺醒。\n記載了大量古代知識的卷冊，真理結社的成員解讀後，能力將獲得大幅提升。",
  str_item_intro_3210702 = "中級覺醒材料，用於無勢力者勢力光靈的覺醒。\n各色人等編寫的生存指南，無勢力者閱讀後，能學會更多知識與心得。",
  str_item_intro_3210802 = "中級覺醒材料，用於龍洲勢力光靈的覺醒。\n龍洲修行者煉製的丹藥，採用種種富含靈氣的材料，據說有易經洗髓之效。",
  str_item_intro_3210103 = "高級覺醒材料，用於白夜城勢力光靈的覺醒。\n白夜城黎明學院保存的物品，以獨特的魔法增強過能量，能將光靈的力量提升一個層次。",
  str_item_intro_3210203 = "高級覺醒材料，用於影鎮勢力光靈的覺醒。\n最稀有的命運香檳，能極大幅提升飲用者的力量，口感絕佳。",
  str_item_intro_3210303 = "高級覺醒材料，用於北境勢力光靈的覺醒。\n據說是完美的晨露，別名「北境之淚」，能為北境人提供強大的魔法力量。",
  str_item_intro_3210403 = "高級覺醒材料，用於紅油扳手勢力光靈的覺醒。\n最純粹的紅油，呈現半流體狀態，只有最強大的紅油扳手成員才敢使用。",
  str_item_intro_3210503 = "高級覺醒材料，用於啟光聯邦勢力光靈的覺醒。\n啟光聯邦處理了巨量資料匯總而成的實戰記錄，能夠將閱讀者的戰鬥技巧提升一個層次。",
  str_item_intro_3210603 = "高級覺醒材料，用於真理結社勢力光靈的覺醒。\n記載了大量古代知識的典籍，真理結社的成員解讀後，能力將獲得飛躍性的提升。",
  str_item_intro_3210703 = "高級覺醒材料，用於無勢力者勢力光靈的覺醒。\n包含了各色人等的所有見聞與心得，內容豐富，閱讀後能獲得全面性的生存能力。",
  str_item_intro_3210803 = "高級覺醒材料，用於龍洲勢力光靈的覺醒。\n龍洲隱士煉製的丹藥，集天精地華於一丸，有再造之功，可助服用者突破障壁，修為大進。",
  str_item_intro_3201011 = "初級覺醒材料，是水屬性光靈覺醒的必需品。\n常生於水邊土層的一種耀斑粉末，是大規模工業加工的原料之一。",
  str_item_intro_3201012 = "初級覺醒材料，是水屬性光靈覺醒的必需品。\n閃耀著奇妙藍色光芒的稀有水晶顆粒。",
  str_item_intro_3201013 = "初級覺醒材料，是水屬性光靈覺醒的必需品。\n以特殊光能術調配而成的純白色魔法粉塵。",
  str_item_intro_3201014 = "初級覺醒材料，是水屬性光靈覺醒的必需品。\n神祕物質之一，由海水凝結、轉化而成的原石，質地疏鬆，擁有很多氣孔。",
  str_item_intro_3201021 = "初級覺醒材料，是火屬性光靈覺醒的必需品。\n常於地熱帶發現的一種耀斑粉末，是大規模工業加工的原料之一。",
  str_item_intro_3201022 = "初級覺醒材料，是火屬性光靈覺醒的必需品。\n擁有著強烈紅色火彩的稀有水晶顆粒。",
  str_item_intro_3201023 = "初級覺醒材料，是火屬性光靈覺醒的必需品。\n以特殊光能術調配而成的火紅色魔法粉塵。",
  str_item_intro_3201024 = "初級覺醒材料，是火屬性光靈覺醒的必需品。\n神祕物質之一，必須在高溫下粉碎石塊，並加以燃燒而成。",
  str_item_intro_3201031 = "初級覺醒材料，是森屬性光靈覺醒的必需品。\n常生於岩石層的一種耀斑粉末，是大規模工業加工的原料之一。",
  str_item_intro_3201032 = "初級覺醒材料，是森屬性光靈覺醒的必需品。\n洋溢著清新碧綠色彩的稀有水晶顆粒。",
  str_item_intro_3201033 = "初級覺醒材料，是森屬性光靈覺醒的必需品。\n以特殊光能術調配而成的青綠色魔法粉塵。",
  str_item_intro_3201034 = "初級覺醒材料，是森屬性光靈覺醒的必需品。\n神祕物質之一，據說是上古時期植物分解、轉化而成的產物。",
  str_item_intro_3201041 = "初級覺醒材料，是雷屬性光靈覺醒的必需品。\n導電性佳的一種耀斑粉末，工業用途廣泛，但多半需經加工才能使用。",
  str_item_intro_3201042 = "初級覺醒材料，是雷屬性光靈覺醒的必需品。\n偶爾會閃現金色電光的稀有水晶顆粒。",
  str_item_intro_3201043 = "初級覺醒材料，是雷屬性光靈覺醒的必需品。\n以特殊光能術調配而成的純白色魔法粉塵。",
  str_item_intro_3201044 = "初級覺醒材料，是雷屬性光靈覺醒的必需品。\n神祕物質之一，通常可於雷暴之地發現的石頭，據說帶有閃電的力量。",
  str_item_intro_3202011 = "中級覺醒材料，是水屬性光靈覺醒的必需品。\n由水耀斑粉末加工提煉而成的塵砂，是製作工業品的初級半成品。",
  str_item_intro_3202012 = "中級覺醒材料，是水屬性光靈覺醒的必需品。\n閃耀著奇妙藍色光芒的稀有水晶碎片。",
  str_item_intro_3202013 = "中級覺醒材料，是水屬性光靈覺醒的必需品。\n由水輝煌素和特定溶劑調配而成的產物。",
  str_item_intro_3202014 = "中級覺醒材料，是水屬性光靈覺醒的必需品。\n以海水蒸餾錫礦石凝結成的半流體物質。",
  str_item_intro_3202021 = "中級覺醒材料，是火屬性光靈覺醒的必需品。\n由火耀斑粉末加工提煉而成的塵砂，是製作工業品的初級半成品。",
  str_item_intro_3202022 = "中級覺醒材料，是火屬性光靈覺醒的必需品。\n擁有著強烈紅色火彩的稀有水晶碎片。",
  str_item_intro_3202023 = "中級覺醒材料，是火屬性光靈覺醒的必需品。\n由火輝煌素和特定溶劑調配而成的產物。",
  str_item_intro_3202024 = "中級覺醒材料，是火屬性光靈覺醒的必需品。\n運用強烈燃燒法產生的一種特殊物質。",
  str_item_intro_3202031 = "中級覺醒材料，是森屬性光靈覺醒的必需品。\n由森耀斑粉末加工提煉而成的塵砂，是製作工業品的初級半成品。",
  str_item_intro_3202032 = "中級覺醒材料，是森屬性光靈覺醒的必需品。\n洋溢著清新碧綠色彩的稀有水晶碎片。",
  str_item_intro_3202033 = "中級覺醒材料，是森屬性光靈覺醒的必需品。\n由森輝煌素和特定溶劑調配而成的產物。",
  str_item_intro_3202034 = "中級覺醒材料，是森屬性光靈覺醒的必需品。\n以各種植物的萃取液與錫石混合，並轉化產生的特殊物質。",
  str_item_intro_3202041 = "中級覺醒材料，是雷屬性光靈覺醒的必需品。\n由雷耀斑粉末加工提煉而成的塵砂，是製作工業品的初級半成品。",
  str_item_intro_3202042 = "中級覺醒材料，是雷屬性光靈覺醒的必需品。\n偶爾會閃現金色電光的稀有水晶顆粒。",
  str_item_intro_3202043 = "中級覺醒材料，是雷屬性光靈覺醒的必需品。\n由雷輝煌素和特定溶劑調配而成的產物。",
  str_item_intro_3202044 = "中級覺醒材料，是雷屬性光靈覺醒的必需品。\n利用雷暴之力轟擊石塊而產生的特殊物質。",
  str_item_intro_3203011 = "高級覺醒材料，是水屬性光靈覺醒的必需品。\n水耀斑塵砂經複雜加工而成的片岩，是標準的工業半成品。",
  str_item_intro_3203012 = "高級覺醒材料，是水屬性光靈覺醒的必需品。\n稀有的藍色水晶，堅硬、碧藍，是珍貴的寶石。",
  str_item_intro_3203013 = "高級覺醒材料，是水屬性光靈覺醒的必需品。\n由水輝煌液蒸餾、過濾而成的珍貴藥劑。",
  str_item_intro_3203014 = "高級覺醒材料，是水屬性光靈覺醒的必需品。\n以複雜的魔法從海水提煉出的一種鉛粉。",
  str_item_intro_3203021 = "高級覺醒材料，是火屬性光靈覺醒的必需品。\n火耀斑塵砂經複雜加工而成的片岩，是標準的工業半成品。",
  str_item_intro_3203022 = "高級覺醒材料，是火屬性光靈覺醒的必需品。\n稀有的紅色水晶，擁有紅色彩焰，是珍貴的寶石。",
  str_item_intro_3203023 = "高級覺醒材料，是火屬性光靈覺醒的必需品。\n由火輝煌液蒸餾、過濾而成的珍貴藥劑。",
  str_item_intro_3203024 = "高級覺醒材料，是火屬性光靈覺醒的必需品。\n礦石經強烈燃燒得到的鉛塊，擁有無數蜂孔。",
  str_item_intro_3203031 = "高級覺醒材料，是森屬性光靈覺醒的必需品。\n森耀斑塵砂經複雜加工而成的片岩，是標準的工業半成品。",
  str_item_intro_3203032 = "高級覺醒材料，是森屬性光靈覺醒的必需品。\n稀有的綠色水晶，清新、溫潤，是珍貴的寶石。",
  str_item_intro_3203033 = "高級覺醒材料，是森屬性光靈覺醒的必需品。\n由森輝煌液蒸餾、過濾而成的珍貴藥劑。",
  str_item_intro_3203034 = "高級覺醒材料，是森屬性光靈覺醒的必需品。\n從大量植物萃取出來的罕見綠色鉛粉。",
  str_item_intro_3203041 = "高級覺醒材料，是雷屬性光靈覺醒的必需品。\n雷耀斑塵砂經複雜加工而成的片岩，是標準的工業半成品。",
  str_item_intro_3203042 = "高級覺醒材料，是雷屬性光靈覺醒的必需品。\n稀有的金色水晶，明亮、華麗，是珍貴的寶石。",
  str_item_intro_3203043 = "高級覺醒材料，是雷屬性光靈覺醒的必需品。\n由雷輝煌液蒸餾、過濾而成的珍貴藥劑。",
  str_item_intro_3203044 = "高級覺醒材料，是雷屬性光靈覺醒的必需品。\n利用閃電轟擊裂解石塊而獲得的鉛粉。",
  str_item_intro_3204011 = "特級覺醒材料，是水屬性光靈覺醒的必需品。\n將水耀斑片岩加工，再混合特定物質鑄成的金屬碇，是相當高級的工業成品。",
  str_item_intro_3204012 = "特級覺醒材料，是水屬性光靈覺醒的必需品。\n由稀有的藍色水晶柱聚集而成。",
  str_item_intro_3204013 = "特級覺醒材料，是水屬性光靈覺醒的必需物品。\n由水輝煌劑濃縮而成，能大幅度提升光靈的力量。",
  str_item_intro_3204014 = "特級覺醒材料，是水屬性光靈覺醒的必需品。\n以神祕魔法混合深海之水與汞液而成的鍛造物，是強大的魔法材料。",
  str_item_intro_3204021 = "特級覺醒材料，是火屬性光靈覺醒的必需品。\n將火耀斑片岩加工，再混合特定物質鑄成的金屬碇，是相當高級的工業成品。",
  str_item_intro_3204022 = "特級覺醒材料，是火屬性光靈覺醒的必需品。\n由稀有的紅色水晶柱聚集而成。",
  str_item_intro_3204023 = "特級覺醒材料，是火屬性光靈覺醒的必需物品。\n由火輝煌劑濃縮而成，能大幅度提升光靈的力量。",
  str_item_intro_3204024 = "特級覺醒材料，是火屬性光靈覺醒的必需品。\n在火山口燃燒汞塊冶煉產生的鍛造物精華，擁有強大的力量。",
  str_item_intro_3204031 = "特級覺醒材料，是森屬性光靈覺醒的必需品。\n將森耀斑片岩加工，再混合特定物質鑄成的金屬碇，是相當高級的工業成品。",
  str_item_intro_3204032 = "特級覺醒材料，是森屬性光靈覺醒的必需品。\n由稀有的綠色水晶柱聚集而成。",
  str_item_intro_3204033 = "特級覺醒材料，是森屬性光靈覺醒的必需物品。\n森輝煌劑濃縮而成，能大幅度提升光靈的力量。",
  str_item_intro_3204034 = "特級覺醒材料，是森屬性光靈覺醒的必需品。\n用稀有植物的研末配合特別的綠汞凝結而成的鍛造物，擁有強大的力量。",
  str_item_intro_3204041 = "特級覺醒材料，是雷屬性光靈覺醒的必需品。\n將雷耀斑片岩加工，再混合特定物質鑄成的金屬碇，是相當高級的工業成品。",
  str_item_intro_3204042 = "特級覺醒材料，是雷屬性光靈覺醒的必需品。\n由稀有的金色水晶柱聚集而成。",
  str_item_intro_3204043 = "特級覺醒材料，是雷屬性光靈覺醒的必需品。\n由雷輝煌劑濃縮而成，能大幅提升光靈的力量。",
  str_item_intro_3204044 = "特級覺醒材料，是雷屬性光靈覺醒的必需品。\n將閃電導入一種特殊的汞產生的魔法材料。危險、暴烈，擁有強大的力量。",
  str_item_intro_3205011 = "高級覺醒材料，是水屬性光靈覺醒的必需物品。\n將水耀斑珀磚經過特殊工藝加工，並摻入其他材料合成的精鋼，是最高級的工業成品。",
  str_item_intro_3205012 = "高級覺醒材料，是水屬性光靈覺醒的必需物品。\n使用眾多藍色水晶，輔以光能之力形成的稀有鑽石。",
  str_item_intro_3205013 = "高級覺醒材料，是水屬性光靈覺醒的必需物品。\n水輝煌濃縮劑加以提煉而成的產品，能夠極大幅提升光靈的力量。",
  str_item_intro_3205014 = "高級覺醒材料，是水屬性光靈覺醒的必需物品。\n以深海之水直接煉成的堅硬物質，美麗且光潔，極為昂貴。",
  str_item_intro_3205021 = "高級覺醒材料，是火屬性光靈覺醒的必需物品。\n將火耀斑珀磚經過特殊工藝加工，並摻入其他材料合成的精鋼，是最高級的工業成品。",
  str_item_intro_3205022 = "高級覺醒材料，是火屬性光靈覺醒的必需物品。\n使用眾多紅色水晶，輔以光能之力形成的稀有鑽石。",
  str_item_intro_3205023 = "高級覺醒材料，是火屬性光靈覺醒的必需物品。\n火輝煌濃縮劑加以提煉而成的產品，能夠極大幅提升光靈的力量。",
  str_item_intro_3205024 = "高級覺醒材料，是火屬性光靈覺醒的必需物品。\n將火山岩放入火焰中，提煉而成的堅硬物質紅色銀塊，極為昂貴。",
  str_item_intro_3205031 = "高級覺醒材料，是森屬性光靈覺醒的必需物品。\n將森耀斑珀磚經過特殊工藝加工，並摻入其他材料合成的精鋼，是最高級的工業成品。",
  str_item_intro_3205032 = "高級覺醒材料，是森屬性光靈覺醒的必需物品。\n使用眾多綠色水晶，輔以光能之力形成的稀有鑽石，帶有極大的光能力。",
  str_item_intro_3205033 = "高級覺醒材料，是森屬性光靈覺醒的必需物品。\n森輝煌濃縮劑加以提煉而成的產品，能夠極大幅提升光靈的力量。",
  str_item_intro_3205034 = "高級覺醒材料，是森屬性光靈覺醒的必需物品。\n蒐集大量稀有植物種子，並用神祕方法分解並凝煉成的銀塊，極為昂貴。",
  str_item_intro_3205041 = "高級覺醒材料，是雷屬性光靈覺醒的必需物品。\n將雷耀斑珀磚經過特殊工藝加工，並摻入其他材料合成的精鋼，是最高級的工業成品。",
  str_item_intro_3205042 = "高級覺醒材料，是雷屬性光靈覺醒的必需物品。\n使用眾多黃色水晶，輔以光能之力形成的稀有鑽石，帶有極大的光能力。",
  str_item_intro_3205043 = "高級覺醒材料，是雷屬性光靈覺醒的必需物品。\n雷輝煌濃縮劑加以提煉而成的產品，能夠極大幅提升光靈的力量。",
  str_item_intro_3205044 = "高級覺醒材料，是雷屬性光靈覺醒的必需物品。\n將閃電導入銀塊中所得的魔法材料，十分堅固，蘊含轟天驚雷般的力量。",
  str_item_intro_3220000 = "對於光靈突破有著特別的作用。\n在某些光靈手中會有特別效果的稀有寶石，蘊含著神祕能量，若能駕馭它，便能激發這些光靈的潛在之力。",
  str_item_intro_3220001 = "娜席里絲突破必需品。\n一枚光滑如鏡的寶石，仔細檢視能看見一名白衣少女的翩翩身影。",
  str_item_intro_3220002 = "緋突破必需品。\n這枚寶石偶爾會浮現一條櫻色長龍的形象，十分珍貴。",
  str_item_intro_3220004 = "庫瑪&佩吉突破必需品。\n庫瑪與佩吉佩戴這枚寶石後，寶石會散發出寒冷的氣息，因此是庫瑪與佩吉的最愛。",
  str_item_intro_3220005 = "蜜雅突破必需品。\n這塊寶石中，似乎封印著蜜雅的另一道身影……或許可以發現蜜雅真正的內心。",
  str_item_intro_3220006 = "卡蓮突破必需品。\n這枚寶石偶爾閃爍著長槍狀的淒白色光芒。",
  str_item_intro_3220009 = "浮士德突破必需品。\n偶爾會浮現出詭異扭曲圖案的寶石，他人佩戴的話會感到莫名心慌，然而浮士德卻不怕它，反而相當親近。",
  str_item_intro_3220010 = "露易絲突破必需品。\n擁有明亮氣質的寶石，據說它能讓露易絲·卡萊爾文思泉湧。",
  str_item_intro_3220011 = "希羅娜突破必需品。\n仔細望進這枚稀有寶石，眼前會有模糊的巨龍殘像飄過。",
  str_item_intro_3220012 = "涅墨西斯突破必需品。\n堅硬無比、切面天然的寶石，擁有震撼人心的力量。",
  str_item_intro_3220013 = "諾爾突破必需品。\n摸起來會有極強的寒冷感，卻又不會令人凍傷的奇妙寶石，是諾爾愛好之物。",
  str_item_intro_3220014 = "舒瓦茲突破必需品。\n閃爍著強烈光芒的白色寶石，舒瓦茲認為這枚寶石不僅代表自己，也代表了白夜城。",
  str_item_intro_3220015 = "蜂與銀城能在這塊寶石中看到許多不同景象，獲得非凡的藝術靈感。\n蜂&銀城突破必需品。",
  str_item_intro_3220016 = "卡夫卡突破必需品。\n這枚寶石硬度極高，據說曾經為某人抵擋過致命的攻擊。",
  str_item_intro_3220017 = "菈比突破必需品。\n仔細看去，這枚寶石中有著躍動之火光，彷彿一隻兔子，這正是菈比的幸運象徵。",
  str_item_intro_3220018 = "蕾吉娜突破必需品。\n彷彿散發著太陽光芒的寶石，即使在最黑暗的地方也能帶來光明，還能使蕾吉娜的音樂更上一層樓。",
  str_item_intro_3220019 = "維多利亞突破必需品。\n這枚寶石中擁有無數淚滴狀的細微顆粒，據說是維多利亞自己的……鮮血。",
  str_item_intro_3220021 = "尤拉突破必需品。\n當尤拉觸摸這塊寶石，寶石周圍就會泛起一圈綠色的鉸鏈狀波紋。",
  str_item_intro_3220023 = "克娜莉突破必需品。\n這枚凝結的黑色水滴，在克娜莉手中會變成十分堅硬的寶石。",
  str_item_intro_3220024 = "紅與黑突破必需品。\n這枚水晶會交織閃爍著紅色與黑色的閃光，靠近後還能聽到刀劍劈砍與子彈射擊的聲音。",
  str_item_intro_3220025 = "卡戎突破必需品。\n閃爍著紅黑相間的條紋狀光芒，是卡戎最喜歡的寶石。",
  str_item_intro_3220026 = "烏列爾突破必需品。\n偶爾會閃現灰黑火光的鑽石，雖然華麗，卻有一種幻滅的感覺……",
  str_item_intro_3220027 = "米迦勒突破必需品。\n這枚寶石據說是在轟鳴的雷暴天氣發現的，能為真正的主人帶來強大的力量。",
  str_item_intro_3220028 = "拉斐爾突破必需品。\n擁有奇妙力量的透明寶石，拉斐爾使用時，能夠增強治癒的力量。",
  str_item_intro_3220029 = "加百列突破必需品。\n加百列使用這塊寶石後，會泛起極為美麗的綠色光芒。",
  str_item_intro_3220030 = "醒山突破必需品。\n這枚寶石時時刻刻都散發著高熱，只有醒山才能佩戴。",
  str_item_intro_3220033 = "薇絲突破必需品。\n每次看去，這枚寶石都有著不同顏色的奇妙光彩，似乎蘊含著什麼往事……",
  str_item_intro_3220036 = "休拉德突破必需品。\n散發著不祥氣息的寶石，修拉德卻並不害怕，反而常說「它……與我一樣呢」。",
  str_item_intro_3220038 = "貢露突破必需品。\n據說這枚寶石中有許多人工元素，因此它並非天然形成的……而是古代文明的結晶。",
  str_item_intro_3220040 = "比比比約恩突破必需品。一碰到這枚寶石，就會出現火花……\n還是小心為妙，不要隨意把玩。",
  str_item_intro_3220041 = "Miss. 白蘭突破必需品。\n閃著優雅光芒的寶石，接近它就會給人嫻靜的感覺，很適合端莊的女性佩戴。",
  str_item_intro_3220042 = "巴頓突破必需品。\n這枚寶石隱藏著彷彿戰火的紅色斑點，只有巴頓看得見。也許這是他心中渴望的真實體現。",
  str_item_intro_3220044 = "薇薇安突破必需品。\n有著強烈放射光芒的寶石，很適合鑲嵌在劍柄上作裝飾。",
  str_item_intro_3220045 = "聖釘突破必需品。\n這枚寶石的邊緣十分鋒利，根據某人所說，那代表著「懲戒」……",
  str_item_intro_3220046 = "基汀突破必需品。\n基汀的成員佩戴這枚寶石的時候，腦海中總會出現更多的「詩句」。",
  str_item_intro_3220048 = "烈雀突破必需品。\n據說烈雀佩戴這枚寶石後，能領悟更多的格鬥技巧。",
  str_item_intro_3220054 = "娜汀突破必需品。\n這枚白色寶石時時刻刻散發著溫暖、和煦的光芒。",
  str_item_intro_3220055 = "在查明真相的過程中，彼亞塔曼也曾迷茫，但這枚水晶會為他帶來堅定的力量。\n彼亞塔曼突破必需品。",
  str_item_intro_3220056 = "康斯坦丁突破必需品。\n這枚水晶會在康斯坦丁獵殺暗鬼後自動記錄詳情，是康斯坦丁的默契拍檔。",
  str_item_intro_3220057 = "菲莉詩突破必需品。\n這枚水晶偶爾會散發出黑色氣息，靠近便會發現菲莉詩的真正內心。",
  str_item_intro_3220060 = "約娜突破必需品。\n這枚水晶的底座似乎是融化的黃銅，那正是約娜的手槍子彈所鑄成，代表了她過去的戰績。",
  str_item_intro_3220061 = "錢德菈突破必需品。\n透明寶石，仔細看裡面有一團躍動的氣息，彷彿她所蒐集到的種種情緒。",
  str_item_intro_3220062 = "西爾瓦突破必需品。\n據說這是在風脈之森深處發現的寶石，摸起來頗為清冷，是守林人西爾瓦的象徵。",
  str_item_intro_3220064 = "雷霆突破必需品。\n這枚寶石很重，但到了雷霆手中就會變得很輕，輕到能浮在空中……",
  str_item_intro_3220065 = "當塔塔凝望這枚水晶時，依稀可見雲山的影子，那裡正是她的故鄉……\n塔塔突破必需品。",
  str_item_intro_3220067 = "愛麗絲突破必需品。\n這枚寶石在愛麗絲手中會變成心形，並散發出特別的活力。",
  str_item_intro_3220068 = "溫蒂突破必需品。\n這枚寶石很輕，卻十分堅硬，像極了溫蒂的個性。",
  str_item_intro_3220070 = "莉奧娜突破必需品。\n若凝視這枚水晶，耳邊會聽到惡龍的咆哮。",
  str_item_intro_3220071 = "瀧突破必需品。\n這枚水晶偶爾會現出一條巨龍在噴火的場景，正是瀧的標誌，無疑是專屬於瀧的水晶。",
  str_item_intro_3220073 = "帕蒂&帕西突破必需品。\n這枚寶石會交替出現血紅色的光芒與黑色的氣息。",
  str_item_intro_3220075 = "歐緹突破必需品。\n若將這枚寶石放在耳邊，可以聽到隱約的電流聲，或許能用於通訊。",
  str_item_intro_3220076 = "克萊肯突破必需品。\n這枚奇妙的寶石從不同角度看去，都有不同的色彩，在克萊肯手中尤其多變。",
  str_item_intro_3220077 = "伯利恆突破必需品。\n這枚寶石晶瑩剔透，且寒冷無比，據說是世界上第一枚冰塊形成，只有北境女王才能佩戴。",
  str_item_intro_3220078 = "知更突破必需品。\n翠綠色的寶石，據說佩戴者能夠抵抗一切毒性，是知更的守護符。",
  str_item_intro_3220079 = "米潔妮突破必需品。\n十分方正的寶石，重心極為完美，據說可以用來保持天秤平衡。",
  str_item_intro_3220081 = "黑潮突破必需品。\n這枚寶石摸起來很燙，彷彿某個人氣宇軒昂的活力。",
  str_item_intro_3220083 = "莉莉姆突破必需品。\n這枚寶石只要靠近它真正的主人，就會浮現出電路般的奇妙花紋。",
  str_item_intro_3220084 = "伊斯塔萬突破必需品。\n這枚寶石周圍不時跳動著幾團藍色火焰，靠近它可以隱約聽到寶石中傳出「影主」二字的聲音。",
  str_item_intro_3220085 = "珍突破必需品。\n只要凝視這枚黑色寶石，似乎就能看到很多記錄文字……",
  str_item_intro_3220086 = "尤萊雅突破必需品。\n這枚白色玉石雕刻成花朵的形狀，典雅大方。",
  str_item_intro_3220087 = "貝芙麗突破必需品。\n這枚寶石偶爾會閃現出長矛狀的電花，火花形狀彷彿是貝芙麗的雷槍。",
  str_item_intro_3220088 = "瑪姬突破必需品。\n這枚水晶偶爾會閃爍奇怪的黃色光芒，靠近就能看到其中有一名少女的身影。",
  str_item_intro_3220089 = "伊倫汀突破必需品。\n這枚寶石偶爾會閃耀著藍色閃電，蘊含著強大的力量。",
  str_item_intro_3220090 = "芭芭拉突破必需品。\n擁有火紅色底座的寶石，靠近後能隱約聽見吵鬧的樂曲聲。",
  str_item_intro_3220091 = "克蘿伊突破必需品。\n這枚白色水晶似乎總會凝結出水露，宛如淚滴，靠近會聽到輕微的琴聲。",
  str_item_intro_3220092 = "契法突破必需品。\n這枚寶石堅硬無比，據說不會留下任何刮痕。",
  str_item_intro_3220093 = "彌加德突破必需品。\n這枚寶石似乎是由某個人造生物的脊椎提煉而成，擁有謎一般的能量……",
  str_item_intro_3220095 = "萊斯特突破必需品。\n這枚寶石聞起來令人感覺置身荒野，萊斯特能藉由它找到自己喜歡的氣味。",
  str_item_intro_3220096 = "沙利葉突破必需品。\n這枚寶石到了沙利葉手中會失去原有的型態，變得猶如水滴，而寶石也能為沙利葉帶來強大的力量。",
  str_item_intro_3220097 = "渡突破必需品。\n這枚寶石摸起來極為冰冷，且邊緣鋒利，幾乎可以替代刀具來使用。",
  str_item_intro_3220098 = "庫絲庫塔突破必需品。\n仔細望向這枚水晶，能發現一朵枯萎的黑色之花……",
  str_item_intro_3220099 = "艾蕾雅突破必需品。\n艾蕾雅見到這枚水晶時，身上的詛咒之力似乎減弱了不少……",
  str_item_intro_3220100 = "希卡蕾突破必需品。\n這枚寶石中蘊藏著一片「星空」，據說那是希卡蕾力量的真正來源。",
  str_item_intro_3220101 = "安希雅突破必需品。\n這枚寶石擁有奇妙的黃銅光澤，還有輕微的震動感，這種震動與某種波段的聲音頻率很接近……",
  str_item_intro_3220102 = "泰莎突破必需品。\n這枚寶石閃爍著不規則的電火花，若貿然接近，火花就會突然釋放，唯有泰沙能夠操縱這股力量。",
  str_item_intro_3220103 = "艾希突破必需品。\n凝望這枚水晶，會發現水晶內投放出某種「射線」，令人心生恐懼……",
  str_item_intro_3220104 = "多恩突破必需品。\n這是屬於多恩的寶石，因為當她握住寶石，寶石中便會映出白色花朵的影子，那正是多恩的心靈寄託……",
  str_item_intro_3220105 = "伊芙突破必需品。\n伊芙觸碰這枚水晶時，水晶周圍會產生細小的電弧，正是伊芙所擁有的特殊力量。",
  str_item_intro_3220107 = "戒衛座心珀",
  str_item_intro_3220108 = "焚霜座心珀",
  str_item_intro_3220109 = "童謠座心珀",
  str_item_intro_3220110 = "鎮魂座心珀",
  str_item_intro_3220111 = "被拜里厄握在手中時，這枚水晶會變成血紅色，與拜里厄身上的結晶一模一樣……\n拜里厄突破必需品。",
  str_item_intro_3220112 = "這枚寶石常使其附近的可燃物莫名燃燒，只有在斯莫奇手中時，奇妙的力量才會消失。\n斯莫奇突破必需品。",
  str_item_intro_3220113 = "當波娜瑟觸碰這枚寶石時，腦海中就會湧出無數靈感，讓她創作出新的樂章。\n波娜瑟突破必需品。",
  str_item_intro_3220114 = "它總是閃耀著紅色光芒，彷彿一團熾烈的火焰，有時還會發出馬的嘶鳴聲。\n吉納維芙突破必需品。",
  str_item_intro_3220115 = "納努塞爾配戴這枚水晶後，彷彿能聽見大自然的聲音，與動植物的交流也更加順暢了。\n納努塞爾突破必需品。",
  str_item_intro_3220116 = "這枚寶石能為弗勞爾帶來許多設計靈感，推動其「機甲製造計劃」更進一步。\n弗勞爾突破必需品。",
  str_item_intro_3220117 = "當克將它握在手中時，彷彿能回到自己在「勇士突擊隊」的日子，讓他感慨萬分。\n克突破必需品。",
  str_item_intro_3220119 = "當雷文頓觸碰這顆寶石時，會聽到一陣陣巨劍摩擦鎖鏈的聲音，還能感受到汩汩電流。\n雷文頓突破必需品。",
  str_item_intro_3220120 = "在陽光的照耀下，這塊寶石散發出白色鎧甲一般的光澤。\n海蒂突破必需品。",
  str_item_intro_3220121 = "這枚寶石會偶爾顯現一名短髮女子的身影，那是普律瑪再熟悉不過的人……\n普律瑪突破必需品。",
  str_item_intro_3220122 = "艾爾戈絲將這顆寶石放到耳邊時，會聽到鐘錶轉動的「喀嗒」聲，讓她對時間的掌握更加精確。\n艾爾戈絲突破必需品。",
  str_item_intro_3220123 = "有了這塊寶石，柯蒂更能夠得心應手地處理突發事件了。\n柯蒂突破必需品。",
  str_item_intro_3220126 = "這枚水晶能融入她胸前的寶石中，增添絢爛的光彩。\n貝菲爾突破必需品。",
  str_item_intro_3220127 = "在帕索洛手中時，這枚水晶會變得極薄，而且十分輕盈，能在空中飛舞。\n帕索洛突破必需品。",
  str_item_intro_3220129 = "這枚水晶非常輕盈，路克能讓它浮在空中，以蝴蝶般靈巧的身姿舞動。\n路克突破必需品。",
  str_item_intro_3220131 = "寶石表面雕刻著晦澀難懂的文字，似乎只有諾維亞知道這些文字的意涵。\n諾維亞突破必需品。",
  str_item_intro_3220132 = "浸泡在蜂蜜中的寶石，閃耀著瑩潤的光澤，散發出陣陣甜蜜的氣息。\n愛洛拉突破必需品。",
  str_item_intro_3220133 = "這枚寶石一靠近他人就會燃起炙熱的火光。不過在小林身邊，會化為柔和的粉色。\n朵露突破必需品。",
  str_item_intro_3220134 = "寶石上時不時閃過點點電光，握在手中會感到不可思議的柔軟。\n康娜突破必需品。",
  str_item_intro_3220135 = "一股暖流規律地在寶石上流淌，靜下心來能聽到清泉流動。\n艾爾瑪突破必需品。",
  str_item_intro_3220136 = "盯著寶石久了會看到越來越多景象，天空、海洋、山川、城鎮，最後是一雙深不見底的異色眼瞳。\n露可亞突破必需品。",
  str_item_intro_3220137 = "靠近這枚寶石會聽見不祥的嘶吼，法夫納的聲音混雜其中，低聲吟誦著什麼。\n法夫納突破必需品。",
  str_item_intro_3220138 = "希諾普握住它時，彷彿能看到綠色的絲線……\n希諾普突破必需品。",
  str_item_intro_3220139 = "如果把這塊寶石貼近耳朵，仔細聆聽，說不定能聽見未知存在的呼喚。\n艾莉法突破必需品。",
  str_item_intro_3220140 = "被擦拭得一塵不染的寶石，帶著羊皮紙與墨水的香氣，似乎能聽見裡面傳出讀書與祈禱的回音。\n芙洛琳突破必需品。",
  str_item_intro_3220141 = "這枚寶石強度很高，用球棒擊打後會發出清脆的聲響，很適合用於露比的揮棒練習。\n露比突破必需品。",
  str_item_intro_3220142 = "這枚寶石看起來有些普通，但卻能在花芸的撫摸下現出熊熊火焰的幻影。\n花芸突破必需品。",
  str_item_intro_3220143 = "這枚寶石會偶爾綻放出淡粉色的光芒，被輕輕搖晃時還會發出清脆而歡快的鈴響。\n凜音突破必需品。",
  str_item_intro_3220144 = "一塊平平無奇的寶石，保持著微涼的溫度，在寂靜的黑夜裡散發出幽幽的光。\n柏乃突破必需品。",
  str_item_intro_3220145 = "這枚寶石在雨森手中會變得十分輕盈，偶爾還會閃現出「忍」字。\n雨森突破必需品。",
  str_item_intro_3220146 = "这枚寶石會隱約散發出食物的香氣，靠近觀察便會發現寶石中似乎閃耀著某種奇特的火紅色澤。\n瑤突破必需品。",
  str_item_intro_3220147 = "色彩斑斕的寶石，讓人莫名覺得這東西很好吃。凝神細看的話，會發現寶石里閃爍著兩種相似的光芒。\n阿桃&阿杏突破必需品。",
  str_item_intro_3220148 = "這塊寶石觸感冰涼，在陽光的照耀之下，會折射出幽藍色的光芒。\n青瞳突破必需品。",
  str_item_intro_3220149 = "質地溫潤，不太起眼的寶石，表面偶爾會浮現一個銀髮的人影，每次還沒看清就會被羅伊拿走。他太高了，搶不回來。\n羅伊突破必需品。",
  str_item_intro_3220150 = "不知為何，這枚寶石總是發出「吱拗吱拗」的響聲，聽起來......好像是給人偶上發條的聲音？\n蓮突破必需品。",
  str_item_intro_3220151 = "這枚寶石質地堅硬，溫度極高。被賈爾斯觸碰時，寶石會幻化為一隻羊角的形狀，令人稱奇。\n賈爾斯突破必需品。",
  str_item_intro_3220152 = "被梅握在手中時，這枚寶石的表面會浮現出一隻貓咪的影像，偶爾也會閃現一位光靈的身影，但沒人能看清那是誰。\n梅突破必需品。",
  str_item_intro_3220153 = "這枚寶石由啟光最受人尊重的寶石匠人親手打磨，只有站在啟光聯邦最頂端的人才有資格拿在手上。\n萊因哈特突破必需品。",
  str_item_intro_3220154 = "每當薇絲靠近時，這枚寶石便會開始微微震動，然後交替散發出紅色與綠色的光芒。\n薇絲·空瞳突破必需品。",
  str_item_intro_3220187 = "有點黏手的寶石，湊近時聞得到一股甜膩的味道。李天閑每次使用都會露出真好吃的笑容，難道這是糖塊？\n李天閑突破必需品。",
  str_item_intro_3220188 = "這枚寶石摸起來質地潤滑，湊近嗅聞還有一股淡淡的花香，仔細看會發現上面的細紋構成了一朵海棠花的形狀。\n丹棠突破必需品。",
  str_item_intro_3221000 = "用以兌換限定光靈心珀",
  str_item_intro_3221001 = "用以兌換非限定5星森屬性光靈心珀。",
  str_item_intro_3221002 = "用以兌換非限定5星雷屬性光靈心珀。",
  str_item_intro_3221003 = "用以兌換非限定5星火屬性光靈心珀。",
  str_item_intro_3221004 = "用以兌換非限定5星水屬性光靈心珀。",
  str_item_intro_3221005 = "用以兌換非限定6星森屬性光靈心珀。",
  str_item_intro_3221006 = "用以兌換非限定6星雷屬性光靈心珀。",
  str_item_intro_3221007 = "用以兌換非限定6星火屬性光靈心珀。",
  str_item_intro_3221008 = "用以兌換非限定6星水屬性光靈心珀。",
  str_item_intro_5840001 = "最基礎的奇異樹種包，裡面的種子能培育出最基礎的奇異樹。",
  str_item_intro_5840002 = "精品奇異樹種包，裡面的種子能培育出經過微小突變而來的精品奇異樹。",
  str_item_intro_5840003 = "珍品奇異樹種包，裡面的種子能培育出經過多次突變而來的珍品奇異樹。",
  str_item_intro_5840004 = "稀世奇異樹種包，裡面的種子能培育出經過複雜突變而來的稀世奇異樹。",
  str_item_intro_3220155 = "一塊堅硬又沉重的寶石，偶爾能看見裡面閃過一個巨大的黑色影子，似乎有猛獸的低吼從中傳出。\n巴頓·芒刃突破必需品。",
  str_item_intro_3220156 = "一塊看起來十分稀有的寶石。仔細凝視這塊寶石的話，會發現其中透出的光澤變化無常，似乎在彰顯著一種不屈的意志。\n妮娜突破必需品。",
  str_item_intro_3220157 = "這枚寶石的韌度極高，怎麼摔都摔不碎——至於這一點是怎麼被發現的，恐怕只有早苗知道了。\n早苗突破必需品。",
  str_item_intro_3220158 = "JOKER突破必需品。\n閃爍著強烈光澤的寶石。\n能感受到其中強烈的反抗意志。",
  str_item_intro_3220159 = "QUEEN突破必需品。\n透體晶瑩的寶石。\n能感受到其中強烈的反抗意志。",
  str_item_intro_3220160 = "FOX突破必需品。\n有著溫潤手感的寶石。\n能感受到其中強烈的反抗意志。",
  str_item_intro_3220161 = "VIOLET突破必需品。\n小花形狀的寶石。\n能感受到其中強烈的反抗意志。",
  str_item_intro_3220162 = "MONA突破必需品。\n表面有著類似利爪形成的抓痕的寶石。\n能感受到其中強烈的反抗意志。",
  str_item_intro_3220164 = "乍一看這塊寶石內部似乎凝滿了水蒸氣，但轉瞬間便化為了烈焰。但無論寶石內部如何變化，都無法改變這塊寶石堅毅的本質。\n卡蓮·煜魂突破必需品。",
  str_item_intro_3220165 = "當琪爾仔細看向這塊晶體的時候，似乎從中能瞥見一些神祕公式，它們能為琪爾帶來源源不斷的靈感。\n琪爾突破必需品。",
  str_item_intro_3220166 = "在附近有神奇動物出現的時候，這枚寶石會產生劇烈的震動。\n菲雅突破必需品。",
  str_item_intro_3220167 = "這是一枚神奇的寶石，它能在自身附近製造出自己的幻影......小心，千萬別被它給騙了。\n傑諾突破必需品。",
  str_item_intro_3220168 = "一塊觸感冰涼的寶石，有時候還能從中聽到海浪的聲音。\n虹霞突破必需品。",
  str_item_intro_3220169 = "每當握緊這塊寶石時，塞提總會感覺到有無盡的勇氣從掌心注入全身，連心臟躍動的鼓點也隨之發生了改變。\n塞提突破必需品。",
  str_item_intro_3220170 = "一枚充滿硝煙味道的寶石，神奇的是，這枚寶石的表面偶爾還會閃現出一把刀的影像。\n珀拉珂突破必需品。",
  str_item_intro_3220171 = "這是一枚神奇的寶石，只要注意聽，就能聽到寶石內部傳出的烏鴉鳴叫一般的聲音。\n卡斯特突破必需品。",
  str_item_intro_3220172 = "仔細看，這枚寶石有時會閃現一些精彩的電影片段。有了它，莉莉卡的演技能更上一層樓！\n莉莉卡突破必需品。",
  str_item_intro_3220173 = "當米洛斯的槍口迸發出火光時，這塊寶石中似乎映出了一個牛頭人身的惡魔的身影。\n米洛斯突破必需品。",
  str_item_intro_3220175 = "一塊布滿傷痕的寶石。握著它的時候，雖然能感受到鋒利的稜角，但只要將它一直緊握，便會有種奇異的回溫感。\n阿克希亞突破必需品。",
  str_item_intro_3220176 = "有著美麗顏色的寶石，雖然打磨尚未完成，但已經顯現出明亮的光輝，偶爾有飛鳥的身影從寶石中飛過。\n貝爾塔突破必需品。",
  str_item_intro_3220177 = "這塊彩色寶石摸起來十分溫潤，長期隨身攜帶的話，似乎能分享到屬於歌爾蒂的好運。\n歌爾蒂突破必需品。",
  str_item_intro_3220178 = "這塊寶石質地堅硬，用錘子大力敲擊也無法造成絲毫傷害。\n維克突破必需品。",
  str_item_intro_3220180 = "摸起來有點硬，但是按下去又會立刻回彈，據說珀蘭蒂會用它練習按動快門的手速呢。\n珀蘭蒂突破必需品。",
  str_item_intro_3220181 = "用手撫摸這塊寶石時，能感受到溫暖的氣息，是仲胥熾熱內心的證明。\n仲胥突破必需品。",
  str_item_intro_3220182 = "薄薄的、摸上去有點硬的寶石，像鱗片一樣，隨著光線角度的變化，會呈現出不同顏色。\n木月白突破必需品。",
  str_item_intro_3220183 = "散發著一股淡淡的青草香，略帶苦味，會讓人想起厘青藥房裡的味道。\n厘青突破必需品。",
  str_item_intro_3220184 = "摸上去有種飽經風霜的磨砂感，同時又很剔透美麗。\n耶利亞突破必需品。",
  str_item_intro_3220185 = "摸起來很光滑，似乎經常被凱雅拿在手中撫摸，仔細看裡面透出正在走動的鐘錶盤，原來這是塊錶嗎？\n凱雅突破必需品。",
  str_item_intro_3220186 = "潔白的聖光籠罩著這塊寶石，貿然觸摸可能會玷汙這份光輝。\n蒂娜突破必需品。",
  str_item_intro_3220189 = "摸起來很硬，在陽光下會反射出耀眼的光芒。仔細聞聞，還能嗅到一絲花香。\n零恩突破必需品。",
  str_item_intro_3220190 = "打磨得很精緻的寶石，不知採用什麼切割工藝，總之看起來就十分名貴，還是趕緊放下吧。\n馬太突破必需品。",
  str_item_intro_3220191 = "看起來很硬，但摸起來意外的軟彈，像小狗的爪子一樣，讓人忍不住一直捏捏。\n哈提突破必需品。",
  str_item_intro_3220192 = "這塊寶石沒什麼光澤，摸上去也很是粗糙，李奧說那是被邊境風沙刮磨的痕跡。\n李奧突破必需品。",
  str_item_intro_3220193 = "靠近它時，彷彿能聽到水流的聲音，克莉絲汀的內心，或許正洶湧著這樣的暗流。\n克莉絲汀突破必需品。",
  str_item_intro_3220199 = "自寶石晶瑩剔透的光澤中，傳來了鳥鳴一般的清脆迴響。\n鶯歌突破必需品。",
  str_item_intro_3220200 = "阿納托利收集的寶石，產自永夜境內的礦脈，被千里迢迢帶回了啟光。這塊寶石觸感溫潤，表面似乎能映出人影。\n阿納托利突破必需品。",
  str_item_intro_3220201 = "似乎是一塊容易被忽視的石頭，但是仔細聆聽，兩個糾纏的聲音交錯轟鳴，讓它看起來越發耀眼了。\n蜜雅·滌魂突破必需品。",
  str_item_intro_3220202 = "透過寶石，仿佛能看見雷雨之後的晴天，而這將會是在他統治之下的白夜城的未來。\n舒瓦茲·錚鳴突破必需品。",
  str_item_intro_3220203 = "一塊漂亮的寶石，在陽光的照耀下能散發出五彩斑斕的光芒，投射出一本占卜書的影像。\n加晴突破必需品。",
  str_item_intro_3220204 = "寶石籠罩在溫暖的光線之中，一如冬夜的燭火、黑夜的路燈，為迷途之人指引方向。\n約書亞突破必需品。",
  str_item_intro_3220205 = "常常看到白蘭把玩這塊精美的寶石，她說寶石底部會反射出一片紅色光暈，但其他人完全看不出來。\n白蘭·浣心突破必需品。",
  str_item_intro_3220206 = "萊蕾經常調侃這枚寶石帶有金錢的銅臭味，不過她很喜歡這種味道。\n萊蕾突破必需品。",
  str_item_intro_3220207 = "看似圓潤卻有尖銳觸感的水晶，是否暗示著那看似光鮮的外表，曾隱藏了過去的傷痕？\n希南突破必需品",
  str_item_intro_3220208 = "火熱而耀眼的水晶，正在低速旋轉著……\n叭噗突破必需品。",
  str_item_intro_3220209 = "雷霆·傲骨突破必需品\n觸摸時會感到小小的刺痛，那是盤旋在結晶內部的紅色雷光在蠢蠢欲動，正等著踏向屬於她的戰場。",
  str_item_intro_3220210 = "喬瑟琳突破必需品。\n仔細一看，溫和的光芒在寶石中心律動——似信徒禱告的詠唱，似劃破夜幕的聖光。",
  str_item_intro_3220211 = "這枚寶石在地下埋藏了很久，直至安頓挖掘出來，拂去它的塵土，展露它的辛祕。\n安頓突破必需品。",
  str_item_intro_3220212 = "比起寶石，更像是渾然天成的冰晶，也許是札莉雅自己親手打造的也說不定。\n札莉雅突破必需品。",
  str_item_intro_3220213 = "三十三號在遺跡附近找到的寶石。當極端孤獨時，三十三號也會把它當成「夥伴」，試著與其交流。\n三十三號突破必需品。",
  str_item_intro_3220214 = "麗蓓卡的父母送給她的寶石。每當握緊寶石時，她都能感覺到來自家人的溫暖，永不褪去。\n麗蓓卡突破必需品。",
  str_item_intro_3220215 = "由麗蓓卡的毒液凝結而成的寶石。只要把它帶在身上，伊莎的體內就充滿了力量。\n伊莎突破必需品。",
  str_item_intro_3220216 = "看起來平平無奇的石頭，內部卻隱藏著不知名的力量，不知道璇極會把它嵌入什麼樣的機關。\n璇極突破必需品。",
  str_item_intro_3220218 = "一塊神祕的寶石，剛好是一枚白夜幣的重量。仔細聆聽，彷彿能聽到寶石中傳來白夜幣嘩嘩作響的聲音。\n涉突破必需品。",
  str_item_intro_3220219 = "頗有分量的璀璨寶石，握在手中能感覺到它微微顫著久遠的心緒。那些深埋的過往，彷彿就快噴湧而出。\n伊斯塔萬·沓痕突破必需品。",
  str_item_intro_3220220 = "維吉爾鑑定過的一顆寶石，有很高的藝術價值。據悉，他很喜歡隨身攜帶這顆寶石，似乎是把它當成護身符。維吉爾突破必需品。",
  str_item_intro_3220221 = "一塊來歷不明的寶石，深邃無比，攝人心魄，彷彿預示著光靈神祕莫測的未來……\n阿爾戈爾突破必需品。",
  str_item_intro_3220223 = "遙遠年代的鱗片變化而成的石頭，霓的族群或許在其上寄托了悠遠的思緒。\n辰霓突破必需品。",
  str_item_intro_3220224 = "可能蘊藏著神祕力量的石頭，羅松可能會拿來敲打作惡祟靈的腦袋。\n羅松突破必需品。",
  str_item_intro_3220225 = "與白雪顏色相仿的寶石，一旦掉在地上就會與雪地融為一體，很難再找回來，所以一定要拿好唷。\n提亞拉突破必需品。",
  str_item_intro_3220227 = "一塊稜角異常鋒利的光珀，隨便拿取恐怕會割傷手掌。但只要小心觸碰，便能感到它散發出的微微溫熱。\n「蕾切爾」突破必須品。",
  str_item_intro_3220228 = "一塊華麗的寶石，散發著斑斕的光澤，湊近似乎還能聞到淡淡的糖果香味。\n澤塔突破必需品。",
  str_item_intro_3220229 = "普通的石頭。巴緹牙說可以用鎬子、熔爐，或是別的方法來取得。\n巴緹牙突破必需品。",
  str_item_intro_3220230 = "觸碰此寶石的一瞬，能使人聽到遠古的囈語，不在遠處，也不在耳畔，而是在腦海深處搏動，掙扎著向外鑽，如同某種存在已久的活物。\n維多利亞·墓歌突破必需品。",
  str_item_intro_3220231 = "一塊色澤詭豔的寶石。觸碰瞬間，鮮血從房間四壁緩緩淌下。你嚇得縮回了手，才發現一切都只是幻覺。\n威廉突破必需品。",
  str_item_intro_3220232 = "一握住這塊寶石，天上彷彿墜下千萬道利刃，劃開你的血肉。你在劇痛中慘叫出聲，定睛一看卻毫髮未傷。\n聖釘·祭禮突破必需品。",
  str_item_intro_3220233 = "自遺跡發掘出的寶石，也許可以從中感受到冒險的激情。\n萊莎突破必需品。",
  str_item_intro_3220234 = "自遺跡發掘出的寶石，也許可以從中感受到音樂的美好。\n科洛蒂婭突破必需品。",
  str_item_intro_3220235 = "自遺跡發掘出的寶石，也許可以從中感受到高貴的氣質。\n派翠夏突破必需品。",
  str_item_intro_3220237 = "晶瑩的寶石，觸感像雲端涼風，像深海濕柔。\n握在手中，隱約聽見呢喃：「別害怕，世界就沉睡在妳的夢裡。」\n摩耶突破必需品。",
  str_item_intro_3220238 = "乍看樸素無比，觸摸才頓覺鋒利。搏動的力量潛藏其中，彷彿無聲的怒火。\n蜜特拉突破必需品。",
  str_item_intro_3231101 = "普通禮物，送給白夜城勢力光靈的效果更好。\n和羽毛一樣輕巧的銀箔，十分精緻，相當受白夜城的人們歡迎。",
  str_item_intro_3232101 = "高級禮物，送給白夜城勢力光靈的效果更好。\n將光珀用金箔包裝而成的精美飾品，白夜城上流社會的主要寶石。",
  str_item_intro_3233101 = "送給白夜城勢力光靈效果更好。\n十分珍貴的工藝品，將蘊含光能的寶石鑲在珍貴的白水晶上製作而成。",
  str_item_intro_3231102 = "普通禮物，送給影鎮勢力光靈的效果更好。\n各種著名油畫的臨摹，在影鎮相當受歡迎。",
  str_item_intro_3232102 = "高級禮物，送給影鎮勢力光靈的效果更好。\n珍貴的藏酒，只有影鎮的暴發戶才能偶爾來一杯。",
  str_item_intro_3233102 = "送給影鎮勢力光靈效果更好。\n充滿魅力的獨特寶石，散發著綠色螢光，總令影鎮的人們趨之若鶩。",
  str_item_intro_3231103 = "普通禮物，送給紅油扳手勢力光靈的效果更好。 \n舊時代遺留之一種油脂，紅油扳手之成員都用來裝飾或討好自己的巨像。",
  str_item_intro_3232103 = "高級禮物，送給紅油扳手勢力的光靈效果更好。\n引燃火藥的關鍵物質，子彈、炸藥都會用到，紅油扳手內部的強勢貨幣。",
  str_item_intro_3233103 = "送給紅油扳手勢力光靈效果更好。\n少見的烈酒，只要喝一杯就會十分興奮，紅油扳手人人都喜歡喝。",
  str_item_intro_3231104 = "普通禮物，送給啟光聯邦勢力光靈的效果更好。\n啟光聯邦的常識書籍，多為各種自然知識的圖鑑，繪圖精美，行文簡潔明快。",
  str_item_intro_3232104 = "高級禮物，送給啟光聯邦勢力光靈的效果更好。\n啟光聯邦的教科書，深入淺出教導讀者運用科學知識來處理各種問題。",
  str_item_intro_3233104 = "送給啟光勢力光靈效果更好。\n啟光聯邦的內部書籍，記載了啟光至今發現的各種知識，能使讀者獲益良多。",
  str_item_intro_3231105 = "普通禮物，送給北境勢力光靈的效果更好。\n水滴剛凝結為雪花的型態，北境人認為其中蘊藏強大之魔法，他們喜歡將其蒐集起來。",
  str_item_intro_3232105 = "高級禮物，送給北境勢力光靈的效果更好。\n在在彩虹下發現的寶石，北境人認為能帶來持久的好運，十分珍貴。",
  str_item_intro_3233105 = "送給北境勢力光靈效果更好。\n從北境永不冰封的鏡湖取下的一片水凍結而成，色彩斑斕，是北境人的最愛。",
  str_item_intro_3231106 = "普通禮物，送給真理結社勢力光靈的效果更好。\n上古遺留的琥珀化甲蟲，真理結社的人們認為它具有神祕的魔力。",
  str_item_intro_3232106 = "高級禮物，送給真理結社勢力光靈的效果更好。\n記錄著神祕「天啟知識」的卷冊，真理結社的人們若能成功解讀，將發掘出許多不為人知的知識。",
  str_item_intro_3233106 = "送給真理結社勢力光靈效果更好。\n真理結社的人們認為它蘊藏了最終的祕密，足以改變現代社會的所有常識。",
  str_item_intro_3231107 = "普通禮物，送給無勢力者光靈的效果更好。\n以脫水術製作的壓縮口糧，輕巧、攜帶方便，在許多小聚落相當受歡迎。",
  str_item_intro_3232107 = "高級禮物，送給無勢力者光靈的效果更好。\n神祕的魔法治療藥劑，能讓擁有者在某些庇護所進行臨時醫療。",
  str_item_intro_3233107 = "送給無勢力者的光靈效果更好。\n許多人珍而重之的藏寶圖碎片，巨大的寶藏值得大家賭一把。",
  str_item_intro_3232108 = "普通禮物，送給龍洲勢力光靈的效果更好。\n可以折疊的扇子，以竹為骨，以紙為面，上繪山川嬌色，通行於龍洲的高堂暗室。",
  str_item_intro_3233108 = "高級禮物，送給龍洲勢力光靈的效果更好。\n以紅繩編成的裝飾繩結，心相印，情相結，是龍洲人心中相當有份量的禮物。",
  str_item_intro_3231201 = "普通禮物，送給擁有童心的光靈效果更好。\n擁有童心之人喜愛的糖果，五種口味，最大的賣點是能夠吹出哨子聲。",
  str_item_intro_3232201 = "高級禮物，送給擁有童心的光靈效果更好。\n擁有童心之人十分喜愛的遊戲書，玩家可以透過口語描述來進行有趣的冒險遊戲。",
  str_item_intro_3233201 = "送給擁有童心的光靈效果更好。\n擁有童心之人喜愛的模型，細節雕琢幾近完美，現已絕版。",
  str_item_intro_3231202 = "普通禮物，送給熱愛浪漫的光靈效果更好。\n個性浪漫之人喜愛的手工縫製玩偶，既像兔子又像熊，製作者不詳。",
  str_item_intro_3232202 = "高級禮物，送給熱愛浪漫的光靈效果更好。\n在昏暗的環境向瓶中望去，會發現瓶裡蘊含著美麗的霞光，十分浪漫。",
  str_item_intro_3233202 = "送給熱愛浪漫的光靈效果更好。\n使用稀有植物「純花」製作而成的美麗書籤，紋理多變、色彩斑斕。",
  str_item_intro_3231203 = "普通禮物，送給有奇特愛好的光靈效果更好。\n這種昆蟲以特異的長相聞名，某些嗜好奇特的人會蒐集這種刺蟲的標本。",
  str_item_intro_3232203 = "高級禮物，送給有奇特愛好的光靈效果更好。\n謎之生物的結晶化骨頭，長滿了芒刺，某些嗜好奇特的人很喜歡蒐集。",
  str_item_intro_3233203 = "送給有奇特愛好的光靈效果更好。\n嗜好奇特的人喜歡蒐集這種腐朽木塊，因為木塊的斷面偶爾會傳出神祕的低語聲。",
  str_item_intro_3231204 = "普通禮物，送給高貴的光靈效果更好。\n小巧輕盈、雕刻精美的銀質鈴鐺，個性高貴之人認為它能帶來好運。",
  str_item_intro_3232204 = "高級禮物，送給高貴的光靈效果更好。\n在不同光照強度下，會呈現出各種絢爛色彩的稀有礦石，貴族之間通常用來當作禮物。",
  str_item_intro_3233204 = "送給高貴的光靈效果更好。\n深受貴族喜愛的稀有特殊材質，多產於寒冷地帶，柔軟輕薄且不易磨損。",
  str_item_intro_3231205 = "普通禮物，送給性格直爽的光靈效果更好。\n荒漠地區著名的特色小吃，個性直爽的人很喜歡它吃起來的獨特口感。",
  str_item_intro_3232205 = "高級禮物，送給性格直爽的光靈效果更好。\n能夠滿足常見修繕需求的工具組，是個性豪邁之人的好幫手。",
  str_item_intro_3233205 = "送給性格直爽的光靈效果更好。\n能夠偵測生物與機械的機能數值，對個性豪邁的人來說相當實用。",
  str_item_intro_3239997 = "有多種口味的糖果！贈送給光靈後，可以增加大量好感度。",
  str_item_intro_3239998 = "贈送給光靈後，可以大幅提升好感度。",
  str_item_intro_3239999 = "美味的巧克力！贈送給光靈可以大幅提升好感度",
  str_item_intro_3300001 = "相當堅硬的物質，卻並非金屬……似乎是上古流傳至今的生化材料，能夠修復破損的巨像，並連結能源線路。",
  str_item_intro_3300002 = "看得出來是經過強化的巨像肌材，能夠將巨像內的房間補強得更加穩固。",
  str_item_intro_3300003 = "這種巨像肌材不僅堅固，更富有彈性；上面隱約浮現不知名的文字，是修復巨像某些關鍵設施的必要材料。",
  str_item_intro_3300004 = "升級巨像核心「艦橋」的必要插件，十分稀有，請珍惜使用。",
  str_item_intro_3300005 = "這個魔術方塊有著奇妙的結構，可能是某位英勇探索者的遺物。若將上面蝕刻的資訊輸入巨像的資料庫中，或許能解鎖新的房間。",
  str_item_intro_3300006 = "這個插件被埋藏在地下多年，看起來就是17年前臨空者號遺失的那個！使用它可以解鎖巨像中的某個房間。",
  str_item_intro_3400001 = "藍色的初級加強箱，開啟後可獲得水屬性初級覺醒材料各1個。",
  str_item_intro_3400002 = "紅色的初級加強箱，開啟後可獲得火屬性初級覺醒材料各1個。",
  str_item_intro_3400003 = "綠色的初級加強箱，開啟後可獲得森屬性初級覺醒材料各1個。",
  str_item_intro_3400004 = "黃色的初級加強箱，開啟後可獲得雷屬性初級覺醒材料各1個。",
  str_item_intro_3400005 = "藍色的中級加強箱，開啟後可獲得水屬性中級覺醒材料各1個。",
  str_item_intro_3400006 = "紅色的中級加強箱，開啟後可獲得火屬性中級覺醒材料各1個。",
  str_item_intro_3400007 = "綠色的中級加強箱，開啟後可獲得森屬性中級覺醒材料各1個。",
  str_item_intro_3400008 = "黃色的中級加強箱，開啟後可獲得雷屬性中級覺醒材料各1個。",
  str_item_intro_3400009 = "藍色的高級加強箱，開啟後可獲得水屬性高級覺醒材料各1個。",
  str_item_intro_3400010 = "紅色的高級加強箱，開啟後可獲得火屬性高級覺醒材料各1個。",
  str_item_intro_3400011 = "綠色的高級加強箱，開啟後可獲得森屬性高級覺醒材料各1個。",
  str_item_intro_3400012 = "黃色的高級加強箱，開啟後可獲得雷屬性高級覺醒材料各1個。",
  str_item_intro_3400013 = "藍色的初級補給箱，開啟後可隨機獲得1個水屬性初級覺醒材料。",
  str_item_intro_3400014 = "紅色的初級補給箱，開啟後可隨機獲得1個火屬性初級覺醒材料。",
  str_item_intro_3400015 = "綠色的初級補給箱，開啟後可隨機獲得1個森屬性初級覺醒材料。",
  str_item_intro_3400016 = "黃色的初級補給箱，開啟後可隨機獲得1個雷屬性初級覺醒材料。",
  str_item_intro_3400017 = "藍色的中級補給箱，開啟後可隨機獲得1個水屬性中級覺醒材料。",
  str_item_intro_3400018 = "紅色的中級補給箱，開啟後可隨機獲得1個火屬性中級覺醒材料。",
  str_item_intro_3400019 = "綠色的中級補給箱，開啟後可隨機獲得1個森屬性中級覺醒材料。",
  str_item_intro_3400020 = "黃色的中級補給箱，開啟後可隨機獲得1個雷屬性中級覺醒材料。",
  str_item_intro_3400021 = "藍色的高級補給箱，開啟後可隨機獲得1個水屬性高級覺醒材料。",
  str_item_intro_3400022 = "紅色的高級補給箱，開啟後可隨機獲得1個火屬性高級覺醒材料。",
  str_item_intro_3400023 = "綠色的高級補給箱，開啟後可隨機獲得1個森屬性高級覺醒材料。",
  str_item_intro_3400024 = "黃色的高級補給箱，開啟後可隨機獲得1個雷屬性高級覺醒材料。",
  str_item_intro_3400025 = "綜合性質的初級加強箱，開啟後可獲得所有初級覺醒材料各1個。",
  str_item_intro_3400026 = "綜合性質的中級加強箱，開啟後可獲得所有中級覺醒材料各1個。",
  str_item_intro_3400027 = "綜合性質的高級加強箱，開啟後可獲得所有高級覺醒材料各1個。",
  str_item_intro_3400028 = "應急性質的初級補給箱，開啟後可隨機獲得1個初級覺醒材料。",
  str_item_intro_3400029 = "應急性質的中級補給箱，開啟後可隨機獲得1個中級覺醒材料。",
  str_item_intro_3400030 = "應急性質的高級補給箱，開啟後可隨機獲得1個高級覺醒材料。",
  str_item_intro_3400031 = "常見的瑩玉原石，開啟後會隨機獲得1枚一階瑩玉（水、火、雷、森其中一種）。",
  str_item_intro_3400032 = "擁有各種瑩玉與多樣色彩的共生石，開啟後會獲得一階瑩玉（水、火、雷、森）各1枚。",
  str_item_intro_3400033 = "常見的瑩玉原石，開啟後會隨機獲得1枚二階瑩玉（水、火、雷、森其中一種）。",
  str_item_intro_3400034 = "擁有各種瑩玉與多樣色彩的共生石，開啟後會獲得二階瑩玉（水、火、雷、森）各1枚。",
  str_item_intro_3400035 = "色彩更加絢爛的瑩玉原石，開啟後會隨機獲得1枚三階瑩玉（水、火、雷、森其中一種）。",
  str_item_intro_3400036 = "擁有各種瑩玉與絢爛色彩的共生石，開啟後會獲得三階瑩玉（水、火、雷、森）各1枚。",
  str_item_intro_3400037 = "不知是誰送來的禮品袋，裡面包著禮物，快看看是什麼吧？\n使用後可隨機獲得1件普通禮物。",
  str_item_intro_3400038 = "突然出現的精緻禮包……裡面應該放著很不錯的禮物吧？\n使用後可隨機獲得1件高級禮物。",
  str_item_intro_3400039 = "包裝精美的禮盒，裡面的禮物應該很貴重吧？快拆開來看看！\n使用後可隨機獲得1件高價值的光靈禮物。",
  str_item_intro_3400040 = "由水晶打造，再以光能術加強的透明方盒，輕巧、堅固，裡面收藏著珍貴的光珀。\n使用後可獲得50光珀。",
  str_item_intro_3400041 = "存放白夜城發行貨幣所用的金幣箱，隨著白夜幣流通普及，這種箱子也變得隨處可見。\n內含100,000白夜幣。",
  str_item_intro_3400042 = "散發微光的透明水晶匣，裡面儲存的光能可以充入稜鏡中，使稜鏡恢復能量。\n使用後可獲得10稜鏡。",
  str_item_intro_3400043 = "造型方正的水晶盒，中心處閃著光芒，可以為稜鏡提供較多能量。\n使用後可獲得60稜鏡。",
  str_item_intro_3400044 = "由大型水晶打磨而成，裝飾華麗，裡面儲存著很多光能，能讓稜鏡恢復相當多的能量。\n使用後可獲得50稜鏡。",
  str_item_intro_3400045 = "閃爍著微光的大型晶匣，裡面儲存的光能可以充入數枚稜鏡中，令之恢複原有的能量。\n使用後可獲得60稜鏡。",
  str_item_intro_3400046 = "光靈聯軍早期開發的補給箱，開啟後將隨機獲得以下材料其中1個：白夜石、命運香檳、晨松之露、紅油凝脂、初級實戰記錄、舊日殘卷、大陸生存見聞、壯骨散丹。",
  str_item_intro_3400047 = "光靈聯軍早期開發的補給箱，開啟後將隨機獲得以下材料其中1個：晨光石、命運香檳珍品、晨松之霜、紅油固脂、中級實戰記錄、舊日古冊、大陸生存指南、洗髓靈丹。",
  str_item_intro_3400048 = "光靈聯軍早期開發的補給箱，開啟後將隨機獲得以下材料其中1個：黎明石、命運香檳絕品、晨松之淚、紅油醇脂、高級實戰記錄、舊日典籍、大陸生存百科、再造金丹。",
  str_item_intro_3400049 = "在北境，有一座矗立的燈塔，只要這座燈塔還散發著光芒，暗鬼就無法對這片極北之地造成威脅。",
  str_item_intro_3400050 = "獲得後可解鎖助理-薇絲便服。\n薇絲的便服形象。",
  str_item_intro_3400052 = "獲得後可解鎖背景圖-覆雪森林。\n北境邊緣茂密的樹林，在冬日覆蓋上厚厚的雪。如此美景經常令誤入其中的人迷失方向",
  str_item_intro_3400053 = "獲得後可解鎖背景圖-遠東的道館。\n在遠東地區，它是習武之所，也是人們修身養性的地方。",
  str_item_intro_3400054 = "獲得後可解鎖背景圖-心中的天空。\n在遺落的遠古城市裡，這片天空曾是它的居民們最大的慰藉。",
  str_item_intro_3400055 = "獲得後可解鎖背景圖-少女們的舞台。\n少女們曾於夏日起舞的地方。雖已過去很久，但這裡仍保留了當時的氣氛。",
  str_item_intro_3400056 = "獲得後可解鎖背景圖-櫻庭走廊。\n富有遠東特色的走廊與庭院，在櫻花開放的時節，別有一番風景。",
  str_item_intro_3400057 = "獲得後可解鎖背景圖-軍團長專列。\n當啟光聯邦的四名軍團長一起乘坐專列時，恐怕有什麼重要的事情發生了……",
  str_item_intro_3400058 = "獲得後可解鎖背景圖-綠洲。\n紅油扳手的主要據點之一，周圍地形複雜。",
  str_item_intro_3400059 = "獲得後可解鎖背景圖-四天使。\n這四位騎士長代表了白夜城貴族的強大力量。",
  str_item_intro_3400060 = "獲得後可解鎖背景圖-夏夜音樂會。\n在盛夏時節的夜晚中，少女們盡情享受音樂之處，直至現在似乎還能聽見那些歡笑與歌聲。",
  str_item_intro_3400061 = "獲得後可解鎖背景圖-熾焰之牙。\n以犬牙差互的地貌而得名的峽谷，陡峭崎嶇，難以通行。",
  str_item_intro_3400062 = "獲得後可解鎖背景圖-神祕宅邸。\n來歷成謎，主人未知的豪宅，似乎能在此享受一番悠閒的時光......",
  str_item_intro_3400063 = "獲得後可解鎖背景圖-環狀系統。\n來自於遠古的區域，究竟有著什麼樣的祕密？",
  str_item_intro_3400064 = "獲得後可解鎖背景圖-和弦紐帶。\n神祕的空間，神祕的力量......",
  str_item_intro_3400065 = "獲得後可解鎖背景圖-四手聯彈。\n還記得嗎？與薇絲一同啟動它的那個時刻......",
  str_item_intro_3400066 = "獲得後可解鎖背景圖-空谷巨像。\n當巨像再次出現在空谷時，是否預示著什麼？",
  str_item_intro_3400067 = "獲得後可解鎖背景圖-風中來信。\n據說是風帶來的消息，它告訴那名空裔，該回家了。",
  str_item_intro_3400068 = "獲得後可解鎖背景圖-寧靜墓園。\n空谷中一片寂靜的地方，時間也在此停止了流淌。",
  str_item_intro_3400069 = "獲得後可解鎖背景圖-盛裝驛站。\n空谷驛站裝飾一新，請期待接下來的節日夜晚吧。",
  str_item_intro_3400070 = "獲得後可解鎖背景圖-節日之憶。\n那是在空之山谷度過的第一個節日夜晚......",
  str_item_intro_3400071 = "獲得後可解鎖背景圖-影鎮夜晚的街道。\n當影鎮進入黑夜後，街道既顯靜謐，卻又暗藏一絲危機。",
  str_item_intro_3400072 = "獲得後可解鎖背景圖-夜與霧之影。\n影鎮籠罩在一片黑夜與迷霧之中，眾人能否讓此地恢復一線光明？",
  str_item_intro_3400073 = "獲得後可解鎖背景圖-安德森宅邸。\n氣派十足的宅邸，彰顯了主人的富足與優雅。",
  str_item_intro_3400074 = "獲得後可解鎖背景圖-雲櫻旅店。\n食宿上佳，溫泉更是超級棒，而且還提供浴衣喔～",
  str_item_intro_3400075 = "獲得後可解鎖背景圖-好泊港邊。\n晴空之下，享受微風，此時好泊城的港口邊是最佳去處了～",
  str_item_intro_3400076 = "獲得後可解鎖背景圖-海濱夏夜。\n如果這樣的時刻能永遠持續，便是無上的人生享受。",
  str_item_intro_3400077 = "獲得後可解鎖背景圖-沙灘轟鳴警告。\n這個......如果打下去的話，遊戲就提前結束了～",
  str_item_intro_3400078 = "獲得後可解鎖背景圖-舊日教堂。\n位於尤佛里亞的破敗建築，和其他地方一樣，只是個遮風擋雨的去處。",
  str_item_intro_3400079 = "獲得後可解鎖背景圖-神祕之地。\n無名的隱祕之地，埋藏了太多的過去及祕密，而這些能否有重見天日的那一刻？",
  str_item_intro_3400080 = "獲得後可解鎖背景圖-犧牲？。\n面對洶湧而來的暗鬼，那個人選擇了「犧牲」，殊不知這只是他的計策之一......",
  str_item_intro_3400082 = "獲得後可解鎖背景圖-真理的追求。\n大陸上眾人皆知的知識，他們卻認為是虛假的。真正的真理依舊在遙遠的彼岸，等待著他們去追尋、去獲取。",
  str_item_intro_3400083 = "獲得後可解鎖背景圖-巨像舞台。\n「臨空者號」酒吧內的舞台，設備齊全，足以讓大家展示才華。",
  str_item_intro_3400084 = "獲得後可解鎖背景圖-上古廢城。\n僅僅望著那倒塌的巨大建築，便已感受到那場遠古戰爭的慘烈。",
  str_item_intro_3400085 = "獲得後可解鎖背景圖-冬日之下。\n如果看到那閃亮的長劍與飛舞的金髮，應該就是出外巡遊的北境女王；在冬日之下，她正悉心巡視著這片土地。",
  str_item_intro_3400086 = "獲得後可解鎖背景圖-極光天幕。\n即使在北境，這種遍布天幕的極光也是難得一見的，據說當它出現時，或許會對未來產生某些莫名的影響……",
  str_item_intro_3400087 = "獲得後可解鎖背景圖-歌頌之路。\n漂流於四處的巨像之中，其走廊上已遍布那名少女的身影，而那份帶有希望的天籟，也即將散播於整個大陸。",
  str_item_intro_3400088 = "獲得後可解鎖背景圖-蜃風號甲板。\n只有這巨大、堅實的甲板，才能承受那高聳的船樓。",
  str_item_intro_3400089 = "獲得後可解鎖背景圖-東方碼頭。\n位於另一片大陸上的碼頭，房居、船隻都與艾斯特拉大陸迥然不同，不變的則是那喧囂、忙碌的景象。",
  str_item_intro_3400090 = "獲得後可解鎖背景圖-戰友反目。\n與大元帥並肩戰鬥，擊敗過無數敵人的戰友，現在卻對她刀兵相向。\n命運，如此捉弄！",
  str_item_intro_3400091 = "獲得後可解鎖背景圖：紅油信使。\n位於紅油沙漠的信使公會分部，看來已逐漸適應了此地的生活。",
  str_item_intro_3400092 = "獲得後可解鎖背景圖：耶利亞辦公室。\n處理每日事務的同時，耶利亞也讓此處染上濃濃的個人風格。",
  str_item_intro_3400093 = "獲得後可解鎖背景圖：安閒之所。\n在這種氛圍之下，無論是咖啡廳、餐廳還是酒吧，都有一個共同的功能——休息、放鬆，營造一處供人享受閒暇時光的場所。",
  str_item_intro_3400094 = "獲得後可解鎖背景圖：冰雪婚禮。\n晶瑩剔透的妝點小物，映照著新人們的身影，無瑕、透明，代表他們純潔的感情。冰雪之境的婚禮中，或許連寒冷也抵擋不了熾烈之心的貼近。",
  str_item_intro_3400099 = "獲得後可解鎖背景圖-烈火中影。\n紅色的惡魔四面襲來，那伸出援手的身影……",
  str_item_intro_3400100 = "獲得後可解鎖背景圖-倉庫一覽。\n隨處可見的儲藏間，或許有著什麼不為人所知的過去。",
  str_item_intro_3400101 = "獲得後可解鎖背景圖-上城一景。\n整潔、優雅，人稱「永不淪陷」的城區，這裡不僅是白夜城的中心，甚至可以說是整個大陸的中心……",
  str_item_intro_3400102 = "獲得後可解鎖背景圖-姐妹嬉笑。\n那姐妹玩鬧的一刻，雖已過去數千個日夜，仍猶在眼前。",
  str_item_intro_3400103 = "獲得後可解鎖背景圖-夜色庭台。\n白夜城的中央廣場，即使在夜色下，也散發著輝煌之氣，一如白晝。",
  str_item_intro_3400109 = "獲得後可解鎖背景圖-黎明學院。\n白夜城中有一個為光之神培養虔誠信徒的地方，在這裡人人都心懷敬仰。",
  str_item_intro_3400110 = "獲得後可解鎖背景圖-神祕遺跡。\n這裡是北境之下的一片未知空間，似乎有某種人造裝置仍在活躍。",
  str_item_intro_3400111 = "獲得後可解鎖背景圖-靜謐星空。\n艦橋上，星空下，獨自無眠的夜晚。你沒有按下控制台的琴鍵，仍能聽到來自宇宙的音樂。",
  str_item_intro_3400112 = "獲得後可解鎖背景圖-恬靜午後。\n白夜城裡有許多精緻而溫馨的小花園，貴族可以在這裡享用下午茶。末日好像離大家很遠很遠。",
  str_item_intro_3400113 = "獲得後可解鎖背景圖-地下診所。\n略顯簡陋的診所，但這裡承載著珍貴的回憶。",
  str_item_intro_3400114 = "獲得後可解鎖背景圖-陰暗角落。\n即便身處黑暗之中，她仍渴望著能再次擁抱光明。",
  str_item_intro_3400115 = "獲得後可解鎖背景圖-待客之道。\n只有被涉認可的人，才能住進這豪華又舒適的房間。",
  str_item_intro_3400116 = "獲得後可解鎖背景圖-新大陸。\n蜃風號成功抵達了新大陸，不過這並不表示冒險迎來尾聲，有更多未知的事物正在等著他們。",
  str_item_intro_3400117 = "獲得後可解鎖背景圖-影，無處不在。\n即使身處宅邸，影主仍然在時時觀察著影鎮。影子，會一直注視著你。",
  str_item_intro_3400118 = "獲得後可解鎖背景圖-歷史的陰霾。\n塵封的歷史終有揭祕的一日。他究竟是支配影鎮的獨裁者，還是拯救影鎮的英雄？",
  str_item_intro_3400119 = "獲得後可解鎖背景圖-會客室。\n燈火通明的房間裡，所有的物品和裝飾都擺放得井井有條。這裡是辦公、會客的專用場所。",
  str_item_intro_3400120 = "獲得後可解鎖背景圖-龍洲元素。\n雙榭城西側由影鎮管理，但在人文風俗方面，仍可窺見龍洲的獨特魅力。從懸掛在街頭巷尾的燈籠，到美味的龍洲小吃，無不展現著龍洲的鮮明特色。來到這裡的人們可盡情地感受龍洲的文化與風俗。",
  str_item_intro_3400121 = "獲得後可解鎖背景圖-雙榭港口。\n從龍洲大陸啟航的貨運船隻，最終都會停靠在雙榭城的港口。他們會在這裡從事貨物的買賣與交換，接著再返回龍洲大陸。可以說，這些港口在龍洲大陸與艾斯特拉大陸的航運中，發揮著關鍵作用。",
  str_item_intro_3400122 = "獲得後可解鎖背景-濟國春朔節。\n春朔節是龍洲大陸最重要的節日。在此期間，王室宴請貴客，百姓則團聚休閒。濟國人會在節日裡辦廟會、拜龍女、趕年獸，以求來年安康與好運。部分商戶會雇來祟靈進行驅趕年獸的儀式，為節日增添趣味。",
  str_item_intro_3400126 = "獲得後可解鎖背景圖-春朔團年飯。\n在龍洲，春朔之夜即是團聚之時。龍洲的夥伴們聚集在空裔身邊，與他共進這頓美味又吉祥的節日大餐，祝願他迎來更美好的一年。",
  str_item_intro_3400123 = "獲得後可解鎖背景圖-莊園風景。\n莊園坐落在碧空島上，風景優美；憑藉其得天獨厚的地理位置和深厚的人文底蘊，獨受白夜城貴族的青睞。有不少貴族喜歡在這裡漫步，放鬆心情。",
  str_item_intro_3400129 = "獲得後可解鎖背景圖-邊境洞穴。\n冰雪覆蓋的洞穴深處，冰柱連通穹頂與地面，彷彿是神靈的雕塑。每當極光傾瀉而下，那些險峻冰柱和巍峨洞壁上的霜花便凝固成奇異的型態，形成莊嚴而凜冽的氛圍。",
  str_item_intro_3400130 = "獲得後可解鎖背景圖-雪域邊隅。\n陰沉的雪天，原本無垠的雪原荒漠也有了盡頭。高大的山峰猶如一道城牆屹立在遠方，將世界分隔開來。山腳下幾座覆雪的矮屋若隱若現。生活在此，必然充滿了孤寂吧？",
  str_item_intro_3400133 = "獲得後可解鎖背景圖-地底火山核心。\n過往的歲月裡，馳騁沙漠的紅油扳手並未發現這座地底火山仍舊活躍。",
  str_item_intro_3400134 = "獲得後可解鎖背景圖-沙漠之夜。\n看起來似乎永遠不會有交集的幾人，如今卻一起坐在沙漠的繁星之下。她們的眼中閃爍，彼此的回憶相互交錯。",
  str_item_intro_3400135 = "獲得後可解鎖背景圖-衝擊者號。\n比起臨空者號，他的內部結構更加簡潔、圓滑，各個控制台也散發出危險的氣息。",
  str_item_intro_3400136 = "獲得後可解鎖背景圖-燒個痛快。\n叛逆和服從，只是形狀不同的柴薪，只要有足夠的溫度，燃起的將是同一團烈火。",
  str_item_intro_3400138 = "獲得後可解鎖背景圖-聖鳴節遊行。\n你是真理結社集體智慧的體現。你所經歷的一切，將指引真理結社未來的道路。 ",
  str_item_intro_3400139 = "獲得後可解鎖背景圖-遺跡孤島沙灘。\n遙遠的海域中，隱藏著一座遺忘於世的孤島。島嶼四周環繞著無盡的蔚藍，島上覆蓋著蓊鬱的密林植被。一座遺跡就沉睡在這片原始環境，歷經了悠久的歲月。",
  str_item_intro_3400140 = "獲得後可解鎖背景圖-戲水一刻。\n島嶼沉默埋藏舊日時光，新的夏日冒險揚帆起航。\n攜手並肩的同伴，就是最珍貴的寶藏。\n在有限的時間裡，和同伴一起享受無盡的冒險吧！",
  str_item_intro_3400141 = "獲得後可解鎖背景圖-跨越千年的思念",
  str_item_intro_3400142 = "獲得後可解鎖背景圖-終將重逢。\n當星辰抵達歸宿。\n他邁步，走向陽光下的夥伴們。",
  str_item_intro_3410101 = "藍色的初級訂購箱，開啟後可任選1個水屬性初級覺醒材料。",
  str_item_intro_3410102 = "藍色的中級訂購箱，開啟後可任選1個水屬性中級覺醒材料。",
  str_item_intro_3410103 = "藍色的高級訂購箱，開啟後可任選1個水屬性高級覺醒材料。",
  str_item_intro_3410104 = "藍色的特級訂購箱，開啟後可任選1個水屬性特級覺醒材料。",
  str_item_intro_3410201 = "紅色的初級訂購箱，開啟後可任選1個火屬性初級覺醒材料。",
  str_item_intro_3410202 = "紅色的中級訂購箱，開啟後可任選1個火屬性中級覺醒材料。",
  str_item_intro_3410203 = "紅色的高級訂購箱，開啟後可任選1個火屬性高級覺醒材料。",
  str_item_intro_3410204 = "紅色的特級訂購箱，開啟後可任選1個火屬性特級覺醒材料。",
  str_item_intro_3410301 = "綠色的初級訂購箱，開啟後可任選1個森屬性初級覺醒材料。",
  str_item_intro_3410302 = "綠色的中級訂購箱，開啟後可任選1個森屬性中級覺醒材料。",
  str_item_intro_3410303 = "綠色的高級訂購箱，開啟後可任選1個森屬性高級覺醒材料。",
  str_item_intro_3410304 = "綠色的特級訂購箱，開啟後可任選1個森屬性特級覺醒材料。",
  str_item_intro_3410401 = "黃色的初級訂購箱，開啟後可任選1個雷屬性初級覺醒材料。",
  str_item_intro_3410402 = "黃色的中級訂購箱，開啟後可任選1個雷屬性中級覺醒材料。",
  str_item_intro_3410403 = "黃色的高級訂購箱，開啟後可任選1個雷屬性高級覺醒材料。",
  str_item_intro_3410404 = "黃色的特級訂購箱，開啟後可任選1個雷屬性特級覺醒材料。",
  str_item_intro_3410501 = "光靈聯軍生產的訂購箱，開啟後可任選1個初級勢力覺醒材料。",
  str_item_intro_3410502 = "光靈聯軍生產的訂購箱，開啟後可任選1個中級勢力覺醒材料。",
  str_item_intro_3410503 = "光靈聯軍生產的訂購箱，開啟後可任選1個高級勢力覺醒材料。",
  str_item_intro_3410504 = "光靈聯軍生產的訂購箱，開啟後可任選1個特級勢力覺醒材料。",
  str_item_intro_3410601 = "影鎮商會生產的瑩玉訂購箱，開啟後可任選1枚一階瑩玉。",
  str_item_intro_3410602 = "影鎮商會生產的瑩玉訂購箱，開啟後可任選1枚二階瑩玉。",
  str_item_intro_3410603 = "影鎮商會生產的瑩玉訂購箱，開啟後可任選1枚三階瑩玉。",
  str_item_intro_3410604 = "光靈聯軍之前使用過的禮包，打開後可任選1件高級勢力禮物。",
  str_item_intro_3410605 = "你在荒典中留下了屬於自己的功績，也獲得了屬於自己的獎勵。\n打開後隨機獲得各種養成材料，還有低機率獲得召集星標哦！",
  str_item_intro_3410606 = "獲得這個寶箱，就證明你已經和[寂靜獵兵]的成員有了極深的羈絆。打開後將獲得豐富獎勵。",
  str_item_intro_3410607 = "裝有特殊結構體的寶箱，打開後可獲得1個攜行者。",
  str_item_intro_3410608 = "在一片混亂的狂歡活動中獲得的箱子，雖然不清楚裡面是什麼，但這份驚喜才是最有意思的。",
  str_item_intro_3410609 = "特別訂購的禮包，打開後可以任選一件高級禮物。",
  str_item_intro_3410610 = "高級訂購合成箱，打開後可任意選擇1個高級覺醒材料。",
  str_item_intro_3410611 = "特級訂購合成箱，打開後可任意選擇1個特級覺醒材料。",
  str_item_intro_3410612 = "可以從心珀晶簇·雷，心珀晶簇·水，心珀晶簇·森，心珀晶簇·火中自選一個。",
  str_item_intro_3410613 = "低級訂購合成箱，打開後可任意選擇1個初級覺醒材料。",
  str_item_intro_3410614 = "中級訂購合成箱，打開後可任意選擇1個中級覺醒材料。",
  str_item_intro_3410615 = "可獲得助力光靈覺醒3階段的材料，包括：二階瑩玉·共通 *300，白夜幣 *750,000，聯軍低級訂購箱 *10，聯軍中級訂購箱 *10，聯軍高級訂購箱 *10，低級訂購合成箱 *30，中級訂購合成箱 *50，高級訂購合成箱 *50，特級訂購合成箱 *20。",
  str_item_intro_3410616 = "辛苦的巡邏、危險的驅逐，這些行動不會毫無收穫，快打開看看裡頭有哪些戰利品吧！",
