  str_item_intro_3420132 = "從指定5星光靈名單中選擇一位與你並肩作戰，人選包含：<color=#ffffff>貝爾塔/卡斯特/琪爾/早苗/羅伊/柏乃/艾莉法/烈雀/薇薇安/蜜雅/涅墨西斯/蕾吉娜/知更/浮士德/克萊肯/巴頓/基汀/露易絲/諾爾/修拉德/舒瓦茲/瑪姬/伊斯塔萬/芭芭拉/莉奧娜/契法/歐緹/菲莉詩/渡/紅與黑/庫絲庫塔/艾蕾雅/希卡蕾/貝芙麗/瀧/吉納維芙/納努塞爾/柯蒂/凱雅/克莉絲汀/白蘭·浣心/喬瑟琳</color>。",
