  str_item_intro_3420130 = "從指定6星光靈名單中選擇一位與你並肩作戰，人選包含：<color=#ffffff>維多利亞/拉斐爾/克娜莉/烏列爾/貢露/卡戎/卡蓮/醒山/希羅娜/加百列/娜席里絲/伊芙/約娜/米迦勒/雷霆/伊倫汀/沙利葉/艾希/彌加德/緋/拜里厄/弗勞爾/斯莫奇/雷文頓/克/普律瑪/貝菲爾/路克/海蒂/諾維亞/希諾普/芙洛琳/露比/凜音/雨森/瑤/青瞳/蓮/賈爾斯/巴頓·芒刃/妮娜/卡蓮·煜魂/菲雅/傑諾/珀拉珂/莉莉卡/米洛斯/阿克希亞/維克</color>。\n注意：2週年特選召集箱有期限，過期將轉化為3,000光珀，經由郵件發放給您。請記得在期限內使用：（UTC0）2023年8月31日09:00，不同時區對應時間請導航員自行換算。",
  str_item_intro_3430101 = "開啟後，可從「渡」、「莉奧娜」、「蜜雅」、「艾蕾雅」中任選1位光靈獲得，以及將該光靈提升至覺醒1階段等級10的所有養成材料。",
  str_item_intro_3430102 = "打開後可從「巴頓」、「瑪姬」、「涅墨西斯」、「希卡蕾」中任選1位光靈獲得，以及將該光靈提升至覺醒1階段等級25的所有養成材料。",
  str_item_intro_3430103 = "打開後可從「修拉德」、「伊斯塔萬」、「薇薇安」、「露易絲」中任選1位光靈獲得，以及將該光靈提升至覺醒2階段等級1的所有養成材料。",
  str_item_intro_3440001 = "使用後可獲得美味黑巧克力、光珀和隨機光靈養成材料。",
  str_item_intro_3440002 = "使用後可以獲得玩鬧糖果、光珀和光靈隨機養成材料。",
  str_item_intro_3440003 = "在「蜃風號」上大家一起過「春朔節」時，由船長木月白給大家的紅包，裡面不知道有什麼驚喜哦！",
  str_item_intro_3440005 = "使用後可以獲得光珀和光靈隨機養成材料。",
  str_item_intro_3500001 = "在遠古遺跡發現的神祕物質，擁有奇妙的力量，是改造裝備的必需材料。",
  str_item_intro_3500003 = "使用後可使光靈提升至覺醒2階段等級1。\n神祕的遠古遺物，其中蘊含著宛如太陽般璀璨光芒的神祕物質，能夠最大限度提升光靈的能力。",
  str_item_intro_3511001 = "用於提升水屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的瞬間片段。",
