  str_item_intro_3513002 = "用於提升森屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的零散片段。",
  str_item_intro_3513003 = "用於提升森屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的某些片段。",
  str_item_intro_3513004 = "用於提升森屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的重點片段。",
  str_item_intro_3513005 = "用於提升森屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的關鍵片段。",
  str_item_intro_3514001 = "用於提升雷屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的瞬間片段。",
  str_item_intro_3514002 = "用於提升雷屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的零散片段。",
  str_item_intro_3514003 = "用於提升雷屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的某些片段。",
  str_item_intro_3514004 = "用於提升雷屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的重點片段。",
  str_item_intro_3514005 = "用於提升雷屬性啟迪等級。\n啟迪者提供的神祕立方體，可無痕嵌入石板使其得到啟動，具現出啟蒙訓練中的關鍵片段。",
  str_item_intro_3621001 = "附有坐墊的高背椅，可以讓背有地方靠，也許還能把頭躺在高背上打個盹。",
  str_item_intro_3621002 = "適合一個人坐的小沙發，由於沒有靠背，總覺得前面應該再放張矮桌……",
  str_item_intro_3621003 = "能夠讓兩人同時坐下的寬大沙發，當然一個人躺上去也沒問題……",
  str_item_intro_3621004 = "少見的長沙發，能讓四人一起坐下，很適合在聚會時使用。",
  str_item_intro_3621005 = "六邊形矮桌，通常用來放飲料、茶壺、水杯、零食，很適合擺放在開小型派對的房間。",
  str_item_intro_3621006 = "長形矮桌，與雙人沙發、四人沙發很搭，很適合擺放在開大型派對的房間。",
  str_item_intro_3621007 = "能夠自動做飲料的機器，當然做出什麼飲料就根據裝填的原料而定；比如放入咖啡粉就能做出黑咖啡，放入方糖就只會流出普通的糖水……",
  str_item_intro_3621008 = "據說是由早期部落的打擊樂器演變而來，起先流行於影鎮。通常由一面大鼓、幾面中型鼓與鈸組成，有時會依演奏需要，增設其他的打擊樂器。但無論組成樂器多少，都是由一人演奏。",
  str_item_intro_3621009 = "種植在小盆中的低矮植物，可以為房間帶來一絲綠意，還能淨化空氣。",
  str_item_intro_3621010 = "幾乎有一人高的大盆栽，不僅能淨化空氣，也能當做裝飾，為房間加入一絲自然氣息，必要時還能用來藏身……",
  str_item_intro_3622001 = "精美細緻的風景畫，掛在牆上的話，人們不必出門也能看到各地的美景。",
  str_item_intro_3623001 = "能夠完全貼在天花板的燈具，由於形似太陽，且照明範圍廣、幾乎沒有死角，因此很多人稱為「太陽燈」。",
  str_item_intro_3623002 = "以鐵架垂吊，裝在室內的照明燈，輕巧、安裝方便，還可以附加各種裝飾，因此廣受歡迎。",
  str_item_intro_3623003 = "能夠為房間帶來陣陣涼風的裝置。據說起初是啟光聯邦為了讓地下城通風所使用的設備，隨後人們發現了它的新作用——讓房間變得舒適涼爽。",
  str_item_intro_3623004 = "裝在天花板的燈管，耗能低，照明廣，而且省空間，因此許多城邦紛紛採用。",
  str_item_intro_3623005 = "垂吊在天花板上的照明燈。由於是絞鎖結構，因此調整起來十分方便。但是若遇到地震或大風天氣，吊燈就會來回搖晃，十分危險。因此這種吊燈被禁止在船隻上使用。",
  str_item_intro_3631001 = "舶來品，是征服了大洋的船隊從遠東帶回的奢侈陳設。質感細膩、配色典雅，然而易碎，一定要輕拿輕放。",
  str_item_intro_3631002 = "太陽形狀的聖像，莊嚴肅穆，即使只是默默佇立在房間角落，也能讓人感覺到強烈的信仰之力。",
  str_item_intro_3631003 = "著名工匠製作的大桶，造型華麗，裡面必須存放陳年佳釀，才配得上如此豪華的裝飾。",
  str_item_intro_3631004 = "據說這種家具起源於遠東，由於具備擋風、遮隱的用途，還能點綴、美化房間，並強調主人的神祕感，因此很快就在艾斯特拉大陸諸城邦流行起來。",
  str_item_intro_3631005 = "鍍金的巨大占星儀，上面鑲嵌了各種寶石來代表星辰的位置。熟悉占星術的學者能夠很快進行占卜，不過準確度就……",
  str_item_intro_3632001 = "啟光聯邦的產物，原用於地下城之間的通訊，隨著交流漸增，其他城邦也開始用起這種先進的溝通方式。",
  str_item_intro_3632002 = "白夜城舉行慶典時常擺放的鍍金杯，裝飾華麗，製作者甚至附了某些特殊的光能術，可以產生一對翅膀的動態幻象。",
  str_item_intro_3632003 = "這面浮雕板代表了白夜城擁有的古老文明，每個圖案背後都擁有豐富的典故。每次看到它，都能讓人想起那些久遠的歷史……",
  str_item_intro_3632004 = "這架燭台由特殊的光能術強化過，永遠不會被煙熏黑，而且上面的蠟燭還能自行點亮和熄滅。",
  str_item_intro_3632005 = "白夜城工匠的精巧構思，加上啟光聯邦的機械技術，造就了這架外形華麗的掛鐘。對它來說，時間顯示是次要功能，裝飾才是主要目的。",
  str_item_intro_3641101 = "白夜城貴族的傳統陳設，尚武的家族會擺放一副全身鎧甲作為裝飾。這不僅是陳設，也是一種象徵，更是在提醒家族的後人——不能放棄尚武精神，變成紈絝子弟。",
  str_item_intro_3641201 = "影鎮中附庸風雅之人喜歡的陳設，多用名貴木材製成，上面擺放著經典書籍、名貴器皿等。不過，這些古董的真偽令人存疑……",
  str_item_intro_3641301 = "啟光聯邦的產物，用於擺放步槍的支架，放在房間能令人彷彿置身戰場。不愧是對抗暗鬼的主要勢力，連家具都充滿了戰爭氣息。相對於之前的兩款設計，三式步槍架的重心更平衡，且整體重量減輕了不少。",
  str_item_intro_3641501 = "微縮汽車模型，佈滿了管子、鉚釘與各種焊接金屬板，甚至還有木頭，拼湊感極強。一看便知，原型正是紅油扳手的產物——「風壓」敞篷車。",
  str_item_intro_3641102 = "華貴的布料，精細的紡織工藝，這是出自白夜城能工巧匠之手的地毯，並不是尋常人家消費得起的……除了在金錢方面頗具價值，它還是身分的象徵。",
  str_item_intro_3641202 = "產自影鎮的寬大黑色地毯，織目細密，柔軟厚實，踩上去幾乎不會發出任何聲音。",
  str_item_intro_3641302 = "頗為方正的地毯，經緯線也很整齊，帶有強烈的啟光聯邦的工業風格，一看就是迦南城工廠的製品，經久耐用。",
  str_item_intro_3641402 = "這席地毯十分厚重，用大量產自北境的棉料編織而成，還加入大量的動物毛，在最冷的環境也能隔絕地面傳來的寒氣。",
  str_item_intro_3641502 = "應該是紅油扳手那些粗線條的傢伙們用舊衣物胡亂縫合而成的吧……似乎還能聞到輕微的紅油味，看來是用這種東西染了色。真的有人會花大價錢把它買來放在家裡嗎？",
  str_item_intro_3641602 = "十分引人注目的紅色地毯，讓人幾乎忽略了上面的圖案。仔細一看，地毯的針織紋路似乎在微微抖動，抖得你心裡發寒。真的有人會喜歡這種地毯嗎……",
  str_item_intro_3642102 = "家具，可設置於巨像的房間。\n白夜城某位不知名畫家的鉅作，真品掌握在某位大貴族手中，這是複製品。其傑出的畫作技巧，讓觀賞者看了之後感到莫名心安，因此也有很多臨摹品，這便是其中之一。即便如此它也要價不菲，購買者趨之若鶩。",
  str_item_intro_3642201 = "影鎮中各種地下勢力間往往有著各種明爭暗鬥，而當糾紛無法調和時，就需要動用這一對細劍。糾紛的雙方會各派出一名劍客，以這兩把細劍，用單挑的方式進行最終裁決。",
  str_item_intro_3642301 = "啟光聯邦的裝飾都充滿了軍事風格——當他們覺得牆上應該擺些什麼時，第一個想到的就是這把步槍。看來啟光的成員，果然時時刻刻都做好了上戰場的準備。",
  str_item_intro_3642401 = "家具，可設置於巨像的房間。\n即便在冰天雪地的北境，這種植物仍四季常青。因此北境居民都認為它象徵希望與豐饒，很多人都說「沒有槲寄生就沒有幸福」。因此北境居民會採集槲寄生，編結成環掛在家中，希望能為自己帶來好運。",
  str_item_intro_3641103 = "家具，可設置於巨像的房間。\n在白夜城，它代表了那些王公貴族們握有的權力。裝飾華美，通體以貴金屬製成，既彰顯了權力的誘惑，也象徵著權力帶來的沉重。",
  str_item_intro_3641503 = "由各種廢舊鋼條、鐵皮和鉚釘拼接而成，上面放著不知道從哪裡弄來的墊子。雖然破舊，坐起來還算舒服，而且意外地堅固。",
  str_item_intro_3651001 = "尖碑的微縮模型，質感強烈，還原度也相當高，彷彿帶來了尖碑內所封印的力量。",
  str_item_intro_3651002 = "看起來就像是將尖碑縮小後擺放在這裡一般，極為逼真，靠近後還能感受到尖碑中的遠古神祕力量。",
  str_item_intro_3651003 = "只有探索到尖碑高層的探索者才能獲得的裝飾品。它不僅外形逼真，還封存著一部分尖碑的力量。人們看到它，就彷佛站在真正的尖碑前一般。",
  str_item_intro_3651004 = "這是只有那些探索尖碑的人們才能獲得的極稀有紀念品。雖然是模型，但是其外型卻與尖碑別無二致，仔細觀察還能發現許多還原了尖碑結構的細節。有傳言說透過它可以影響真正的尖碑……",
  str_item_intro_3651005 = "據說是尖碑主動「贈送」的紀念品，要非常深入探索尖碑才能獲得。可以說它代表了一部分尖碑的意志與對探索者的認可。",
  str_item_intro_3651101 = "在祕境裡發現的暗鬼微縮模型，應該是其他探索者留下來的紀念品。由於不會動，也沒有暗鬼身上的可怕氣息，因此毫無威嚇感。只要習慣它的存在，甚至會覺得有點可愛……",
  str_item_intro_3651102 = "祕境深處發現的模型，看起來應該是某個高級暗鬼的雕像。由於其面目猙獰，所以即便不會動，還是多少令人感覺到一絲恐懼。不過如果習慣了它的存在，反而能靠它嚇退那些偷偷摸進房間的宵小之輩……",
  str_item_intro_3651201 = "相當稀有的微縮模型，長得跟「臨空者號」一模一樣。是由導航員的夥伴集齊自己的光能術，再運用「臨空者號」的某些神祕技術製成，代表他們與導航員以及「臨空者號」的牢牢羈絆。",
  str_item_intro_3662001 = "脫離暗鬼追擊後，為了紀念大家的初次相遇，臨空者號特地讓螢盞根據自己記錄的影像繪製了這幅掛畫。由於極為逼真地還原了當時的場景，幾乎所有人看到都認為這是照片。",
  str_item_intro_3661101 = "從赤眼谷找到的岩石，現在還帶有些許的火山之力，摸起來很燙。它偶爾會發出輕微的「轟隆」聲，抑或是小小地「噴發」一下，不過總體來說是無害的。膽子大的人說不定能用它來煮飯或烤肉。",
  str_item_intro_3661102 = "多恩在赤眼谷中栽種的白色花朵，每隔數年才開花一次。花朵異常美麗，其花語為「破曉的希望」。",
  str_item_intro_3662101 = "由於體內的惡疾，伊芙一度只能喝十五度左右的冷水或四十五度左右的熱水。而在紅油沙漠這般缺水的條件下，為了讓妹妹隨時能喝到水，醒山時時刻刻都會帶著這兩個保溫瓶。瓶子上面還畫著笑臉圖案，用來哄妹妹開心。",
  str_item_intro_3661103 = "雖然道館已不復存在，但是這副榮角道館的刀架卻仍舊保存良好。拂去灰塵，擺上刀具後，依稀能重現榮角道館往日的輝煌。",
  str_item_intro_3661104 = "只有雲山一帶才能見到的稀有櫻花樹，色彩絢爛。人們喜歡在上面懸掛各種祈福短籤，祈禱自己的願望能夠早日實現。",
  str_item_intro_3662102 = "帶有異國色彩的繪畫。上面繪製的巨龍張牙舞爪，卻不會令人感到畏懼，反而給人一種莫名的安全感。這或許與遠東獨特的文化有關吧。",
  str_item_intro_3661105 = "雲山地區流行的一種玩偶。放在家中能帶來好運，興許還能為主人實現某些願望。",
  str_item_intro_3661106 = "看起來有點凶惡的福蛋。擺在家裡能祛除厄運，還能防止惡人上門喔～",
  str_item_intro_3661107 = "偶爾會發出金光的福蛋，看見它似乎就能看到即將滾滾而來的財富～希望如此。",
  str_item_intro_3661108 = "代表學識的福蛋。據說它可以保佑考試順利，因此很多學子都會求上一枚。如果把它帶到迦南城，會很搶手吧",
  str_item_intro_3661109 = "據說，每個人都會碰到一枚最適合自己的福蛋，它會實現你許下的美好願望，還能保佑你一生平安。",
  str_item_intro_3661110 = "家具，可設置於巨像的房間。\n海邊那座造型誇張的城堡的模型，還原了神祕、詭異的感覺，偶爾還會隱約傳出叫聲，不禁令人聯想到這裡面的某些遠古傳說。",
  str_item_intro_3661111 = "家具，可設置於巨像的房間。\n參考臨空者號的技術後，弗勞爾製作了機甲「紅油動力激鋼ν零號機」，這是它的模型。相較真正的機甲，性能大幅提升，可說是一件完美的機甲。喔，除了它很小以外。",
  str_item_intro_3661112 = "家具，可設置於巨像的房間。\n為了賺外快而製作的推車，利用特別的設備製作冰塊，再打成刨冰販售，在炎炎夏日中為人們提供一份消暑的新選擇。雖然結束營業了，但推車上的器材都還能用，偶爾還會自己啟動一下，似乎想表示自己「還沒退役」。",
  str_item_intro_3661113 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的充氣沙發，背後裝有水槍，可以定時噴射水流，為人們在炎炎夏日帶來清涼感受。",
  str_item_intro_3661114 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的充氣沙發，靠墊後面的噴射裝置可以定時產生噴泉。雖然更加清涼，不過由於噴泉力度太大，偶爾會嚇到坐在上面的人。",
  str_item_intro_3661115 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的充氣沙發，請小心攜帶，因為背後附設自動煙火發射器。一旦啟動就會射出各色煙火，讓大家欣賞一場小小的煙火表演。由於發射角度有特別設計過，煙火不會傷到坐在上面的人，但可能會嚇他們一跳。",
  str_item_intro_3661116 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的充氣沙發，兩側的扶手其實是泡泡機。啟動後就會有色彩絢爛的泡泡四處飛舞，頗受孩子們喜愛。",
  str_item_intro_3661117 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的水冷沙發，攜帶方便。展開後可以插上椰子樹配件作為裝飾，加滿水後坐進去，就能有來到海邊的感覺。",
  str_item_intro_3661118 = "家具，可設置於巨像的房間。\n「白金夏潮」飯店出品的衝浪板，以特殊材質製成。輕便、堅固、耐用，造型流線順眼，相當適合喜愛駕馭海浪的健兒。",
  str_item_intro_3662103 = "家具，可設置於巨像的房間。\n眾人前往「潮汐祭」的留念，看著畫冊中的碧海藍天、沙灘綠樹，就彷佛讓大家又回到了海邊，重溫那一段快樂的日子。",
  str_item_intro_3661119 = "家具，可設置於巨像的房間。\n24號地下城是位於熱砂防線上的重要基地之一，幾乎承擔整座熱砂防線的後勤、新兵訓練、醫療等功能。這座模型完美呈現了上述特點。",
  str_item_intro_3661120 = "家具，可設置於巨像的房間。\n啟光聯邦軍校內部使用的沙盤，由專門的測量人員實地測繪後，再等比例縮小。以泥沙、木料和小模型組成的地圖，足以模擬戰場環境，讓學員進行作戰指揮演練。",
  str_item_intro_3661121 = "家具，可設置於巨像的房間。\n這面勳章牆的主體，是一面烙著許多彈痕的鐵板，據說是當年「勇士別動隊」抵抗暗鬼留下的證明，也是他們的驕傲。掛在上面的勳章則象徵「勇士別動隊」從未離去，而是一直矗立在熱砂防線上，與其他戰士一同抵禦暗鬼。",
  str_item_intro_3662104 = "家具，可設置於巨像的房間。\n為了表揚熱砂防線的守軍成功阻止暗鬼大規模入侵，啟光聯邦內部特別頒發了這面軍旗。每當駐紮防線的守軍看到這面旗，榮譽感會讓他們銘記著信條——人在，防線就在。",
  str_item_intro_3661122 = "請放心，這裡沒有埋葬任何死者，所以就不能稱之為「墓碑」。什麼？你問那隻手？啊，沒事啦～只是特別演出而已～",
  str_item_intro_3661123 = "不給白夜幣就出現！好吧，其實牠不會說話，也不是真的幽靈，其實就是一隻披著床單的雞而已～",
  str_item_intro_3662105 = "其實是用木板拼接而成的燈，造型是南瓜狀而已。燈光會從上面的「眼睛」、「鼻子」、「嘴巴」亮出來，頗有一種怪異的感覺。",
  str_item_intro_3661124 = "巍峨的白塔是空之山谷的象徵，那是一座筆直的山峰，通體潔白。這座精巧的模型完美還原了白塔的樣貌，栩栩如生。",
  str_item_intro_3661125 = "一名空裔少年的公仔，擺在地上滿可愛的，而且似乎很受螢盞喜愛。",
  str_item_intro_3661126 = "種有蒲公英的盆栽。雖然花朵看起來非常纖細，但是這種頑強的植物，只要有水和泥土就能生存。",
  str_item_intro_3661127 = "家具，可設置於巨像的房間。\n這是模型嗎？簡直是迷你世界！不僅有能夠移動的火車，還有山川、植被等自然景觀。即使只是看著火車模型盤山而上，也彷彿自己身歷其境，欣賞美景。",
  str_item_intro_3661128 = "家具，可設置於巨像的房間。\n居然將秋天的樹也搬到巨像裡……不知道是什麼原理，這個盆景還保留了季節的顏色。偶爾有枯黃的樹葉落下，讓人隨時隨地有一絲秋天的惆悵感，只不過就麻煩清潔人員了。",
  str_item_intro_3661129 = "家具，可設置於巨像的房間。\n永遠向著陽光的花朵！看著就能讓人積極向上的盆栽。放在房間裡，整個屋子都溫暖許多。",
  str_item_intro_3661130 = "家具，可設置於巨像的房間。\n代表榮譽的金腰帶，這是在影鎮的「地下格鬥賽」中揮灑汗水、承受傷痛的證明，可不能讓人隨便觸碰，只能遠觀。",
  str_item_intro_3661131 = "家具，可設置於巨像的房間。\n一樁合理的交易對雙方都應該是公平的。作為秤量貨物的基準，這架鍍金天平代表了雙方都認可的公正。因此影鎮商會往往會陳設它，擺放在大廳內，示意來賓——該商會的交易都公正無欺。",
  str_item_intro_3662106 = "家具，可設置於巨像的房間。\n舶來品。扇面是用輕柔而堅韌的紙張製成，上面的繪畫有著別緻的藝術風格，頗具異國情調。",
  str_item_intro_3662107 = "家具，可設置於巨像的房間。\n白夜城工匠用彩色玻璃巧奪天空地拼接而成的畫。當光線照在上面，會反射出豐富亮麗的色彩，甚至有絢爛奪目的效果。",
  str_item_intro_3661132 = "家具，可設置於巨像的房間。\n據說是曾在北境上方巡視過的冰龍，不過現在的「牠」完全沒有威脅～畢竟只是一尊雕像而已，放在家中可以帶來冷氣，真不錯。",
  str_item_intro_3661133 = "家具，可設置於巨像的房間。\n衣架和斗篷都很簡單，不過根據某些北境年長居民所說，背後有一個離奇的故事呢～",
  str_item_intro_3661134 = "家具，可設置於巨像的房間。\n在某些北境居民的傳說中，穿上它就能獲得真愛，無論男女喔～",
  str_item_intro_3661135 = "家具，可設置於巨像的房間。\n北境最常見的房屋模型。屋頂的皚皚積雪、偶爾從煙囪裡冒出的白煙都栩栩如生。從窗戶中投射出的搖曳燈光，彷彿真的有小人在裡面生活一樣。",
  str_item_intro_3662109 = "家具，可設置於巨像的房間。\n看起來是一顆馴鹿的頭，但別害怕，這不是標本喔。其實，這是北境居民用毛皮和樹木製作的裝飾品，裡面有特別的裝置，眼睛還能動喔～",
  str_item_intro_3661136 = "家具，可設置於巨像的房間。\n如果想透過料理展現愛意，沒有什麼比用自己身體的一部分當材料更適合了。朵露對自己的尾巴肉很有信心，油花的分布和風味遠勝普通食材。朵露對炭烤火候的掌握也早已爐火純青，非常美味。但是要小心，因為裡面有毒。",
  str_item_intro_3661137 = "家具，可設置於巨像的房間。\n朵露一時興起製作的木雕。對龍來說，人們口中的「藝術」往往難以理解，因為無論是題材還是製作工藝都太簡單。朵露仿照別人的作品製作了這個木雕，她不瞭解涵義，但能受到喜愛就夠了。",
  str_item_intro_3662110 = "家具，可設置於巨像的房間。\n既然出來玩，一定要拍照做紀念吧！大家站近一點，五隻龍要塞進鏡頭真不容易……來，三、二、一——起司！",
  str_item_intro_3661138 = "家具，可設置於巨像的房間。\n在失落之都發現的鋼琴，樣式類似艾斯特拉大陸的某些鋼琴，但材質特殊，過了這麼多年仍能發出漂亮的音色。即便因碰撞導致某些音準跑掉，也能利用獨特的內部構造來調音。是音樂家們不可多得的寶物。",
  str_item_intro_3661139 = "家具，可設置於巨像的房間。\n樣式十分簡約，但不同於啟光追求的「質樸」風格，有著獨特的光滑材質與美觀的設計。即便是白夜城的人也會喜歡吧。",
  str_item_intro_3661140 = "家具，可設置於巨像的房間。\n在失落之都發現的地毯，不僅材質極為特殊，其交叉線條構成的菱形圖案更引人注目。看來失落之都過去居民的審美觀也有些與眾不同。",
  str_item_intro_3661141 = "家具，可設置於巨像的房間。\n它在失落之都的街頭上比比皆是，簡直比路燈還多，有時候感覺甚至能用來當路標了……它的螢幕上都是亂七八糟的圖案，閃爍不停，時亮時滅，也不知道裡面有什麼東西。看來只有砸開才能知道了。",
  str_item_intro_3661142 = "家具，可設置於巨像的房間。\n在失落之都找到的郵筒，由於上面的字跡已模糊不清，一開始還被誤認為是存放應急口糧的小型儲物箱。直到發現裡面的信件，人們才明白它原來是個郵筒。只不過現在應該沒人投入信件了吧。",
  str_item_intro_3661143 = "家具，可設置於巨像的房間。\n失落之都中常見的長凳，一般設在路邊，應該是供過路人休息使用。嗯，搬回家中自然也可以用來坐，還能讓人躺著休息呢～",
  str_item_intro_3661144 = "家具，可設置於巨像的房間。\n過了這麼多年居然沒壞！失落之都的技術果然奇妙。只要放入紙張，就會將其切成細碎的紙屑，使人無法辨識上面的資料。嗯，保密意識很強呢。",
  str_item_intro_3661145 = "家具，可設置於巨像的房間。\n即便經歷了這麼多歲月，它依然保持完好……但是已經沒人使用了。打掃後還可以看到乾淨整潔的桌面，以及各種辦公用品，讓人對工作充滿活力呢。",
  str_item_intro_3661146 = "家具，可設置於巨像的房間。\n這把奇妙的椅子不僅能自由轉動方向、調節座椅高低，甚至還能把椅背放下來，讓使用者半躺在上面舒適地小憩。從色調上來看，如果和辦公桌放在一起，就會產生一種奇妙的和諧感，讓人流連工作，忘卻時間。",
  str_item_intro_3661147 = "家具，可設置於巨像的房間。\n來自遠東地區的擺飾，用竹子製成，需要用流水驅動，巧妙的機關讓它可以定時地發出竹子碰撞的「咔噠」聲，清脆悅耳，而且還能計時～",
  str_item_intro_3661148 = "家具，可設置於巨像的房間。\n種植著巨大竹子的盆栽，長得很快，因此需要經常修剪。雖然有點麻煩，但是好處是可以得到很多竹節，而且竹葉被風吹動時的「沙沙」聲，聽起來也別有一番風味～",
  str_item_intro_3663001 = "家具，可設置於巨像的房間。\n掛在門廊下的娃娃，雖然製作起來很簡單，但是真的很可愛，微風經過後它們還會隨之起舞，彷彿在祈求不要下雨～如果真的靈驗了，那就是上天看到它們的舞蹈了！",
  str_item_intro_3661149 = "家具，可設置於巨像的房間。\n遠東地區的武士們佩戴的頭盔，上面的裝飾物十分誇張，據說它不僅代表了這名武士所屬的勢力或家族，更重要的是它能夠作為榮譽的象徵。",
  str_item_intro_3661150 = "家具，可設置於巨像的房間。\n原本是作戰時士兵或武士們插在後背上的旗幟，用於指引後方軍隊。若將之擺放在家中，會給人一種嚴肅的感覺。",
  str_item_intro_3662111 = "家具，可設置於巨像的房間。\n遠東地區的人們喜歡的一種字帖，通常由書法大家寫成，當然大部分都是臨摹的。無論如何，這些字在遠東地區的人們眼中都有著特別的美感，不是那個地區的人，基本上是沒有辦法欣賞其韻味的。",
  str_item_intro_3661151 = "家具，可設置於巨像的房間。\n雖然叫做「山水」，但是前面的「枯」字表示了這種微縮景觀其實沒有水，而是用細沙代表水，用石塊代表假山。在遠東地區，人們認為這種靜止不變的景觀有助於冥想，會給人帶來心靜的效果。",
  str_item_intro_3661152 = "家具，可設置於巨像的房間。\n在雲島上隨處可見的路燈，有著遠東地區風格的裝飾。此地的居民不僅利用它們來照明，還會將之當作路標。",
  str_item_intro_3663002 = "家具，可設置於巨像的房間。\n江富城中的人們喜歡使用的燈籠，平時掛在門上用於照明，家家戶戶的燈籠將街道照得亮如白晝。人們也可以將它卸下來，用竹竿挑起用於照亮夜路。",
  str_item_intro_3661159 = "家具，可設置於巨像的房間。\n卡蓮受封成為騎士時曾獲贈一柄長槍，隨後它與卡蓮出生入死，成為了她的專屬武器。這件只是複製品，雖然不是真的，但將其擺放在家中，也能感受到「月之繭」的威力……",
  str_item_intro_3662116 = "家具，可設置於巨像的房間。\n「著名」製作人巡迴犬十分中意的裝飾，據說只要將這場記板掛在家中，他就能經常聽到板子敲打而發出的脆響，這表示開工的聲音能讓他能產生無窮的動力。見到他如此勤奮，旁人也不由得受到感染，一起努力吧。",
  str_item_intro_3661153 = "家具，可設置於巨像的房間。\n為拉力賽加油打氣的啦啦隊員經常使用這種花球，並配合各種舞蹈來鼓勵參賽者。不過，這對花球被某人進行了改造，加上了奇怪的設備後，能夠自己進行加油、鼓勁。起初可能會覺得奇怪，但習慣之後還是很有意思的。",
  str_item_intro_3661154 = "家具，可設置於巨像的房間。\n原本是用於賽車上的輪胎，長期使用以致破損後當廢物利用，疊在一起被改造成了座椅。雖然看起來很粗糙，然而坐上去很軟很舒適。",
  str_item_intro_3662112 = "家具，可設置於巨像的房間。\n據說是擺放在「熾焰拉力賽」終點盡頭的旗幟，參賽者大多會把它帶回去掛在家中作為裝飾，或者插在自己的車上以做紀念。",
  str_item_intro_3661155 = "家具，可設置於巨像的房間。\n紅油扳手舉辦的拉力賽，幾乎所有的成員都會參加，而且還吸引了很多不同勢力的人前來觀看甚至一顯身手。該獎盃就是在拉力賽中表現優異者的證明。",
  str_item_intro_3661156 = "家具，可設置於巨像的房間。\n幾乎只生長在沙漠中的植物，十分耐寒，據說沒水也能活，所以這種盆栽特別好養活，但要小心它的刺！而且注意不要經常澆水！",
  str_item_intro_3662113 = "家具，可設置於巨像的房間。\n雖然叫做「動力輪胎」，實際上只是普通的賽車輪胎而已，不過掛在牆上的話，多少會給人一種依舊身處拉力賽之中的感覺。",
  str_item_intro_3661157 = "家具，可設置於巨像的房間。\n據真理結社成員們說，該卷軸是在一處古代遺跡中找到的，雖然沒有文字，但是很多真理結社的成員都從中看到了特別的「啟示」......",
  str_item_intro_3642602 = "家具，可設置於巨像的房間。\n由某位不知名的真理結社成員所繪。該成員在宣稱自己曾看到過「世界的真實」後繪製了這幅畫，並很快神祕消失，且沒人相信那位成員的話。這幅畫作真的很詭異，卻又有一種吸引人的奇怪力量......",
  str_item_intro_3661158 = "家具，可設置於巨像的房間。\n「不可分割」、「完美」、「循環」、「真實」、「唯一」......很多真理結社成員都對這個圖案有不同的解讀，這些成員認為將七芒星放置於腳下，會讓他們更好地窺見「最終的真相」......",
  str_item_intro_3662115 = "家具，可設置於巨像的房間。\n沙漠！賽車！熾焰拉力賽誠邀最勇敢、最堅韌、最機敏的賽車手，用速度一決高下！盡情馳騁！開到世界盡頭吧！",
  str_item_intro_3661169 = "家具，可設置於巨像的房間。\n用神祕力量驅動的小型機械，只要稍微推它一下，就會轉個不停。據說如果不故意令它停止，它能轉到天荒地老～",
  str_item_intro_3661170 = "家具，可設置於巨像的房間。原\n來是放在空庭中的門，造型大方，也很適合擺在其他地方作為裝飾。",
  str_item_intro_3661162 = "家具，可設置於巨像的房間。\n能夠將魚骨如此完整地剔出，並擺放整齊的人，一定對魚十分瞭解，這魚骨豎件不僅是裝飾，也是對手藝的炫耀。",
  str_item_intro_3662117 = "家具，可設置於巨像的房間。\n從拓片就能想像到釣手的功力，擁有如此龐大身形的魚，掙扎時肯定造成了驚濤駭浪，想必釣手與之經過了一番搏鬥，才征服了它，因此才留下這份拓片以做紀念吧。",
  str_item_intro_3661163 = "家具，可設置於巨像的房間。\n直接用一根圓圓的木樁製作而成的椅子，表面粗糙不平，還能看到樹木的年輪，不過能為房間增添一些荒野的氣息，別有風味。",
  str_item_intro_3661164 = "家具，可設置於巨像的房間。\n據說是空裔們之前所用的地毯，上面繪有各種線條和圖形組成的紋樣。那些紋樣看得久了，有人說像是高塔的一部分，有的人則聯想到了天空，真是玄妙。",
  str_item_intro_3661165 = "家具，可設置於巨像的房間。\n在異世界被稱為「車」的交通工具的模型。\n對於心之怪盜團來說，這似乎是令人熟悉的設計。\n看著模型的MONA擺著一臉得意的表情，難道是錯覺嗎？",
  str_item_intro_3661166 = "家具，可設置於巨像的房間。\n以異世界某個地區的妖精為模型的毛絨玩具。\n能讓人聯想到雪人的形狀，所以很有吸引力。\n有時能聽到「hee-ho」的聲音，難道是錯覺嗎？",
  str_item_intro_3661167 = "家具，可設置於巨像的房間。\n從古代遺跡中發現的神祕裝置，據說能自動將食物炸熟，甚至還能調味！由於太過少見，據說甚至有不少人為了得到它，進行了一場「美食車之王」的比賽......",
  str_item_intro_3661168 = "家具，可設置於巨像的房間。\n放入油、脫殼穀物和調味料——通常是糖，啟動後脫殼穀物就會膨化，最終製作出這種奇妙的零食，可惜這裡的只是擺件，不能使用......",
  str_item_intro_3661160 = "家具，可設置於巨像的房間。\n幾乎是遊樂場中必不可少的項目之一，能夠讓孩子們體會到騎乘的快樂。當然，這裡的自旋木馬有點小......只能用於觀賞了。",
  str_item_intro_3661161 = "家具，可設置於巨像的房間。\n是蹺蹺板！蹺蹺板！不過它看起來太小了，恐怕只有小動物才能玩耍。在巨像上，它卻得到了螢盞們的歡迎，螢盞似乎覺得蹺蹺板能夠訓練動作的協調性，經常可以看到牠們在蹺蹺板上起伏。",
  str_item_intro_3661001 = "家具，可設置於巨像的房間。\n充飽氣後，這個游泳圈長得像一隻……很厲害的暗鬼？呃……反正它只是個游泳圈罷了，而且還是粉紅色的，看起來就沒那麼張牙舞爪，甚至還很可愛。",
  str_item_intro_3661002 = "家具，可設置於巨像的房間。\n本來是啟光聯邦製作外銷的自動風扇，自從某座小鎮的人們重新塗裝後，便相當富有夏日風情。據說採用新塗裝後，吹出來的風便清涼無比，不知是真是假～",
  str_item_intro_3661003 = "家具，可設置於巨像的房間。\n白夜城接駁港豎立的站牌，材料非常堅固、耐用，即使經過多年的日曬雨淋也不會鏽蝕。站牌配色簡約，造型大方，很適合作為紀念品帶回家中珍藏。",
  str_item_intro_3661004 = "家具，可設置於巨像的房間。\n此皇冠非彼皇冠，不代表實在的權力而是真實的魅力。這頂皇冠過去被用在影鎮舉辦的選美大賽上，做為贈與冠軍的獎勵。光彩奪目的珠寶映襯傾國傾城之容貌，讓影鎮居民留下深刻印象。",
  str_item_intro_3661005 = "家具，可設置於巨像的房間。\n從沙漠流傳出來的一種帽子，帽沿特別寬闊，據說是為了抵擋飛舞的沙塵而設計。沙漠附近的居民會戴著面具和這種斗篷帽，在節日上唱歌跳舞，替外來者提供特別的體驗。",
  str_item_intro_3661006 = "家具，可設置於巨像的房間。\n沙漠附近的部分居民喜歡用馬鈴薯製作一種名叫「薯袋」的食物。愛屋及烏下，他們也會縫製這種類似於「薯袋」造型的沙發，還會貼上可愛的表情，讓人特別想一屁股陷進去。",
  str_item_intro_3661007 = "家具，可設置於巨像的房間。\n能夠讓大家在巨像中也能看到格鬥賽的陳設，選手的投影還能進行「格鬥」，重現比賽過程。",
  str_item_intro_3661008 = "家具，可設置於巨像的房間。\n較大的楓葉盆景，單獨一盆就能點綴房間。當然，如果能組合擺放更好。",
  str_item_intro_3661009 = "家具，可設置於巨像的房間。\n種有小型楓樹的盆栽，建議將多個盆栽組合擺放，看起來更加美觀。",
  str_item_intro_3661010 = "家具，可設置於巨像的房間。\n某些小鎮居民認為這種鬼臉能夠嚇走敵人，帶來幸運。因此將它當作重要陳設，擺在家中顯眼位置，希望能造福全家。",
  str_item_intro_3661011 = "家具，可設置於巨像的房間。\n遠東地區流行的家具，近年來也逐漸在大陸上流行。在冬日裡，它能為人們帶來溫暖與安心。只要坐進去，能夠一整天動也不動，簡直是「暖桌的詛咒」。",
  str_item_intro_3661012 = "家具，可設置於巨像的房間。\n雲杉是北境最常見的樹，也是房屋與家具的材料，因此北境居民認為它象徵了「家庭」。新年時，北境居民會掛上各種裝飾，並將禮物放在樹下，然後一起拆開，歡度佳節。",
  str_item_intro_3661013 = "家具，可設置於巨像的房間。\n遠東地區的人們喜歡用這種裝飾品來慶賀節日，據說原本是一種食物，人們認為它代表著祈福之後，就用黏土、布料取代了。不過，看起來怎麼有點像塔塔呢～",
  str_item_intro_3661014 = "家具，可設置於巨像的房間。\n「在特別的日子裡，為心愛的對方做一顆心形蛋糕。」不知道是什麼時候興起的風潮，尤其風靡於年輕女孩間。畢竟這不僅好看，還很好吃，更重要的是那種甜蜜的心情～",
  str_item_intro_3661015 = "家具，可設置於巨像的房間。\n應該也是遠東地區流傳過來的一種掛飾，輕巧、方便，可以掛在屋簷或門窗下。風一吹過，就會發出清脆的「叮鈴鈴」聲音，令人心曠神怡～",
  str_item_intro_3661016 = "家具，可設置於巨像的房間。\n看起來就很可愛的熊，送給心儀的人一定很合適。而且，它不僅外表可愛，或許嘗起來也會意外的不錯。不過，你真的忍心吃掉它嗎～",
  str_item_intro_3661017 = "家具，可設置於巨像的房間。\n據說是根據古代國王身邊的「弄臣」為原型製作的玩具。看起來又蠢又萌，很適合在某些特別的日子里送給好友，帶來別樣的歡樂～",
  str_item_intro_3661018 = "家具，可設置於巨像的房間。\n紅油扳手成員喜歡佩戴的頭盔，不僅能在各種事故中提供保護，也可以在駕駛時抵禦撲面而來的風沙，而且色彩鮮豔的頭盔也讓他們更為顯眼、更加招搖。",
  str_item_intro_3661019 = "家具，可設置於巨像的房間。\n用各種特製薄片拼插而成的臨空者號，看起來是某些小孩子的傑作。在最大程度上模仿了臨空者號，只不過有些地方看起來還是帶著孩童的稚趣。",
  str_item_intro_3661020 = "家具，可設置於巨像的房間。\n為了慶祝共度一年時光，特別定製的巨大蛋糕塔，當它擺在眼前的時候，確實令人驚艷！因為真的是......好高！不僅如此，每層蛋糕都能微微旋轉，讓大家能看到它們的繽紛多彩的各種花邊。",
  str_item_intro_3661021 = "家具，可設置於巨像的房間。\n啊......已經一年了，那些過往的回憶，都可以在這上面找到。",
  str_item_intro_3662118 = "家具，可設置於巨像的房間。\n在異世界裡心之怪盜團寄給目標的「預告信」海報。在獨特設計中感受到了藝術性。\n看著海報的FOX看起來很得意，難道是錯覺嗎？",
  str_item_intro_3661022 = "家具，可設置於巨像的房間。\n配色是不是很熟悉？沒錯，它正是以黑潮為原型製成的衝浪板。和他本人一樣，該衝浪板堅固耐用、性能可靠，而且很容易操縱喔～",
  str_item_intro_3661176 = "家具，可設置於巨像的房間。\n為了欣賞它，居然把......一整棵樹都搬來做盆栽了！能想到這件事的人，恐怕真的是非常喜歡棕櫚樹吧。",
  str_item_intro_3661171 = "家具，可設置於巨像的房間。\n栩栩如生的海星雕塑，乍看下還以為牠們跑到陸地上來了。雖然是用沙子做的，但不知道用了什麼方法加以黏結，令鬆軟的沙子也能緊緊粘在一起，出人意料的牢固。",
  str_item_intro_3661172 = "家具，可設置於巨像的房間。\n雖然搭建得很堅固，但是畢竟是沙子堆砌的呀，不要從字面意義上去理解它！好吧，起這個名字的原意是希望它能夠保持得更久一點，以這座城堡的表現來看，做得還不錯。",
  str_item_intro_3661173 = "家具，可設置於巨像的房間。\n快去看吧！有著各種奇妙演出演出的盛宴，足以讓觀眾感嘆道「居然會有這樣的表演」，只要看一眼就不會忘記。因此，即使這幅海報只是一張畫，也十分具有吸引力。",
  str_item_intro_3661174 = "家具，可設置於巨像的房間。\n有著多種顏色的圓球，隨便擺弄幾下就足以在舞台上吸引觀眾的眼球，更不要說利用它做各種雜耍動作了，是奇妙演出必不可少的道具之一。",
  str_item_intro_3661175 = "家具，可設置於巨像的房間。\n有好多氣球！不僅色彩繽紛，而且拉著它能感覺到一些浮力！請注意勿讓年齡過小的孩子玩耍，若不稍加注意，孩子會被拉上天空！",
  str_item_intro_3661177 = "家具，可設置於巨像的房間。\n這種樹是怎麼長的呢？枝幹歪曲成這樣竟然也能活......感覺很適合出現在恐怖故事中烘托氣氛，再掛上一些燈籠，八成能嚇倒不少人吧。",
  str_item_intro_3661178 = "家具，可設置於巨像的房間。\n她在笑什麼呢？估計只有製作者才知道吧，看久了總感覺面具的笑容有點奇怪，那真的是在笑嗎......",
  str_item_intro_3661179 = "家具，可設置於巨像的房間。\n咕嚕嚕......咕嚕嚕......這種奇妙的大鍋中不知道熬煮了什麼，是那些童話故事中的魔藥？亦或是某種......黑暗料理？",
  str_item_intro_3661180 = "家具，可設置於巨像的房間。\n影鎮中某些奇怪的商人製作的玩偶，看起來像是普通的巨像模型，但內裡是空的，稍微按一下就會發出奇怪的尖叫，這是在模仿什麼橋段呢......",
  str_item_intro_3661023 = "家具，可設置於巨像的房間。\n只要灌滿了水，就能利用其中的機關不斷射出水流的裝置，帶來陣陣清涼，很適合在夏天使用。不過玩耍過後，別忘了要將地板擦乾淨。",
  str_item_intro_3661024 = "家具，可設置於巨像的房間。\n居然用一個輪子也能前進！儘管速度有點慢就是了......看著騎士如同雜技般的車技，不禁讓人感嘆又擔心。",
  str_item_intro_3661025 = "家具，可設置於巨像的房間。\n似乎是從神祕遺跡中發現的機器，雖然有點舊，然而運行完好，能忠實地將影像記錄下來。",
  str_item_intro_3701001 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
  str_item_intro_3701002 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
