  str_item_intro_3711002 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
  str_item_intro_3711003 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
  str_item_intro_3711004 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
  str_item_intro_3711005 = "這是一冊散落的典籍，先收到咖啡廳的書架上了，有興趣就去看看吧～",
  str_item_intro_3751002 = "獲得後可解鎖對應頭像。\n「我想到一個很好的點子！哦？你也想到了？別說出來，維持這種默契吧～」",
  str_item_intro_3751003 = "獲得後可解鎖對應頭像。\n「你看那個人，好有趣啊，哎呀，那個人！不會吧～」",
  str_item_intro_3751004 = "獲得後可解鎖對應頭像。\n「事情又不順利啦！要怎麼辦呢！哎呀，不能說粗話……但是——！」",
  str_item_intro_3751005 = "獲得後可解鎖對應頭像。\n「啊～煩死啦，怎麼會這樣？看來還是有所不足，再努力一下吧～」",
  str_item_intro_3751006 = "獲得後可解鎖對應頭像。\n「事情沒辦好，會被長官罵嗎？還是不要先想得太糟吧，嗚嗚嗚……」",
  str_item_intro_3751009 = "獲得後可解鎖對應頭像。\n「請您不要質疑自己，您一定有屬於您的使命，一定的！」",
  str_item_intro_3751011 = "獲得後可解鎖對應頭像。\n「分配給你的任務都完成啦？給你一朵小花～」",
  str_item_intro_3751015 = "獲得後可解鎖對應頭像。\n「這聲音，既悅耳又讓人安心，要一起聽嗎～」",
  str_item_intro_3751017 = "獲得後可解鎖對應頭像。\n「不能扯大家的後腿，要不要再發明一些新的東西呢？像是……」",
  str_item_intro_3751019 = "獲得後可解鎖對應頭像。\n「豐富的知識、廣博的見聞，都無法形容眼前這件事，真令人瞠目結舌～」",
  str_item_intro_3751023 = "獲得後可解鎖對應頭像。\n「你為什麼這麼急？忙著去吃霸王餐？晚了就不熱了唷～」",
  str_item_intro_3751025 = "獲得後可解鎖對應頭像。\n「無聊的人呀，為何要想方設法殺時間～沒有其他事可做了嗎？」",
  str_item_intro_3751030 = "獲得後可解鎖對應頭像。\n「我們親愛的巨像呀，為何要逞強，飛在天上～」",
  str_item_intro_3751032 = "獲得後可解鎖對應頭像。\n「為何不認清自己？為何不照照鏡子？那些完全不行的人，真沒自知之明～」",
  str_item_intro_3751033 = "獲得後可解鎖對應頭像。\n「金杯共汝飲，白刃不相饒。」",
  str_item_intro_3751034 = "獲得後可解鎖對應頭像。\n「當你凝視影子時，影子也在凝視著你。」",
  str_item_intro_3751035 = "獲得後可解鎖對應頭像。\n「很多時候真理藏沒於雲霧之中，若隱若現，你我皆需擦亮自己的雙眼。」",
  str_item_intro_3751036 = "獲得後可解鎖對應頭像。\n「秩序？規則？哈哈！那是什麼？」",
  str_item_intro_3751037 = "獲得後可解鎖對應頭像。\n「未來仍舊黑暗，然而我已看到了一絲曙光。」",
  str_item_intro_3751038 = "獲得後可解鎖對應頭像。\n「真的很不錯！和我一起來對抗暗鬼吧！為了啟明之光！」",
  str_item_intro_3751301 = "獲得後可啟用對應頭像。\n「幹得不錯！要不要加入紅油扳手啊~？」",
  str_item_intro_3751302 = "獲得後可解鎖啟用頭像。\n「謝謝大家，我的力量已經恢復了，要不要我幫你打暗鬼啊~？」",
  str_item_intro_3751303 = "獲得後可解鎖對應頭像。\n「與我一起去雲山欣賞櫻花吧～」",
  str_item_intro_3751304 = "獲得後可解鎖對應頭像。\n「擁有「刨冰之魂」的攤主精心製作的刨冰，在夏日中帶給你無上的清涼感受。」",
  str_item_intro_3751305 = "獲得後可解鎖對應頭像。\n「帶上它！你就是「紅油動力激鋼ν零號機」了！」",
  str_item_intro_3751306 = "獲得後可解鎖對應頭像。\n「唉……好像大家都去玩了，我也……」",
  str_item_intro_3751307 = "獲得後可解鎖對應頭像。\n「想要涼爽些嗎？沒問題，冰花~」",
  str_item_intro_3751308 = "獲得後可解鎖對應頭像。\n「已經一百天了？吃個蛋糕紀念一下吧～」",
  str_item_intro_3751309 = "獲得後可解鎖對應頭像。\n「啊……我好像是沙漠人了。」",
  str_item_intro_3751310 = "獲得後可解鎖對應頭像。\n「頭怎麼好重，原來是它們……那就這樣待著吧。」",
  str_item_intro_3751311 = "獲得後可解鎖對應頭像。\n「勝利了？放個禮花炮慶祝一下！」",
  str_item_intro_3751312 = "獲得後可解鎖對應頭像。\n「關於這件事，希望你我能達成共識。」",
  str_item_intro_3751313 = "獲得後可解鎖對應頭像。\n「想要窺探我面具下的容貌？沒問題，先加入我的傭兵團吧。」",
  str_item_intro_3751314 = "獲得後可解鎖對應頭像。\n「白夜至上，希望我能夠肅清世間不公之事。」",
  str_item_intro_3751315 = "獲得後可解鎖對應頭像。\n「它代表影鎮地下格鬥賽的至高榮譽！是你成為王牌拳手的證明！」",
  str_item_intro_3751316 = "獲得後可解鎖對應頭像。\n「先森先森，偶會蘇展魔法啦！」",
  str_item_intro_3751317 = "獲得後可解鎖對應頭像。\n「微笑的鬼臉！一起去熱鬧一下吧！」",
  str_item_intro_3751318 = "獲得後可解鎖對應頭像。\n「能在巡邏時遇到可愛的貓貓～今天的心情都變好了呢！！」",
  str_item_intro_3751319 = "獲得後可解鎖對應頭像。\n「在白夜城，它就是權力的象徵，通常只有貴族才能擁有。」",
  str_item_intro_3751320 = "獲得後可解鎖對應頭像。\n「北境新年期間，人人都會如此打扮，我也不例外。」",
  str_item_intro_3751321 = "獲得後可解鎖對應頭像。\n「新的一年，祝您擁有幸福與安寧。」",
  str_item_intro_3751322 = "獲得後可解鎖對應頭像。\n「現在知道我是天下第一女僕了吧！」",
  str_item_intro_3751323 = "獲得後可解鎖對應頭像。\n「乖孩子連睡覺時都很乖，不會亂動，甚至能在她頭上放顆橘子。」",
  str_item_intro_3751324 = "獲得後可解鎖對應頭像。\n「我會……把它們一筆一筆畫下來。」",
  str_item_intro_3751325 = "獲得後可解鎖對應頭像。\n「你看這個……我估計起碼有一千年了！」",
  str_item_intro_3751326 = "獲得後可解鎖對應頭像。\n「要慶祝嗎？看來節日也有屬於自己的需求呢。」",
  str_item_intro_3751327 = "獲得後可解鎖對應頭像。\n「嗨！和我一起去外面逛逛！」",
  str_item_intro_3751328 = "獲得後可解鎖對應頭像。\n「再好的記性，也不如一本筆記。」",
  str_item_intro_3751329 = "獲得後可解鎖對應頭像。\n「嗷嗚～～沒被嚇到吧～」",
  str_item_intro_3751330 = "獲得後可解鎖對應頭像。\n「愛情誠可貴\n自由價更高\n若為誓言故\n兩者皆可拋」",
  str_item_intro_3751331 = "獲得後可解鎖對應頭像。\n「叮鈴～你要鈴鐺喵？」",
  str_item_intro_3751332 = "獲得後可解鎖對應頭像。\n「請傾聽這神樂鈴的聲音吧。」",
  str_item_intro_3751333 = "獲得後可解鎖對應頭像。\n「我是不會把包子讓給別人的！」",
  str_item_intro_3751334 = "獲得後可解鎖對應頭像。\n「你醒啦？快去幹活吧～」",
  str_item_intro_3751335 = "獲得後可解鎖對應頭像。\n「勝利了！要不要去做些有意思的事情？」",
  str_item_intro_3751336 = "獲得後可解鎖對應頭像。\n「它像不像我？」",
  str_item_intro_3751338 = "獲得後可解鎖對應頭像。\n「啊哈哈，貓貓頭也在看著你。」",
  str_item_intro_3751339 = "獲得後可解鎖對應頭像。\n「它們……有什麼不一樣？」",
  str_item_intro_3751340 = "獲得後可解鎖對應頭像。\n「一直以來受到你的很多照顧，就收下這個吧。」",
  str_item_intro_3751341 = "獲得後可解鎖對應頭像。\n「據說在今天要表達心意呢……是這樣的嗎？」",
  str_item_intro_3751342 = "獲得後可解鎖對應頭像。\n「聽說這件睡衣是導航員人氣特別款？我排了好久的隊才買到的！」",
  str_item_intro_3751343 = "獲得後可解鎖對應頭像。\n「眼睛的顏色......不一樣了。」",
  str_item_intro_3751344 = "獲得後可解鎖對應頭像。\n「嗯......好像有什麼工作忘記做了？」",
  str_item_intro_3751345 = "獲得後可解鎖對應頭像。\n「把重要事項及時記下來，是作為參謀長的良好習慣～」",
  str_item_intro_3751346 = "獲得後可解鎖對應頭像。\n「這套衣服？是我在影鎮逛街的時候淘到的喔，風格是不是很獨特？」",
  str_item_intro_3751347 = "獲得後可解鎖對應頭像。\n「丘布商人大概收購到好貨，開心得唱起了歌。」",
  str_item_intro_3751348 = "獲得後可解鎖對應頭像。\n「啟光需要你的力量，我們等待你的加入！」",
  str_item_intro_3751349 = "獲得後可解鎖對應頭像。\n「嗯？你想聽我唱歌？可以呀，作為交換之後要陪我打遊戲喔！」",
  str_item_intro_3751350 = "獲得後可解鎖對應頭像。\n「為什麼要扮成尤彌？因為尤彌很可愛啊」",
  str_item_intro_3751351 = "獲得後可解鎖對應頭像。\n「你說頭上的耳朵？這是菲莉詩非要讓我戴上去的，不然她就要向希羅娜長官報告說我不小心踩到了她的尾巴......」",
  str_item_intro_3751352 = "獲得後可解鎖對應頭像。\n「和我組隊吧！無論什麼比試都不會輸的！」",
  str_item_intro_3751353 = "獲得後可解鎖對應頭像。\n「啊？那個有什麼難的？」",
  str_item_intro_3751354 = "獲得後可解鎖對應頭像。\n「偶爾也要放鬆一下。」",
  str_item_intro_3751355 = "獲得後可解鎖對應頭像。\n「挖到哪裡了？」",
  str_item_intro_3751356 = "獲得後可解鎖對應頭像。\n「啊！好熱！」",
  str_item_intro_3751357 = "獲得後可解鎖對應頭像。\n「今年夏天很熱，戴太陽帽可以有效防止曬傷。導航員，你也要注意防暑。」",
  str_item_intro_3751358 = "獲得後可解鎖對應頭像。\n「誰會拒絕在炎炎夏日裡，來一杯冰涼美味的刨冰呢？」",
  str_item_intro_3751359 = "獲得後可解鎖對應頭像。\n「炎炎夏日裡，呆在卡蓮身邊時總能感受到一絲涼爽」",
  str_item_intro_3751360 = "獲得後可解鎖對應頭像。\n「真的很舒服，一起享受這狂歡中的寧靜吧。」",
  str_item_intro_3751361 = "獲得後可解鎖對應頭像。\n「暗夜就是我的夥伴，蝙蝠就是我的臣民，那麼，我是誰？」",
  str_item_intro_3763022 = "獲得後可解鎖對應頭像。\n「別害怕，這怪燈是我為了這幾天的活動增加氣氛而做的，還不錯吧？」",
  str_item_intro_3751362 = "獲得後可解鎖對應頭像。\n「讓我來看看發生了什麼！」",
  str_item_intro_3751363 = "獲得後可解鎖對應頭像。\n「就算很嚴肅，還是會允許蛇呆在頭上的。」",
  str_item_intro_3751365 = "獲得後可解鎖對應頭像。\n「想買糖果嗎？那就用你的故事來交換吧。」",
  str_item_intro_3751366 = "獲得後可解鎖對應頭像。\n「打扮成狼的樣子，導航員一定不會拒絕的，對吧？」",
  str_item_intro_3751367 = "獲得後可解鎖對應頭像。\n「卡戎興沖沖地戴上假牙套、披上斗篷，開始了演出」",
  str_item_intro_3751368 = "獲得後可解鎖對應頭像。\n「成為魔法師對緋來說也是修行的一種。」",
  str_item_intro_3751369 = "獲得後可解鎖對應頭像。\n「普律瑪把自己用繃帶包了起來，準備給討要糖果的孩子們一個驚喜。」",
  str_item_intro_3751370 = "獲得後可解鎖對應頭像。\n「這枚硬幣……代表了我的過去。」",
  str_item_intro_3751371 = "獲得後可解鎖對應頭像。\n「各種顏色的燈光，很好看。」",
  str_item_intro_3751372 = "獲得後可解鎖對應頭像。\n「來和我一起，成為偶像吧！」",
  str_item_intro_3751373 = "獲得後可解鎖對應頭像。\n「預備，開機！」",
  str_item_intro_3751374 = "獲得後可解鎖對應頭像。\n「菲莉詩說這是用小魚乾換來的新年款熱門睡衣，嗯，雖然很舒適，但為什麼會有耳朵？」",
  str_item_intro_3751375 = "獲得後可解鎖對應頭像。\n「有著特殊香氣的螺粉，是木月白最喜歡的食物」",
  str_item_intro_3751376 = "獲得後可解鎖對應頭像。\n「你看起來不太舒服，需要我們給你看看嗎？」",
  str_item_intro_3751377 = "獲得後解鎖對應頭像。\n「耶利亞習慣靜靜觀察周遭人與事。」",
  str_item_intro_3751378 = "獲得後解鎖對應頭像。\n「鐵面無私的米迦勒會沒收出現在她面前的所有玫瑰。」",
  str_item_intro_3751379 = "獲得後解鎖對應頭像。\n「偶爾喬裝打扮外出能得到別樣的體驗呢。」",
  str_item_intro_3751380 = "獲得後可解鎖對應頭像。\n「危險動作，請勿模仿。」",
  str_item_intro_3751381 = "獲得後可解鎖對應頭像。\n「傑諾邀你和他一起喝杯黑咖啡。你會接受他的邀請嗎？」",
  str_item_intro_3751382 = "獲得後可解鎖對應頭像。\n「身為白夜城的審判官，應具備一錘定音的魄力。」",
  str_item_intro_3751383 = "獲得後可解鎖對應頭像。\n「這個玩偶和我長得很像，抱著它有安全感。」",
  str_item_intro_3751384 = "獲得後可解鎖對應頭像。\n「我喜歡這些音樂，能令我心情平靜。」",
  str_item_intro_3751385 = "獲得後可解鎖對應頭像。\n「喜歡和仙鶲貼貼的鶯歌，內心一定很溫柔吧。」",
  str_item_intro_3751386 = "獲得後可解鎖對應頭像。\n「用劍來開疆拓土，用手來撫慰民心，是李奧堅守的原則。」",
  str_item_intro_3751387 = "獲得後可解鎖對應頭像。\n「紅茶的香氣能夠舒緩蜜雅的心情，讓她放鬆下來。」",
  str_item_intro_3751388 = "獲得後可解鎖對應頭像。\n「他手中的紫羅蘭，是誰最愛的花呢？」",
  str_item_intro_3751389 = "獲得後可解鎖對應頭像。\n「從水晶球裡，可以看到過去還是未來呢？」",
  str_item_intro_3751390 = "獲得後可解鎖對應頭像。\n「難過時如果有一個溫柔的擁抱，應該能讓你好過些吧？」",
  str_item_intro_3751391 = "獲得後可解鎖對應頭像。\n「當我的觀眾或與我共舞，你會選哪一個呢？」",
  str_item_intro_3751392 = "獲得後可解鎖對應頭像。\n「炎炎夏日，來碗沁涼的刨冰消暑吧！」",
  str_item_intro_3751393 = "獲得後可解鎖對應頭像。\n「我有一個能賺錢的好想法，你要不要和我一起嘗試一下？」",
  str_item_intro_3751394 = "獲得後可解鎖對應頭像。\n「你問我在笑什麼？嗯……不如你來猜猜看？」",
  str_item_intro_3751395 = "獲得後可解鎖對應頭像。\n「問我夏天喜歡的甜點嗎？大概是帶有蜥蜴乾的冰淇淋吧。」",
  str_item_intro_3751501 = "獲得後可解鎖對應頭像。\n「這朵黎花代表著希望。戴上它，驅散過去的陰霾吧！」",
  str_item_intro_3751502 = "獲得後可解鎖對應頭像。\n「櫻華一族的徽章，代表了緋對你的認可。」",
  str_item_intro_3751503 = "獲得後可解鎖對應頭像。\n如果你需要謎之戰士的幫助，請聯絡瀧先生的萬事屋。",
  str_item_intro_3751504 = "獲得後可解鎖對應頭像。\n「嘻嘻，要一起喝下午茶嗎？\n才喝了七桶茶就不行了嗎？～」",
  str_item_intro_3751505 = "獲得後可解鎖對應頭像。\n「陪我回到永恆的黑暗中吧。」",
  str_item_intro_3751506 = "獲得後可解鎖對應頭像。\n「暗鬼很棘手？沒事，讓我來！」",
  str_item_intro_3751507 = "獲得後可解鎖對應頭像。\n「溫德嵐節的驚喜！裡面裝著什麼有趣的禮物呢？」",
  str_item_intro_3751508 = "獲得後可解鎖對應頭像。\n「與我共飲，欣賞這美妙的夜色吧。」",
  str_item_intro_3751509 = "獲得後可解鎖對應頭像。\n「看來……你需要我的幫助。」",
  str_item_intro_3751510 = "獲得後可解鎖對應頭像。\n「我先說好，這頓飯是為小林準備的，你們不准吃！」",
  str_item_intro_3751511 = "獲得後可解鎖對應頭像。\n「我？沒熬夜啊……」",
  str_item_intro_3751512 = "獲得後可解鎖對應頭像。\n「啊……剛醒來覺得好渴，要多喝水。」",
  str_item_intro_3751513 = "獲得後可解鎖對應頭像。\n「哎呀，要問我對導航員大人的看法嗎……」",
  str_item_intro_3751514 = "獲得後可解鎖對應頭像。\n「哪裡還有吃的呀～」",
  str_item_intro_3751515 = "獲得後可解鎖對應頭像。\n「和我一起兜兜風吧！」",
  str_item_intro_3751516 = "獲得後可解鎖對應頭像。\n「能感到蓮的心情嗎？」",
  str_item_intro_3751517 = "獲得後可解鎖對應頭像。\n「未來的戰略......」",
  str_item_intro_3751518 = "獲得後可解鎖對應頭像。\n「最好的時光，就是喝下午茶的時候。」",
  str_item_intro_3751519 = "獲得後可解鎖對應頭像。\n「我收下了。」",
  str_item_intro_3751520 = "獲得後可解鎖對應頭像。\n「吾輩要出場了嗎？」",
  str_item_intro_3751521 = "獲得後可解鎖對應頭像。\n「白夜城與大陸的......一定不會，也一定不能是現在這副模樣。」",
  str_item_intro_3751522 = "獲得後可解鎖對應頭像。\n「有煩惱？那就一起來涼快一下～」",
  str_item_intro_3751523 = "獲得後可解鎖對應頭像。\n「來！打一局！」",
  str_item_intro_3751524 = "獲得後可解鎖對應頭像。\n「呼......解決了。」",
  str_item_intro_3751525 = "獲得後可解鎖對應頭像。\n「生存還是毀滅？\n這是一個永恆的問題。」",
  str_item_intro_3751526 = "獲得後可解鎖對應頭像。\n「靈感來了！拍下！看來這下一定會大熱的！」",
  str_item_intro_3751527 = "獲得後可解鎖對應頭像。\n「帽子帶上鬼頭，俠盜掄飛壞蛋，塞提拿起酷酷，說唱追打一路。」",
  str_item_intro_3751530 = "獲得後可解鎖對應頭像。\n「養花真的可以磨練心性！」",
  str_item_intro_3751531 = "獲得後可解鎖對應頭像。\n「她很美麗，也很……危險。」",
  str_item_intro_3751532 = "獲得後可解鎖對應頭像。\n「啊……好溫暖好柔軟。」",
  str_item_intro_3751533 = "獲得後可解鎖對應頭像。\n「她似乎還沉浸在「那個人」的故事中，還是別打攪她啦。」",
  str_item_intro_3751534 = "獲得後可解鎖對應頭像。\n「新年好！一起來放煙火吧！」",
  str_item_intro_3751535 = "獲得後可解鎖對應頭像。\n「船隻……真是迷人。」",
  str_item_intro_3751536 = "獲得後可解鎖對應頭像。\n「好吃！好吃！還有嗎？」",
  str_item_intro_3751537 = "獲得後解鎖對應頭像。\n「來不及了！只好邊走邊吃啦！」",
  str_item_intro_3751538 = "獲得後可解鎖對應頭像。\n「我沒有在睡覺……ZZZ……」",
  str_item_intro_3751539 = "獲得後可解鎖對應頭像。\n「你能一次過關嗎？」",
  str_item_intro_3751540 = "獲得後可解鎖對應頭像。\n「父親、母親……」",
  str_item_intro_3751541 = "獲得後可解鎖對應頭像。\n「可惡的犯人……我不會放過你的！」",
  str_item_intro_3751542 = "獲得後可解鎖對應頭像。\n「獵物在哪裡？獵物就在眼前～」",
  str_item_intro_3751543 = "獲得後可解鎖對應頭像。\n「靠記性不如記筆記……」",
  str_item_intro_3751544 = "獲得後可解鎖對應頭像。\n「聯合軍演，即將開始！」",
  str_item_intro_3751545 = "獲得後可解鎖對應頭像。\n「什麼都不能忽略，細節很重要。」",
  str_item_intro_3751547 = "獲得後可解鎖對應頭像。\n「只是這樣靜靜看著她們，就已經覺得很幸福了。」",
  str_item_intro_3751548 = "獲得後可解鎖對應頭像。\n「想欣賞？那就大大方方地看吧。」",
  str_item_intro_3751549 = "獲得後可解鎖對應頭像。\n「越危險，越美麗，果真如此？」",
  str_item_intro_3751550 = "獲得後可解鎖對應頭像。\n「好點子加上行動力，是成功的基礎！」",
  str_item_intro_3751601 = "獲得後可解鎖對應頭像。\n「一面裂開的箏形盾。箏形盾為白夜城騎士團的專屬裝備，整體呈風箏形，上寬下窄，稜角分明。盾牌表面刻繪著代表教會的紋章。」",
  str_item_intro_3751602 = "獲得後可解鎖對應頭像。 「一棵枯樹上掛著三顆彩球。對瑪莎來說，過往已盡數枯萎；在燈火點綴的雪境中，她將迎來新的人生。」",
  str_item_intro_3751603 = "獲得後可解鎖對應頭像。\n「在輪胎的中央，放著一枚齒輪。羅砂的車已開進沙漠深處，循跡而來的人再難望見她的背影，僅供憑弔的，只有輪胎留下的痕跡。」",
  str_item_intro_3751604 = "獲得後可解鎖對應頭像。\n「怒放的百合花中，利刃也隨時候命。在伊馮的筆下，赤汞夫人的命運低伏在迷霧中。你永遠無法預測，她會遞送手中的長劍，還是會贈出衣襟上的百合。」",
  str_item_intro_3751901 = "獲得後可解鎖對應頭像。\n臨空者號不僅是一座巨像，更是一位陪伴你十七年的朋友。",
  str_item_intro_3751902 = "獲得後可解鎖對應頭像。\n戴著這副頭盔，覺得自己會變成白夜的守護者。至於是哪種「白夜」，就不要深究了～",
  str_item_intro_3755004 = "獲得後可解鎖對應頭像。\n「珠綴重重，清曉簾櫳，花蕾依舊，世人知否？」",
  str_item_intro_3762001 = "獲得後可解鎖對應頭像框。\n古老圖案代表了「寂靜獵兵」對你的認可，請接收這份來自往昔的無上榮耀。",
  str_item_intro_3762002 = "獲得後可解鎖對應頭像框。\n用精緻又溫馨的飾品來裝飾頭像吧！",
  str_item_intro_3763001 = "獲得後可解鎖對應頭像框。\n驕陽與碧波，和難忘的回憶留在水氣氤氳的海灘。",
  str_item_intro_3763002 = "獲得後可解鎖對應頭像框。\n帶上啟光聯邦的軍帽，彷彿就是他們的一員了。",
  str_item_intro_3763003 = "獲得後可解鎖對應頭像框。\n它能讓你隨時瞭解孰輕孰重，是個好幫手～",
  str_item_intro_3763004 = "獲得後可解鎖對應頭像框。\n有了它，你就是聚會中最青春洋溢的人～",
  str_item_intro_3763005 = "獲得後可解鎖對應頭像框。\n專門頒發給好學生的錦旗！要努力啊！",
  str_item_intro_3763006 = "獲得後可解鎖對應頭像框。\n可愛嗎～？",
  str_item_intro_3763007 = "獲得後可解鎖對應頭像框。\n讓我們陪陪你吧……",
  str_item_intro_3763008 = "獲得後可解鎖對應頭像框。\n摸魚的戰利品！",
  str_item_intro_3763010 = "獲得後可解鎖對應頭像框。\n是春天的氣息呢！",
  str_item_intro_3763011 = "獲得後可解鎖對應頭像框。\n感覺戴上它，就會變成厲害的賽車手了！",
  str_item_intro_3763012 = "獲得後可解鎖對應頭像框。\n鮮紅的幕布之下，乃是黑色的童謠......",
  str_item_intro_3763013 = "獲得後可解鎖對應頭像框。\n彰顯尊貴的冠冕，十分引人注目。",
  str_item_intro_3763014 = "獲得後可解鎖對應頭像框。\n只有大元帥才能穿喔！",
  str_item_intro_3763015 = "獲得後可解鎖對應頭像框。\n戴上這個，就能提升服務精神嗎？",
  str_item_intro_3763016 = "獲得後可解鎖對應頭像框。\n戴上吧，大魔術師！",
  str_item_intro_3763017 = "獲得後可解鎖對應頭像框。\n太陽很厲害的，不要被曬傷啦～",
  str_item_intro_3763018 = "獲得後可解鎖對應頭像框。\n一週年了！快戴上慶祝一下吧！",
  str_item_intro_3763019 = "獲得後可解鎖對應頭像框。\n只要戴上就很像比卡喔～毛茸茸～",
  str_item_intro_3763020 = "獲得後可解鎖對應頭像框。\n放心，不燙的！",
  str_item_intro_3763021 = "獲得後可解鎖對應頭像框。\n像不像蝙蝠爪抓著你？其實那只是頭環太緊啦～",
  str_item_intro_3763023 = "獲得後可解鎖對應頭像框。\n戴上這個帽，說唱水準高，而且沒想到，棒球也變好。",
  str_item_intro_3763024 = "獲得後可解鎖對應頭像框。\n歌手必備！沉浸在音樂之中吧～",
  str_item_intro_3763025 = "獲得後可解鎖對應頭像框。\n它不是用來吃的，而是用來戴的哦！",
  str_item_intro_3763026 = "獲得後解鎖對應頭像。\n「戴上它，或許就能擁有和耶利亞差不多的力量？至少不會怕風了。」",
  str_item_intro_3763027 = "獲得後可解鎖對應頭像框。\n其實這副眼鏡沒有度數喔～",
  str_item_intro_3763028 = "獲得後可解鎖對應頭像框。\n我知道了！犯人就是他！",
  str_item_intro_3763029 = "獲得後可解鎖對應頭像框。\n二週年了？戴上吧！記得把一週年那個取下來喔～",
  str_item_intro_3763031 = "獲得後可解鎖對應頭像框。\n那個世界真的存在？若不存在，為何又能置身於此？",
  str_item_intro_3763032 = "獲得後可解鎖對應頭像框。\n似乎很容易被刺到，究竟誰會願意戴呢……",
  str_item_intro_3763033 = "獲得後可解鎖對應頭像框。\n這樣就是一名紳士了？",
  str_item_intro_3800001 = "內含50光珀",
  str_item_intro_3800002 = "內含50光珀",
  str_item_intro_3800003 = "內含50光珀",
  str_item_intro_3800004 = "內含50光珀",
  str_item_intro_3800005 = "內含50光珀",
  str_item_intro_3801001 = "傳說光靈突破必需物品。\n這是「寂靜獵兵」成員共同擁有的紋章，經過上千年的時光依舊保有強大的力量，足以激發「寂靜獵兵」成員的潛力。",
  str_item_intro_3900101 = "每次模擬指揮後，指揮祕錄都會依據指揮者的表現給予積分。當指揮積分達到一定程度後，可提升指揮等級，這代表戰術指揮的熟練程度。",
  str_item_intro_3900201 = "透過在模擬室中指揮戰鬥，可以從「資料碟」儲存的大量資料中獲得珍貴的資料碎片，累積到一定程度便能拼湊出完整的情報。",
  str_item_intro_3910100 = "長久的訓練才能帶來勝利。\n在該資料碟提供的挑戰中，擊敗所有敵人才能過關。",
  str_item_intro_3910200 = "很多時候，擊敗敵人不是重點，目的是要蒐集足夠的資源。\n在該資料碟提供的挑戰中，獲取X個特定道具才能過關。",
  str_item_intro_3910300 = "即便捨去性命，也要守護夥伴。\n在該資料碟提供的挑戰中，NPC在X回合內未死亡即可過關。",
  str_item_intro_3910400 = "你不知道會遇到什麼樣的敵人，無一例外的是牠們都很強，請小心。\n在該資料碟提供的挑戰中，擊敗菁英敵人才能過關。",
  str_item_intro_3910500 = "頭腦勝過刀劍，以智取勝。\n在該資料碟提供的挑戰中，解開謎題才能過關。",
  str_item_intro_3910600 = "戰鬥即是博弈，亦如棋局。\n在該資料碟提供的挑戰中，擊敗所有敵人才能過關。",
  str_item_intro_3910700 = "在殘酷的戰鬥中，唯一的勝利者就是最後活下來的人。\n在該資料碟提供的挑戰中，在X回合內沒被擊敗才能過關。",
  str_item_intro_3910800 = "敵人宛如海浪，拍擊著身為防禦方的你的沙灘，請堅持下去。\n在該資料碟提供的挑戰中，擊敗所有敵人才能過關。",
  str_item_intro_3910900 = "敵人的戰術與你雷同，不……敵人或許就是你與你的夥伴。\n在該資料碟提供的挑戰中，擊敗所有敵人才能過關。",
  str_item_intro_3911000 = "擒賊擒王，擊殺敵酋，才能結束這場戰鬥，進而結束這場戰爭。\n在該資料碟提供的挑戰中，擊敗敵人的首領才能過關。",
  str_item_intro_4090014 = "雙生的羈絆深深縈繞，破碎的記憶緩緩拼湊。那朵雪白的雙生水仙在鏡湖之畔迎著墨色的雪花緩緩綻放，期待著與鏡中之人再次相逢。",
  str_item_intro_4090334 = "來自雲櫻旅店，極具雲山特色的服裝。這是一件為了薇絲身體構造而臨時改良的女用浴衣。簡潔的配色、特色十足的腰封與墜飾，還有俏皮可愛的小鈴鐺……都為薇絲增添了幾分與平時不同的溫婉氣質。每當她穿上這件浴衣，都會回想起那段難以忘懷的珍貴回憶。",
  str_item_intro_4090923 = "「……你不要盯著我看！」\n還有比這更困窘的時刻嗎？纏繞的荊棘將契法的雙腳吊起，輕薄的絲襪與黑紗被撕成碎片，混亂之中契法勉強維持著手中紅酒杯的平衡。看來這件端莊奢華的服飾，並不如它外表看起來那般好駕馭。",
  str_item_intro_4090383 = "大危機！貢露陷在玩具箱裡出不來了！為了慶祝新年到來，貢露送上了一份驚喜禮物。和玩具們塞在一起的她看起來嬌小又可愛，紅白相間的服裝非常有節慶氛圍，就連她的機械手臂都綁上了蝴蝶結。不過她手上那個充滿惡意的炸彈還是算了吧……",
  str_item_intro_4090333 = "為了海神祭，薇絲為自己選擇了這套簡約舒適的泳裝。這套泳裝採用了特殊的結構設計，更加符合薇絲的穿著習慣，能夠讓尾巴自由擺放。除了特殊結構外，仔細觀察，黑金配色的防曬外套也非常適合活潑好動的她。製冰機嚓嚓作響，滿臉笑意的短髮少女，正邀請你一起下水玩耍。沙灘排球、冰鎮飲料、刨冰推車……這個夏季，你與薇絲有了共同的專屬回憶。",
  str_item_intro_4090853 = "英氣上衣與優雅裙擺結合而成的奇妙服裝，憂鬱而純潔，詭異而優美。精美編織的手袖、充滿儀式感的頭紗、帥氣十足的長靴……珍的服裝不僅令人吃驚，她裙尾開得正盛的鮮花似乎也有特殊寓意。只是不知道——一直想當局外人的她，是出於什麼原因才穿上這套衣服的呢？",
  str_item_intro_4090863 = "以海神祭為主題所設計的白色少女系列服裝。考慮到尤萊雅的身分，特別採用了無暇的純白塗料，彰顯純真與虔誠。花藤輕盈地浮現在她身邊，緊隨她的召喚；在他人眼中，她的狀態並無不同，只有圍繞在周圍的花朵知道——來到海邊的尤萊雅，會暗自為這套衣著感到些許羞澀。晴朗的天空、鹹鹹的海風、冰涼的海水……她揮舞手中的禮儀劍，再次奏響美妙的詩篇樂章。",
  str_item_intro_4090573 = "這是午後的一場美夢，菲莉詩身穿毛絨絨的睡衣蜷縮在床上，陷入沉睡。她夢到尤彌就在她身邊，擁著她，輕撫她的髮絲，像一團炙熱的小火爐，溫暖她的身心靈。一切就像回到了過去。",
  str_item_intro_4091023 = "這身簡單的衣服體現了某種精神，名為「燃燒」的精神，是昏暗壓迫的地下格鬥場中唯一一束強光。挑戰者走向舞台，以筋骨、肉體對抗，以精神、毅力拚搏，使鮮血如烈火般燃燒，轟轟烈烈而來，再如死灰一般逝去。她掰動手指，準備好獵殺眼前的一切。",
  str_item_intro_4090453 = "大雪紛落，凜冬已至。街道上無人經過，唯有暖黃燈光閃爍。倘若你是孤身一人的旅客，不必為迷失方向而擔憂。只要瞧一瞧轉角處——純白燕尾服、墨黑長靴；一頭光亮滑潤的髮型與優雅的舉止——那位低調安靜的紳士，已在馬車旁恭候多時。",
  str_item_intro_4090993 = "這是害羞時才會有的姿勢。艾蕾雅蜷縮在沙發上，光著雙腿。隨便放置的鞋子和身上的小禮服，暗示著一場舞會剛剛結束。彷彿灰姑娘的故事般，曼妙的魔法禮服將隨時間逐漸消逝，唯有這段回憶——與你共度的時光，不會消失，也永不褪色。",
  str_item_intro_4090263 = "存在的意義，對虛無的認知……換上這套奇怪的衣服後，莫名其妙的問題終日縈繞在烏列爾的腦海中，使她不得不思考個不停。而在虛擬的文學世界中，烏利爾是否終將找到答案呢？這一點無法肯定。唯一能做的，便是在她沉溺於文學時，與她同行，共同思考與感受。",
  str_item_intro_4090543 = "嚴肅又認真，這就是娜汀的行事風格。似乎永遠不會疲倦的她，持續不懈地履行自己的職責。即便換了一身與往日截然不同、青春洋溢的衣著，即便她手中的提燈有了別緻的可愛裝扮，也依舊無法掩蓋她這樣的氣質。",
  str_item_intro_4091113 = "一到海邊，即便是平日憂鬱寡歡的拜里厄，也會顯得放鬆許多。這件泳裝雖然款式相當簡約，卻能不時地展現拜里厄的身材，不過她完全沒有注意到這一點，只是將所有精力都投入在那座沙子堆砌的城堡。或許對於拜里厄來說，這是她來到海邊的最大收穫了吧。",
  str_item_intro_4090883 = "藍天、白雲、平整的街道——這是與紅油沙漠完全不同的風景。瑪姬也與往常不同，她身穿乾淨整潔的水手服，大大的領結迎風擺動。在這個晴朗的早晨，看她咬著麵包「悠閒」騎車的樣子，或許是上學要遲到了？\n這身奇妙的衣服，不僅讓瑪姬在紅油扳手一群人中顯得非常獨特，似乎還能讓她看到別樣的場景。或許這就是衣服附帶的魔力。",
  str_item_intro_4090963 = "老、老師？是沙利葉嗎？看來，沙利葉非常認真看待這份兼職，還為此特地換上教師制服。不得不說，現在的沙利葉，看起來確實比平常可靠許多，語氣也顯得溫柔又端莊。或許在接下來的課堂上，真的可以從她那裡學到什麼「知識」吧。",
  str_item_intro_4091053 = "即便只穿著普通的服裝，伊芙也是紅油扳手的人氣王。然而她究竟有多受歡迎，恐怕她自己也不清楚。決定為大家加油打氣的她，在換上這套不知從哪來的奇怪衣服後，人氣不減反增，突破天際！不過大家千萬別目不轉睛地盯著她看，否則小心怒氣沖沖的大扳手從天而降哦～",
  str_item_intro_4090064 = "這輕飄飄，滑溜溜，還滿是絲帶的衣服……竟然是睡衣？！為什麼會有這種不符合常理的設計，這種衣服真的能在別人面前穿嗎？卡蓮陷入了困擾，不知道自己該如何抉擇，最後決定先穿上看看。沒想到以往理智且嚴肅的她竟然顯露出完全不同的氣質。\n為了能參加睡衣派對，順利與大家融洽相處，卡蓮決定冒險一試。",
  str_item_intro_4090303 = "漆黑的衣袖，赤紅的大氅。誠如所見，斬盡天下惡人的武士——赤浪醒之助，參上！\n作為紅油扳手的首領，醒山正以自身實踐著「入鄉隨俗」的準則，不論是身上著物，還是腰間佩刀，都完美地呈現著雲島的韻味，甚至連醒山本人的笑聲似乎都更爽朗不羈了一些。不過還請注意，如果這位浪人武士來了興致，說不定會即興創作俳句，並高歌一曲……",
  str_item_intro_4090443 = "當清風徐徐吹入松林，和煦的日光照耀廳堂，遠離了喧囂的城市與繁忙的公務，來到幽靜的「雲山旅館」，何不趁此機會，小憩片刻？「勞逸結合」可是薇薇安的準則，能夠作為這裡的一日店主放鬆身心，之後也能充滿幹勁地再次開始工作吧！\n當然了，這也是計劃的一部分！",
  str_item_intro_4090643 = "雷霆的新款作戰服裝，由源自東方的絲線編織而成，輕薄貼身、飄逸靈動。雖然看起來有些單薄，但是便於活動，絲毫不會對雷霆的戰鬥力造成影響。\n放開拳腳、舒展筋骨、勇往直前、掃清一切——不論什麼危險襲來，可靠的雷霆都會一如既往地將它們解決！",
  str_item_intro_4090893 = "伊倫汀為了這難得的假期，特意準備了雲島風格的服裝。金色的布料與刺繡，搭配潔白如雪的毛皮披肩，看起來雍容華貴。伊倫汀期待著能穿上這身服裝在雲島街頭漫步，或者搭乘列車遊覽風景名勝。\n然而，突如其來的事件打亂了她的全部計劃，為了守護自己的假期，伊倫汀一點也不介意把審判庭開到雲島的站台上。",
  str_item_intro_4090653 = "「先森，快來和塔塔一起玩板羽球吧！」\n塔塔興沖沖地拿著板羽球找過來時，臉上帶著必勝的笑容。明明聽起來是輕鬆愉快的小遊戲，沒想到最後竟然變成了一場頂尖高手的大戰？！這華麗的發球和強勁的扣球，已經完全不是以普通人水平能夠參與的比賽了！\n聽說輸掉的人會面臨懲罰，被勝者在臉上畫畫，希望塔塔能夠手下留情，少畫幾筆……",
  str_item_intro_4090233 = "雖然很害羞，但是見到夥伴們都去參加「賽車活動」，對此感興趣的克娜莉還是接受了擔任啦啦隊隊員的工作，負責為大家加油打氣。然而，相對於她的日常著裝，這套啦啦隊員服著實有些「特別」。\n即便如此，克娜莉還是接受了某位商人推銷的這套風格奔放的服裝，她也希望借此變得更加活潑開朗。",
  str_item_intro_4090613 = "「啊......這就是大陸的樣子！」\n身處雲層之間的錢德菈，完全沒有對高空的恐懼，反而饒有興趣地看著地面上舉辦的拉力賽，激烈的賽況讓她時不時地解說。只不過......這熱氣球以及那身有些異樣風情的服飾......\n原來，這一切都是她那神奇的「想像療法」，即便如此，卻也能讓他人積壓已久的情緒，得到完美的釋放。",
  str_item_intro_4090843 = "「有著沙的炙熱、水的溫軟，兼備復古元素與新潮。」\n「野調無腔、失禮得令人發指......」\n雖然評論千差萬別，然而當伊斯塔萬穿著這身服飾時，一切負面的評價都不攻自破。即便所處的地方並非豪門大殿，卻也令眾人感受到名流之風，或許這就是「影主」本身的氣場，反而讓它增添了額外的魅力。",
  str_item_intro_4090603 = "賽車比賽裁判員的衣著總是特別顯眼，畢竟要讓處於風馳電掣速度中的車手看到裁判，就必須鮮豔一些不可。\n而因為缺錢喝酒的約娜，在應聘了這次比賽的裁判員後，卻很快發現其中的蹊蹺內幕。本來不想多管閒事的約娜，為了一名小女孩，主動前往賽道，讓那些參與這場黑車賽的壞蛋們，體會一下什麼是「公正」。",
  str_item_intro_4090713 = "如此炙熱的天氣、如此惡劣的氣候，在熾烈陽光下，賽車都要冒煙，汗水落到沙漠之上，頃刻間化為烏有。\n即便如此，瀧還是「全副武裝」地參加了這場比賽，勢要擊敗那些虎視眈眈的對手，一舉奪下冠軍。而讓他如此認真的，僅僅是金錢嗎？",
  str_item_intro_4091263 = "陷入創作瓶頸的戀愛暢銷書作家，喬裝打扮了一番，想去街邊尋找靈感。為什麼要喬裝打扮？也許是因為她並不想讓人們知道，平時威風凜凜的商會管理人，私下裡竟然有這種太過「少女心」的愛好吧。\n但是千萬不要小看貝菲爾對這份愛好的執著——她甚至願意以身試險，只為了那一閃而過的創作靈感......",
  str_item_intro_4090673 = "微風拂來，潔白蓬鬆的裙擺輕輕搖曳，露出點綴其間的紅色花朵。愛麗絲的這身打扮莫名地讓人想起一種蛋糕......對，就是那種只有在生日的時候才能咬上一口的草莓蛋糕！不過在「夢幻甜品屋」，只要誠實地回答店主愛麗絲的問題，您就可以免費品嘗到任何您所垂涎的甜品。這可是愛麗絲對您的特殊懲罰，不對......是特殊「獎賞」喔～",
  str_item_intro_4090103 = "「乾淨整潔的衣裝，是女僕的驕傲！」\n那就換上莉塔親手縫製的女僕工裝裙，戴上蕾絲邊的髮帶吧。喔，對了，別忘了圍上那件縫著一隻金色蝴蝶結的圍裙。\n今天露易絲不僅要服侍主人梳妝打扮，還要負責組織一次下午茶呢。別擔心，小蜜蜂、馴鹿寶寶還有雲朵先生都會來幫忙喔。\n看，女僕小姐的工作已經開始囉～",
  str_item_intro_4090283 = "咳咳，讓我們熱烈歡迎阿普頓莊園的女僕長大人！什麼，看起來有點眼熟嗎？是的，你沒猜錯，這就是我們可愛的拉斐爾喔～\n最近她收到了一項特殊的任務——訓練白夜城的女僕，讓女僕們獲得一些戰鬥技能。學期即將結束，在拉斐爾的悉心指導下，女僕們成績優異。只是......拉斐爾的女僕修行似乎還不太順利呢。",
  str_item_intro_4091163 = "為了做出回憶中的「那種麵包」，弗勞爾花費了不少心思，也做了許多嘗試，但一直都沒能成功。\n這一次，弗勞爾做了更加充足的準備。他換上了縫線整齊的襯衫、熨燙妥帖的圍裙，還有擦拭得鋥亮的皮鞋——據說穿上這樣的服裝，就能做出好吃的麵包。雖然這種傳說聽起來很不靠譜，但是弗勞爾為了心中的那份牽掛，仍然願意去相信。",
  str_item_intro_4090703 = "被這樣的視線注視著的話，會感覺氣氛開始變得灼熱、呼吸也急促了起來......是在緊張嗎？也對，在這樣強大又美麗的莉奧娜面前大概很少有人會不緊張吧。系帶式涼鞋的細帶纏繞著她的雙腿，與往日風格差異極大的配飾點綴著她的身體，她卻慵懶地呈現出一副世間所有都不過是她囊中之物的氛圍感。",
  str_item_intro_4090813 = "這是黑潮為了尋找「某樣東西」而特意為自己準備的服裝。便於行動的泳褲、頗具他個人特色的衝浪板、參考了雨衣設計的透明外套......透明外套？不得不說，黑潮準備這件透明外套的真正目的也許是為了你的那聲誇獎——是的，蛋白粉和辛苦鍛鍊，陽光與汗水鑄就的這副身體，正在等待你的誇獎。",
  str_item_intro_4091123 = "最近的影鎮流傳著某些為眾人津津樂道的傳說。犯罪預告函、把所有人鬧得團團轉的盜賊、失竊的寶石......這名被懷疑的嫌疑人究竟是不是我們面前漫不經心的斯莫奇呢？想知道真相的話，恐怕得先解開她的手銬呢。當然，她的新稱號就和新衣服一樣令人好奇——「黑貓怪盜」，將在三天之後如約來取走寶石。",
  str_item_intro_4090384 = "究竟是先有了這套衣服，還是先有了帶有這套衣服的那個遊戲呢？它的來源並不重要了，關鍵是當貢露穿上它時，就已經進入了休假模式，也就是說這是貢露專門為休假而準備的。即便這休假並不是去海邊，而是在水族館中遊玩一天。",
  str_item_intro_4090413 = "她到底有多少個身分呢？不僅是白夜城的引路人，還擁有多種兼職，其中一項便是擔任「白金夏潮」飯店的宣傳代言人。這身泳裝便是拍攝宣傳單時所穿，無論是用料、剪裁，均十分考究。在這碧海藍天之下，令人對飯店不禁心馳神往。",
  str_item_intro_4090873 = "在前去巡視一處位於海島上的領地時，為了更好地融入當地環境，貝芙麗換上了這套帶有盔甲樣式的泳裝。雖然比平日的裝束要簡單了許多，然而依舊無法掩蓋她身上的貴族之氣。這不僅是尚武家風的影響，更是貝芙麗自身追求貴族榮譽的結果。",
  str_item_intro_4091293 = "雖然一身夏日清涼著裝，但他認真的目光似乎告訴眾人，他不是來享受輕鬆時刻，而是前來完成一個必須的任務。這身裝束不僅能讓路克在濕熱的森林中保持體力，更是專門為保護珍貴的蝴蝶，擊退那些無恥盜獵者而準備的一套「禮服」。",
  str_item_intro_4091483 = "沙漠中的水上狂歡即將開始，然而讓很多人特別興奮的事情，是可以看到青瞳那令人不禁睜大雙眼的身姿！尤其在薄如蟬翼的衣著襯托下......咳，請各位還是要注意自己的視線，不要盯得太久喔！偶爾去享受一下溫熱、濕潤的晚風吹拂，聽聽嘈雜吵擾的音樂，和擁擠的人群一起跳舞，也是很不錯的享受！",
  str_item_intro_4090254 = "古老貴族氣質、華麗的舞台風格......這套服裝看起來與很多人的日常衣著格格不入，因為它是卡戎為自己新設計的演員制服。儘管看起來十分誇張，然而在鏡頭前，卻能最快吸引觀眾的目光，充分發揮卡戎那幾近忘我的投入、那令人過目不忘的演技。可以說，這一時刻的卡戎，與這套服裝，就是為了演戲而生。",
  str_item_intro_4090683 = "推銷！推銷！由於近日信使公會與影鎮報社的合作，信使們不得不承擔新的任務——推銷報紙訂閱。於是，溫蒂換上了一身報童服飾，更方便攜帶報紙並向外推銷。看著她一同與報紙飛舞的姿態，看來就算是全新的業務範疇，溫蒂那追求速度的精神，令她永遠不會落於人後！",
  str_item_intro_4091003 = "束縛於過去的希卡蕾，在此時換上了另一幅打扮，雖然乍看起來像是普通的醫生，然而隨身攜帶的醫療箱卻透露了不同尋常的「工作內容」。因為她不僅要治療生者的疾病，而且還要對那些逝去之人、那些來自於「墓穴」的聲音，也要一視同仁......",
  str_item_intro_4091203 = "這是一項為了增進雙方友誼而舉辦的交流活動。白夜城的海蒂，被大家要求參加，從而前往啟光聯邦的迦南城，成為了宣傳交通安全與犯罪預防的「一日治安官」。為此，儘管海蒂身為白夜城的騎士，卻也聽從命令穿上了啟光制服，雖然她自己多少有些不適應，然而並未影響她的自信與魅力。",
  str_item_intro_4091193 = "為了找回記憶中那難以割捨的味道，雷文頓不惜孤身犯險，決心潛入一座大牢之中，這裡充滿了各種行走在灰色區域的不法人士，可以說是危險重重......來自啟光聯邦，初涉這種混亂之地的雷文頓，她能順利達成自己的目標，完成這特殊的個人臥底任務嗎？",
  str_item_intro_4091213 = "紅豔的花朵，佈滿荊棘的枝幹……普律瑪的這身打扮彷彿寫滿了「生人勿近」，加上那一抹淺淺的微笑，更加凸顯了一種危險的冷艷氣質。總覺得如果不小心惹怒了她，就會有什麼不好的下場，就像傳說影鎮黑幫老大處決對手那樣。還是說，她現在已經是了……",
  str_item_intro_4090123 = "在迦南城中突然興起的「正義執行AKA天罰者」的傳說。每當有人不遵守紀律，就會有一道驚雷突然響起，而涅墨西斯則會閃現在此人身旁，用閃電懲罰此人。之後，便用一段妙語直指人心，令對方徹底悔悟。而完成「正義」的使者會在另一道驚雷中瞬間消失，前往他方。",
  str_item_intro_4090773 = "休息日中的伯利恆，偶然閱讀到一本講述天才女歌手的傳記。沉浸於文字中的她，仿佛自己化身為女歌手，體會她的橫空出世、名噪一時，以及之後的失聲沒落。「如果自己也和她一樣呢？」伯利恆思考再三也想不出這個問題的答案，只有將自己想像為她，想像自己拿起樂器、想像自己激情創作、想像自己在最後的舞台上啞然失聲，體會她的人生，也為自己尋找將來的可能。",
  str_item_intro_4090833 = "為了喚醒所守護的「莉莉」，她們能做的事情……就是，成為偶像？然而一直遵守死板女僕規矩的她們，是否能勝任偶像的工作？畢竟這是一份需要活力與創意的工作。不過，如果有一套標準流程的話，加上她們的人數優勢，或許還真有可能……",
  str_item_intro_4091313 = "雖然抱持不同的看法，但是諾維亞依舊在這個日子中穿上了與以往截然不同的衣著，一瞬間化為鋼琴師，為在北境中堅強生存的人們帶來溫暖與祝福，也為抱有一絲冀望的特別聽眾給予鼓勵，助他們在未來的路上堅定前行、自強不息。",
  str_item_intro_4091383 = "雖然是被上司強迫參加偶像比賽，希諾普還是做了相當多的準備，鍛鍊才藝的同時，在服飾搭配上也不惜成本，投入了相當大的精力進行研究和設計。這科研精神帶來的——是希諾普那驚人的蛻變，是她那散發著無人能遮擋的光芒，那未來可期的明星之路……",
  str_item_intro_4090273 = "她是流傳在白夜城戀人們口中的恐怖傳說——一年一度的冠月節來臨時，就會有一名身穿白衣的騎士在城內各個角落巡邏，尋找熱戀中的人們。只要一被她發現，就會立即開出一張「禁止戀愛」處罰令。因此，她成了戀人們口中畏懼的「斬斷戀情的雷光」。",
  str_item_intro_4090553 = "與平日嚴肅的裝扮不同，彼亞塔曼今天的衣著似乎也受到冠月節氣氛的影響，在不失以往堅毅風采的前提下，潛藏了少見的溫柔。當然，這並不是因為他的心已經屬於某人，而是為了完成他人的一樁心願，去充當一名合格的傳信人。",
  str_item_intro_4090913 = "在克蘿伊的世界裡，愛情總是少不了離別，要她去演奏讚頌甜蜜情感的樂曲，就就點強人所難了。既然如此，不如以神為名讚頌永恆之愛——人之愛會在有限的歲月中逝去，但沒關係，光會平等地祝福世間每一個人，也會愛每一個人。",
  str_item_intro_4091673 = "此處的社交場合不乏各種小魔術，而魔術的重點就在於「隱密」。一張牌、一句話、一個眼神，就在觥籌交錯的不經意間，那盛大精妙的演出就已完成。雖然少了習以為常的掌聲，但偶爾賣個人情給朋友，對傑諾來說也不錯。",
  str_item_intro_4090043 = "冰冷的屍體、被標記出的線索、一道又一道的警戒線…如此經典而充滿懸疑氛圍的現場，總會令人產生無限遐想。比如偵探就是兇手，或者早就和兇手串通；也許兇手就潛伏在我們之中；甚至所有證人都是兇手…但誰又能想到，死者和偵探其實是一夥的呢？",
  str_item_intro_4090483 = "一片祥和的影鎮街頭，不詳的氣息已經悄然而入。路人們似乎還在享受寧靜的夜晚，唯獨那名巡警的警惕眼神不會放過一絲罪惡。只要它們潛藏在這座城市中，守護和平的她就不會停下腳步，不會停下巡邏，一切都是為了……獨一無二的妹妹！",
  str_item_intro_4091484 = "窗明几淨的事務所，柔軟的沙發，令人沉醉其中的美酒，以及那位半躺於沙發之上的「代主理人」，不要被她一副慵懶的樣子欺騙。這位美麗的女人十分危險，尤其是對於那位即將到來的獵物來說…是真正的字面意義上的「危險」。",
  str_item_intro_4091663 = "「嗯…那些可愛的小傢伙們會在哪裡？」為了尋找那些神奇動物，也為了揭穿那裡的真相，菲雅化身為一名偵探，認真開始探查這起「疑案」，仔細端詳著搜尋到的各種證據，並思考其中的關鍵疑點。看著她一副認真又努力的模樣，或許真的能有所發現。",
  str_item_intro_4090983 = "在影主的命令下，一向深居簡出的庫絲庫塔也不得不化身為一名偵探，試圖抓捕那近期十分活躍的罪犯。當然，庫絲庫塔對於街頭走訪、見證談問可能並不擅長，然而敏銳的她，卻能僅僅憑藉手頭上的線索，只要坐在那張「安樂椅」中看著棋局沉思，就能推斷出兇手。",
  str_item_intro_4091034 = "世人皆不應犯罪，犯罪會遭到上天譴責，具象於凡間便為審訊、判決、懲罰。當然，其實這過程也沒有那麼可怕，尤其有審訊專員艾希，她非常溫柔，不會動用任何暴力，就能打開對方的心防……當然或許心防根本就毫無作用。因此如果碰上她，別抵抗，把一切都交給艾希吧。",
  str_item_intro_4090293 = "為了完成那位「大師」的遺願，加百列換上了這件隆重的禮服，前往那座位於影鎮的孤兒院，昏暗、破舊的環境與精緻的服飾形成了鮮明的對比，加上加百列那多少有些遲鈍的表現，令孤兒們將她誤認為「魔女」。不過，最終孤兒們還是感受到了加百列想要守護此地的決心，而這件禮服，似乎也閃耀著令人感到安心的點點輝光。",
  str_item_intro_4090463 = "對於大人們來說是恐怖的黑魔法書，但對於他們來說，則是進入神奇世界的入口，那裡充滿了奇幻、魔力與不可思議，正是為他們這種擁有好奇且孤傲的靈魂所準備的。而為了煉製那「禁忌的魔藥」，四處蒐集各種奇怪材料的他們還換上了專門的服裝，顯得更加與眾不同。",
  str_item_intro_4090623 = "為了能讓莉亞舉辦的讀書會順利舉行，西爾瓦特地換上了這件正式服飾，看起來就如同一位正要面見老師的年輕學者，聰穎、智慧、端正。他的這種態度自然也為讀書會帶來了良好的風氣，因此硬要說的話，他可以算是一位「模範學員」了……",
  str_item_intro_4091433 = "林中夜遊，雷雨突至，據說不祥之物會徘徊於世。為此，凜音穿著隆重巫服，高擎神樂鈴，祛除污穢，保護眾生。\n「即誦陰陽。此一曲，伴汝魂歸彼岸。」\n「三途川下，怨曲幽生。」\n「曼陀羅語，琴瑟和鳴。」\n「聽者寧神，遂吾魂魄。」",
  str_item_intro_5000001 = "據說含有某些遠古訊息的神祕物質，能夠加快建築建構和家具製作的速度。",
  str_item_intro_5000002 = "空庭-寶物更新次數",
  str_item_intro_5002101 = "堅硬且富有韌性的木材，適合用於房屋建築、家具打造等。",
  str_item_intro_5002201 = "剛剛挖掘而出的礦石，需經歷進一步加工方可使用，即便如此，在市場上也有一定價值。",
  str_item_intro_5003001 = "從空庭各處發現的石片，應該是先前的殘留，具體作用不明。丘布們倒是很喜歡它，願意拿某些東西來交換。",
  str_item_intro_5003101 = "建構建築或製作家具時常用的塗膠，可緊實黏著材料，令構造堅固。",
  str_item_intro_5003102 = "建構建築或製作家具時常用的塗膠，只要一點點就能使材料緊密結合，令構造更加堅固。",
  str_item_intro_5011001 = "1級輕柄斧，柄是中空的，為其減輕了重量，揮舞起來更方便，也更快捷，能夠迅速地砍斷粗壯的樹幹。",
  str_item_intro_5011002 = "2級輕柄斧，柄是中空的，為其減輕了重量，揮舞起來更方便，也更快捷，能夠迅速地砍斷粗壯的樹幹。",
  str_item_intro_5011003 = "3級輕柄斧，柄是中空的，為其減輕了重量，揮舞起來更方便，也更快捷，能夠迅速地砍斷粗壯的樹幹。",
  str_item_intro_5011004 = "4級輕柄斧，柄是中空的，為其減輕了重量，揮舞起來更方便，也更快捷，能夠迅速地砍斷粗壯的樹幹。",
  str_item_intro_5011005 = "5級輕柄斧，柄是中空的，為其減輕了重量，揮舞起來更方便，也更快捷，能夠迅速地砍斷粗壯的樹幹。",
  str_item_intro_5012001 = "1級百釣竿，桿身重量平衡，而且富有韌性，魚線也很堅固，在大魚上鉤時，它可是好幫手。",
  str_item_intro_5012002 = "2級百釣竿，桿身重量平衡，而且富有韌性，魚線也很堅固，在大魚上鉤時，它可是好幫手。",
  str_item_intro_5012003 = "3級百釣竿，桿身重量平衡，而且富有韌性，魚線也很堅固，在大魚上鉤時，它可是好幫手。",
  str_item_intro_5012004 = "4級百釣竿，桿身重量平衡，而且富有韌性，魚線也很堅固，在大魚上鉤時，它可是好幫手。",
  str_item_intro_5012005 = "5級百釣竿，桿身重量平衡，而且富有韌性，魚線也很堅固，在大魚上鉤時，它可是好幫手。",
  str_item_intro_5013001 = "1級加重鎬，頭部經過加重的鎬，高舉後下落的勁道十分有力，足以鑿開任何山石。",
  str_item_intro_5013002 = "2級加重鎬，頭部經過加重的鎬，高舉後下落的勁道十分有力，足以鑿開任何山石。",
  str_item_intro_5013003 = "3級加重鎬，頭部經過加重的鎬，高舉後下落的勁道十分有力，足以鑿開任何山石。",
  str_item_intro_5013004 = "4級加重鎬，頭部經過加重的鎬，高舉後下落的勁道十分有力，足以鑿開任何山石。",
  str_item_intro_5013005 = "5級加重鎬，頭部經過加重的鎬，高舉後下落的勁道十分有力，足以鑿開任何山石。",
  str_item_intro_5014001 = "鏟頭經過增厚處理，碰到堅硬石塊也不怕歪扭，挖掘的順手度更是不在話下。",
  str_item_intro_5011012 = "表面粗糙且堅硬的石塊，可以將鈍刀磨得十分鋒利。\n可在背包中升級輕柄斧。",
  str_item_intro_5012012 = "從空庭內找出上好木料，削薄片以增加竿身硬度並保持韌性，配合特製的魚線，令百釣竿可更加從容地應付各種情況。\n可在背包中升級百釣竿。",
  str_item_intro_5013012 = "用手將砂輪轉動得飛快，可以將圓鈍的鎬尖打磨得十分銳利。\n可在背包中升級加重鎬。",
  str_item_intro_5111001 = "蒼覆亭台的設計圖，可至風信塔解鎖蒼覆亭台的製作方法。",
  str_item_intro_5111002 = "青石拱門的設計圖，可至風信塔解鎖青石拱門的製作方法。",
  str_item_intro_5111003 = "途中貨站的設計圖，可至風信塔解鎖途中貨站的製作方法。",
  str_item_intro_5111004 = "綠里水井的設計圖，可至風信塔解鎖綠里水井的製作方法。",
  str_item_intro_5111005 = "漸旋風車的設計圖，可至風信塔解鎖漸旋風車的製作方法。",
  str_item_intro_5121001 = "空庭木欄的設計圖，可至風信塔解鎖空庭木欄的製作方法。",
  str_item_intro_5121002 = "空庭木柵的設計圖，可至風信塔解鎖空庭木柵的製作方法。",
  str_item_intro_5121003 = "空庭木籬的設計圖，可至風信塔解鎖空庭木籬的製作方法。",
  str_item_intro_5121004 = "空庭石欄的設計圖，可至風信塔解鎖空庭石欄的製作方法。",
