  str_item_intro_5176012 = "冠月薔薇籃的設計圖，可至風信塔解鎖冠月薔薇籃的製作方法。",
  str_item_intro_5176013 = "冠月瑰毯的設計圖，可至風信塔解鎖冠月瑰毯的製作方法。",
  str_item_intro_5134046 = "這是訴言箋牆的設計圖，可至風信塔解鎖訴言箋牆的製作方法。",
  str_item_intro_5176101 = "歇洛克式桌椅的設計圖，可至風信塔解鎖歇洛克式桌椅的製作方法。",
  str_item_intro_5176102 = "歇洛克式案件板的設計圖，可至風信塔解鎖歇洛克式案件板的製作方法。",
  str_item_intro_5176103 = "歇洛克式轎車的設計圖，可至風信塔解鎖歇洛克式轎車的製作方法。",
  str_item_intro_5176104 = "歇洛克式咖啡器具的設計圖，可至風信塔解鎖歇洛克式咖啡器具的製作方法。",
  str_item_intro_5176105 = "歇洛克式衣帽架的設計圖，可至風信塔解鎖歇洛克式衣帽架的製作方法。",
  str_item_intro_5176106 = "歇洛克式手推車的設計圖，可至風信塔解鎖歇洛克式手推車的製作方法。",
  str_item_intro_5176107 = "歇洛克式小提琴的設計圖，可至風信塔解鎖歇洛克式小提琴的製作方法。",
  str_item_intro_5176108 = "歇洛克式沙發椅的設計圖，可至風信塔解鎖歇洛克式沙發椅的製作方法。",
  str_item_intro_5176109 = "歇洛克式菸斗架的設計圖，可至風信塔解鎖歇洛克式菸斗架的製作方法。",
  str_item_intro_5176110 = "歇洛克式放大鏡的設計圖，可至風信塔解鎖歇洛克式放大鏡的製作方法。",
  str_item_intro_5176111 = "歇洛克式提燈的設計圖，可至風信塔解鎖歇洛克式提燈的製作方法。",
  str_item_intro_5176112 = "歇洛克式推理板的設計圖，可至風信塔解鎖歇洛克式推理板的製作方法。",
  str_item_intro_5176113 = "歇洛克式書架的設計圖，可至風信塔解鎖歇洛克式書架的製作方法。",
  str_item_intro_5176114 = "歇洛克式傘桶的設計圖，可至風信塔解鎖歇洛克式傘桶的製作方法。",
  str_item_intro_5176201 = "這是紀緬公庭的設計圖，可至風信塔解鎖紀緬公庭的製作方法。",
  str_item_intro_5176202 = "這是紀緬水晶球的設計圖，可至風信塔解鎖紀緬水晶球的製作方法。",
  str_item_intro_5176203 = "這是紀緬騎士像的設計圖，可至風信塔解鎖紀緬騎士像的製作方法。",
  str_item_intro_5176204 = "這是紀緬展示櫃的設計圖，可至風信塔解鎖紀緬展示櫃的製作方法。",
  str_item_intro_5176206 = "這是紀緬邸桌的設計圖，可至風信塔解鎖紀緬邸桌的製作方法。",
  str_item_intro_5176207 = "這是紀緬貴座的設計圖，可至風信塔解鎖紀緬貴座的製作方法。",
  str_item_intro_5176208 = "這是紀緬旗幟的設計圖，可至風信塔解鎖紀緬旗幟的製作方法。",
  str_item_intro_5176209 = "這是紀緬長晝燈的設計圖，可至風信塔解鎖紀緬長晝燈的製作方法。",
  str_item_intro_5176210 = "這是紀緬低欄的設計圖，可至風信塔解鎖紀緬低欄的製作方法。",
  str_item_intro_5176211 = "這是紀緬瓶景的設計圖，可至風信塔解鎖紀緬瓶景的製作方法。",
  str_item_intro_5176212 = "這是紀緬綠蓬的設計圖，可至風信塔解鎖紀緬綠蓬的製作方法。",
  str_item_intro_5134049 = "這是典錄方碑的設計圖，可至風信塔解鎖典錄方碑的製作方法。",
  str_item_intro_5211001 = "有著歪斜支柱的涼亭，頂棚是一方覆蓋了苔蘚的石片，雖然看似不甚符合建築常理，但確實很堅固。",
  str_item_intro_5211002 = "據說用一整塊石頭鑿刻而成的拱門，即便上面覆了一層青草，牢固性也無須擔心。",
  str_item_intro_5211003 = "可供人在山谷內運送物資期間小憩的停靠站，建造快速，拆解方便，路途中可以建造很多座。",
  str_item_intro_5211004 = "建於地下水源匯集處的井，往下望深不見底，周圍加裝石製圍擋，避免有人失足落水。井打得很深，取得的地下水純淨且清涼。",
  str_item_intro_5211005 = "造型獨特的風車，看起來略嫌低矮，但對風力的利用可是十分充足！而且透過某些奇妙的技術，即便無風時節期間，也能緩緩轉動。",
  str_item_intro_5221001 = "木製的圍欄，連接起來設置就能在空庭中圍出一片土地。",
  str_item_intro_5221002 = "較短的柵欄，木條隨意拼接的樣子頗具田園氣息。",
  str_item_intro_5221003 = "木製籬笆，製作方便，也很適合用於隔開建築，劃分領域。",
  str_item_intro_5221004 = "石製的圍欄，沉重又牢固，比木製的圍欄更加耐用。",
  str_item_intro_5221005 = "石製的籬笆，僅需安插在地上，經歷多少風吹日仍可用上很多年。",
  str_item_intro_5221006 = "粗壯的石柵，不僅穩定性強，還能給人莫名的安全感。",
  str_item_intro_5223001 = "方形的地磚，可以鋪設得很整齊，適合用於主要道路以及重要建築物附近的地面鋪設。",
  str_item_intro_5223005 = "由不規則石塊拼接而成的地磚，適合用於鋪設小路以及裝點庭院。",
  str_item_intro_5231001 = "用兩片梯形石板支撐起來的桌子，沉重且堅固。",
  str_item_intro_5231002 = "較小的圓形石桌，與同款座椅搭配，適合一到兩位朋友於此閒談。",
  str_item_intro_5231003 = "四面都有支撐的木桌，寬大、平整，適合多人一起閒坐使用。",
  str_item_intro_5232001 = "圓形石凳，中空的構造內有一根石柱支撐，不僅堅固，圓潤的外圍結構可以降低人誤撞到石頭邊緣的機率。",
  str_item_intro_5232002 = "下寬上窄的方石凳，上面有一層木板用於隔絕石頭的寒氣，造型大方，製作簡單，美中不足的是其邊緣處容易被人撞上。",
  str_item_intro_5232003 = "簡單、輕便的木椅，使用兩側支撐的方式，坐上去會有輕微的搖晃感。",
  str_item_intro_5232005 = "造型奇特的石柱垂吊一根繩索，床被設計成圓葉狀，巧妙地維持平衡，能夠讓人舒舒服服地躺在裡面，也不怕翻下去。",
  str_item_intro_5232006 = "由一條石臺組成的長椅子，不僅能坐還可以躺，由於為石製，還能為人帶來滿滿的清涼感。",
  str_item_intro_5233001 = "一大一小兩根山石交錯放置，若擺設位置適當，能為周圍房舍提供獨特的景緻。",
  str_item_intro_5233002 = "看起來像放大數倍的石筍，經過適當裝點可形成很不同的感覺。",
  str_item_intro_5233003 = "由數塊造型各異的碎石組成的群落，通常擺放在路邊或庭院中裝飾。",
  str_item_intro_5233004 = "這座涼亭的頂棚為傘狀，用一根柱子支撐，故意做成歪斜一側的造型，據說這是為了製造更多的陰涼面積。頂棚上爬滿了藤蔓，風吹過垂下的枝葉，另有一番風味。",
  str_item_intro_5233005 = "交疊堆砌的山石，汩汩清水形成了小瀑布，以及用厚重石片圍成的小池，三者結合，便能為庭院帶來連綿不絕的悅耳水聲。",
  str_item_intro_5233006 = "直立的岩柱，可以用於充當山石群的主體。",
  str_item_intro_5233007 = "由多根歪斜的岩柱組成，看起來彷彿一座小山嶺。",
  str_item_intro_5233008 = "稍微有些傾斜的岩柱，很適合作為造型差別極大的山石之間的協調裝飾。",
  str_item_intro_5233009 = "這根岩柱的峰端較為尖銳，整體也顯得纖細，給人一種凜冽之氣，最好尋找與之合適的山石進行搭配。",
  str_item_intro_5233010 = "看起來彷若斜斜的山崗，也可以考慮將之作為山石群的主體。",
  str_item_intro_5234001 = "利用某些奇妙技術而得以維持明亮的路燈，較低矮，只能照亮一小片區域。",
  str_item_intro_5234002 = "用一根柱子支撐起來的路燈，高高的光源足以照亮遠處的區域。",
  str_item_intro_5234007 = "較高的花架，可以讓人在遠處就欣賞到盛開的花朵。",
  str_item_intro_5234009 = "這上面釘有各種指明方向的木牌，足以讓人在龐大的空庭中不至於迷路，不過一定要把方位放正確喔！",
  str_item_intro_5234011 = "能夠帶來充足陰涼地的傘，缺點是有點沉，不容易搬動。",
  str_item_intro_5234012 = "宛如太陽而得名的花朵，高挑的莖幹外加巨大的花盤，令它有一種高傲的氣質，也有人認為其代表了「心向光明」。",
  str_item_intro_5234013 = "用石塊堆砌出來的區域，地面也理得平整，專門用於種植各種花卉。",
  str_item_intro_5234014 = "較為低矮的花架，適合擺放在路邊、門前作為裝飾。",
  str_item_intro_5234018 = "野外用的個人帳篷，錐形保證了帳篷內有足夠的高度，搭設也方便，就是面積較小，僅供一人使用。",
  str_item_intro_5234019 = "擺滿各色食物的桌布，看來這下在野外也可以享用一頓美餐啦～",
  str_item_intro_5234020 = "爐身堅固、耐高溫，底座的縫隙能很好地讓空氣進入，令火焰高漲，從而散發強烈的熱氣。",
  str_item_intro_5234023 = "即便是雜草也不能浪費，將它們蒐集起來後，或許還有其他用處。",
  str_item_intro_5234024 = "用木板釘合而成的箱子，加工方便，體積大，很適合存放物資。",
  str_item_intro_5234025 = "由多個板木箱堆放而成，只要看到它們，就知道這裡多半是個倉儲之地了。",
  str_item_intro_5234037 = "用石塊圍起來的篝火灶，能夠在野外生火，同時還不會引發火災。",
  str_item_intro_5234038 = "從海底發現的船錨，極為堅固，看樣子足以讓一艘大船在帶波浪起伏的海面上固定。可惜其主人已經不知所蹤，只能靜靜地等待有人再度啟用它了。",
  str_item_intro_5234039 = "以起伏的海浪為動力，使用者可以在水面上來去自如，甚至還能做出各種各樣的動作。放在空庭中多少有點可惜......",
  str_item_intro_5241002 = "坐上去就會輕微搖晃的鞦韆，注意不要盪得太高！也有某些人喜歡坐在上面睡覺，這種悠悠搖晃的感覺，確實能令人很快入眠。",
  str_item_intro_5241003 = "能帶來些許騎乘感覺的玩具，據說可以鍛鍊平衡感～",
  str_item_intro_5241004 = "放風箏適合在晴朗且有微風的日子中進行。將風箏放飛到天上後，只要將風箏線束在架子上，它就不會被風吹跑囉～",
  str_item_intro_5241005 = "輕便的畫板架，專門用於戶外寫生，恰到好處的角度和大小，能令人保持作畫時的專注。",
  str_item_intro_5241006 = "劇台和擴音器的位置經過精心設計，能夠讓觀眾在各種角度都欣賞到台上的表演。據說這劇台還有奇妙的技術，有時會根據不同節目而展現不同的特殊效果。",
  str_item_intro_5241007 = "據說是為了紀念某位曾經遊歷過大陸上所有名山大川的空裔女性而建，然而現在已經沒人記得她的名字了，只留下這樣一座雕像供後人紀念。",
  str_item_intro_5241008 = "每次看到它，似乎總會莫名地想打上兩拳......不過你永遠打不到倒它喔，雖然有點遺憾，不過用來發洩倒是很不錯。",
  str_item_intro_5241016 = "巨大的迴廊，廊柱看起來頗向什麼遠古生物的骨頭......也有人說它實際上是巨像內的一組重要構件。",
  str_item_intro_5242101 = "雖然外表看來很奇怪，然而其獨特構造令房間內的採光充足，空氣流通，十分適宜居住。",
  str_item_intro_5243001 = "肥料豐沃的土地，能為所有作物提供充足養分。",
  str_item_intro_5234008 = "這個稻草人的頭是用麻布做的，近看仿佛臉上長了不少麻子，據說能大幅提高威嚇效果喔！",
  str_item_intro_5234015 = "一圖勝過千言，只要看到木牌，就會明白它想表達的意思——「請不要傷害鱗甲獸！」",
  str_item_intro_5234016 = "能夠根據陽光的投影來判斷時間的裝置，可以說是鐘錶的雛形。缺點是，陰天下雨和夜晚就沒辦法用了。",
  str_item_intro_5234017 = "用於測定風向的儀器，十分靈敏，即便是微風也能準確測量。如果風太大讓風標經常改變方向的話，記得將它取下來喔！免得它因為轉得太快而壞掉了。",
  str_item_intro_5234026 = "需要一定力氣才能推動的石磨，據說在過去人們用它來磨製麵粉，在現代卻顯得既費力氣又低效，不過偶爾用它來鍛鍊一下膂力還是不錯的。",
  str_item_intro_5234027 = "堅固又輕巧的木桶，提把處還有防滑設計，免得不慎翻落，空費力氣。",
  str_item_intro_5234028 = "儘管是陶瓷製品，但是邊緣被加固過，所以耐摔、耐砸，而且還有把手以方便搬運。",
  str_item_intro_5234029 = "只要一個人簡單操作就能紡出布料的機器，就是維護起來複雜了一些......",
  str_item_intro_5234030 = "種有茂盛青草的罈子，很沉，需要用點力氣才能搬動。",
  str_item_intro_5234033 = "覆滿了藤蔓的架子，在夏日能提供陰涼，即便在深秋時節也能留存一份綠意。",
  str_item_intro_5234036 = "用三層石頭堆起來的花壇，不僅可以讓花朵在最頂層吸引目光，下面兩層還能種上綠草，以做陪襯。",
  str_item_intro_5241015 = "打開後，就能用放置其上的唱片來播放音樂的奇妙裝置。由於採用擴音喇叭，所以音樂能傳達到很遠的地方，久久迴響。",
  str_item_intro_5241017 = "水族箱",
  str_item_intro_5251001 = "風信塔",
  str_item_intro_5252001 = "陳列館",
  str_item_intro_5253001 = "商店",
  str_item_intro_5254001 = "祈望池",
  str_item_intro_5255001 = "堅固、防水、防塵的大箱子，能夠存放很多物品。",
  str_item_intro_5256001 = "與夥伴們的冒險中充滿了挑戰、驚險，也有各種歡聲笑語，為了紀念旅途中的這些令人難忘的點點滴滴，夥伴們製作了這些徽章，放在這裡，作為對空裔以及他們自己的獎勵與紀念。",
  str_item_intro_5270001 = "培育地塊",
  str_item_intro_5275001 = "為了愛與希望，將歌聲傳播到整個大陸吧！這種舞台專門為了巡演而建造，在快速建造的同時滿足了各種功能，而且很堅固，可滿足大家在上面的各種唱跳。",
  str_item_intro_5275002 = "只需要敲上幾個節奏，就能為演出增加氣氛！如果一個樂隊有領頭者，那一定就是鼓手啦~因此它可是巡演舞台上必不可少的。",
  str_item_intro_5275003 = "舞曲自然不能少了音樂作為鋪墊，鍵盤琴操作簡單，而且音色多變，好的鍵盤手就能自己成為一支樂隊~",
  str_item_intro_5275004 = "向星星許願吧！不知道什麼時候，在偶像粉絲的口中有了這種傳聞，據說向這種星星裝飾許願，就會讓自己的鼓勵傳達到偶像心中。",
  str_item_intro_5275005 = "為偶像加油鼓氣，不能少了應援物品，因此在巡演舞台附近放上這樣一張桌子，就能很方便地讓粉絲們領取到各種應援物品。",
  str_item_intro_5275006 = "為巡演而準備的各種吉他，不僅讓吉他手可以任意選用符合自己風格的吉他，也能讓多名吉他手一起演奏，為演出大大增加熱烈氣氛。",
  str_item_intro_5275007 = "巡演自然少不了這種擴音裝置，無論場地再大，觀眾再多，都能將偶像的聲音傳到每個人的耳中，而且它的外形很可愛哦~",
  str_item_intro_5275008 = "在巡演會場附近的裝飾，看著它們飄在天空、迎風飛舞的樣子，感覺也是在為了偶像而伴舞呢。",
  str_item_intro_5275009 = "放在巡演舞台附近的裝飾用燈，似乎是粉絲們用來鼓勵偶像所用，雖然並非官方出品，卻意外地很搭配。",
  str_item_intro_5275010 = "巡演怎麼能少了偶像的立牌？即使無法和偶像合影，甚至見不到偶像一面，只要看到這個立牌，粉絲們也會得到安慰吧。",
  str_item_intro_5275011 = "鮮花代表了祝福，許多鮮花則代表許多祝福。如果不是有所控制，可能整個巡演場地都會被粉絲們送的花籃所淹沒吧。",
  str_item_intro_5275012 = "據說這面牆上的星星裝飾都是粉絲們一個一個粘上去的，它已經不僅僅是裝飾品，更是粉絲的祝福，希望他們的偶像能巡演成功。",
  str_item_intro_5275013 = "為巡演專門安排的座椅，當然很多粉絲不願意坐著，更願意站著上面為偶像加油，當然，這樣做還有另一個原因——希望偶像能看到自己。",
  str_item_intro_5234043 = "雪是鬆軟的，那麼能不能用它來做沙發呢？可能很多人都有這種想法吧，當然這張沙發還是用普通材質做的，只不過靠背做成了雪山的樣子，加上鬆軟的坐墊，真有一種躺在雪上的感覺。",
  str_item_intro_5234044 = "據說這種奇妙的生物永遠不會老去。這件奇妙的陳設也是模仿了該傳說，如果盯上一會的話，可是會上癮的喔。",
  str_item_intro_5234045 = "即便天涯海角，也要傳達思念與心願！據說這種信箱就是專門為此設立的，盡量縮短思念的距離。",
  str_item_intro_5234046 = "若有不敢當面說的話語，就寫進信箋，留在這裡吧。相信對方會看到，也會明白你的心意。",
  str_item_intro_5276001 = "「冠月節」時經常搭設的禮台，適合舉辦各種聚會，尤其是情投意合之人的婚禮。",
  str_item_intro_5276002 = "無論是在慶典中遊行，還是乘坐去迎接新人，以派頭、裝飾和舒適度來說，這都是輛最好的車。",
  str_item_intro_5276003 = "似乎是一種新興的娛樂。情侶們在上面玩個幾圈下來後依舊能維持對彼此的照顧，就足以證明彼此的感情。",
  str_item_intro_5276004 = "據說亭子上的玫瑰經過特殊培育，只會在「冠月節」當天盛開，藉此祝福特來到此地的新人們。",
  str_item_intro_5276005 = "巧克力本來的口味苦澀，因為加了糖才擁有甜味。或許……這就是某些感情的真諦？無論如何，巧克力儼然已成冠月節的標誌性禮物之一，或許因為大多數人只記得甜味，忽略了其中的苦澀。",
  str_item_intro_5276006 = "造型別緻的拱門，上面綴滿了各色花朵。讓新人在此之下拍照留念或許願都再合適不過了。",
  str_item_intro_5276007 = "經常出現在「冠月節」的一種裝飾。由數盞盛滿飲品的高腳杯組成，專門用於款待賓客。",
  str_item_intro_5276008 = "飛揚的流線造型不僅讓這燭台看起來令人賞心悅目，也能讓蠟燭散發的光芒投射到各處，為新人的婚禮增添幾分浪漫。",
  str_item_intro_5276009 = "它應該是所有婚禮主持人的「夢中情人」了吧……若善用它，不僅可以讓在場賓客聽清楚兩位新人的誓詞，甚至還能用來播放音樂，為會場增添氣氛。",
  str_item_intro_5276010 = "即便不是在「冠月節」，這種長椅也很適合戀人們一起坐。若在「冠月節」當天，可能會坐滿出雙入對的人們吧。",
  str_item_intro_5276011 = "咦？原來他們是一對？哦……看來只是為了節日而做的換裝，不得不說看起來還挺登對。",
  str_item_intro_5276012 = "無論做為禮物還是裝飾都相當適合在「冠月節」上出現，不僅能為聚會增添鮮豔的色彩，還能讓賓客們享受到微微的芬芳。",
  str_item_intro_5276013 = "用玫瑰鋪成的地毯！如此奢華的安排代言了主辦人對這場典禮的態度。待新人們踏上它時，想必會受到所有來賓的注目吧。",
  str_item_intro_5276101 = "造型復古的一組桌椅，幸好坐起來還滿舒適的，而且還很適合進行某些會談，特別是商討推理案件的時候。這印象或許也是受到那位名偵探的影響吧。",
  str_item_intro_5276102 = "據說那位名偵探經常在這種樣式的記錄板上匯集情報、整理線索，並進行各種分析，甚至僅仰賴這一步驟便能找到犯人。",
  str_item_intro_5276103 = "自從聲名大噪之後，那位名偵探喜歡乘坐的車輛也連帶受到眾人的歡迎。畢竟結實耐用、速度快且容易操控的車輛，不管是誰都會喜歡的。",
  str_item_intro_5276104 = "「如果思考進了死胡同，就來一杯咖啡。如果依舊想不通，那就再來一杯。」作為沉思的最佳伴侶，那位名偵探在挑選咖啡器具時可是從不吝嗇金錢的。",
  str_item_intro_5276105 = "很多時候，犯罪都發生在清冷的夜晚，名偵探的著裝也多以能擋風的大衣和帽子為主，所以房間內自然也少不了這種衣帽架。",
  str_item_intro_5276106 = "小巧、輕便的手推車，通常用來放下午茶要用的咖啡、茶點等物品。方便僕人們在招待客人時可以盡快擺放好多種食物。",
  str_item_intro_5276107 = "推理的靈感枯竭，或是陷入思考迷宮時，那位名偵探特別愛用這種樂器稍作放鬆，此時整條街都能聽到他那差強人意的琴音。幸虧人們在意的並非演奏技巧，而是熱衷於名偵探的傳奇，因此仍對這種樂器趨之若鶩。",
  str_item_intro_5276108 = "寬而高的靠背，柔軟的墊子，讓人在維持良好坐姿的同時，又能感受到最大的舒適度，確實很適合「放鬆即思考」的偵探們。",
  str_item_intro_5276109 = "能放很多支菸斗的架子，造型別緻，更能彰顯家中的「偵探感」。當然，這也是因為推理迷對那位名偵探的追捧，所以即便不抽菸，也會擺上一組裝飾。",
  str_item_intro_5276110 = "「不能放過任何線索！」很多時候，魔鬼和真相都藏在細節裡，這種放大鏡可是一位名偵探不可少的標準配備。",
  str_item_intro_5276111 = "無論明亮度抑或持續時間都很優異的提燈，防風、重量輕，可以單手輕鬆提著。置於地面使用當然也沒問題。",
  str_item_intro_5276112 = "這面小黑板高度偏矮，恰恰適合那位名偵探坐在沙發椅中用它來整理案情，是快速分析案情的好幫手。",
  str_item_intro_5276113 = "這組兩腳書架的造型頗為特殊，卻很受那位名偵探喜愛，看來與眾不同的人，其審美觀也和大眾不同。身為一名偵探愛好者，自然是無論如何都要在家中擺設一組的。",
  str_item_intro_5276114 = "無論是陰雨天還是烈陽酷暑，傘都是好用的遮擋工具，緊急時刻還能作為武器使用。因此在門口放上這樣的一個傘桶，用於收納各種傘，想必也是有必要的吧。",
  str_item_intro_5234047 = "「如果一名作家置身於一座被暴風雪困住的山莊，其寫作效率會是原本的十倍。」——此話似乎成了不少影鎮編輯的信條之一，也導致這種品牌的打字機大為流行，一度成為文字工作者的專屬配備。",
  str_item_intro_5234048 = "若是要在影鎮開一間氣派的事務所，這種沙發不可或缺。無論是在現實還是故事中，主理人們都會坐於沙發上會客、面談大小事宜，或者進行某些交易。",
  str_item_intro_5223003 = "圓形的小地磚，用來作為草坪、路邊的點綴，再合適不過。",
  str_item_intro_5223004 = "比較大的圓形地磚，不僅可以用來鋪路，也能作為道路圖案中的主要組成部分。",
  str_item_intro_5351001 = "空庭中最明顯的建築，也是此處的地標，儲存著大量用於重建空庭的資料。",
  str_item_intro_5351002 = "空庭中最明顯的建築，也是此處的地標，儲存著大量用於重建空庭的資料。",
  str_item_intro_5351003 = "空庭中最明顯的建築，也是此處的地標，儲存著大量用於重建空庭的資料。",
  str_item_intro_5352001 = "為了展示各類物件、記錄並普及知識而設置的場所。",
  str_item_intro_5352002 = "不僅空間比原先的更大，而且略微經過裝飾，能夠很方便地觀看陳列品。",
  str_item_intro_5352003 = "加裝了更多房間的陳列館，不僅空間很多，而且還能方便地進行分類。",
  str_item_intro_5353001 = "空庭中的交易場所，不僅能進行一般的買賣，還有神祕訂單喔！",
  str_item_intro_5353002 = "新增富有流線型的外觀裝飾，比原先氣派了許多。",
  str_item_intro_5353003 = "擁有很多房間的商店，已經是一座專門用於交易的宅邸了。",
  str_item_intro_5354001 = "望著清澈的泉水，不僅能欣賞美麗的魚，據說還能丟進硬幣來許願。",
  str_item_intro_5354002 = "較大的水池，不僅能欣賞到交錯波光下游動的魚，許願似乎也更加靈驗了。",
  str_item_intro_5354003 = "噴泉不僅為魚們帶來了流動的活水，據說還能讓心願都能實現喔～",
  str_item_intro_5355001 = "堅固、防水、防塵的大箱子，能夠存放很多物品。",
  str_item_intro_5276201 = "一般是白夜城公侯使用的庭座，足以彰顯上流貴族的氣派，為覲見者帶來不小的震撼，藉此讓對方下意識約束自身舉止。當然，位於其上的人也要有足夠的氣質才行。",
  str_item_intro_5276202 = "「方寸之中，別有天地。」據說這顆水晶球裡藏著一座城市的「幻影」，不過對於某些人來說，那可能是極為珍貴的回憶。",
  str_item_intro_5276203 = "「善待弱者、勇對暴權。」騎士，白夜城的一方基石，亦是白夜城的一面旗幟。雖然不知道這座雕像的名字，但是看到那巍然的身姿，即便是平民也能湧出一股騎士的精神。",
  str_item_intro_5276204 = "「眾多收集，自應展示，若將其祕藏於寶庫，則是暴殄天物。」這架展示櫃不僅裝飾華貴，結構也很牢固，既實用又美觀，足以放置任何收藏品。",
  str_item_intro_5234049 = "「將文字鐫刻於石碑，可存萬年之久。」在雕刻百年之後，城市荒廢、文明凋零，惟方碑依舊矗立，令後人得以窺見今時之景，想必就是它存在的意義。",
  str_item_intro_5276206 = "多用於白夜城貴族宅邸中的長桌。寬大、厚實、氣派，無論是宴請賓客、款待親友、家族聚會，甚至是商談要事都上得了檯面。",
  str_item_intro_5276207 = "在白夜城貴族宅邸中常見的高背椅，不僅舒適，也能讓就坐者維持端莊威嚴的姿勢而不會失態。",
  str_item_intro_5276208 = "白色的旗幟，白色的城市。身為白夜城的代表，很多時候只要看到它，就會想到白夜城——騎士、貴族、天空與文明。",
  str_item_intro_5276209 = "在人們的印象中，這種燈永遠不會熄滅，得益於白夜城強大的光能術，事實也的確如此。",
  str_item_intro_5276210 = "造型雅致的低矮圍欄，目的並非阻止外人進入，而是用於劃定貴族宅邸、莊園的邊界。",
  str_item_intro_5276211 = "即使只是小小一個盆栽，白夜城也與他處不同，不僅花瓶造型高大、精緻，其中植物也高大繁茂，看來位於這天空之上，一定吸收了足夠的陽光。",
  str_item_intro_5276212 = "藤蔓叢生，爬滿高架。雖錯落卻有序，間隙不疏不密，正好令陽光能點點撒入，不至於令人焦躁，若有微風拂過，真是個悠閒享受下午茶的好去處。",
  str_item_intro_5234050 = "雖然沒有真的摩天輪那樣宏偉，但是看起來也很大了，可惜不能坐，只能遠遠看著它轉動，回憶一下乘坐摩天輪的感覺。",
  str_item_intro_5234052 = "藍色的外殼、巨大的水倉，在沙漠中它不再是戰鬥的化身，而是潑灑雨露的恩澤之神，為乾旱的大家帶來涼爽與舒潤。",
  str_item_intro_5234053 = "栩栩如生的雕塑，乍看之下以為是某隻可憐的鳥被沙子團團包裹了。請注意，別讓它碰到水，否則會「消失」成一灘沙子的。",
  str_item_intro_5234054 = "這椅子……真的能坐嗎？那些花朵確實很美麗，但是椅子上滿布的荊刺又不斷發出警告——「請保持坐姿端正，否則就會受傷。」",
  str_item_intro_5400001 = "能令奇異樹的培育時間大大縮短的神祕液體，十分容易揮發，所以一定要裝在瓶子中。",
  str_item_intro_5400002 = "似乎是從頂級奇異樹中提取的汁液的混合，熬煉後加入神祕配方形成的粘稠液體，能改變頂級奇異樹的品種。\n外形：粘稠的綠色液體，帶有黃色污泥。",
  str_item_intro_5401001 = "樹木 C-B 必定突破道具",
  str_item_intro_5401002 = "樹木 B-A 必定突破道具",
  str_item_intro_5401003 = "樹木 A-S 必定突破道具",
  str_item_intro_5402001 = "樹木 C-B 定向突破道具",
  str_item_intro_5402002 = "樹木 B-A 定向突破道具",
  str_item_intro_5402003 = "樹木 A-S 定向突破道具",
  str_item_intro_5403001 = "不常見的細碎晶體，會散發各色光芒，其中蘊含的力量能讓奇異樹的顏色產生多種變化。",
  str_item_intro_5403002 = "樹木 染色晶體II型",
  str_item_intro_5403003 = "樹木 染色晶體III型",
  str_item_intro_5409001 = "甲系樹苗",
  str_item_intro_5409002 = "乙系樹苗",
  str_item_intro_5409999 = "這是紅色昆嵐樹【基礎】的種子",
  str_item_intro_5411111 = "這是紅色昆嵐樹【基礎】的種子",
  str_item_intro_5411112 = "這是昆嵐樹【基礎】的種子",
  str_item_intro_5411113 = "這是黃色昆嵐樹【基礎】的種子",
  str_item_intro_5411211 = "這是紅色小葉昆嵐樹【精品】的種子",
