  str_item_intro_5411221 = "這是紅色大葉昆嵐樹【精品】的種子",
  str_item_intro_5411222 = "這是大葉昆嵐樹【精品】的種子",
  str_item_intro_5411223 = "這是褐色大葉昆嵐樹【精品】的種子",
  str_item_intro_5411311 = "這是和煦昆嵐樹【珍品】的種子",
  str_item_intro_5411312 = "這是藍色和煦昆嵐樹【珍品】的種子",
  str_item_intro_5411313 = "這是黃色和煦昆嵐樹【珍品】的種子",
  str_item_intro_5411321 = "這是紅色盛陽昆嵐樹【珍品】的種子",
  str_item_intro_5411322 = "這是盛陽昆嵐樹【珍品】的種子",
  str_item_intro_5411323 = "這是藍色盛陽昆嵐樹【珍品】的種子",
  str_item_intro_5411331 = "這是粉色冷鬱昆嵐樹【珍品】的種子",
  str_item_intro_5411332 = "這是紅色冷鬱昆嵐樹【珍品】的種子",
  str_item_intro_5411333 = "這是冷鬱昆嵐樹【珍品】的種子",
  str_item_intro_5411341 = "這是藍色凜冽昆嵐樹【珍品】的種子",
  str_item_intro_5411342 = "這是凜冽昆嵐樹【珍品】的種子",
