  str_item_intro_5421111 = "用瑰色琉璃培育出的紅色昆嵐樹，看起來有著旺盛的生命力。",
  str_item_intro_5421112 = "剛培育出來的基礎昆嵐樹，乍看不見任何異樣，但微風吹拂下會發出奇妙聲響。",
  str_item_intro_5421113 = "用瑰色琉璃培育出的黃色昆嵐樹，給人些許蕭瑟印象。",
  str_item_intro_5421211 = "經歷細微突變而來的小葉昆嵐樹，再以瑰色琉璃培育而得的品種，有一種類似於紅瑪瑙的色彩。",
  str_item_intro_5421212 = "經歷細微突變而來的精品昆嵐樹，樹葉偏小且密集，因此得名。",
  str_item_intro_5421213 = "經歷細微突變而來的小葉昆嵐樹，再以瑰色琉璃培育而得的品種，黃色的葉子在微風下擺動時會呈現奇妙的波瀾。",
  str_item_intro_5421221 = "經歷細微突變而來的小葉昆嵐樹，再以瑰色琉璃培育而得的品種，每一片葉子看起來都有如薄薄的紅色水晶。",
  str_item_intro_5421222 = "經歷細微突變而來的精品昆嵐樹，樹葉寬大結實，幾乎可直接用於縫製成衣。",
  str_item_intro_5421223 = "經歷細微突變而來的大葉昆嵐樹，再以瑰色琉璃培育而得的品種，整棵樹看起來頗有秋天的氣息。",
  str_item_intro_5421311 = "經歷多次突變而來的珍品昆嵐樹，樹冠成團，樹葉光滑而緊密，別有風味。",
  str_item_intro_5421312 = "經歷多次突變而來的和煦昆嵐樹，再以瑰色琉璃培育而得的品種，藍色的樹冠十分賞心悅目。",
  str_item_intro_5421313 = "經歷多次突變而來的和煦昆嵐樹，再以瑰色琉璃培育而得的品種，黃色樹葉層層疊疊，縱有強風吹襲也無法使之散開。",
  str_item_intro_5421321 = "經歷多次突變而來的盛陽昆嵐樹，再以瑰色琉璃培育而得的品種，紅色的樹冠色調熾烈。",
  str_item_intro_5421322 = "經歷多次突變而來的珍品昆嵐樹，樹冠茂密，枝幹粗壯，有著旺盛的活力。",
  str_item_intro_5421323 = "經歷多次突變而來的盛陽昆嵐樹，再以瑰色琉璃培育而得的品種，遠遠望去，其藍天樹冠仿佛湖水一般，令人感到寧靜。",
  str_item_intro_5421331 = "經歷多次突變而來的冷鬱昆嵐樹，再以瑰色琉璃培育而得的品種，粉色樹葉配合其樹冠與樹身，為其加上些許春日氣息。",
  str_item_intro_5421332 = "經歷多次突變而來的冷鬱昆嵐樹，再以瑰色琉璃培育而得的品種，紅色的樹冠與本源的冷豔氣息形成強烈的反差。",
  str_item_intro_5421333 = "經歷多次突變而來的珍品昆嵐樹，樹葉參差不齊，纖細而堅硬，有種冷豔的氣質。",
  str_item_intro_5421341 = "經歷多次突變而來的盛陽昆嵐樹，再以瑰色琉璃培育而得的品種，藍色的樹冠在原有的凜冽之上更增添一抹寒冷。",
  str_item_intro_5421342 = "經歷多次突變而來的珍品昆嵐樹，樹葉邊緣鋒利，呈現不規則的凸起，微風吹過樹冠的樣子彷彿舞動的利刃，形成一種凜冽的印象。",
  str_item_intro_5421343 = "經歷多次突變而來的凜冽昆嵐樹，再以瑰色琉璃培育而得的品種，淡黃色樹葉弱化了原本的凜冽氣息，更帶來一絲溫暖。",
  str_item_intro_5421411 = "經歷複雜突變而來的仰空昆嵐樹，再以瑰色琉璃培育而得的品種，藍色樹冠彷彿擁有純潔之心的信者，仰望藍天衷心祈禱，因此有了別名「祈禱昆嵐樹」。",
  str_item_intro_5421412 = "須歷經複雜突變才能培育出的稀世昆嵐樹，形似一座仰天而張的喇叭，很難想像單憑那細瘦的枝幹竟能支撐起如此巨大的樹冠，只能解釋為某種奇異力量所致。",
  str_item_intro_5421413 = "歷經複雜突變而來的仰空昆嵐樹，再以瑰色琉璃培育而得的品種，黃色的喇叭形樹冠看起來就像一支黃銅號角，據說在遠古時，真的有巨人曾吹奏它們！因故得名「號角昆嵐樹」。",
  str_item_intro_5421421 = "歷經複雜突變而來的磐石昆嵐樹，再以瑰色琉璃培育而得的品種，站在綠色樹冠上，會有一種身處原野丘陵之上的錯覺，因此別名「小丘昆嵐樹」。",
  str_item_intro_5421422 = "歷經複雜突變而來的磐石昆嵐樹，再以瑰色琉璃培育而得的品種，潔白樹冠外形十分平整，甚至可以在上面安心睡個好覺。",
  str_item_intro_5421423 = "須歷經複雜突變才能培育出的稀世昆嵐樹，十分珍貴，樹冠硬化成為一座小石檯！據說樹幹內有一根支撐它的石桿，只不過外側被厚重樹皮包起來看不見......如此奇異的樹是否還能視之為植物，確實有待商榷。",
  str_item_intro_5421431 = "須歷經複雜突變才能培育出的稀世昆嵐樹，極度稀有，樹葉成絲狀，輕柔、細軟，纏成一團，看起來彷彿傳說中飄動的靈魂，也有人認為這種昆嵐樹確實有意識，甚至有靈魂......",
  str_item_intro_5421432 = "歷經複雜突變而來的盛陽昆嵐樹，再以瑰色琉璃培育而得的品種，紅色樹冠營造出一種不祥的氣息，卻有股致命的吸引力，那片輕柔絲葉隨風舞動的樣子很容易使人沉迷，不禁看上幾天幾夜。",
  str_item_intro_5421433 = "歷經複雜突變而來的魂靈昆嵐樹，再以瑰色琉璃培育而得的品種，黃色的樹葉形成各式各樣的飄逸緞帶，在樹冠上搖晃，彷彿在歡迎某人到來，因此有了別名「迎賓昆嵐樹」。",
  str_item_intro_5421441 = "須歷經複雜突變才能培育出的稀世昆嵐樹，極為稀有，樹葉交匯而成一片巨大而緊密的樹冠，不時間會有樹葉從中飛出，形成奇妙的「落葉之雨」的景象。",
  str_item_intro_5421442 = "歷經複雜突變而來的怒放昆嵐樹，再以瑰色琉璃培育而得的品種。綠色樹冠看起來十分有生命力，而且如果接近那垂下的枝條，不僅枝條會微微顫動，整棵書也會「沙沙」作響，仿佛在回應來者......",
  str_item_intro_5421443 = "歷經複雜突變而來的怒放昆嵐樹，再以瑰色琉璃培育而得的品種。當藍色的樹葉紛紛落下時，會令人有種置身河海之中的錯覺，因此別名「陸上藍海昆嵐樹」。",
  str_item_intro_5421451 = "須歷經複雜突變才能培育出的稀世昆嵐樹，極為稀有，其生命力相當旺盛，據說將其砍斷後依舊能再度生長，因此也被人稱為「從不低頭的強者」。",
  str_item_intro_5421452 = "歷經複雜突變而來的不屈昆嵐樹，再以瑰色琉璃培育而得的品種。雖然棕黃色的樹葉看起來令其帶有一絲衰老的氣息，然而其生命力反而更加頑強，據說不用澆水都能生存。",
  str_item_intro_5421453 = "歷經複雜突變而來的不屈昆嵐樹，再以瑰色琉璃培育而得的品種。生長迅速，幾乎能在一夜之間就在枝頭上形成藍色葉子組成的樹冠，故而別名「生生不息的蔚藍樹海」。",
  str_item_intro_5421461 = "須歷經複雜突變才能培育出的稀世昆嵐樹，極為稀有，會從根部兩邊生長，最終樹幹結成中空的輪圈狀，宛如一道樹木製成的門框，因此也被人稱為「昆嵐楣」。",
  str_item_intro_5421462 = "歷經複雜突變而來的櫱侖昆嵐樹，再以瑰色琉璃培育而得的品種。藍色樹門偶爾會泛有水蒸氣，冬天時會結成一層霜花，遠遠看去仿佛是冰雪凝結而成。",
  str_item_intro_5421463 = "歷經複雜突變而來的櫱侖昆嵐樹，再以瑰色琉璃培育而得的品種。紅色樹門不會令觀者感到恐懼，反而會心生一種溫暖的安寧之感，也有人說能為種植者帶來好運。",
  str_item_intro_5421471 = "要經過複雜突變才能出現的稀世昆嵐樹，極為稀有，由於分叉的樹幹以及樹冠在微風下的搖曳身姿，加上露水形成的涓涓細流，擁有一種令人放鬆的奇妙力量，因而獲名「悠閒的昆嵐」。",
  str_item_intro_5421472 = "將經過複雜突變而來的怡愉昆嵐樹，以瑰色瑠培育後得到的品種，收集到的露水呈藍色，遠遠望去令這株昆嵐樹彷彿浸沒在淺海一般，因而獲名「近海休憩之處」。",
  str_item_intro_5421473 = "將經過複雜突變而來的怡愉昆嵐樹，以瑰色瑠培育後得到的品種，紫色露水令整株奇異樹擁有了一絲妖艷氣息，此時在微風下顯得悠然自得的搖曳身姿，也變成帶有魅惑的引誘了。",
  str_item_intro_5421481 = "要經過複雜突變才能出現的稀世昆嵐樹，極為稀有，直立的樹幹，加上那團火焰形狀的樹冠，形成了一株類似火炬的高大樹木，或許真的有人錯拿它們當做照明物呢！",
  str_item_intro_5421482 = "將經過複雜突變而來的炬焰昆嵐樹，以瑰色瑠培育後得到的品種，巨大的粉色樹冠像是一團奇妙的霧氣般浮在樹幹枝頭。若有風吹過，那團「粉色水霧」的樹冠則會變成不規則的形狀，別有異樣感覺。",
  str_item_intro_5421483 = "將經過複雜突變而來的炬焰昆嵐樹，以瑰色瑠培育後得到的品種，紅色的樹冠讓它成為名副其實的「火炬」，尤其被風吹動的時候，真的有那種烈火燎原的錯覺！",
  str_item_intro_5422111 = "以瑰色琉璃培育而得的淺綠色亞氏樹，比原生種更加挺拔，且有股孤傲的氣質。",
  str_item_intro_5422112 = "以瑰色琉璃培育而得的墨綠色亞氏樹，形態沉穩，令人心神寧靜。",
  str_item_intro_5422113 = "剛培育出來的基礎亞氏樹，看不出異樣，唯其挺拔的主幹、緊湊的細枝，以及向上生長的針狀樹葉，彰顯出它的與眾不同。",
  str_item_intro_5422211 = "經歷細微突變而來的短葉亞氏樹，再以瑰色琉璃培育而得的品種，紅色針葉十分短小，落下於樹腳形成一片紅色地毯，賞心悅目。",
  str_item_intro_5422212 = "經歷細微突變而來的短葉亞氏樹，再以瑰色琉璃培育而得的品種，短小的針葉有著翠綠的紋理，彷彿一顆顆亮晶晶的綠寶石。",
  str_item_intro_5422213 = "經歷細微突變而來的精品亞氏樹，與原種大不相同，枝幹向外延伸的同時，樹冠稀疏，樹葉也變得短粗，若無特意標註，恐怕難以意識到它由亞氏樹異變而來。",
  str_item_intro_5422221 = "經歷細微突變而來的長葉亞氏樹，再以瑰色琉璃培育而得的品種，樹葉落地後會很快變乾，被踩到即發出清脆悅耳的「咔嚓」聲。",
  str_item_intro_5422222 = "經歷細微突變而來的長葉亞氏樹，再以瑰色琉璃培育而得的品種，細長的葉子柔軟又堅韌，用其製作的筆桿廣受人們喜愛。",
  str_item_intro_5422223 = "經過微小突變的精品亞氏樹，外形卻有極大變化，枝杈肆意生長，樹葉轉為細長，難以想像它的源頭是那般挺拔的亞氏樹。",
  str_item_intro_5422311 = "經歷多次突變而來的珍品亞氏樹，樹冠與枝幹融為一體，整體宛如一高嶺堅石，表面硬化，內部中空，敲打可聽見奇妙的迴音。",
  str_item_intro_5422312 = "經歷多次突變而來的高嶺亞氏樹，再以瑰色琉璃培育而得的品種，枝幹一側的綠色紋理，常被誤認為附著其上的青苔。",
  str_item_intro_5422313 = "經歷多次突變而來的高嶺亞氏樹，以瑰色琉璃培育後得到的品種，部分樹皮已略呈現出些許紅色，從而衍生出幾則恐怖的傳說，不過全屬無稽之談。",
  str_item_intro_5422321 = "經歷多次突變而來的珍品亞氏樹，樹冠低垂，長而柔軟的枝幹從中垂落，遠看彷彿一片小樹林，因此它也有著「獨木成林」的美譽。",
  str_item_intro_5422322 = "經歷多次突變而來的獨林亞氏樹，再以瑰色琉璃培育而得的品種，紅色的巨大樹冠彷若傘蓋，足以遮擋酷烈驕陽，為人們投下一片涼爽的樹蔭。",
  str_item_intro_5422323 = "經歷多次突變而來的獨林亞氏樹，以瑰色琉璃培育後得到的品種，綠色的巨大樹冠，加上垂下的粗壯枝幹，身處其中恐怕會以為自己誤入了一片小樹林。",
  str_item_intro_5422331 = "經歷多次突變而來的荒原亞氏樹，再以瑰色琉璃培育而得的品種，蒼白淒涼感的樹冠配上龜裂的樹幹，很多人會誤以為它已枯死，待他們見證這棵樹挺立許久，自會改變想法。",
  str_item_intro_5422332 = "經歷多次突變而來的珍品亞氏樹，因為酷似在荒原上隨處可見的枯樹而得名，不過生在它扭曲樹幹上的小樹冠則彰顯著頑強的生命力，彷彿在對眾人大喊「我還活著」。",
  str_item_intro_5422333 = "經歷多次突變而來的荒原亞氏樹，以瑰色琉璃培育後得到的品種，綠色樹冠與枯槁的枝幹形成強烈對比，甚至令人不禁懷疑兩者並非一體，然而事實是它們確實屬於同一棵樹，或許這就是奇異樹的魅力所在。",
  str_item_intro_5422341 = "經歷多次突變而來的泉池亞氏樹，再以瑰色琉璃培育而得的品種，汁液是淡黃色，初入口時口感略硬，後味卻有些許甘甜，據說對恢復體力有幫助，也有人說喝多會頭昏腦脹。",
  str_item_intro_5422342 = "經歷多次突變而來的珍品亞氏樹，因樹根處形成天然池子，樹冠末梢還會不停向其滴水而得名。這種神祕的循環至今無人能明白其原理以及存在的意義，只能飲用一口樹根池子中的水，並感嘆異變的力量。",
  str_item_intro_5422343 = "經歷多次突變而來的泉池亞氏樹，以瑰色琉璃培育後得到的品種，其聚積的池水帶有綠色，乍看可能誤以為有毒，實則清涼無比，並有沁人心脾的微香，令人萬分詫異。",
  str_item_intro_5422411 = "經歷多次突變而來的輝硯亞氏樹，再以瑰色琉璃培育而得的品種，一部分樹乾和樹冠都閃耀綠色的光芒，彷彿有涓涓溪水在其間流動，甚為夢幻。",
  str_item_intro_5422412 = "須歷經複雜突變才能培育出的稀世亞氏樹，十分少見，其樹根外露，樹幹膨脹並硬化，樹冠則變成一團發光的葉團！遠遠看去彷彿一座矮小的燈塔，因此得名「燈塔亞式樹」。",
  str_item_intro_5422413 = "歷經複雜突變而來的輝硯亞氏樹，再以瑰色琉璃培育而得的品種，石檯形狀的樹幹和樹冠都閃耀金色，不知者甚至會以為來到某座金碧輝煌的宮殿，因此別名「宮殿亞氏樹」。",
  str_item_intro_5422421 = "須歷經複雜突變才能培育出的稀世亞氏樹，其部分樹幹與硬化樹冠結合，形成一座座中空的石盤！這石盤外壁堅硬卻十分薄，敲擊之會產生多種多樣的聲音，甚至有人說它會利用樹冠說話......",
  str_item_intro_5422422 = "歷經複雜突變而來的煌磐亞氏樹，再以瑰色琉璃培育而得的品種，綠色的巨大樹冠彷彿碧綠的寶石，輕輕敲打就能發出各種清脆悅耳的響聲，因此得名「亞氏樹中的音樂家」。",
  str_item_intro_5422423 = "歷經複雜突變而來的煌磐亞氏樹，再以瑰色琉璃培育而得的品種，藍色石盤會發出悠揚的聲音，還會微微顫動，形成夢幻的閃藍色殘影。",
  str_item_intro_5422431 = "歷經複雜突變而來的耀藏亞氏樹，再以瑰色琉璃培育而得的品種，黃色樹心散發光芒時，樹幹的紋理上會映出淡黃樹葉的片片幻影，感覺這株奇異樹又有了生命力！因此得名「亞氏樹中的複活者」。",
  str_item_intro_5422432 = "須歷經複雜突變才能培育出的稀世亞氏樹，樹幹已經中空，其內的樹心形成奇特的菌菇造型並散發奇妙光芒。據說一旦感知到危險，外側樹皮就會闔上以遮擋光芒，也因此有了「藏匿光輝的亞氏樹」之名。",
  str_item_intro_5422433 = "歷經複雜突變而來的耀藏亞氏樹，再以瑰色琉璃培育而得的品種，從樹心出散射的藍色光芒經過中空樹幹的偏折，構成此樹被涓涓溪流所縈繞的錯覺，甚至會誤以為它位處水下......",
  str_item_intro_5422441 = "須歷經複雜突變才能培育出的稀世亞氏樹，部分樹枝和樹葉已經結合變異成了一架「提燈」，而其中充當「燈芯」的樹枝，還能散發溫暖的光亮！這無疑為那些漫步於漆黑野外的旅人們，提供了一盞明燈。",
  str_item_intro_5422442 = "歷經複雜突變而來的燁明亞氏樹，再以瑰色琉璃培育而得的品種。據說它的樹幹中蘊含著某種特別的光能，因此其「提燈」散發著溫和的藍色光芒。",
  str_item_intro_5422443 = "歷經複雜突變而來的燁明亞氏樹，再以瑰色琉璃培育而得的品種。其樹葉是紅色，但「提燈」則散發著淺紅色，映在白色樹幹上，別有韻味。",
  str_item_intro_5422451 = "須歷經複雜突變才能培育出的稀世亞氏樹，樹冠已經消失，數條亮色花瓣組成的藤蔓遍布樹幹之上，有的垂下，有的在枝幹間相連，遠遠看去仿佛樹木上結成了一道花門。",
  str_item_intro_5422452 = "歷經複雜突變而來的珖茵亞氏樹，再以瑰色琉璃培育而得的品種。其白色花瓣摸起來清冷無比，然而一旦摘下握在手中，卻又會感覺到一絲溫度。",
  str_item_intro_5422453 = "歷經複雜突變而來的珖茵亞氏樹，再以瑰色琉璃培育而得的品種。擁有獨特的綠色花瓣，看起來仿佛就是樹葉，只有近距離觀察才能分辨。",
  str_item_intro_5422461 = "須歷經複雜突變才能培育出的稀世亞氏樹，沒有樹冠，而是從枝幹末梢長出巨大樹葉包裹而成的圓球！這被人稱之為「螢團」的圓球中似乎蘊含光能，微風吹過後，點點光能會隨著破碎的葉屑飄出，為周圍帶來點點亮光。",
  str_item_intro_5422462 = "歷經複雜突變而來的螢曄亞氏樹，再以瑰色琉璃培育而得的品種。其「螢團」散發著宛如大海的碧藍色，當它在風中飄動時，給人仿佛巨大水球在跳舞的錯覺，因此別名「奇異樹中的水舞者」。",
  str_item_intro_5422463 = "歷經複雜突變而來的螢曄亞氏樹，再以瑰色琉璃培育而得的品種。黃色的「螢團」帶有強烈的生命氣息，能感受到它內在的旺盛活力，能為周圍的植物帶來令之欣欣向榮的支持。",
  str_item_intro_5422471 = "經歷複雜突變才能出現的稀世亞氏樹，樹冠已經完全變異，凝聚成一整片，向四周下垂，呈現奇特的碗狀。「碗」的中心伸出的奇妙枝幹，宛如火炬一樣閃著微光，無時無刻吸引著觀賞者的目光。",
  str_item_intro_5422472 = "經歷複雜突變而來的璀薈亞氏樹，再以瑰色琉璃培育而得的品種，其碗狀樹冠呈現令人安心的藍色，經由中間枝幹散發的光芒映照，竟然有種身處深水區的錯覺，因此別名「淵之幻覺」。",
  str_item_intro_5422473 = "經歷複雜突變而來的璀薈亞氏樹，再以瑰色琉璃培育而得的品種，站在下方，能看到紅色樹冠彷彿血色殘陽般遮天蔽日，令人有種黃昏的錯覺。",
  str_item_intro_5422481 = "經歷複雜突變才能出現的稀世亞氏樹，整棵樹已經完全硬化，形成類似石台的東西，頂端落下的潺潺細流正好匯入下方的樹洞，形成一幅奇妙的景象。",
  str_item_intro_5422482 = "經歷複雜突變而來的焢硯亞氏樹，再以瑰色琉璃培育而得的品種，樹梢呈白色，和流淌而下的淺藍色溪水交織出清新的景觀，讓人感覺只是站在下方聽著潺潺流水聲就無比愜意，因此別名「悅耳之滴」。",
  str_item_intro_5422483 = "經歷複雜突變而來的焢硯亞氏樹，再以瑰色琉璃培育而得的品種，樹幹和頂端的「樹枝」都呈現奇妙的藍色，若透過滴落的黃色溪水看去，會有種異樣的感覺，故也有「朦朧的紫色之藍」之名。",
  str_item_intro_5423111 = "剛剛培育出來的基礎朵然樹就已經顯示出它的獨特性，那就是盛開的花朵。",
  str_item_intro_5423112 = "以瑰色琉璃培育而得的紫色朵然樹，有著令人迷離的微光。",
  str_item_intro_5423113 = "以瑰色琉璃培育而得的黃色亞氏樹，在光芒映襯下，有一種日暮的感覺。",
  str_item_intro_5423211 = "經歷細微突變而來的精品朵然樹，就已經幾乎變成另一個品種，源自一條樹根的多棵樹幹從地下伸出，總會令人誤認為是出現了好幾株植物。雖然外貌與基礎的朵然樹大相徑庭，但每根樹幹上的花朵，足以體現它是由其異變而來。",
  str_item_intro_5423212 = "經歷細微突變而來的紛節朵然樹，再以瑰色琉璃培育而得的品種，淡黃色的花朵看起來宛如微縮的太陽，若聚在一起甚至會令人感覺目眩。",
  str_item_intro_5423213 = "經歷細微突變而來的紛節朵然樹，再以瑰色琉璃培育而得的品種，淡藍色的花朵十分輕盈，隨風擺動時宛如天上的雲朵。",
  str_item_intro_5423221 = "經歷細微突變而來的精品朵然樹，樹幹變粗，花朵卻完全變成了另外一種樣子，喇叭形狀的花朵中生有很多花蕊，故得此名。",
  str_item_intro_5423222 = "經歷細微突變而來的繁蕊朵然樹，再以瑰色琉璃培育而得的品種，藍色花朵中的蕊包含水分，完全可以用來解渴，甚至還能釀造飲品！",
  str_item_intro_5423223 = "經歷細微突變而來的繁蕊朵然樹，再以瑰色琉璃培育而得的品種，花蕊與花朵顏色一致，都是熾烈的火紅色，與普通的繁蕊朵然樹不同，這種花蕊在被取出後很快就會變得乾硬、鬆軟，很適合用於引火。",
  str_item_intro_5423311 = "經歷多次突變而來的珍品朵然樹，花朵位於主幹，從根部深處的多條枝幹，宛如侍從一般將其包圍，因此也別名「被拱衛的花朵之木」。",
  str_item_intro_5423312 = "經歷多次突變而來的翹悅朵然樹，再以瑰色琉璃培育而得的品種，花朵和花瓣變成了接近金的黃色，在日光照耀下，遠遠望去彷彿映照上了一層明亮的晃動。",
  str_item_intro_5423313 = "經歷多次突變而來的翹悅朵然樹，淺藍色的花朵和花瓣令樹乾和枝葉顯得有些鋒利，某些人便稱之為「藍色鋒銳之植」。",
  str_item_intro_5423321 = "經歷多次突變而來的翠葛朵然樹，樹幹彎曲成圓形，密集的花朵形成的樹冠是垂下來的，真是令人驚嘆是如何支撐的，只能感嘆它的奇妙了。",
  str_item_intro_5423322 = "經歷多次突變而來的翠葛朵然樹，再以瑰色琉璃培育而得的品種，垂下的藍色花朵配合圓形枝幹，形成了天然的門廊，即便放在建設好的園林中，也沒有任何不協調的感覺。",
  str_item_intro_5423323 = "經歷多次突變而來的翠葛朵然樹，花瓣已經成為鮮嫩的白色，微風拂過，身處花團之下，便可感受到陣陣清香，因此它也成為了某些香水的重要原料。",
  str_item_intro_5423331 = "經歷多次突變而來的珍品朵然樹，其樹幹扭結、彎曲，遠觀之彷彿盛開的花，令人忽略了其上生長的花朵，根據學者的研究，它如此生長的原因是為了保護花朵免遭某些生物垂涎，因此才將枝幹生長成如此的模樣。",
  str_item_intro_5423332 = "經歷多次突變而來的芭漓朵然樹，再以瑰色琉璃培育而得的品種，枝幹尖端暈染成了淺藍色，從枝幹上低落的露水則更深一些，據說能用於書寫，也是良好的染料。",
  str_item_intro_5423333 = "經歷多次突變而來的芭漓朵然樹，枝幹末梢為淺綠色，樹根部的水池中也散發著碧色光芒，帶有強烈的自然氣息。",
  str_item_intro_5423341 = "經歷多次突變而來的珍品朵然樹，據說型態很類似遠方的一種樹，怒放的花朵不僅美麗，而且帶有淡香，駐足觀看良久之後，甚至會看到彩虹的幻像......當然這只是一個傳說，然而它卻以此得名。",
  str_item_intro_5423342 = "經歷多次突變而來的箋霞朵然樹，再以瑰色琉璃培育而得的品種，紫色的花朵分外妖嬈，由於色彩強烈，作為裝飾或點綴的時候，一定要適度使用。",
  str_item_intro_5423343 = "經歷多次突變而來的箋霞朵然樹，黃色的花朵幾乎全天都在怒放，帶有強烈的生命氣息，也有傳言說用其花蕊製作的藥水，能帶來活力，因此別名「生生不息的彩虹之樹」。",
  str_item_intro_5423411 = "須歷經複雜突變才能培育出的稀世朵然樹，雖然花冠只有一朵，但十分巨大，色彩極為絢爛，香氣更是帶有一絲危險的甜膩，據說花蕊還是上佳的調味料。由於它很容易令觀賞者沉迷其中，又得名「魅惑眾生的妖異之花」。",
  str_item_intro_5423412 = "經歷多次突變而來的妖蓉朵然樹，再以瑰色琉璃培育而得的品種，淺藍色的花冠會令人聯想到夏日的海浪，甚至會聞到略帶腥味的海風......因此也有人說，如果想去享受一下海邊的體驗，只要來看它就行了。",
  str_item_intro_5423413 = "歷經複雜突變而來的妖蓉朵然樹，再以瑰色琉璃培育而得的品種，花朵變成了更加危險的粉色，僅僅是看著它就能忘記一切憂愁，令人久久不願離去，因此某些觀賞者會定鬧鐘加以提醒，免得自己為了太過沉溺其中。",
  str_item_intro_5423421 = "須歷經複雜突變才能培育出的稀世朵然樹，花瓣繁多，而且修長柔細，遠遠看去彷若少女秀髮，其質感也極為細膩，據說之前有人嘗試將其作為織物，可惜將其從樹上取下後，即刻乾枯碎裂，令人扼腕不已。",
  str_item_intro_5423422 = "歷經複雜突變而來的芸鬢朵然樹，再以瑰色琉璃培育而得的品種，藍色的花冠令人不禁想到了傳說中擁有一頭藍髮的「海洋之女」，有人據說真的在它身旁聞到了深海的氣息......",
  str_item_intro_5423423 = "歷經複雜突變而來的芸鬢朵然樹，再以瑰色琉璃培育而得的品種，有人說那那一團綠色的花鬢中隱藏了神祕「花之靈魂」，如果能見到它，絕對會一見傾心......",
  str_item_intro_5423431 = "須歷經複雜突變才能培育出的稀世朵然樹，巨大的花冠成盤狀，似乎在仰望什麼，而且一旦被很多人注意到，就會微微側過去，力求不讓他人注意，因此也有「驕傲又嬌貴的仰望之花」的別名。",
  str_item_intro_5423432 = "歷經複雜突變而來的嬌望朵然樹，再以瑰色琉璃培育而得的品種，紅色花冠給人感覺帶有熾烈的情感，又有人傳言是在給它所望去的天空注入活力。",
  str_item_intro_5423433 = "歷經複雜突變而來的嬌望朵然樹，再以瑰色琉璃培育而得的品種，花瓣泛白，據說順著它望去的方向，會看到一些神祕的幻象，而且各自都不相同，因此它也被人稱之為「奇異幻境之製造者」。",
  str_item_intro_5423441 = "須歷經複雜突變才能培育出的稀世朵然樹，其花瓣整齊美麗，交錯層疊數片，只要一眼望去，觀者內心就會產生心醉的感覺，因而獲得許多少女的寵愛。",
  str_item_intro_5423442 = "歷經複雜突變而來的淑瑾朵然樹，再以瑰色琉璃培育而得的品種，藍色的花冠擁有令人迷醉的能力，很多觀者在其周圍都能聞到清新的氣息，彷彿雨後的藍天，因此別名「晴空之天」。",
  str_item_intro_5423443 = "歷經複雜突變而來的淑瑾朵然樹，再以瑰色琉璃培育而得的品種，紫色的花朵帶有危險的色彩，據說旁人在觀看它時，那花朵還會輕微地搖曳，散發妖艷氣息，令觀者沉溺於此……總之，請小心。",
  str_item_intro_5423451 = "須歷經複雜突變才能培育出的稀世朵然樹，巨大的花冠形成天然的漏斗，其花瓣內壁極為光滑，足以將清晨的露水收集起來，注入到樹幹內用以滋潤自身。",
  str_item_intro_5423452 = "歷經複雜突變而來的曦露朵然樹，再以瑰色琉璃培育而得的品種，紫色花冠會將收集起來的露水染上相同的顏色，某些學者認為這種露水帶有神祕的力量，專門用於書寫某些典籍。",
  str_item_intro_5423453 = "歷經複雜突變而來的曦露朵然樹，再以瑰色琉璃培育而得的品種，其花冠收集的露水會帶有一絲藍色，只要看上去就沁人心脾，似乎還能清除體內的不潔，因此也被人稱之為「清晨時分的潔淨者」。",
  str_item_intro_5423461 = "經過複雜突變才能出現的稀世朵然樹，花冠分成數朵輕而柔軟的長瓣，繞著花蕊交錯分布。據說某位設計師看過後靈光乍現，以這種花瓣造型設計了許多衣裙，因此也有著「美人裙」的別稱。",
  str_item_intro_5423462 = "將經過複雜突變而來的裙鎏朵然樹，以瑰色琉璃培育後得到的品種。橘色的花瓣看來頗有一絲誘惑的氣息，加上那特有的花香，令人不禁想起那些迷人又危險的存在……",
  str_item_intro_5423463 = "將經過複雜突變而來的裙鎏朵然樹，以瑰色琉璃培育後得到的品種。花瓣轉為天空般澄澈的顏色，加上白色葉片的點綴，給人一種清新、潔淨之感，頗受孩童喜愛。",
  str_item_intro_5423471 = "經過複雜突變才能出現的稀世朵然樹，花冠與花蕊形成宛如蝴蝶的造型，不僅迷惑了賞花者，甚至也引來真的蝴蝶在花朵旁翩翩起舞，彷彿在崇敬神明。",
  str_item_intro_5423472 = "將經過複雜突變而來的蝶瀾朵然樹，以瑰色琉璃培育後得到的品種。從遠方看去，巨大的黃色花冠仿佛一隻逗留在大樹上的蝴蝶；若恰巧有微風吹過，就更分辨不出來了……",
  str_item_intro_5423473 = "將經過複雜突變而來的蝶瀾朵然樹，以瑰色琉璃培育後得到的品種。藍色花冠加上原有的蝴蝶外形，令人產生一種詭異的感覺。一旦發現真面目，也會不由得感嘆這種樹的奇妙，因此也別名「不存於世的美麗蝴蝶」。",
  str_item_intro_5424111 = "看那圓滾滾的根莖，就已經展現出基礎果罕樹與其他品種的不同之處，不由得令人感歎它們的奇特。",
  str_item_intro_5424112 = "以瑰色琉璃培育而得的黃色果罕樹，那黃色的果實與葉瓣仿佛代表了秋日的收獲。",
  str_item_intro_5424113 = "以瑰色琉璃培育而得的紫色果罕樹，乍看會以為帶有某些奇特的氣息，實際上這種樹的汁液完全無味，品嘗起來甚至清澈無比。",
  str_item_intro_5424211 = "經歷細微突變而來的精品果罕樹，其根莖更加粗壯，果實外側出現尖刺，起到了強大的防護作用，圍繞在周圍的藤蔓似乎也在展現出一種「生人勿近」的意味。",
  str_item_intro_5424212 = "經歷細微突變而來的茁皎果罕樹，再以瑰色琉璃培育而得的品種，藍色的藤蔓和莖葉展現了它與原品種的不同，不過似乎內裡的果實還是一樣的。",
  str_item_intro_5424213 = "經歷細微突變而來的茁皎果罕樹，再以瑰色琉璃培育而得的品種，藤條和莖葉給人一種有些枯萎的感覺，實際上內在的果實極為飽滿，看來這是它的一種偽裝罷了。",
  str_item_intro_5424221 = "經歷細微突變而來的精品果罕樹，其根部的果實完全變成了另外一種樣子，分開的果實和葉瓣據說能各自汲取養分，這樣即便其中一部分損壞了，其他部分也可以依舊成長，保證存活率。",
  str_item_intro_5424222 = "經歷細微突變而來的滋玖果罕樹，再以瑰色琉璃培育而得的品種，外表呈現紅色，據說是因為其中的汁液含有某種特別成分所致。",
  str_item_intro_5424223 = "經歷細微突變而來的滋玖果罕樹，再以瑰色琉璃培育而得的品種，果實呈現出一種特別的黃色，似乎是因為其外皮失去水分所致，一旦將其外皮剝下，就會很快變脆，進而碎開，成為一堆樹末。",
  str_item_intro_5424311 = "經歷多次突變而來的珍品果罕樹，果實外側已經硬化，令其變成了一顆石球，看來要吃它的果實，還真是困難……",
  str_item_intro_5424312 = "經歷多次突變而來的堅嶺果罕樹，再以瑰色琉璃培育而得的品種，雖然不知道果實是否發生了變化，然而從樹葉就能隱約感覺到，或許品嚐它的果實，並不是一個好的主意。",
  str_item_intro_5424313 = "經歷多次突變而來的堅嶺果罕樹，樹冠和樹葉都呈現出鮮豔的顏色，與下面的「果實石球」行程了強烈的對比，某些人稱之為「鮮花掩蓋的石子」。",
  str_item_intro_5424321 = "經歷多次突變而來的胥溫果罕樹，樹幹彎曲不說，下面的果實居然分開成兩瓣，成為了天然的水池，只要有了它，就不會愁沒水喝。",
  str_item_intro_5424322 = "經歷多次突變而來的胥溫果罕樹，再以瑰色琉璃培育而得的品種，其「果實水池」中的汁液，嚐起來有一種莫名的滋味，據說這是其中蘊含一種沒有發現的神祕調味品所致。",
  str_item_intro_5424323 = "經歷多次突變而來的胥溫果罕樹，水池中的汁液更加清澈，甚至還帶有一絲冰涼，在炎炎夏日，它可是好夥伴。",
  str_item_intro_5424331 = "經歷多次突變而來的珍品果罕樹，其樹幹扭結，然而其實這是因為它內在的果實導致，某些研究表明其果實已經彎曲，而那所謂的「樹幹」其實是保護果實的表皮而已。",
  str_item_intro_5424332 = "經歷多次突變而來的甘拱果罕樹，再以瑰色琉璃培育而得的品種，枝幹尖端暈染成了綠色，而露出的果實極為苦澀，只要舔上一口，就能令人好幾天吃不下飯。",
  str_item_intro_5424333 = "經歷多次突變而來的甘拱果罕樹，樹幹處的顏色變化十分明顯，這也預示著果實滋味發生了極大的變化，聽一些勇於嘗試者說，似乎是略有辛辣且回酸的感覺。",
  str_item_intro_5424341 = "經歷多次突變而來的珍品果罕樹，其型態最能體現這一類奇異樹的樣子，那巨大且堆放在一起的果實，從中伸出的枝幹……因此有著「名副其實的果實巨樹」的別稱。",
  str_item_intro_5424342 = "經歷多次突變而來的碩實果罕樹，再以瑰色琉璃培育而得的品種，藍色的巨大果實看起來極為飽滿，而它也確實名副其實，其中蘊含的汁液據說能提供一個村落的用水……因此有人也叫它為「水箱奇異樹」。",
  str_item_intro_5424343 = "經歷多次突變而來的碩實果罕樹，再以瑰色琉璃培育而得的品種，巨大的紅色果實極為鮮豔，沒人能忽略它的存在，因此有傳說宣稱其汁液能帶來活力，然而現在來看，或許只是個傳說。",
  str_item_intro_5424411 = "經歷複雜突變才能出現的稀世果罕樹，果實巨大而且擁有奇妙的絢爛色彩，加上構造繁複的枝條，看久了很容易令觀賞者產生某種獨佔欲，甚至為此與親朋好友發生紛爭，又得名「紛爭之果實」。",
  str_item_intro_5424412 = "經歷多次突變而來的至末果罕樹，再以瑰色琉璃培育而得的品種，綠色的果實帶有強烈的自然氣息，看多了會令人沉浸其中，宛如置身森林之中，甚至能聽到蟲鳴鳥叫，感受到被風吹動的樹葉撲面而來……",
  str_item_intro_5424413 = "經歷複雜突變而來的至末果罕樹，再以瑰色琉璃培育而得的品種，果實變成了鮮豔且迷人的粉色，若久久凝視，甚至能恍然看到果實內部有跳躍的律動，詭異無比。",
  str_item_intro_5424421 = "經歷複雜突變才能出現的稀世果罕樹，果實眾多，大小不一，交錯堆疊。據傳它是最早出現的此類奇異樹之一，甚至有野生的記載！因此也有「果之奇異樹祖先」的別稱。",
  str_item_intro_5424422 = "經歷複雜突變而來的先莧果罕樹，再以瑰色琉璃培育而得的品種，粉色的果實令人不禁想汲取其中的汁液，據說能用其釀造出令君王也極為稱讚的美味飲品，故而別名「帝王品飲之實」。",
  str_item_intro_5424423 = "經歷複雜突變而來的先莧果罕樹，再以瑰色琉璃培育而得的品種，那一顆顆果實遠觀仿佛碧藍海水凝結而成的液球，或許還能看到其中的漣漪，但那究竟是不是觀看者的幻覺，就不得而知了……",
  str_item_intro_5424431 = "經歷複雜突變才能出現的稀世果罕樹，巨大的果實無時無刻不在散發著奇妙的氣息，有人說那可以為嗅者帶來莫名的勇氣，令其擁有征服四方的念頭，因而得名。",
  str_item_intro_5424432 = "經歷複雜突變而來的龕世果罕樹，再以瑰色琉璃培育而得的品種，綠色果實能讓最兇暴的戰士也安靜下來，十分適合冥想與思考，據說有不少智者在它的眷顧下領悟了道理，因此也有「開悟之果」的別名。",
  str_item_intro_5424433 = "經歷複雜突變而來的龕世果罕樹，再以瑰色琉璃培育而得的品種，巨大的藍色果實不僅能給人帶來勇氣，還會令其擁有從不甘於人下的強烈野心，從而走上一條無法回頭的爭王之路，因此它也被人稱之為「危險的擁王者」。",
  str_item_intro_5424441 = "歷經複雜突變始可長成的稀世果罕樹，果實被隱藏在「樹幹」當中。根據某些學者的研究可知，包裹果實的並非樹幹，而是果實本身堅固的硬化外皮！為了不讓外界接觸其果實，看來這種奇異樹真是費盡苦心呢。",
  str_item_intro_5424442 = "將歷經複雜突變而來的僻凡果罕樹，以瑰色琉璃培育後所得的品種。綠色的果實據說懷有生命的「源力」，若萃取得當，不僅能滋長植物、促進作物豐收，甚至可以改善荒蕪的土壤和乾硬的鹽鹼地！因此許多人稱其為「生命果」。",
  str_item_intro_5424443 = "將歷經複雜突變而來的僻凡果罕樹，以瑰色琉璃培育後所得的品種。藍色的巨大果實蘊含了甘甜的清水，而外層「樹皮」具備強大保濕能力，即便在沙漠中也能維持住果實裡的水分而不流失，簡直就像一座活水庫……",
  str_item_intro_5424451 = "歷經複雜突變始可長成的稀世果罕樹，巨大的果實乍看「平凡無奇」，卻會在特定時間散發出極為迷人的香氣，據說那香氣令人終身難忘！這或許就是它平日並無特殊氣味卻不乏蝶兒圍繞的原因吧。",
  str_item_intro_5424452 = "將歷經複雜突變而來的馥非果罕樹，以瑰色琉璃培育後得到的品種。根據某部分人的轉述，紫色果實每隔幾百年就會散發出瀰漫整個大陸的香氣！而伴隨其香氣瀰漫的則還有某位「王者」降臨於世的傳說……",
  str_item_intro_5424453 = "將歷經複雜突變而來的馥非果罕樹，以瑰色琉璃培育後得到的品種。與其他馥非果罕樹不同，藍色果實帶有些許的清新氣息，可中和其他氣味！因此頗受園林花匠們的喜愛，然而無法移栽的特性則令一般花匠只能望之興嘆。",
  str_item_intro_5424461 = "歷經複雜突變始可長成的稀世果罕樹，外殼已形成了牢籠一般的存在，裡面的果實十分香甜，這從它偶爾散發的霧氣就能得知，據說這霧氣能迷醉接近的生物，防止覬覦果實者得手。",
  str_item_intro_5424462 = "將歷經複雜突變始可長成的世霧果罕樹，再以瑰色琉璃培育而得的品種，據說其綠色果實有著極強的酸澀味道，就連散發的霧氣也有刺鼻氣息，因此被訛傳帶有劇毒，實則毫無危害。",
  str_item_intro_5424463 = "將歷經複雜突變始可長成的世霧果罕樹，再以瑰色琉璃培育而得的品種，藍色的果實中的肉質部分發生了奇妙的變化，極為堅韌，又極富彈性，就連沉重車輛碾過後，也能很快恢復原狀……",
  str_item_intro_5424471 = "歷經複雜突變始可長成的稀世果罕樹，果實分成了兩大部分——主要果實被厚重外殼包裹，而從枝條末端懸掛的那顆散發光芒的「果實」，據說是樹冠變異的！不過從外形、氣味甚至口味來講，都不太支持這種說法……",
  str_item_intro_5424472 = "將歷經複雜突變始可長成的熠仁果罕樹，再以瑰色琉璃培育而得的品種，其散發的藍色光芒據說能令人聞到海水的氣息，因此被稱為「海風的使者」，也有人宣稱那不過是果香造成的幻覺。",
  str_item_intro_5424473 = "將歷經複雜突變始可長成的熠仁果罕樹，再以瑰色琉璃培育而得的品種，其頂上的「果實」散發的綠色光芒有著令人安靜的力量，據說最兇暴的動物來到附近也會變得溫和，是真是假，不得而知。",
  str_item_intro_5425111 = "這類的奇異樹從基礎開始就與其他品種大相徑庭，不禁令人懷疑它們還是不是「樹」……根據許多學者研究，它還是屬於這個種類，只能說奇異樹的確名副其實，總能給人奇妙的觀感。",
  str_item_intro_5425112 = "用瑰色琉璃培育而來的紅色葰菇樹，那紅色的巨大傘冠給人一種焦躁的感覺，因此在下面乘涼大概不是個好選擇。",
  str_item_intro_5425113 = "用瑰色琉璃培育而來的藍色葰菇樹，藍色傘冠會給人來自天空的曠達錯覺，也有人在其周圍能嗅到「雲朵的清香」……",
  str_item_intro_5425211 = "經歷細微突變的精品葰菇樹，傘冠出現極大的變化，柔軟而富有韌性，因重量使其自然下垂，給人一種拱頂的感覺，看來如果加上一些木梁支撐，再豎起圍牆，或許真的能成為一座小屋。",
  str_item_intro_5425212 = "將經歷細微突變而來的荏茸葰菇樹，以瑰色琉璃培育後得到的品種，傘冠內部變成了天藍色，身處其中的人若向上望去，會有置身大海的錯覺。",
  str_item_intro_5425213 = "將經歷細微突變而來的荏茸葰菇樹，以瑰色琉璃培育後得到的品種，紅色的傘冠內側令人不禁感到害怕，也有傳聞說它有毒，其實這都是世人偏見所致。",
  str_item_intro_5425221 = "經歷細微突變而來的精品葰菇樹，莖稈粗壯，傘冠卻縮小了很多，感覺變成一座水桶。而它也名副其實，其粗壯的莖稈能從地底汲取水分並儲存起來，成為天然的儲水倉，因此別名「水菇」。",
  str_item_intro_5425222 = "將經歷細微突變而來的笙松葰菇樹，以瑰色琉璃培育後得到的品種，外表呈紅色，然而其中儲存的水分並未受到影響，靠近還能聽到裡面微微流動的水聲。",
  str_item_intro_5425223 = "將經歷細微突變而來的笙松葰菇樹，以瑰色琉璃培育後得到的品種，傘冠受到大量儲水的影響而呈現藍色，因此有人稱之為「海洋蓋」。某些人說站在傘冠上，俯下身用耳朵貼近傘冠，便能聽到粗壯莖稈中的海濤聲……",
  str_item_intro_5425311 = "歷經多次突變而來的珍品葰菇樹，傘冠似乎還保持了原先的巨大，只不過肥厚了很多，而且還彌漫著一股奇妙的味道……",
  str_item_intro_5425312 = "將歷經多次突變而來的彼惑葰菇樹，以瑰色琉璃培育後得到的品種。傘冠已經變成藍色，即使不靠近而只是盯著看，也會有身處淺海海面下的錯覺。",
  str_item_intro_5425313 = "經歷多次突變而來的彼惑葰菇樹。傘冠呈豔麗的紅色，據說能誘惑觀賞者，令其沉醉其中、逐漸走近強大力量。不過這種誘惑沒有惡果，其目的至今不明。",
  str_item_intro_5425321 = "歷經多次突變而來的珍品葰菇樹。不僅體型變小，而且成為群聚生長，好在造型大致沒變。最大特徵是傘冠會閃爍各種光芒，還會散發螢光點點的粉末，是一道美景。",
  str_item_intro_5425322 = "將歷經多次突變而來的霓爍葰菇樹，以瑰色琉璃培育後得到的品種。熾烈的紅色仿佛群聚的火焰，而那些螢光點會令人誤認為噴射出來的火星，因此也有「燃火之菇眾」的別稱。",
  str_item_intro_5425323 = "將歷經多次突變而來的霓爍葰菇樹，以瑰色琉璃培育後得到的品種。紫色傘冠不僅看起來妖豔，其散發的螢光點據說還有蠱惑人心的效果。也有學者宣稱它是彼惑葰菇樹的變種或遠親，當然這僅僅是一種猜測。",
  str_item_intro_5425331 = "歷經多次突變而來的珍品葰菇樹，莖稈歪斜，且生出兩頂傘冠。有學者推測可能是為了維持兩頂傘冠的存活，它會從地底汲取大量水分，甚至會超出自身儲存的最大限度，導致水分自傘冠分泌出來，再如雨點般落下。",
  str_item_intro_5425332 = "歷經多次突變而來的洽霑葰菇樹。通體變成了黃色，落下的雨點也帶有淡淡的夕陽氣息，當雨點落得倉促時，甚至會感覺是一道黃昏的雨幕在樹周圍出現。",
  str_item_intro_5425333 = "將歷經多次突變而來的洽霑葰菇樹，以瑰色琉璃培育後得到的品種，藍色使其彷彿海洋生物，而落下的雨點又如同濺起的碧藍浪花，故而別名「海洋之水的操控者」。",
  str_item_intro_5425341 = "歷經多次突變而來的珍品葰菇樹。擁有多條下垂的輕柔樹枝是其特色，乍看仿佛是老人長的鬍鬚，給人一種智者的感覺，因此也有著「葰菇之智者」的別稱。",
  str_item_intro_5425342 = "將歷經多次突變而來的梳鬚葰菇樹，以瑰色琉璃培育後得到的品種，黃色的鬍鬚看起來更加睿智，甚至有人宣稱這代表光明的護佑。當風吹動樹鬚時，甚至能看到一絲絲彷彿陽光的閃爍。",
  str_item_intro_5425343 = "將歷經多次突變而來的梳鬚葰菇樹，以瑰色琉璃培育後得到的品種，眾多的綠色樹鬚看起來與藤蔓無異，位於傘冠下的觀賞者會有一種身處原始森林的錯覺。",
  str_item_intro_5425411 = "歷經複雜突變始可長成的稀世葰菇樹。傘冠變得十分巨大，且十分輕薄，據說從某些角度來看甚至都接近透明！當然，很多人說這種透明感並非來自那薄薄的傘冠，而是源於時刻散發的寒氣，令人不禁想起透明的寒冰。",
  str_item_intro_5425412 = "將歷經多次突變而來的津凕葰菇樹，以瑰色琉璃培育後得到的品種。黃色的傘冠配上偶爾散發的寒冷氣息，令人有在驕陽下依舊感到寒冷的錯覺，因此也有人將其稱為「冰封之陽地域的奇妙樹」。",
  str_item_intro_5425413 = "將歷經複雜突變始可長成的津凕葰菇樹，以瑰色琉璃培育後得到的品種。傘冠變成眩目的紅色，加上天然帶有的微微透明感，不僅令人懷疑這是否是一件人工製成的藝術品，並非自然產物。",
  str_item_intro_5425421 = "歷經複雜突變始可長成的稀世葰菇樹。傘冠似乎變得較為「尋常」，但偶爾會噴出氣流，給人「正在呼吸」的錯覺，加上它們多為群居，因此當接二連三地噴出氣流時，甚至會產生一片淡淡霧氣，故而得名。",
  str_item_intro_5425422 = "將歷經複雜突變始可長成的素靄葰菇樹，以瑰色琉璃培育後得到的品種。當紅色傘冠「呼吸」時，偶爾可見開合的微小孔洞彷彿皮膚上的傷口，加上噴出氣流在某些時刻會凝成疑似血霧的場景，故而別名「慘烈戰場重現者」。",
  str_item_intro_5425423 = "將歷經複雜突變始可長成的素靄葰菇樹，以瑰色琉璃培育後得到的品種。藍色傘冠散發的霧氣，會給觀賞者一種「凜冬」的感覺，因此很多人誤認為它原本生活在北境。然而它們都錯了，這種樹散發的氣流並不冷，甚至還有點溫度。",
  str_item_intro_5425431 = "歷經複雜突變始可長成的稀世葰菇樹，傘冠變得超級巨大，令人不禁懷疑它的莖稈是否撐得住。由於傘冠太過巨大，當觀賞者站在其下，向上眺望時，整片天空都被遮住了，因此也有人稱之為「遮天之樹」。",
  str_item_intro_5425432 = "將歷經複雜突變始可長成的穹幕葰菇樹，以瑰色琉璃培育後得到的品種。綠色傘冠不時散發著水草的清香，觀賞者會有身處水邊的異樣錯覺。據說這種樹能為附近的水草提供養分，令其繁茂生長，不過沒人證實過這一點。",
  str_item_intro_5425433 = "將歷經複雜突變始可長成的穹幕葰菇樹，以瑰色琉璃培育後得到的品種。鮮紅色的傘冠給人豐收的錯覺，也確實有人宣稱在其周圍聞到果實清香味。然而這種奇異樹完全不能食用，尤其傘冠不僅堅硬、極難烹飪，更是毫無營養。",
  str_item_intro_5510001 = "肥胖的身體不是生存的阻礙，因為大肚腩內擁有致命毒素。但其極為鮮美的肉質還是吸引了眾多不怕死的食客。",
  str_item_intro_5510002 = "因色彩明亮而著稱，數量龐大、肉質鮮嫩，是餐桌上的主力。",
  str_item_intro_5510003 = "身材細長且形似刀身，故而得名，總是成群結隊地活動。",
  str_item_intro_5510004 = "乍看像蛇，實際上則是一種身材很細長而且魚鰭很小的魚種，喜歡潛藏在水中的石頭下，突然衝出來嚇人一跳。",
  str_item_intro_5510005 = "喜歡生活在清水中的魚類，數量龐大、分佈廣泛，很多地方都能看到牠的身影。",
  str_item_intro_5510006 = "據說這種魚在水中是霸王級的掠食者，然而因為肉質鮮美而被食客們盯上，現在已經成為高檔宴席間的「常客」。",
  str_item_intro_5510007 = "一種細長的小魚，多聚集在河岸邊，或休息或巡遊，以水中各種微小生物為食，不僅肉可食用，其魚油還能製作各種顏料。",
  str_item_intro_5510008 = "喜歡成群游動，數量龐大，性格暴躁，在惡鬥中喜用頭衝撞對手，就像一把把標槍。肉質堅實，其細小鱗片經曬乾後多用於製作零食。",
  str_item_intro_5520001 = "水中緩慢巡遊的龜，到岸上就幾乎不能動，可能是因為速度實在太慢，才有了後背上那堅硬的殼，禦敵全靠它。",
  str_item_intro_5520002 = "據說這種稀有的水生生物十分喜歡冷水，因此通常群聚在結冰的海域之下活動，由於其身體部分透明，並且有著多變的色彩，故而得名。在溫水中十分少見，看來多半是迷路了吧……",
  str_item_intro_5520004 = "這種水中生物的身體十分扁平，游速非常緩慢，且很喜歡在河溪底部活動和休息。由於背部有很多奇妙的圓點，因此很多捕魚者在河溪上觀察時，很容易將牠誤認為是一大群散落的珍珠，故而得名。",
  str_item_intro_5520005 = "喜歡在水底爬行的一種生物，因為奇特的身體構造而為人所知。據說很多人第一眼看到它的時候，還以為是長相有些奇怪的水藻或珊瑚，直到它緩緩移動後，才意識到它居然是動物……",
  str_item_intro_5520006 = "通常喜歡居住在水藻、珊瑚甚至海葵間的奇妙魚類，外表鮮豔，長相看起來十分「滑稽」，令人忍俊不禁。有人看到牠一出現，附近的水草就開始翩翩起舞，遂認為是牠的「搞笑天賦」所致，因而得名。",
  str_item_intro_5520007 = "似乎是最近發現的水生生物，皮膚光滑、肌肉鬆軟，游泳姿勢顯得飄逸、慵懶，因此很快得到了眾人的喜愛。據說某些欣賞者只要看到它在水中徘徊巡遊的樣子，就會感到身心愉悅，數日的勞累一掃而空。",
  str_item_intro_5520016 = "喜歡生活在廣闊的水域，卻不知何故跑到這裡來了……由於通體黑色，加上造型實在太過怪異，人們一度避而遠之。其實牠個性十分溫和，喜歡在水中悠閒巡遊，遇到小型水中動物，甚至會主動避讓。",
  str_item_intro_5520101 = "因色彩艷麗而成為了最名貴的觀賞魚之一，不僅有著「水中活寶石」的別稱，而且據說能為其飼養者帶來好運。",
  str_item_intro_5520102 = "因紋路多變因而廣受喜愛，被人稱為「魚中的高雅之士」，觀賞使人心情放鬆，很多人認為牠能致使家庭和睦。",
  str_item_intro_5520103 = "高檔觀賞魚，因其優美的泳姿，有著「會游泳的藝術品」之稱，據說還能為飼養者消除未來的災禍。",
  str_item_intro_5520104 = "性情溫和，紋路自然，而且很喜歡親近人，尤其是小孩子，因此也有人認為牠能保佑兒童順利成長。",
  str_item_intro_5520105 = "其鱗片會在陽光下閃耀絢爛的金黃色，因此被認為會帶來財運，很多商人都喜歡養上幾隻。",
  str_item_intro_5520201 = "在水中閃耀著點點紅色的觀賞魚，鱗片十分明顯，幾乎會將一片水域染成淡粉色，從而形成瑰麗的景象。",
  str_item_intro_5520202 = "雖然看起來有點「邪惡」，但其血紅色的鱗片會在陽光的照耀下顯出一片朱紅色，給人穿了一身紅寶石鎧甲的印象。",
  str_item_intro_5520203 = "閃耀著藍色鱗片的牠，在水中緩緩游動時，會給人帶來莫名的清涼之感，在盛夏時尤其可貴。",
  str_item_intro_5520204 = "黃金色的整齊魚鱗，讓牠彷彿成為了傳說中的將軍，其泳姿也是盛氣凌人，周圍的小魚都要退避三分。",
  str_item_intro_5520205 = "與其他瓏鰭相比，牠顯得優雅、從容不迫，銀白色的魚鱗和流線型的體態令其擁有一種貴族氣息。",
  str_item_intro_5520301 = "扁平的身材，耀眼的顏色，這種魚彷彿是落入水中的蝴蝶，翩翩游動。",
  str_item_intro_5520302 = "頭部發白，身體基本多為黑色的觀賞魚，性情溫和，仔細觀察，黑白交界處的斑點都有細微的不同，可以說每隻黑蝶鱸，都是獨一無二的。",
  str_item_intro_5520303 = "身體上有黃色與白色相間，將身體分成三大段，故得此名。牠性格聒噪，喜歡捉弄其他魚類，因此只要有牠在，水域就變得熱鬧起來。",
  str_item_intro_5520304 = "擁有漂亮寶藍色外形的觀賞魚，色彩富有變化，性格害羞，不喜歡拋頭露面，很多時候都躲在石頭、水草間不出來，因此別名「羞澀少女」。",
  str_item_intro_5520401 = "鮮豔的顏色，靈動的大眼睛，喜歡親近其他魚類，而且又不會被排斥，堪稱觀賞魚中的「交際花」。",
  str_item_intro_5520402 = "背上的雜色斑點令其得名，如果配上和牠顏色差不多的水草......就是天然的保護色，因此在佈置的時候，一定要注意環境與牠的顏色搭配，如此才能彰顯牠的存在。",
  str_item_intro_5520403 = "身體基本為黑色，背上的黃白色魚鰭是其特點，性格安靜，但是一旦發怒就會與對手鬥爭到底，就像荊棘一樣——有刺，所以不要碰。",
  str_item_intro_5520501 = "很少有人養這種觀賞魚，因為實在是......不好看，只有那發光的魚須，令之顯得與眾不同。",
  str_item_intro_5520502 = "白色的提燈鱇，顯得似乎平易近人了許多，光芒卻也暗淡了一些，或許是對比的原因吧。",
  str_item_intro_5520601 = "據說是生活在深海中的水駒，不知道為何跑到這裡來了，由於習慣了深海，因此通常潛伏於水底，很難發現。\n平時見不到，只會在附近有光能的情況下出現，但是過於濃烈的光能會嚇跑牠。",
  str_item_intro_5520602 = "這種水駒喜歡棲息在溪流的石頭間隙中，由於移動迅速，因此往往被誤認為是石頭染上了黃色，故得此名。\n平時見不到，只會在附近有光能的情況下出現，但是過於濃烈的光能會嚇跑牠。",
  str_item_intro_5520603 = "通常在河流、小溪中棲息，身體顏色成為了天然的保護，而豎著的游泳方式也讓牠們能很好地躲藏在溪流的水泡中，不被天敵發現。\n平時見不到，由於對光能不太敏感，需要在更強光能的吸引下才會出現，但是過於濃烈的光能會嚇跑牠。",
  str_item_intro_5520701 = "喜歡生活在河灣之處的水下生物，擁有多條附肢，看起來兇惡無比。實際上這都是牠的偽裝，其性格十分溫順，通常就待在水藻團中隱居，很難發現。",
  str_item_intro_5520702 = "牠喜歡棲息在清澈的河灣之中，將自己的大部分身軀埋入水下的黃沙內，由於膚色與沙粒很接近，幾乎不會有其他生物注意到，因此牠伏擊獵物時十分輕鬆。",
  str_item_intro_5520801 = "別看牠現在很「小」，卻有1公斤重，而且牠還是「磅鱅」中最小的一種！雖然看起來稍微普通了點，但是牠有著成長的潛力......",
  str_item_intro_5520802 = "較大的「磅鱅」，足足有5公斤，顏色更加濃厚，但是也難以捉到，看來增長的不僅有體重，也有警惕性。",
  str_item_intro_5520803 = "重達10公斤的「磅鱅」，外形開始變得圓潤，大大的眼睛仿佛在說「我還可以更重唷」。",
  str_item_intro_5520804 = "20公斤的重量讓它成為「磅鱅」中的強者之一，雖然游起來比較緩慢，然而看到牠在水中那份氣定神閑的模樣，就感覺到莫名的心安，真是奇妙。",
  str_item_intro_5520805 = "超級大的「磅鱅」！50公斤！這令牠成為了「磅鱅」中的王者，那大大的肚子似乎在說「重量都在這裡」！牠的個性也十分霸道，別的水下生物見了牠，多半都會避讓。",
  str_item_intro_5520806 = "儘管牠體型不小，然而令其成為最受歡迎的「磅鱅」的原因，是那片宛如鍍了一層金的魚身，而令人目眩的是鱗片上還有各種各種星狀花紋，令人不禁感歎，牠真的是上天賜予凡間的傑作。",
  str_item_intro_5520811 = "看起來張牙舞爪、兇惡至極的水生生物，實際上那對大螯只是用來挪開阻攔牠四處漫游的石子、水草，戰鬥只是附加功能。其實，牠性格十分溫和，只有在防禦時才顯得勇猛善鬥。",
  str_item_intro_5520812 = "喜歡潛藏在水底石頭群中，說是「潛藏」，其實是因為牠喜歡在水底用強壯的大螯搬運石子、搭建「城堡」，躲起來埋伏那些或倒楣、或好奇的水生生物，飽餐一頓。",
  str_item_intro_5520014 = "因身上長滿藍色圓環而著名，在河流中很少見。但是當它出現時，很多水中生物都要退避三舍，這主要是因其體內含有的劇毒，據說只要一滴便能致死。因此，它的外形才會如此招搖奪目，絲毫不怕引起其他生物的注意。",
  str_item_intro_5520901 = "十分罕見的魚，身軀絢爛多彩，體型較小，游動速度很快，十分警覺，只要水面上稍有動靜就會將身軀的顏色隱藏，極難發現，因此需要極大的耐心才能釣到牠。雖然很辛苦，但是看到牠在水池中游動形成的「彩帶」時，這一切便都是值得的。",
  str_item_intro_5530001 = "意外收穫！這只貝殼正好生有珍珠，從色澤和外形來看，賣相很不錯，能賣個好價錢。",
  str_item_intro_5530101 = "破舊的鐵皮罐頭，不知道是誰丟到水裡，太不照顧環境了......",
  str_item_intro_5530201 = "這鞋子應該在水中「生活」好多年了，連水草都把它當做了自己的家。",
  str_item_intro_5601101 = "終有一天，我也能在天空之下，守護我的家園。",
  str_item_intro_5601201 = "希望我能明白那些引導巨像的奇妙能量……",
  str_item_intro_5602101 = "記憶只能保有一生，記錄卻可流傳千年，因此我將記住它、寫下它、存留它，直到有人找到它。",
  str_item_intro_5602201 = "我發誓一定會找到那些設計圖，即便走到天涯海角。",
  str_item_intro_5602202 = "有外人說，一切都有代價，那麼知識的代價是什麼呢？",
  str_item_intro_5602203 = "頭腦需要學習來維護，生活需要情調來維護。",
  str_item_intro_5603101 = "莫要輕言放棄，即便實驗失敗了九十九次，下一次也有成功的可能。",
  str_item_intro_5603201 = "能將一件物品轉化為另一件物品的終極原理是什麼呢？尋找源頭的道路，能走下去就好了。",
  str_item_intro_5603202 = "靈感就像火花，一閃而過，為了能讓這火花永恆，我寧願花費一生去尋找。",
  str_item_intro_5603301 = "刃並非越鋒利越好，有時候反而鈍一點會有奇效。在和她相處中，或許偶爾也要變得「鈍」一點……",
  str_item_intro_5604101 = "每棵樹都有自己的命運，我也會有嗎？但願我能早日知曉……",
  str_item_intro_5604201 = "葉子有銀色的嗎？她告訴我沒有，但是我不相信，所以我來了。",
  str_item_intro_5604202 = "年輪是刻印在樹木內裡的歲月印記，是它們的歷史，也是它們的記憶。與它們對話，或許會了解我們不知道的過去——那是我們的年輪。",
  str_item_intro_5604203 = "葉子與樹交錯的影子間，似乎浮現了他的側臉，這是命運的設計嗎？",
  str_item_intro_5604301 = "它們總是安靜地生長，安靜地凋謝，這種孤高的做法，真是值得學習。",
  str_item_intro_5604302 = "我們的根脈在哪裡？希望有生之年能夠得知……",
  str_item_intro_5605201 = "看著那些水紋，我想起了教我釣魚的父親。",
  str_item_intro_5605301 = "那根白色的魚竿是母親留下的遺物，我會將它傳給我的兒女。",
  str_item_intro_5605302 = "我和她之間只剩下了這根細線，但願它堅固不斷。",
  str_item_intro_5605303 = "即便她的禮物是魚餌，我也願意上鉤。",
  str_item_intro_5605304 = "有時候釣魚不是為了收穫，而是看那些波瀾上的光。",
  str_item_intro_5605305 = "我能知道水的流向，但要到何時才能明白她的心呢？",
  str_item_intro_5605306 = "魚鉤輕輕晃動，就代表有魚兒來了。要是生活中也能有這樣的提示就好了。",
  str_item_intro_5606201 = "希望將來不會像我父親一樣，一事無成，什麼也沒有挖到，願好運！",
  str_item_intro_5606301 = "勤奮終將掩蓋我的愚笨，讓大家真心叫我一聲挖礦天才。",
  str_item_intro_5606302 = "不要忽略碎石，有時候裡面也會有寶貝。",
  str_item_intro_5606303 = "務要時刻磨利鎬尖！",
  str_item_intro_5606304 = "就像戀愛一樣，挖礦不僅需要力量，也需要技巧！",
  str_item_intro_5606305 = "礦脈也有氣味！我的鼻子可是很靈敏的，但我多希望能知道他的蹤跡……",
  str_item_intro_5606306 = "堅持下去，一定會找到那條礦脈，無論它是否在這山谷中。",
  str_item_intro_5607201 = "他是籃子，我的心意被裝在那裡面了。",
  str_item_intro_5607301 = "如果能讓她採集到我的心意就好了。",
  str_item_intro_5607302 = "小時候我被樹上的果實砸中了，從那以後一直都有好運氣，願今後也是如此。",
  str_item_intro_5607303 = "許多時候需要跟著蜜蜂才能找到好花蜜，如果我能聽懂牠們的話就好了……",
  str_item_intro_5607304 = "如果心有手套的話，或許就不會被那些帶刺的「花草」傷了吧？",
  str_item_intro_5607305 = "要一下就找到果實，需要好的眼力；嗯，希望今後的人生也能保持如此水準。",
  str_item_intro_5608101 = "植物不會拒絕陽光。也希望他不要拒絕我。",
  str_item_intro_5608201 = "播種並不是僅僅為了收穫，更多的是埋下希望。",
  str_item_intro_5608301 = "我最喜歡看風車緩緩轉動的樣子，因為什麼也不用想，足足可以看上一天......",
  str_item_intro_5608302 = "種子真是太不可思議了，只是那麼一點，就能長出那麼多的作物！所以......只要有種子，就有希望！",
  str_item_intro_5608303 = "作物需要太陽作為養分，就像我需要她一樣。",
  str_item_intro_5608304 = "陽光不能太熾烈，否則會破壞作物，對他的關心亦是如此。",
  str_item_intro_5608305 = "作物不能種得太密集，必須有壟溝，看來得和她保持一定的距離了。",
  str_item_intro_5609201 = "如果能種出一種無需修剪的草，就可以用它來做一大張舒適的睡毯了～",
  str_item_intro_5609301 = "水滴，柔軟又堅硬，我能成為像它一樣的人嗎？",
  str_item_intro_5609302 = "如果要讓植物茁壯、健康地成長，就需要良好的培土，而我們又何嘗不是如此？感謝長老給了我們不同的培土，讓我們成為了自己想成為的人。",
  str_item_intro_5609303 = "希望能獲得最甜的花蜜，給我未來的兒女。",
  str_item_intro_5609304 = "唉，什麼時候能像蜜蜂那樣肆意起舞就好了。",
  str_item_intro_5609305 = "不能光矚目著美麗的花朵，也要看看襯托的綠葉呀，是不是？",
  str_item_intro_5610101 = "我可以驅使龐大的牧群，但無法理解家人們的心，但願我未來的孩子不會這樣。",
  str_item_intro_5610201 = "據說，如果在倒牛奶的時候，牛奶杯中能浮現出笑臉一樣的花紋，那麼未來的一年都會很幸運喔！",
  str_item_intro_5610202 = "聽說外面的村莊都用巡邏犬來幫著放牧，我呢，只有他了～",
  str_item_intro_5610203 = "聽說遠方的沙漠中有一種叫做「駱駝」的生物，牠的奶很不錯喔～",
  str_item_intro_5610204 = "終有一天，我會看到青草發芽，那片草原也會再次出現在那裡。",
  str_item_intro_5610301 = "聽說谷地之外有更廣闊的草原，然而我就喜歡這裡的青草。",
  str_item_intro_5610302 = "奶酪是這個世界上最好吃的食物，如果能一輩子每天都吃到的話，簡直是到了傳說中的天堂啦。",
  str_item_intro_5610303 = "據說沙漠中的人會依水源定居，無法離開半步，那看來她就是我的水源了~",
  str_item_intro_5611101 = "聽說海邊的人曾見過一艘和小島那樣大的船隻，真想去看看！",
  str_item_intro_5611201 = "如果我能不睡覺，就可以一直當哨兵了。",
  str_item_intro_5611202 = "有我在，一定不會讓任何邪佞接近這裡，更不會讓孩子們受到威脅......",
  str_item_intro_5611203 = "成為這裡的守護者後，即使在夜晚，我都不能休息。",
  str_item_intro_5611204 = "任何細節都不能放過，否則很有可能釀成大禍。",
  str_item_intro_5611301 = "我能連續步行三天三夜都不累，我將這份天賦用於巡邏這片谷地，警惕外來者的進入。",
  str_item_intro_5611302 = "我將成為族人的堅盾！哈哈，從白夜城的騎士誓言裡學來的，挺帥呢！我會說到做到！",
  str_item_intro_5611303 = "如果能讓那些貌似火炬的大樹真的亮起來，是不是就能當做夜晚的哨燈呢？",
  str_item_intro_6400001 = "獲得後解鎖稱號：對局先手\n獲得後可在名片-稱號介面使用該稱號！",
