  str_item_intro_6400011 = "獲得後解鎖稱號：冬春荏苒\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400012 = "獲得後解鎖稱號：沉睡的復甦\n獲得後可在名片-稱號介面使用該稱號！",
