  str_item_intro_6400014 = "獲得後解鎖稱號：皓潔群匯\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400015 = "獲得後解鎖稱號：昭晳眾盈\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400016 = "獲得後解鎖稱號：頂階征攝\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400017 = "獲得後解鎖稱號：絕巔王至\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400018 = "獲得後解鎖稱號：舊日的揭示\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400019 = "獲得後解鎖稱號：覺醒的呼喚\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400020 = "獲得後解鎖稱號：無盡淵主\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400021 = "獲得後解鎖稱號：通曉典籍\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400026 = "獲得後解鎖稱號：未識有進\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400030 = "獲得後解鎖稱號：海路守護者\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6400031 = "獲得後解鎖稱號：凌空叱令\n獲得後可在名片-稱號介面使用該稱號！",
  str_item_intro_6500001 = "初始名片名飾，可在名片-名飾使用該背景！",
  str_item_intro_6500002 = "初始名片名飾，可在名片-名飾使用該背景！",
  str_item_intro_6500003 = "初始名片名飾，可在名片-名飾使用該背景！",
  str_item_intro_6500004 = "初始名片名飾，可在名片-名飾使用該背景！",
  str_item_intro_6500005 = "初始名片名飾，可在名片-名飾使用該背景！",
  str_item_intro_6500008 = "連綿起伏的群山，白芒覆蓋，幽冷、靜謐，卻又似乎有著別樣的生機。",
  str_item_intro_6500011 = "霧氣籠罩了影鎮街道，不為人知的交易就在其中進行，這便是影鎮的另一種日常。",
  str_item_intro_6500014 = "啟光地下城內的維修工廠，足以快速修理好很多損壞的裝置，甚至是大型機械。",
  str_item_intro_6500015 = "白夜城的慶典，一如往常般盛大。",
  str_item_intro_6500016 = "水流、十字路口，地理與地形上的便利造就出影鎮的繁榮。",
  str_item_intro_6500017 = "當太陽被莫名的黑暗所吞噬，是否預示了某種巨變的降臨？",
  str_item_intro_6500018 = "北境，冰與寒，那裡屬於伯利恆，也是她所要守護的地方。",
  str_item_intro_6500020 = "無論如何，那些歹人都不能破壞演唱會！這是正義！",
  str_item_intro_6500021 = "北境，冰與寒，那裡屬於伯利恆，也是她所要守護的地方。",
  str_item_intro_6500024 = "在那一刻，她似乎放下了所有的戒備，開心的笑容展露出孩子氣的一面，這正是只屬於那兩個人的祕密。",
  str_item_intro_6500026 = "紅油扳手的慶功宴，似乎變成了各種沙漠美食的大會。",
  str_item_intro_6500033 = "旅途之中若覺疲憊，不妨與這些同伴坐下來，小憩談天，聽一聽他們的故事。",
  str_item_intro_6500035 = "天空之城的陽光，多年未曾改變，身穿昔日裙裳的她，站在那副巨大油畫前久久駐足，似乎想起了什麼……",
  str_item_intro_6500036 = "只要有芙洛琳在身旁，再危險的水域也會變得安全。",
  str_item_intro_6500037 = "有人百餘年來固守在這裡，只為了實踐那項早已被遺忘的使命。",
  str_item_intro_6500038 = "微風輕拂，吹散了舊日的陰霾，而霞光將會猶如烈焰一般將一切憂愁燃盡，為你帶來嶄新的未來。",
  str_item_intro_6500039 = "她將如燈塔一般，照亮整片漆黑的海洋，為冒險者指明歸家的方向。",
  str_item_intro_6500041 = "即使天氣寒冷，萬里冰封，但只要和同伴們在一起，心中就總會泛起一股暖流。導航員，佳節快樂！",
  str_item_intro_6500042 = "涉跳上高空，擊退了來犯的敵人，此時她終於亮出自己不為人知的另一面。",
  str_item_intro_6500043 = "戈壁邊緣，一個個觀察哨所紛紛成立。它們將在這裡保衛遠處的家園，不受敵人騷擾。",
  str_item_intro_6500044 = "店鋪如雲，人聲鼎沸。居民與遊客齊聚在雙榭城的鬧市，挑選著喜歡的商品，好不熱鬧。",
  str_item_intro_6500045 = "「感謝您對我的認可。白夜至上！」",
  str_item_intro_6500046 = "「我喜歡一個人發呆，但現在……有你陪在身邊，也不錯。」",
  str_item_intro_6500047 = "「這世界依然充滿戰火。今後，你也願意陪我一起解決那些紛爭嗎？」",
  str_item_intro_6500049 = "「呱呱呱！」",
  str_item_intro_6500051 = "鷹群般的無人機環繞少女，而她回首望向你。\n「沒事了。」",
  str_item_intro_6500053 = "耀眼的她微笑著，縱身躍入深淵。\n「不要讓任何人奪走你的力量，還有快樂。」",
  str_item_intro_6500054 = "站在宿命的歧點，該選擇怎樣的未來？",
  str_item_intro_6500056 = "你所經歷的一切，將指引真理結社未來的道路。 ",
  str_item_intro_6500057 = "海風、刨冰、三輪車。與那位少女初次度過的夏日回憶，至今仍未褪色。",
  str_item_intro_6500058 = "重逢誓言，心靈的交匯點",
  str_item_intro_9993001 = "戰鬥勝利後，隨機使隊伍內一名存活光靈恢復20%生命值",
  str_item_intro_9993002 = "職業為「輔助」的光靈戰鬥時，連鎖技和主動技能帶來的恢復效果提升25%",
  str_item_intro_9993003 = "戰鬥內拾取的繃帶恢復生命值增加80%",
  str_item_intro_9993004 = "職業為「狙擊手」的光靈，屬性剋制效果提升10%",
  str_item_intro_9993005 = "職業為「爆破」的光靈連線15格以上時，連鎖技能傷害提升30%",
  str_item_intro_9993006 = "暗鬼受到的中毒、灼燒和流血傷害增加50%",
  str_item_intro_9993007 = "職業為「狙擊手」的光靈，連鎖技能傷害提升15%",
