  str_item_intro_9993027 = "森屬性光靈攻擊力提升5%",
  str_item_intro_9993028 = "森屬性光靈攻擊力提升5%",
  str_item_intro_9993029 = "雷屬性光靈攻擊力提升5%",
  str_item_intro_9993030 = "雷屬性光靈攻擊力提升5%",
  str_item_intro_9993031 = "雷屬性光靈攻擊力提升5%",
  str_item_intro_9993032 = "雷屬性光靈攻擊力提升5%",
  str_item_intro_9993033 = "雷屬性光靈攻擊力提升5%",
  str_item_intro_9993034 = "戰鬥勝利時，職業為「變化」與「輔助」的光靈，生命值提升3%，最高30%",
  str_item_intro_9993035 = "戰鬥勝利時，職業為「狙擊手」與「爆破」的光靈，攻擊力提升1.5%，最高15%",
  str_item_intro_9993036 = "戰鬥勝利時，隊伍內隨機一名存活光靈獲得一層可疊加的傷害減免效果，每層減免1.5%傷害，直到該次祕境探索結束",
  str_item_intro_9994001 = "每次擊殺暗鬼時，隨機使隊伍內一名存活光靈恢復10%生命值",
  str_item_intro_9994002 = "中毒狀態的暗鬼每次觸發毒傷時，職業為「輔助」的光靈將恢復毒傷量100%的生命值",
  str_item_intro_9994003 = "職業為「爆破」的光靈，對異常狀態的暗鬼傷害提升30%",
  str_item_intro_9994004 = "當處於中毒、灼燒或流血狀態的暗鬼死亡時，將對全場敵人附加3層中毒",
  str_item_intro_9994005 = "當暗鬼回合開始時，處於中毒、灼燒或流血狀態的暗鬼會對周圍兩圈內的暗鬼附加中毒效果",
  str_item_intro_9994006 = "己方隊伍處於異常狀態時，職業為「狙擊手」的光靈傷害提升30%",
  str_item_intro_9994007 = "每次受到傷害時，職業為「爆破」的光靈傷害提升5%（戰鬥結束後重設）",
  str_item_intro_9994008 = "戰鬥開始時，戰場中生成一個繃帶",
  str_item_intro_9994009 = "生命值在70%以上，職業為「狙擊手」的光靈，傷害提升20%",
  str_item_intro_9994010 = "職業為「爆破」的光靈攻擊時，傷害將提升為目前損失生命值的10%",
  str_item_intro_9994011 = "光能泉額外恢復5點MS值",
  str_item_intro_9994012 = "於光能泉選擇恢復生命值時，恢復人數+1",
  str_item_intro_9994013 = "危險區域中，職業為「爆破」的光靈攻擊力提升10%",
  str_item_intro_9994014 = "致死區域中，職業為「爆破」的光靈攻擊力提升10%",
  str_item_intro_9994015 = "祕寶盜掘者逃跑時，強制延遲4回合",
  str_item_intro_9994016 = "擊殺大體型暗鬼時，所有光靈會減少1回合冷卻",
  str_item_intro_9994017 = "擊殺大體型暗鬼時，職業為「狙擊手」的光靈攻擊力提升20%",
  str_item_intro_9994018 = "擊殺大體型暗鬼時，使隊伍內生命值最少的一名存活光靈恢復20%生命值",
  str_item_intro_9994019 = "使所有小體型怪物附加緩速效果",
  str_item_intro_9994020 = "所有小體型怪物的初始生命值減少20%",
  str_item_intro_9994021 = "所有小體型怪物的攻擊力降低10%",
  str_item_intro_9994022 = "開場時，使一名職業為「變化」且主動技能未冷卻完的光靈冷卻減少1",
  str_item_intro_9994023 = "獲得後會漂浮在光靈身邊，隊長攻擊時造成一次火屬性傷害",
  str_item_intro_9994024 = "獲得後會漂浮在光靈身邊，隊長攻擊時造成一次水屬性傷害",
  str_item_intro_9994025 = "獲得後會漂浮在光靈身邊，隊長攻擊時造成一次森屬性傷害",
  str_item_intro_9994026 = "獲得後會漂浮在光靈身邊，隊長攻擊時造成一次雷屬性傷害",
  str_item_intro_9995001 = "當隊伍中有光靈死亡時，以50%生命值復活（每場戰鬥僅有第一位受到致命傷害的光靈能觸發一次）",
  str_item_intro_9995002 = "擁有此聖物時，職業為「變化」的光靈單次受到的傷害不會超過生命上限的20%",
  str_item_intro_9995003 = "職業為「輔助」的光靈溢出的治療量，將按比例轉化為一層護盾，持續一回合",
  str_item_intro_9995004 = "每次進入戰鬥，有50%機率施放衝擊波，使敵方全體單位眩暈一回合",
  str_item_intro_9995005 = "職業為「狙擊手」的光靈，普通攻擊和連鎖技能傷害將直接消除暗鬼護盾",
  str_item_intro_9995006 = "戰鬥開始時，身邊8個格子會隨機刷出4個彩色格子",
  str_item_intro_9995007 = "戰鬥開始時，戰場將產生一個補充MS值的棱度計",
  str_item_intro_9995008 = "戰鬥開始時，隨機對10組2x2格子進行落雷，對範圍內的單位造成固定百分比的傷害，對光靈無效",
  str_item_intro_9995009 = "在移動的起點留下一個炸彈，並在己方行動結束後引爆",
  str_item_intro_9995010 = "普通攻擊combo數是5的倍數時，追加一次爆炸效果",
  str_item_intro_9995011 = "召喚死亡的氣息，秒殺生命值低於7%的暗鬼",
  str_item_intro_9995012 = "職業為「爆破」的光靈施放連鎖技能時，在連線起始位置生成一個施放技能的光靈虛影，同時施放連鎖技能",
  str_item_intro_9995013 = "盛放命運骰的骰盒，消耗命運骰可以重新隨機獲得一個祕境聖物",
  str_item_intro_9995014 = "職業為「狙擊手」的光靈，有40%機率額外施放一次連鎖技能",
  str_item_intro_9995015 = "光靈施放主動技能時，隨機使一名職業為「變化」的光靈冷卻減少1",
  str_item_intro_9995016 = "職業為「狙擊手」的光靈，普通攻擊將使暗鬼附加緩速效果，暗鬼移動力減少1",
  str_item_intro_9995017 = "開場使全場暗鬼附加重傷效果，使暗鬼每移動一格受到3%傷害",
  str_item_intro_9995018 = "職業為「輔助」的光靈，其普通攻擊將使暗鬼附加致盲效果，暗鬼攻擊時有30%機率無法命中",
  str_item_rpintro_9993001 = "這根蠟燭散發的溫暖光芒，擁有能夠治癒光靈傷口的力量。",
  str_item_rpintro_9993002 = "舊時代的塗料，吸收光能的效果很好。",
  str_item_rpintro_9993003 = "恢復藥水的輔助品，方便為戰鬥人員恢復傷勢。",
  str_item_rpintro_9993004 = "似乎是古代的學者手稿，上面記載了相性之間的奇妙關係，能指導戰鬥人員如何針對相性進行作戰。",
  str_item_rpintro_9993005 = "舊時代的勳章，構造神祕，能夠在微觀層面進行光能連結，增加戰鬥力。",
  str_item_rpintro_9993006 = "舊時代的遺物，似乎附有強烈的詛咒術，佩戴者若用毒液作戰，足以令人致命。",
  str_item_rpintro_9993007 = "舊時代的護符，能夠在微觀層面進行光能連結，在戰鬥時大幅傷害敵人。",
  str_item_rpintro_9993008 = "古老的短劍，使用了舊時代的高強度合金，十分鋒利。",
  str_item_rpintro_9993009 = "注入光能的皮甲，輕便、堅固，能夠提高探索者的抗擊打能力。",
  str_item_rpintro_9993010 = "注入光能的皮甲，輕便、堅固，能夠提高探索者的抗擊打能力。",
  str_item_rpintro_9993011 = "注入光能的皮甲，輕便、堅固，能夠提高探索者的抗擊打能力。",
  str_item_rpintro_9993012 = "注入光能的皮甲，輕便、堅固，能夠提高探索者的抗擊打能力。",
  str_item_rpintro_9993013 = "注入光能的皮甲，輕便、堅固，能夠提高探索者的抗擊打能力。",
  str_item_rpintro_9993014 = "神祕的紅色七角形寶石，火屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993015 = "神祕的紅色七角形寶石，火屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993016 = "神祕的紅色七角形寶石，火屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993017 = "神祕的紅色七角形寶石，火屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993018 = "神祕的紅色七角形寶石，火屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993019 = "神祕的藍色七角形寶石，水屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993020 = "神祕的藍色七角形寶石，水屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993021 = "神祕的藍色七角形寶石，水屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993022 = "神祕的藍色七角形寶石，水屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993023 = "神祕的藍色七角形寶石，水屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993024 = "神祕的綠色七角形寶石，森屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993025 = "神祕的綠色七角形寶石，森屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993026 = "神祕的綠色七角形寶石，森屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993027 = "神祕的綠色七角形寶石，森屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993028 = "神祕的綠色七角形寶石，森屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993029 = "神祕的黃色七角形寶石，雷屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993030 = "神祕的黃色七角形寶石，雷屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993031 = "神祕的黃色七角形寶石，雷屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993032 = "神祕的黃色七角形寶石，雷屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993033 = "神祕的黃色七角形寶石，雷屬性的光靈擁有它便能大幅提升力量。",
  str_item_rpintro_9993034 = "舊時代流傳下來的小雕像，以高強度材料製成，堅固又輕便，還會賜福於攜帶者。",
  str_item_rpintro_9993035 = "舊時代流傳下來的武器，不僅以高強度材料製成，還注入了光能，令佩戴者擁有很強的力量。",
  str_item_rpintro_9993036 = "舊時代的古老盾牌……擁有完美的弧形，據說更注入了太陽的力量，光能的力量會擋開一切致命的攻擊。",
  str_item_rpintro_9994001 = "泛有一絲邪惡氣息的斬刀，似乎是上古時代專門用於惡戰的武器，出刀必須見血。",
  str_item_rpintro_9994002 = "舊時代醫生佩戴的面具，在戰亂時期成為詛咒的象徵。",
  str_item_rpintro_9994003 = "來自於舊時代的名刃，執刀者會感受到媲美神的力量。",
  str_item_rpintro_9994004 = "據說是強大戰士親手製作的詛咒物品，足以使敵人無法逃離死亡的命運。",
  str_item_rpintro_9994005 = "一位佚名作者很久以前繪製的古老畫作，描繪瘟疫橫行的慘狀，作者本人也死於這場瘟疫，隨後它就擁有了可怕的力量。",
  str_item_rpintro_9994006 = "來自於舊時代的名刃，執刀者是一位著名的叛徒，他在死亡前夕的吶喊，賦予了這把刀奇妙的力量。",
  str_item_rpintro_9994007 = "這具古老鎧甲上刻著「復仇」的字樣，穿著者無一不感到隱藏在鎧甲之中的無盡憤怒。",
  str_item_rpintro_9994008 = "保存良好的女神塑像，會為光的信眾提供治癒之力。",
  str_item_rpintro_9994009 = "帶著她就能擁有勝利女神的庇護，在戰鬥中將會無往不利。",
  str_item_rpintro_9994010 = "相傳這把匕首誕生於上古文明的內戰，散發著不祥之氣，出鞘必見鮮血，否則與普通刀刃無異。",
  str_item_rpintro_9994011 = "舊時代的技術，雖然只是個小小的盒子，但能儲存大量光能。",
  str_item_rpintro_9994012 = "不知是誰遺落的摺疊睡袋，能夠恢復體力。",
  str_item_rpintro_9994013 = "獲太陽之力賜福的火槍，雖然射速慢，然而威力巨大，是面對強大敵人的有力武器。",
  str_item_rpintro_9994014 = "在漫長的歲月中，曾歷經多位主人之手，然而時間都不長……",
  str_item_rpintro_9994015 = "會發射麻痺射線的遠程兵器，射程近，威力不大，通常用於捉拿小偷。",
  str_item_rpintro_9994016 = "舊日勇士的光輝遺物，上面還附著來自過去的祝福，對付強力的敵人時效果卓越。 （同時擁有三種光輝遺物時效果翻倍）",
  str_item_rpintro_9994017 = "舊日勇士的光輝遺物，上面還附著來自過去的祝福，對付強力的敵人時效果卓越。 （同時擁有三種光輝遺物時效果翻倍）",
  str_item_rpintro_9994018 = "舊日勇士的光輝遺物，上面還附著來自過去的祝福，對付強力的敵人時效果卓越。 （同時擁有三種光輝遺物時效果翻倍）",
  str_item_rpintro_9994019 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。（同時擁有三種銀月遺物時效果翻倍）",
  str_item_rpintro_9994020 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。（同時擁有三種銀月遺物時效果翻倍）",
  str_item_rpintro_9994021 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。（同時擁有三種銀月遺物時效果翻倍）",
  str_item_rpintro_9994022 = "古老而神祕的錢幣，擁有它的光靈偶爾會獲得力量增益、行動更敏捷",
  str_item_rpintro_9994023 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。同時擁有四種屬性的浮游器的話，光靈施放連鎖技能時，能再追加一次強力攻擊。",
  str_item_rpintro_9994024 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。同時擁有四種屬性的浮游器的話，光靈施放連鎖技能時，能再追加一次強力攻擊。",
  str_item_rpintro_9994025 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。同時擁有四種屬性的浮游器的話，光靈施放連鎖技能時，能再追加一次強力攻擊。",
  str_item_rpintro_9994026 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。同時擁有四種屬性的浮游器的話，光靈施放連鎖技能時，能再追加一次強力攻擊。",
  str_item_rpintro_9995001 = "與此地有著神祕聯繫的人工製品，即使佩戴者的心臟停止跳動，也能及時挽救生命。",
  str_item_rpintro_9995002 = "獲太陽之力賜福的強大戰甲，使穿戴者能熬過一次次的殘酷戰鬥。",
  str_item_rpintro_9995003 = "舊時代的一種神祕裝置，可以感應溢出的光能，並轉化為保護佩戴者的力場。",
  str_item_rpintro_9995004 = "表面佈滿細微裂紋的粗糙水晶，這表示其中蘊含過多光能，只要輕輕觸碰就會釋放，足以在戰鬥中使敵人暈眩。",
  str_item_rpintro_9995005 = "舊時代流傳至今的強力武器，製作材料已無法考究，只知道刃尖十分鋒利，幾乎沒有任何裝甲能夠抵禦。",
  str_item_rpintro_9995006 = "蘊含所有顏色的寶石，擁有絢爛的多變光芒。",
  str_item_rpintro_9995007 = "用來儲存光能的裝置，釋放後可以補充失去的光能。",
  str_item_rpintro_9995008 = "舊時代的名刃，其中封印了雷霆的力量，只要拔出來就會瞬間爆發，消滅敵人。",
  str_item_rpintro_9995009 = "舊時代的產物，專門用於對付追兵。蘊含的光能之力會殘留在經過的路線上，並在一段時間後爆發，殺傷追擊的敵人。",
  str_item_rpintro_9995010 = "舊時代的產物，雖然外表美麗，卻帶有可怕的力量，會讓敵人宛如落花般死於爆炸之中。",
  str_item_rpintro_9995011 = "從這尊小雕像裡，能感受到敵人的生命氣息，攜帶在身邊，足以立刻殺死搖搖欲墜的殘敵。",
  str_item_rpintro_9995012 = "舊時代的強力裝置，可以產生幻影以迷惑敵人。",
  str_item_rpintro_9995013 = "上古遺物，望向其中可以看到所有人的命運，當然也有可能是幻覺。",
  str_item_rpintro_9995014 = "一種稀有的紅色蘭花，是舊時代特別培育出的產物，必定成對出現、成對開放、成對凋零，能使佩戴者擁有神祕感應，協力作戰時更順利。",
  str_item_rpintro_9995015 = "舊時代的產物，會在兩名戰鬥者之間產生神祕的感應作用。",
  str_item_rpintro_9995016 = "來自戰亂年代的產物，據說能讓人感到瞬間衰老，頓時步履蹣跚。",
  str_item_rpintro_9995017 = "據說是上一次毀滅性戰爭時出現的神祕物品，帶有強大的詛咒之力，足以重傷對手。",
  str_item_rpintro_9995018 = "鏡片會在戰鬥時發出炫目的光芒致盲對手，並會保護佩戴者免疫此種光芒，屬於輔助性質的裝備。",
