  str_item_1602381 = "蜜特拉",
  str_item_intro_1600011 = "北境的代言人，隨身攜帶的巨型鏡面映射著她不凡的容顏，並隱藏了許多祕密……",
  str_item_intro_1600021 = "嚴肅、認真、堅定，做事雷厲風行且毫不猶豫的啟光聯邦軍團長，靠著手中的長刀立下了赫赫戰功。",
  str_item_intro_1600031 = "原為白夜上城的貴族管家，後因觸犯其他大貴族而被貶至白夜下城，不過根據某些人宣稱，他是帶有祕密任務的……",
  str_item_intro_1600041 = "由兩隻動物外形的流浪漢組成的奇葩雙人組，現為遊蕩的傭兵，憑著強大的戰鬥力與幽默感稱霸一方。",
  str_item_intro_1600051 = "在影鎮出沒的女孩子，笑起來有點瘋狂，喜歡跟人玩危險的「遊戲」，因此人人避而遠之。",
  str_item_intro_1600061 = "白夜城城主的次女，從小養成獨立自主的習慣，憑著天賦與努力成為白夜城的衛隊長。",
  str_item_intro_1400071 = "來自紅油扳手的刺客少女，特立獨行，擅長完成高難度的任務。",
  str_item_intro_1400081 = "紅油扳手技術員，陽光發射器的研發製造者，有一套屬於自己的戰鬥方式。",
  str_item_intro_1500091 = "真理結社的英俊青年，笑起來很迷人，充滿知性魅力，然而無時無刻不在宣揚他心中的學術理念，是個徹頭徹尾的嘮叨鬼。",
  str_item_intro_1600101 = "來自北境的爛漫少女，懷著夢想渴望旅行，對世界上的一切事物都有樂觀的展望。",
  str_item_intro_1600111 = "啟光聯邦的軍團長，擁有「龍之力」的青年軍官。外表冷漠，然而卻是位值得信賴的夥伴。",
  str_item_intro_1500121 = "啟光聯邦的驍勇少女，正義的執行者與踐行人，懷著崇高理想而不停戰鬥。",
  str_item_intro_1500131 = "來自北境的少女，強大的魔法足以操縱冰雪，令整片地區陷入凜冬。",
  str_item_intro_1600141 = "白夜城城主，隨時維持著白夜城秩序的統治者，為此殫精竭慮，絲毫不敢鬆懈。",
  str_item_intro_1400171 = "矮個子女孩，紅油扳手的隊長。反應快、動作靈敏，很少有敵人能抓住她的位置。",
  str_item_intro_1500181 = "紅油扳手的搖滾樂手，相當受歡迎；她不僅能鼓舞士氣，還會身先士卒，帶頭衝鋒。",
  str_item_intro_1600191 = "擁有致命誘惑力的成熟女性，還掌握著某種禁忌知識的真理結社成員，熱衷於推廣某些「真理」……",
  str_item_intro_1500201 = "北風",
  str_item_intro_1500211 = "彷彿鄰家大哥的啟光聯邦成員，十分瞭解自然學，擅長園藝，喜歡引導自然之力去攻擊對手。",
  str_item_intro_1300221 = "戴著兔子頭套的狂熱少年，對柴油與暴力沉迷不已，是紅油扳手的亡命之徒之一。",
  str_item_intro_1600231 = "十分自閉的少女，靠著單簧管與操縱水形之物的獨特能力，在龍蛇混雜的影鎮立足。",
  str_item_intro_1500241 = "來自啟光的搭檔，紅囂張狂野，黑沉著冷靜。雖然性情不同，但配合得天衣無縫，是啟光精銳的戰鬥士官。",
  str_item_intro_1600251 = "啟光聯邦的後勤長官，擁有列車「彼岸號」。無論是戰鬥還是日常生活，都與「彼岸號」配合得天衣無縫。",
  str_item_intro_1600261 = "白夜城騎士團的四天使之一。常常泛起悲觀情緒，與她身旁的熊熊火焰形成奇妙的反差……",
  str_item_intro_1600271 = "白夜城騎士團的四天使之一。正直，不苟言笑，曾因身受重傷接受啟光的改造，因而失去了一部分情感。",
  str_item_intro_1600281 = "白夜城騎士團的四天使之一。擁有獨特的治療能力，以及積極向上的樂觀態度。",
  str_item_intro_1600291 = "白夜城騎士團的四天使之一。個性安靜恬淡、處變不驚，彷彿對任何事都看得雲淡風輕……",
  str_item_intro_1600301 = "紅油扳手領袖，直爽豪邁的大叔，與多位成員都有過命之交。十分照顧妹妹，目前正努力維持紅油扳手的生存。",
  str_item_intro_1500311 = "舒曼",
  str_item_intro_1400321 = "白夜城審判庭的一員，只有一片羽翼的……天使，個性敏感且自尊心強，雖然年輕卻有豐富的戰場經歷。",
  str_item_intro_1500331 = "年紀輕輕便見多識廣，為人努力、熱情，是啟光聯邦器重的優秀人才。",
  str_item_intro_1500341 = "十四行詩",
  str_item_intro_1400351 = "奔走四方的信使，是個工作狂，只要手上的工作還沒完成，就會睡不著……",
  str_item_intro_1500361 = "來自白影鎮的獨行俠。為人叛逆，對於白夜城的秩序十分不以為然，尤其似乎對貴族懷著莫名敵意……",
  str_item_intro_1600381 = "啟光聯邦現任的科研長官，駕駛著巨大機甲，據說是從軍隊退役的一名天才少女。",
  str_item_intro_1400401 = "喜歡爆炸的小女孩，只要聽到爆炸聲就會莫名興奮的紅油扳手成員。",
  str_item_intro_1400411 = "在白夜城中扮演引路人，為新來者帶路的角色。遇到天大的事也能泰然自若，似乎過去有著不尋常的經歷。",
  str_item_intro_1400441 = "嚴肅、認真，身為啟光聯邦的參謀長，大大小小的事情她都能安排得井然有序、鉅細靡遺。",
  str_item_intro_1300461 = "四名小孩子，白夜城的自走廣播小團隊。身為學院唱詩班的一員，本應天真爛漫，卻以奚落他人為樂……",
  str_item_intro_1300471 = "啟光聯邦的天才研究員，求知若渴，世界上吸引她的似乎只有知識以及……啟光聯邦的某位軍團長。",
  str_item_intro_1400481 = "雖然年紀輕輕，但她已經是「烈雀幫」的老大了。她以過人的決斷力與一手奇詐的冷兵暗器，在影鎮穩穩立足。",
  str_item_intro_1300491 = "高大、強壯的戰士，總是穿著全身鎧甲，揹著大劍行走在影鎮，從不摘下頭盔，性格沉默寡言，喜歡以武力說話。",
  str_item_intro_1200501 = "就算笑起來也會令人渾身顫抖的鯊魚！是一座小聚落的守護者，雖然看起來凶悍又恐怖，其實是相當溫柔的人。",
  str_item_intro_1300511 = "沉默寡言的鱷魚榴彈手、聒噪浮誇的牙籤鳥狙擊手，紅油扳手內的奇妙搭檔，是可靠的傭兵。",
  str_item_intro_1300521 = "為啟光聯邦提供郵遞服務的信使，本人其實非常懶惰，完全沒有快遞員該有的勤奮，對工作能推就推，能敷衍就敷衍……",
  str_item_intro_1300531 = "來自紅油扳手的商人，愛財又狡猾，是個隨處可見的奸商。只要有利可圖，他十分願意為雇主服務……",
  str_item_intro_1300741 = "啟光軍團的下級軍官，性格自閉的他與同伴格格不入。據說，這是因為他的神祕血統導致的……",
  str_item_intro_1300581 = "認真、積極的白夜城新晉騎士，由於年紀輕輕便獲重任，因此常常過度緊張。",
  str_item_intro_1400161 = "紅油扳手成員，持有一把強悍的超級電磁導軌步槍，消滅一切進犯的狙擊手敵人。",
  str_item_intro_1400541 = "白夜城新晉守夜人隊長，沉穩、專注，對待任何事情都會拿出令人佩服的認真態度。",
  str_item_intro_1400611 = "樂觀、開朗的啟光聯邦研究員，擁有獨特能力可以吸收同伴的負面情緒，治療他人的心理創傷。",
  str_item_intro_1400731 = "影鎮伊斯塔萬商會的新成員，時時刻刻都處於超級興奮的狀態，請小心她們！",
  str_item_intro_1500421 = "啟光聯邦的軍團長，是個無法忍受無聊和平的戰爭狂，會不擇手段運用一切招數來追求勝利。",
  str_item_intro_1500761 = "禮貌溫和、從容淡定，但會習慣性說謊的紳士，影鎮著名的欺詐師。",
  str_item_intro_1500781 = "影鎮「烈雀幫」的成員，為人自閉且社交恐懼，與姐姐烈雀相依為命，在影鎮中努力生存。",
  str_item_intro_1600771 = "北境的統治者，擁有長年累積下來的知識，人生閱歷豐富，面對任何事都能處變不驚，從容應對。",
  str_item_intro_1300591 = "信使公會成員，專門負責與真理結社的聯絡事務。做事馬虎又缺乏責任感，但為人直言不諱，眾人也就忍受了她的缺點。",
  str_item_intro_1300801 = "啟光聯邦研究人員，對機械、模型狂熱的天才少女。有社交困難，但當她說起自己瘋狂愛好的興趣，就會滔滔不絕。",
  str_item_intro_1300821 = "北境綠松之地的仙子，天真可愛、不諳世事。她長著特別而寶貴的寶石之角，從小便受到特別的呵護。",
  str_item_intro_1400451 = "真理結社的核心成員，維多利亞的追隨者。沉默寡言的他，篤信真理結社的理念，以弘揚理念為終身目標。",
  str_item_intro_1400571 = "啟光聯邦情報長，平日溫和、平易近人，有點慵懶，然而心中的第二人格卻十分叛逆。",
  str_item_intro_1400681 = "信使公會成員，負責的是紅油扳手區域。自信滿滿，可愛、勇猛、不畏挑戰。喜歡在送信途中四處胡鬧，是個可愛的小流氓。",
  str_item_intro_1400791 = "白夜城稅務官，理性、公平、獨立，習慣將一切換算為金幣價值。",
  str_item_intro_1400811 = "紅油扳手亡命陣列小隊成員，充滿自信的熱血笨蛋，沒有心機，任何事情都想當第一。",
  str_item_intro_1400831 = "啟光聯邦科研機構侍從人員，表面是說話方式像機器人的女僕，其實是某個強大生命體的複製人。",
  str_item_intro_1601231 = "啟光治安官，執行任務時總被各種突發情況嚇哭。但為了實現正義，她依然樂觀地在崗位上努力。",
  str_item_intro_1601201 = "出生於富裕家族的貴族少女，天資聰穎，足不出戶，喜歡閱讀。唯一的朋友是自己啟動的巨型鎧甲「龐佩」。",
  str_item_intro_1500151 = "影鎮畫商，蜂懂得鑑賞名畫，而銀城擁有高超的繪畫技巧。兩人默契十足，也會以僱傭兵身分活動。",
  str_item_intro_1501321 = "北境松霜谷口的居民，非常喜歡蜂蜜以及蜂蜜相關的一切。身上的花藤雖然美麗，卻能施放特殊的能力。",
  str_item_intro_1601311 = "北境的子民，與伯利恆關係密切。通曉歷史，富有愛心。認為北境是光靈最後的淨土，希望用自己的力量守護北境。",
  str_item_intro_1601331 = "朵露是一隻極盡殘暴的惡龍，曾單槍匹馬挑戰神明，險些因此喪命。在異世界愛上小林後，選擇成為女僕與她共同生活。",
  str_item_intro_1601341 = "和朵露一樣是龍族，外表與性格都像個小孩。因為惡作劇被家裡放逐，此後一直追隨著朵露。",
  str_item_intro_1501351 = "致力於解決世間紛亂的龍，曾被稱為「聖海的巫女」。個性正直認真，喜愛美食，尤其對甜食毫無抵抗力。",
  str_item_intro_1501361 = "曾是遠古時代掌管文化的神明，具有強大的力量，但平時只是個懶散的大姐姐。",
  str_item_intro_1401371 = "朵露的朋友，過去在另一個世界守護洞窟裡的財寶。見識過太多貪婪的傢伙，因此對他人懷有滿滿的敵意。",
  str_item_intro_1601381 = "啟光聯邦的研究人員，工作時理性效率高，私下則慵懶隨性。醉心於古代科技的她常年在外奔波，調查各種遺跡。",
  str_item_intro_1501391 = "出生於白夜城，黎明學院學生會的成員，總是跟在芙洛琳身邊。經常冒出天馬行空的想法，偶爾也會語出驚人。",
  str_item_intro_1601401 = "出生於白夜城，在黎明學院時擔任學生會長，面冷心熱地照顧著朋友，正在為成為一名優秀的騎士而不斷努力。",
  str_item_intro_1601411 = "出生於紅油扳手，生性活潑的她從小就喜歡探險故事。在掌握了足夠的知識與技巧後，露比踏上了自己的探險之旅。",
  str_item_intro_1501421 = "紅油扳手成員，十分依賴露比。說話帶刺，但那只是心口不一的體現，其實是個細心善良的好孩子。",
  str_item_intro_1601431 = "雲島的巫女，知書達理，禮儀端正。被統治雲島的將軍撫養長大，希望靠自己的力量替雲島的百姓排憂解難。",
  str_item_intro_1501441 = "來自云島的高大女性，曾經被凜音拯救，自稱能夠看見「那些東西」，似乎有些怕生。",
  str_item_intro_1601451 = "出生於雲島，因戰亂而失去家園，被人所救後學習忍術。她的經歷令她個性冷酷，卻對同伴十分忠誠。",
  str_item_intro_1601461 = "出生於雲島，曾在林家商會學習「氣術」。武藝高強，個性活潑，很喜歡行俠仗義、遊歷四方。",
  str_item_intro_1501471 = "出生於雲島的雙胞胎，常常推著一輛拉麵車販賣蟹家拉麵，在雲島生意紅火。希望能夠一邊賺錢一邊探尋極致的美味。",
  str_item_intro_1201631 = "來自北境的謎之生物，熱衷於製作遊戲，不管遇到誰都會先問一句「老師，約稿嗎」。",
  str_item_intro_1601481 = "我行我素的紅油扳手探索小隊成員，長期獨自在外調查各類對紅油扳手有利的情報，曾經是被奉為傳奇的賽車手。",
  str_item_intro_1501491 = "紅油扳手的後勤管理人，看起來有些玩世不恭，但其實心思縝密，為守護整個紅油扳手大家庭操碎了心。",
  str_item_intro_1601501 = "真理結社的一員，沉默寡言但能力出眾。沒有自己的想法更沒有什麼野心，只是在等待著別人為自己下達任務。",
  str_item_intro_1601511 = "真理結社的一員，看起來十分懶散，但激動時會變成另一副模樣。堅信自己是為了傳播「那個童謠」而來到世上。",
  str_item_intro_1501521 = "自閉偏執的少女，為了能在真理結社內得到重用，討好著身邊的大人。其實內心缺愛，只是想得到大家的關注。",
  str_item_intro_1601551 = "啟光聯邦的軍團長，在使用了「和弦紐帶」裝置之後，外表和能力發生了變化，但內心依舊是那個戰爭狂。",
  str_item_intro_1601541 = "啟光聯合探索隊長，性格開朗，體貼善良。機緣巧合下解救了被困地下的空之末裔，開啟了精彩刺激的冒險之旅。",
  str_item_intro_1601531 = "啟光聯邦名副其實的大元帥，她不僅驍勇善戰，且為人坦蕩、治理有方，深受啟光人的愛戴。",
  str_item_intro_1601561 = "出身於影鎮的白夜城貴族人家。雖然她看上去有些不好接近，但私下的她其實並沒那麼難相處......嗯，大概吧。",
  str_item_intro_1501571 = "出生雲島，命途坎坷。為了謀生來到艾斯特拉，卻迷迷糊糊地欠下一大筆債務，現在只希望可以不被僱主辭退。",
  str_item_intro_1601581 = "來自異世界的少年。可以使用名為「Persona」的特殊能力。\n真面目隱藏在面具之下，用代號進行自稱，給人一種不同尋常的感覺。\n在異世界有個轟動一時的「心之怪盜團」，而他正是怪盜團的首領。",
  str_item_intro_1601591 = "來自異世界的「心之怪盜團」成員。\n以作戰參謀的身分，為怪盜團提供行動方針的少女。\n可以使用「Persona」的能力。",
  str_item_intro_1501601 = "來自異世界的「心之怪盜團」成員。\n性情獨特，看上去有些遠離塵世的少年。\n可以使用「Persona」的能力。",
  str_item_intro_1501611 = "與「心之怪盜團」一同來自異世界的少女。\n出於某些原因，暫時與怪盜團共同行動。\n可以使用「Persona」的能力。",
  str_item_intro_1501621 = "來自異世界，外表酷似貓的謎之存在。會講人話。\n為「心之怪盜團」做出過各種指引。\n可以使用「Persona」的能力。",
  str_item_intro_1601641 = "卡蓮·德·舒瓦茲。在前往「好泊城」的旅途中，她的能力發生了變化，對「領導力」的領悟也更加深刻。",
  str_item_intro_1501651 = "啟光的工程學天才。內向、怕生，但渴望與人交往，夢想是製作一台強大的動力裝甲。",
  str_item_intro_1601661 = "小小神奇動物訓練師，任性又倔強，卻意外地愛哭。為了成為比師父維克還要厲害的神奇動物專家而不斷努力著。",
  str_item_intro_1601671 = "魔手·比爾馬戲團的團長，也是真理結社的成員。神祕、詭異、寡言，志向是成為最偉大的魔術師。",
  str_item_intro_1501681 = "因為暗鬼襲擊而背井離鄉的少女，單純、活潑，把保護綠榴石號當作自己的使命，經常客串馬戲團的暖場嘉賓。",
  str_item_intro_1501301 = "出身於白夜城的特洛伊家族。為什麼他出身如此高貴，職位卻如此之低？也許可以從他的性格中得到答案。",
  str_item_intro_1501711 = "看似冷淡，實則很有擔當。為了更好地保護住在教堂的孩子，與珀拉珂一起自稱「烏鴉血」做著自由傭兵的工作。",
  str_item_intro_1601701 = "強勢、幹練的她擁有一段不願回首的往事，如今在破敗蕭條的尤佛里亞堅守著一座教堂，收留無家可歸的孩子。",
  str_item_intro_1401691 = "出生於影鎮的怪力少女，帥氣的外表下是一顆純真又執著的心，把完成各種各樣的委託視作成為俠盜的修行。",
  str_item_intro_1601721 = "樂觀可愛的陽光女孩，為了追逐電影夢想隻身來到影鎮的「好夢塢」，雖然吃了很多苦，但從來沒有想過退縮。",
  str_item_intro_1601731 = "來自影鎮安德森家族的大管家，優雅、強勢的完美主義者。為了報答家主的恩情，他可以獻上自己的一切。",
  str_item_intro_1601751 = "名為阿克希亞的「戰鬥機器」，隸屬於啟光聯邦。儘管擁有這樣的威名，但私底下她的身體狀況卻令人擔心。",
  str_item_intro_1501761 = "白夜城的戰鬥醫生，曾經受到名為約翰的醫生救助。從那時起，她便下定決心，想要成為一名優秀的醫生。",
  str_item_intro_1601771 = "出生在影鎮的著名少女偶像，不只擁有天生的好運，她的積極樂觀也感染著每個人。",
  str_item_intro_1601781 = "在樹林中隱居的神奇動物專家，雖然說話做事常常惹人生氣，還會欺負徒弟菲雅，但對神奇動物卻很好。",
  str_item_intro_1501801 = "目前只是小報社的實習記者，但對採訪充滿熱情，熱衷探聽八卦，目標是成為影鎮最知名的大記者。",
  str_item_intro_1601811 = "曾經的龍洲兆國大將軍，如今的逍遙浪客，無論何時何地，他只願堅守自己內心的事物。",
  str_item_intro_1601821 = "「蜃風號」船長，冷漠果斷，表裡如一。目標是製造出最厲害的遠航船，開闢最安全的遠航線路。",
  str_item_intro_1501831 = "師從名醫卜存子的小醫生，人小鬼大，言語辛辣，同時也是位靠譜的好醫生。雖說如此，他也有不禁夸的一面。",
  str_item_intro_1601841 = "信使公會紅油扳手分部的長老。為人隨和，個性散漫，但同時也是個極具智慧的觀察者。",
  str_item_intro_1501851 = "雖然是新人信使，卻是信使公會裡為數不多認真負責的人，不過有時過於嚴格地遵守公會制度反而導致出錯。",
  str_item_intro_1601861 = "既是承襲爵位的白夜城貴族，也是審判庭的審判官，同時還是一個時常處於昏睡狀態的「特殊體質」少女哦～",
  str_item_intro_1601891 = "白夜城的審判官，剛正不阿，嫉惡如仇，對待他人一視同仁。與之相對的，也有過於固執，與人疏遠的一面。",
  str_item_intro_1501901 = "白夜城審判庭的審判官，雖然天分奇高，但沒有太大野心，只想開心且富有地過平凡的生活。",
  str_item_intro_1601911 = "擁有亞人血統的影鎮獨行者，沒什麼朋友，由於說話過於直接而常常引發不必要的誤會。",
  str_item_intro_1501931 = "雖然出生於貴族世家，但也有著特立獨行的態度，根據自己的心願成為了白夜城的見習審判官。",
  str_item_intro_1601921 = "「鐵棘騎士團」團長，性格果斷，為人威嚴又不失親和，力求改變白夜城現有的腐朽格局。",
  str_item_intro_1601991 = "出生於啟光的軍人家庭，現在是委員會的高級情報官。在她深邃的眼底，正籌謀著一個個計畫。",
  str_item_intro_1502001 = "啟光聯邦的情報官，冷靜又可靠，只是偶爾會說出令人意外的吐槽，也不知道他這樣做究竟是有意還是無意。",
  str_item_intro_1602011 = "隱居影鎮的白夜城騎士，不被提及的舒瓦茲長女。單純善良的她，似乎一直渴望獲得父親的認可。",
  str_item_intro_1602021 = "壯年的舒瓦茲，持劍遠征暗鬼，既是即位不久的白夜城統治者，也是上陣殺敵的戰士。",
  str_item_intro_1502031 = "北境使者，為人十分熱情活潑，不過由於占卜術還不太熟練，加上馬馬虎虎的性格，經常惹出一些麻煩。",
  str_item_intro_1602041 = "人們都說她長相酷似那位已逝的城主夫人，但似乎又並非同一個人。約書亞希望帶著理想，造訪世上更多地方……",
  str_item_intro_1502051 = "從「守夜人」守衛隊長一職退隱多年的白蘭再次拿出作戰服，當年的「紅女士」重出江湖！",
  str_item_intro_1602061 = "在影鎮長大的富家小姐，原本可以在家中悠閒享受生活，卻偏要獨自創業，只為完成她心中的夢想。",
  str_item_intro_1602071 = "奉行「活在當下」人生準則的峽谷度假村總管，外表看似輕浮，辦事卻意外可靠。",
  str_item_intro_1502081 = "不光是巨像「陸行者號」的導航員，也是紅油扳手的「軍師」，不過在大家眼中，她似乎更像是吉祥物……",
  str_item_intro_1400861 = "白夜城黎明學院成員兼葬禮司儀。作風大膽，溫柔細膩，總是沉著冷靜、笑瞇瞇地面對一切。",
  str_item_intro_1400911 = "白夜城樂師，溫柔友善、很容易陷入悲傷的回憶。因戰爭失去家人，自此生活在悲傷當中，難以自拔。",
  str_item_intro_1500701 = "影鎮中的獨行俠，擁有「龍之力」。心高氣傲且喜怒無常，總覺得自己背負著家族的命運。",
  str_item_intro_1500751 = "紅油扳手的技術人員，對自己的通訊技術很有自信，喜歡在通訊頻道裡亂噴人，但在現實生活遇到問題就會手忙腳亂。",
  str_item_intro_1500841 = "影鎮的地下領袖，為人果斷、灑脫，十分講義氣。經歷過嚴酷的生存挑戰，因此獲得了如今的聲望與地位。",
  str_item_intro_1500881 = "紅油扳手成員，通常負責偵查。膽小、害羞、笨拙，但戰鬥時會進入「亢奮狀態」，威力強大且不受控制，瑪姬自己也很苦惱。",
  str_item_intro_1500901 = "紅油扳手的偶像歌手，外表甜美溫柔，但要是遇到沒禮貌的粉絲，會展現出暴躁的一面。",
  str_item_intro_1500921 = "真理結社成員，剛正不阿但不知變通，一旦認定目標就會專心一意努力。品味十分獨特，常常跟他人抬槓。",
  str_item_intro_1600601 = "紅油扳手的幹部，神槍手，也曾是賞金獵人。個性散漫、玩世不恭，對敵人毫不留情。沒人看過她手銬拿下來的樣子。",
  str_item_intro_1600641 = "啟光聯邦近衛軍團長，野心勃勃，試圖堂堂正正地挑戰啟光領袖的位置。她精力充沛，努力爭取大權，佔有欲強。",
  str_item_intro_1600891 = "白夜城審判庭審判長，善良溫和、正直堅定，擁有自我奉獻的精神；心中有偏執的一面，只是隱忍不發。",
  str_item_intro_1601031 = "來自真理結社的審問官，維多利亞的追隨者。瞳孔擁有強大的「災厄之力」，目前已經被封印。",
  str_item_intro_1500871 = "白夜城尚武派貴族，地位尊貴、力量強大。忠於傳統、責任感強，為人略嫌傲慢，但最近已經逐漸在改了。",
  str_item_intro_1401011 = "啟光的通訊員，負責傳遞通訊內容。工作認真，善於察言觀色，偶爾喜歡開一些無傷大雅的玩笑。",
  str_item_intro_1401021 = "影鎮烈雀幫的盟友，喜歡隨性、無拘無束的生活，口中的棒棒糖與手中釋放的電流，是她的專屬標誌。",
  str_item_intro_1500991 = "影鎮的流浪傭兵。出生便背負著詛咒，從小體弱多病，只能靠著手中的魔劍維持生命。",
  str_item_intro_1501001 = "真理結社成員，生於古老的貴族家庭。從小被選為祕密墓穴的守護人，受到嚴苛的教育，知性但冷漠。",
  str_item_intro_1600931 = "啟光負責生命科學的研究員，平常看起來遊手好閒，但在關鍵時刻卻會展現出冷靜沉著的一面。",
  str_item_intro_1500981 = "由於詛咒而缺乏正常情感，似乎會依賴每天醒來後見到的第一個人。現隱居於影鎮，是伊斯塔萬麾下的刺客。",
  str_item_intro_1400621 = "北境的守林人，外表是清秀冷峻的少年，但內心溫和，渴望摯友。由於年齡尚小，外表稚氣未脫。",
  str_item_intro_1400951 = "擁有動物般的身形，是一名四處遊走的傭兵。如果不把眼前看到的所有東西都吐槽一遍，就會渾身不對勁。",
  str_item_intro_1300941 = "來自北境的巡邏員，天真善良、不諳世事。她習慣獨自在寒冷的環境巡邏，並為人們捎來春日的氣息與希望。",
  str_item_intro_1600961 = "出生於啟光，為了尋找祖父生前的情報而流浪至影鎮。她做事迷迷糊糊，不太懂得辨認資訊的虛實。",
  str_item_intro_1500971 = "出沒於影鎮的刺客，為伊斯塔萬執行「特別」的任務。在此之前，他曾是一名醫術精湛的外科醫師。",
  str_item_intro_1500561 = "在大陸各地獨自旅行的獵人，思路異於常人。隨身攜帶燧發槍與筆記本，隨時準備獵殺暗鬼，喜歡詳細記錄獵殺過程。",
  str_item_intro_1701071 = "被封印的古代英雄。出於對暗鬼的仇恨而接受改造，一度變得十分暴戾，但最終恢復了沉穩、積極的性格。",
  str_item_intro_1701081 = "被封印的古代英雄。由於接受改造而掌握了強大力量，又因無法控制力量而導致一場災難，至今仍自責不已。",
  str_item_intro_1701091 = "被封印的古代英雄。由於接受改造而失去了大部分的情感，據說在完成自己的使命後，被她所捍衛的國家所拋棄……",
  str_item_intro_1701101 = "被封印的古代英雄。從小便站在對抗暗鬼的最前線，任性、嘮叨。雖然接受了改造，卻保留了認真、單純的初心。",
  str_item_intro_1501041 = "由於黑暗力量的影響，導致她雙目失明。外表冷漠、孤僻，熟悉後便會與人親近，是個有話直說的率直女孩。",
  str_item_intro_1601051 = "醒山的妹妹，小時候受到暗鬼影響導致失控，一度失去自我。治癒後，終於回到了本來天真爛漫的個性。",
  str_item_intro_1500711 = "從遠東來到影鎮定居的「萬事屋」老闆，也是伊斯塔萬的盟友。為人孤僻、叛逆，做事果決俐落。",
  str_item_intro_1400671 = "來自北境的少女，擁有一點亞人族的血統。個性天真活潑，好奇心強，目前正與兩名玩偶四處旅行。",
  str_item_intro_1601111 = "真理結社成員，能夠掌控強大的「血晶領域」，用其困住敵人。然而，這些紅色晶石也對她的心志產生影響，令她淡漠、寡言，內心經常縈繞悲觀的念頭。",
  str_item_intro_1601121 = "生活在影鎮的自由人，性格狂野且直來直往，擁有強大的火焰之力，喜歡追求新鮮刺激的事物。",
  str_item_intro_1501131 = "真理結社中的音樂家，表面可愛熱情，實際上為了追求終極的樂章而不擇手段。對自己的音感充滿自信，並且很鄙夷白夜城的音樂水準。",
  str_item_intro_1501141 = "表面上是賞金獵人，實際為真理結社的成員。舉止優雅，個性開朗，愛好琴酒。現在正試圖為真理結社建立情報網，順便追蹤「那傢伙」的下落。",
  str_item_intro_1601151 = "信使公會成員，專門負責白夜城的工作。性格沉靜、優雅，擁有與動植物交流的神祕力量，身旁總是跟著幾隻動物及無數螢火蟲。",
  str_item_intro_1601161 = "好脾氣的紅油扳手技術員。他不懂如何拒絕他人，偶爾會引起騷動，為此十分苦惱。他擅長修理各種機械，也在努力建造一架屬於自己的機甲。",
  str_item_intro_1401271 = "曾居住在紅油沙漠，後加入真理結社，能夠操縱奇妙的紙箋戰鬥。平常的性格顯得弱勢，但堅信靈魂存在，已經達到偏執的地步。",
  str_item_intro_1601191 = "啟光新兵，戰鬥天才，然而性格孤傲、衝動，不擅溝通。她渴望在戰鬥中立下功績，證明自己。",
  str_item_intro_1601221 = "來自影鎮的僱傭槍手，擁有精湛的射擊技術。為人精打細算，喜歡蒐集古董，夢想是賺到足夠的錢開一家古董店。",
  str_item_intro_1601171 = "曾經活躍於啟光防線上的老兵，現已退役成為後勤人員。個性外粗內細，在戰鬥中是一位可靠的戰友。據說曾一度因過去戰爭的創傷而失落消沉，好在現在已經走出來了。",
  str_item_intro_1601211 = "真理結社成員，性格叛逆、理性、有底線。她原為白夜城修女，後突遭變故，看穿白夜城內在的虛偽，就此離開，從此投身於揭露其真面目的行動。",
  str_item_intro_1300651 = "信使公會成員，負責北境區域。是一位熱心的信使，但是多少有點笨手笨腳，加上獨特的口音，顯得單純、可愛。",
  str_item_intro_1500551 = "白夜城審判庭的審判官，性格古板、務實、雷厲風行，現在正為了查明過去的案件四處奔走。",
  str_item_intro_1601261 = "影鎮總商會負責人，伊斯塔萬的副手，也是其養女，性格認真、嚴肅，行事一副商業風格。",
  str_item_intro_1601291 = "影鎮傭兵團的副團長，為人講信用，熟稔影鎮種種地下消息，現在正為了壯大傭兵團而努力。",
  str_item_intro_1602371 = "傳聞中幻蜃一族的後裔，幾乎無法保留記憶，卻十分樂觀、善良。因為感激好泊城收留自己，正在努力助人為樂。",
  str_item_intro_1602381 = "蜜特拉出身朗基努斯一族，延續兩千年來捍衛星辰祕密的使命。 她為人低調謹慎，將鋒芒藏匿黑羽之下。",
  str_item_intro_1702361 = "祭劍座曾是國王的左膀右臂，亦為寂靜獵兵的隊長。他秉持公義，絕不動搖。縱使光能不再眷顧，他仍以星辰之力開闢未來。",
  str_item_get_discovery = "{0}",
