  str_item_5273056 = "地圖道具",
  str_item_5273057 = "郵筒道具",
  str_item_5234040 = "「紅油美食節」",
  str_item_5234041 = "「探祕尖叫屋」",
  str_item_5234042 = "「為了啟明之光」",
  str_item_5234031 = "棘針獸像",
  str_item_5234032 = "三角獸像",
  str_item_5241014 = "胖胖巨像熱氣球",
  str_item_5232007 = "懸空庭凳",
  str_item_5234035 = "數紋之碑",
  str_item_5222001 = "灌木叢矮牆",
  str_item_5222002 = "灌木叢高牆",
  str_item_intro_5212001 = "「船隻已經被我搞沉了，接下來就是你！啊啊啊——怎麼突然用我的手玩起了滑梯？好吧，看在你們很高興的份上，這次就饒過你們！」\n據說是仿製海怪的觸手製作的滑梯，怎麼樣，很刺激吧？",
  str_item_intro_5212002 = "不知道是誰將船上的桅杆搬到這裡來的，總之，爬上去就能讓你望得很遠。偶爾喊上一句「船長！陸地！」，就仿佛置身於大洋之上。",
  str_item_intro_5212003 = "能夠在鬆軟沙灘上也能穩穩矗立的營帳，整體十分輕盈，而且材質都是防火的！這或許是考慮到遊客要在營帳內生火玩樂吧。",
  str_item_intro_5212004 = "能夠讓兩人並排盪起的鞦韆，很適合在海岸邊玩耍，加上迎面而來的微微海風，絕對會創造一段美好回憶。",
  str_item_intro_5212005 = "直接用廢棄掉的半截小船做的遮陽椅，看來是某些水手們的奇思妙想。",
  str_item_intro_5212006 = "在沙灘上看到的展示架，可以在板子上繪製各種圖案，有時候也被人當作留言板，還能將各種彩旗系在架子上，用於吸引遊人的眼球。",
  str_item_intro_5212007 = "秉承「廢物利用」的精神，某些水手將半截小船拆開，船板做了桌椅，龍骨則當成了遮陽用的藤蔓架，別有一番風味。",
  str_item_intro_5212008 = "有點重的遮陽傘，搬運起來比較吃力。它的傘柄尾部是尖的，可以很方便地插入海灘，牢牢地固定在地面上。",
  str_item_intro_5212009 = "這種椅子採用了貼合身體的設計，躺在上面不僅十分舒適，還能很愜意地伸展手腳。",
  str_item_intro_5212010 = "輕便、靈巧的桌子，可以讓遊客隨意挪來挪去，方便他們在沙灘上找個好位置，聚在一起度過這美妙的時光。",
  str_item_intro_5212011 = "玩累了就休息一下吧！這時候就需要它了，坐在上面，再來一些飲料，可是恢復精力的捷徑。",
  str_item_intro_5212012 = "咦？這些是海底石柱，還有珊瑚？什麼時候搬到陸地上的？再仔細看下，其實是用木頭加上油漆巧妙製作的圍欄，不僅美觀，還很符合臨海的氣息。",
  str_item_intro_5212013 = "用細沙鋪設的一片區域，仿佛將沙灘搬過來一樣，給人營造一種濃濃的海邊氛圍。",
  str_item_intro_5241018 = "這個大箱子中放有微縮山石和些許水草，加上機關裝置在其中讓水流循環，足以令魚兒們在其中安然暢遊。",
  str_item_intro_5241019 = "色彩豐富的珊瑚擺件，配合石頭底座，令觀者仿佛置身於海洋之中，甚至還能看到魚群游過的身影......",
  str_item_intro_5241020 = "神祕的上古遺跡之一，據說能汲取周遭的光能，發出無害的光線，很適合作為裝飾、照明，或者向遠方發出訊號～",
  str_item_intro_5212014 = "好大的貝殼！大到不像是天然形成的。如果裡面有珍珠，那一定是稀世珍品。即便是貝殼，也沒有被浪費，有人在裡面鋪上了軟墊，製成了這奇妙的沙發。",
  str_item_intro_5212015 = "水母造型的氣球，將之放在天空上時，垂下的彩帶形成了它的「觸手」，加上飄蕩的身姿，感覺它就是一隻活的水母，只不過在天上浮游而已。",
  str_item_intro_5212016 = "不要被它的造型嚇跑！其實它只想給你照亮道路而已，你看，它的嘴巴裡沒有牙齒呢～",
  str_item_intro_5212027 = "很適合與長桌一起擺放的高腳凳，不僅能調整高度，椅面還能轉動，這受到很多小孩子的青睞。",
  str_item_intro_5212028 = "不可缺少的綠色裝點之物，綠植盆的外形也和其他節日裝飾物相得益彰，感覺擺放再多也不會有什麼問題～",
  str_item_intro_5212029 = "連成一排的柵欄，用於在節日中劃分區域所用，因此還進行了專門的塗裝，感覺在上面放上一些其他裝飾，也是沒問題的～",
  str_item_intro_5212030 = "為了溫德嵐節專門辟出的苗圃，提前培植的蒲公英已經成熟，專等在節日夜晚放飛。",
  str_item_intro_5212031 = "別看路燈架子的構造很簡單，用的也是尋常木料，但由於在關鍵地方進行了加固，因此還是很牢靠的。其實這架子上不僅能掛照明燈，也可以讓小動物們短暫歇息，充當臨時落腳點。",
  str_item_intro_5212032 = "具有節日氣息的矮柱，連成一排後與圍欄有同樣效果。",
  str_item_intro_5234034 = "石制外表令其看起來多少有些粗糙，但是裡面的構造十分巧妙，空間很大，只要打開箱口，就能很輕鬆地回收裡面的垃圾。",
  str_item_intro_5212020 = "很適合擺放在路邊的架子，路過者可以將小件物品放在其上，也可以依照自己的想法略加裝點，成為野外的一道風景。",
  str_item_intro_5212021 = "看著很大，其實是木板製成，裡面是空心的，因為很輕，所以很適合快速搬到各種地方，多半用在節日中進行輔助裝飾所用。",
  str_item_intro_5212022 = "造型十分簡單的木杆，裡面似乎經過特別加固，可以讓很多小動物在上面逗留，以這個角度來說，或許倚著它休息一下也不是不行......",
  str_item_intro_5212023 = "輕巧的燈欄，由於構造比較特殊，足以掛起很多燈籠，用於照明或在節日中增加氣氛。",
  str_item_intro_5212024 = "以木杆和白布為基礎，上面裝點了各種藤蔓、綠葉以及花朵，多用於各種節日，據說在下面走過時，有微風吹過，導致布簾碰到身軀，或花瓣、葉草落在肩頭，未來一段時間都會擁有好運的。",
  str_item_intro_5212025 = "不知道是誰第一個在節日上搭建了這種枝巢，據說當時吸引了不少小動物，一起度過了那個熱鬧的節日。此後就成為了不成文的傳統，總有些人喜歡在節日上搭建這種枝巢，據說引來的小動物愈多，獲得的祝福就會愈多～",
  str_item_intro_5212026 = "在節日中放在外面的桌子，略有一些重，因為桌面是實木的，並且用石板加以支撐，據說這麼做是擔心有人在桌子上跳舞，所以必須堅固耐用。",
  str_item_intro_5234021 = "不僅可以擺在房間中，也能放在郊外的櫃子，木板還算結實，經得起日曬雨淋，通常會在裡面臨時存放一些暫時用不上的物件。",
  str_item_intro_5212018 = "通常在溫德嵐節中掛的彩偶，裡面放了很多彩紙和彩帶，敲打後會灑出來，頗受小孩子歡迎。有時候還會在裡面放上鈴鐺或「幸運幣」，用聲音或驚喜的獎勵來吸引更多孩子的「關注」。",
  str_item_intro_5212019 = "足以讓人在上面跳舞的巨鼓，鼓面很薄，然而十分堅固，在上面肆意跳躍也不會破！由於特別的構造，鼓聲能傳出很遠，而且鼓面十分敏感，能感受到鼓手踩踏的各種變化，發出不同的聲響。",
  str_item_intro_5241021 = "鱗甲獸可不常見，更別提傳說中的鱗甲獸一族！快快去合影吧！還能充當一下這一族的成員呢～",
  str_item_intro_1601881 = "身為被當作質子的鄴國郡主，丹棠卻表現得相當從容。她在濟國潛心學習的同時，也等著回到家鄉的機會。",
  str_item_intro_5212017 = "這座石像的具體意義已經不明，據說是上古留下的遺物。在溫德嵐節中，很多空裔都會到這裡祝福、許願。據說那些蠟燭會聽從空裔的心聲，傳遞給石像，讓石像用神祕的力量幫助許願者喔～",
  str_item_intro_5271001 = "特別大的泳池，需要有比較大的空間才能放得下，當然也能允許很多人在其中一同游水嬉戲。",
  str_item_intro_5272001 = "通常被擺放在泳池旁的小屋子，擁有淋浴設備，能清潔身軀，當然還有一個更重要的功能——換衣服。",
  str_item_intro_5272002 = "游泳是十分耗費氣力的運動，太累了不妨休息下，再到這奇妙的自動裝置前拿一筒冰淇淋，便是無上的享受～",
  str_item_intro_5272003 = "音樂不能少！光是戲水也容易無聊，休息時到這裡聽歌放鬆，還能跟隨音樂節奏起舞！",
  str_item_intro_5272004 = "充了氣的長椅，躺上去很舒服。如果將其放在水中的話，足以成為一座小舟，無論是休息還是幫人浮在水面上，都是很適合的。",
  str_item_intro_5272005 = "由於採用充氣填充，因此這椅子極為輕便，不僅能隨身攜帶，在放氣後甚至可以收進背包中，不占任何空間～",
  str_item_intro_5272006 = "不識水性者的福音！利用它，即便是旱鴨子也能浮在水面，甚至還能撲騰著游上幾下。",
  str_item_intro_5272007 = "無論在泳池邊還是泳池裡都會用到的玩具，充氣後不僅有彈性，可以在地上跳來跳去，更重要的是，掉進水中也不往下沉～",
  str_item_intro_5272008 = "游泳是極為消耗體力的運動，必要時就躺在它上面恢復一下體力。做成魚形的枕墊特別舒適，而且富有海濱氣息～",
  str_item_intro_5272009 = "這柄傘雖然有些大，不利攜帶，但是為了避免陽光直曬身軀，無疑是值得的。在炎炎夏日，它帶來珍貴的陰涼。",
  str_item_intro_5272010 = "用來自海洋中的各種貝殼，加上裝飾而成的製品，若放置得當，足以給人帶來身處海邊的感覺。",
  str_item_intro_5272011 = "海星實在太受歡迎了，即便單單放上幾個牠的擺件，就會吸引不少人的目光～",
  str_item_intro_5272012 = "據說是用某些上古技術製作的展示牌，能自動顯示各種圖案！似乎還能用奇妙的裝置來改變上面的訊息，看來應該有什麼意想不到的用處......",
  str_item_intro_5271002 = "據說是某位熱愛海洋的空裔設計的，還有配套的雕像，據說能獲得海洋的祝福哦！如果要出海旅行的話，來這裡待上那麽一會，或許真的有用~",
  str_item_intro_5272013 = "如果能在海洋上看到它，代表航行中會有極大收獲！不過她們真的存在嗎？還是水手們的幻想？無論如何，至少這座雕像很漂亮，會吸引不少年輕人駐足。",
  str_item_intro_5272014 = "遠洋時，某些迷路的水蛸會誤爬進船隻，暫時無法回去，好心的水手將之釋放後，它們往往在幾天後回來贈與一些小禮物，例如小珍珠、遺落在海中的錢幣……這座雕像因此也就代表了友誼與餽贈。",
  str_item_intro_5272015 = "聽很多人說過，如果能在航行時看到跳躍的海豚，那麽這一路就會平安無事。不知道它們會不會祝福陸地上的旅行者呢？",
  str_item_intro_5271003 = "在導演們的天馬行空想像之下，利用角度、道具布置和攝影機，足以製造出各種或驚險刺激、或美麗夢幻、或恐怖可怕的場景，並在其中將那些停留於書本之上的故事，變為逼真的影像。",
  str_item_intro_5273001 = "雖然是圖片，然而在鏡頭中足以體現出王家宮殿的氣勢，用來拍攝宮廷劇之類的電影再適合不過。",
  str_item_intro_5273002 = "看起來仿佛名貴石磚構成的地面，其實只是鋪上了一層紙喔！畢竟是道具性質的「地板」，能夠滿足快速更換的需求才是第一位的。",
  str_item_intro_5273003 = "雖然是道具，然而這面「魔鏡」也十分沉重，起碼是鐵制的......當然上面的鍍金和寶石都是假的，鏡面倒是保持了魔鏡的感覺，反射不出任何事物，這究竟是怎麼做到的呢......？該不會真的是魔鏡，而不是道具吧？",
  str_item_intro_5273004 = "僅僅是當作道具，當然不可能真的從北境找一棵燈螢木啦～只是用了普通的木頭加上紙片、彩帶來裝扮的而已，千萬不能送給北境住民喔。",
  str_item_intro_5273005 = "說是硬木衣架，其實只是用劣質膠合板製作而成，反正並不會真的經常用它來放置衣物，所以只要看起來像就可以了。",
  str_item_intro_5273006 = "內裡用黏土，外側用白色細沙製作而成的玩偶，乍一看仿佛真的是用雪堆積而成的，不過它的好處是永遠不會融化喔～",
  str_item_intro_5273007 = "在道具師們的巧手之下，這木制雕像看起來與真雕像一樣栩栩如生，重點是它很輕，非常適合在片場搬來搬去。",
  str_item_intro_5273008 = "用舊的真貨加以清洗、晾乾後的「道具」。作為舊貨，雖然不少地方已經陳舊了，但是從某個角度來看，還是很新的～",
  str_item_intro_5273009 = "它......它居然也能浮空！這是道具還是真貨呀～？反正無論真假，浮空原理都不太清楚。不過它真的適合出現在片場嗎？",
  str_item_intro_5273010 = "即便是貼上去的背景板，也能給人一種十分恐怖的感覺，這究竟是道具師高超的繪畫功力導致的，還是這木屋真的很嚇人？現在來看，那些恐怖電影中的尖叫聲，或許不是演出來的。",
  str_item_intro_5273011 = "和恐怖木屋背景板相搭配的道具，鋪開後就仿佛冒出一股陳年朽爛之氣，很適合在恐怖電影中出場。",
  str_item_intro_5273012 = "故意做舊的「古」籍，裡面是寫有文字的喔！據說為了逼真，文字、排版方式、插圖都是一比一複製下來的，連封面也是！在某種程度上，已經是一本抄本了，不過裡面的內容可是祕密喔！",
  str_item_intro_5273013 = "能夠漂浮在空中的道具，裡面應該是氣球吧......下面還用細線栓在底座上，令其不會飄到天上。",
  str_item_intro_5273014 = "直接把某些玩具拿過來用了，比起新貨，只是有點舊而已。雖然這玩具的本意是在某些節日裡逗小孩子開心，但是放在恐怖電影的片場中，反而有一種特別的詭異感。",
  str_item_intro_5273015 = "無論是「石碑」還是土地，其實都是木架、木片蒙上紙製成，很輕，重點是可以快速製作很多個，擺在片場的話，能夠迅速製造出陰慘慘的墓園氣氛。",
  str_item_intro_5273016 = "用木頭和金屬片製作而成的傳聲器，當然是不能用來交流的，所以大家在恐怖電影中看到的那些使用傳聲器說話的場景，或許都是演員在分飾兩角喔～真是很辛苦的。",
  str_item_intro_5273017 = "鬼臉看起來很適合恐怖片，不過那頂帽子......總感覺戴上去會有一種沙漠風情，或許是要追求不同的影片風格？",
  str_item_intro_5273018 = "盆和土都是真的，花肯定是假的，聽說是用布片裁剪，再繪上圖案製成，廉價又便捷，並且永遠不會凋謝～",
  str_item_intro_5273019 = "只要布置好後，就仿佛能聞到酒香、聽到隱隱約約的碰杯聲，甚至還有輕盈的歌曲。在這種「酒吧」裡，不知道會上演什麼樣的名橋段呢？",
  str_item_intro_5273020 = "略微陳舊的地板，看起來就很有年頭了，因此即便鋪得不好也沒關係，這種酒吧的木制地板，偶爾破洞也是能夠接受的～",
  str_item_intro_5273021 = "或許是最昂貴的道具之一了，畢竟這是真貨，放上唱片就有聲音飄出！因此編劇們千萬不能寫「主角砸碎唱片機」的橋段，雖然限制了某些劇本的發揮，不過它倒是可以免費為片場配音，也算「一具兩得」。",
  str_item_intro_5273022 = "吧台是膠合板做的，還算堅固，當然比不了那些用實木做的真品......椅子倒是從某些酒吧收購而來，雖然舊了點，好在刷了一遍漆後，就可以當新的來用。",
  str_item_intro_5273023 = "與酒吧氣氛相得益彰的桌椅，無論是樣式還是裝潢，都給人一種「這桌椅應該放在酒吧」的感覺，擺上一、兩套，即便沒有導演的具體指示，演員多半也會讀懂片場氣氛，明白這場戲是發生在酒吧中了。",
  str_item_intro_5273024 = "據說是某些導演為了拍攝奇怪題材的影片而特別借來的桌椅，擺上去就會有工作氣息，不過真的適合放在酒吧嗎？感覺好像是因為經費不夠了所以才從別的片場強行搬過來的。",
  str_item_intro_5273025 = "真的鋼琴實在太重了！而且很貴的！所以弄個假的來充數就好，反正現在不少新晉演員也不會真的去彈，只要比劃兩下就行了～",
  str_item_intro_5273026 = "用木板快速搭建的舞台，比起真的舞台來說不算太牢固，好在不用消耗太多人力，萬一弄壞了可以很快地再搭一座～",
  str_item_intro_5273027 = "木制刀架是真的，不過上面的刀......應該是道具刀，用來比劃兩下是沒問題，因為沒有開刃，即便在某些打鬥戲中失手砍到演員，也不會受什麼傷。",
  str_item_intro_5273028 = "陽光灑進教室之中，課桌椅整齊的排列著，似乎還隱約能聞到粉筆的氣味。\n而想必靠窗的倒數第二排，就是為你準備的座位吧。",
  str_item_intro_5273029 = "非常常見的木質地板，但經過了特殊處理變得更加耐用。請換上室內鞋再走在上面哦。",
  str_item_intro_5273030 = "樣子奇怪的料理機，也是轉蛋機。在打開它掉落出來的東西之前難以分辨裡面是什麼。",
  str_item_intro_5273031 = "神祕的烹飪器具，據說相比油炸更加健康，即使是料理新手也能使用自如。",
  str_item_intro_5273032 = "裡面咕嘟咕嘟的冒著氣泡，必須一直攪拌才能讓裡面的材料充分融合。\n誰會不喜歡由一位美少女來做這項工作呢？",
  str_item_intro_5273033 = "裝著神祕液體的桶，裡面隱隱散發出不妙的氣味。",
  str_item_intro_5273034 = "日夜工作不停，供給食品和飲料的機器，拯救懶人的福音。",
  str_item_intro_5273035 = "需要熟練技巧才能奏響，不過到了晚上沒人也會響個不停。",
  str_item_intro_5273036 = "這個只是道具，千萬不可以吃哦！",
  str_item_intro_5273037 = "富有生活氣息的客棧，店裡聲音嘈雜、魚龍混雜，誰也說不清這裡有些什麼人，會發生什麼事。",
  str_item_intro_5273038 = "木質的地板，踩上去吱呀作響。",
  str_item_intro_5273039 = "客棧裡用來收銀的櫃檯，老闆會一直坐在這裡，如果孤身一人令你感到寂寞，可以來找他聊聊天。",
  str_item_intro_5273040 = "考究的瓷器，可以看出老闆在擺設上頗有品味。",
  str_item_intro_5273041 = "奇奇怪怪的擺件，也許是某位客人送給客棧的。",
  str_item_intro_5273042 = "魚骨頭製成的標本，從大小上來看，它生前的樣子一定很威猛。",
  str_item_intro_5273043 = "做工簡陋的木制家具。一旦遇上脾氣不好的客人，家具是最先遭殃的東西，可不敢買太貴重的。",
  str_item_intro_5273044 = "讓人熟悉的桌椅擺設，坐上去有種回家的感覺。",
  str_item_intro_5273045 = "看起來就很暖和的家具，如果是冬天的話，在裡面躺上一天一定非常舒服。",
  str_item_intro_5273046 = "老闆釀造的美酒，揭開蓋子來有一股濃郁的香氣，人們時常會在氤氳中悵然若失，為此生未盡的那些遺憾落淚。",
  str_item_intro_5273047 = "不知從何處弄來的紀念品，為店裡增添了一些異國風情。也許它會令人浮想聯翩，年邁的老闆與異國他鄉的聖盃之間，曾經發生過什麼值得紀念的故事呢？",
  str_item_intro_5273049 = "風聲蕭瑟，鴉聲四起，周圍的環境一片肅殺。孤身行走其中的英雄武士，注定要踏上一條險峻的道路。",
  str_item_intro_5273050 = "亂世之中，多得是這種無名之地，在此地潛行時，注意不要讓腳下的枯草吱嘎作響，也不要留下自己的氣息。",
  str_item_intro_5273051 = "怎麼看都像一個普通櫃子，但一旦破解了機關，就立刻會彈出名貴的刀劍。請一定要在知情人士的指導下操作哦。",
  str_item_intro_5273052 = "畫著蘆葦圖案的裝飾片，布置在片場的話，會讓人忍不住想要騎著馬在其中隨意馳騁。",
  str_item_intro_5273053 = "畫著麥田圖案的裝飾片，布置在片場的話，會有武士埋伏其中嗎？",
  str_item_intro_5273054 = "畫著向日葵圖案的裝飾片，布置在片場的話，陽光都會被吸引過來吧。",
  str_item_intro_5273055 = "來源神祕的放映機，下面墊的襯布也很有年代感，一旦把錄影帶放進去的話，似乎就能看到一些關鍵資訊。",
  str_item_intro_5273056 = "來源神祕的地圖，很像是戰爭時期才會使用的軍事地圖，上面似乎記載著一些關鍵資訊。",
  str_item_intro_5273057 = "來源神祕的郵筒，沒有人知道它在這裡設立了多久，仔細觀察筒身的刻痕，似乎就能看到前人留下的一些關鍵資訊。",
  str_item_intro_5234040 = "機靈的紅油扳手商人狡木，連這裡都不忘記放上廣告，看樣子是讓大家參與「紅油美食節」，據說優惠很多的，不過那邊都是沙漠，不會有什麼奇怪的食物吧？",
  str_item_intro_5234041 = "據說是「史上最年輕的天才美少女製片人兼導演兼主演兼攝像的傑出處女作電影」，聽說又恐怖又搞笑，這一點從看板上就能看出來了。票房究竟如何？只能拭目以待了。",
  str_item_intro_5234042 = "啟光聯邦的招募牌，帶有獨特的啟光氣勢。那句「與我們一起站在對抗暗鬼的最終、最強防線之上」的宣傳語，鏗鏘有力，看來會有不少人心動吧。",
  str_item_intro_5234031 = "頭頂長有針的動物，似乎一副十分暴躁的樣子，好在它只是個雕塑～",
  str_item_intro_5234032 = "雖然它有著很長的角，但是看起來很溫順......而且有一種很想摸摸這種動物的感覺。",
  str_item_intro_5241014 = "發生了什麼事？它怎麼變得這麼胖了！雖然如此，它還是能飛的～也能將別人帶上天空，讓人享受下身在高處的感覺。",
  str_item_intro_5232007 = "這個技術太神祕了！原理到現在都不清楚，只知道坐上去就會漂浮起來，而且石凳還能自己保持平衡！不用怕，去試試吧～",
  str_item_intro_5234035 = "這座古代紀念碑上的雕紋有著整齊的規律，形成了奇妙圖案。據說它代表了某種數學原理，但具體是什麼就不得而知了～",
  str_item_intro_5222001 = "將容易生長的灌木種在一起，加以修建形成的矮牆。不僅能達到裝點效果，還能用來隔開空間。",
  str_item_intro_5222002 = "用較為高大的灌木密集種植而成的牆，通常在庭院中作為外牆使用，據說有的地方會種植大量的灌木叢高牆，形成植物迷宮。",
  str_item_condition_103 = "初步探索「π號地下城」後獲得",
  str_item_condition_104 = "中度探索「π號地下城」後獲得",
  str_item_condition_105 = "深入探索「π號地下城」後獲得",
  str_item_condition_106 = "荒典段位達到紫鑽5次",
  str_item_condition_107 = "荒典段位達到紫鑽20次",
  str_item_condition_108 = "完成主線關卡第8章",
  str_item_condition_109 = "累積獲得1億白夜幣",
  str_item_condition_110 = "導航員等級達50級",
  str_item_condition_111 = "導航員等級達80級",
  str_item_condition_112 = "累積登入100天",
  str_item_condition_113 = "累積登入365天",
  str_item_condition_114 = "完成主線關卡第1章",
  str_item_condition_115 = "完成主線關卡第3章",
  str_item_condition_116 = "擁有20位好感度達10級的光靈",
