  str_item_use_3000299 = "影片劇本，獲得後可以在空庭的拍攝片場中拍攝影片。",
  str_item_3661026 = "節日雞肉大餐",
  str_item_intro_3661026 = "家具，可設置於巨像的房間。\n在節日中就要大吃大喝啦~這盤雞肉大餐無論從外觀還是味道，都對得起節日主食的地位，還等什麼？",
  str_item_3661181 = "巨像掛鐘",
  str_item_intro_3661181 = "家具，可設置於巨像的房間。\n本來應該是貓頭鷹外形的掛鐘，但是某些商人認為太普通了……於是就換成巨像，不知為何還挺合適，只可惜翅膀不會動。",
  str_item_3661182 = "鐵勺騎士",
  str_item_intro_3661182 = "家具，可設置於巨像的房間。\n來！吃我一勺！鐵勺騎士可是著名的大胃王，你看他那個大大的肚子，連鎧甲都要特別訂製！還有從嘴邊留出的口水，莫非又盯上誰家的餐桌了吧？",
  str_item_3661027 = "歌爾蒂應援燈牌",
  str_item_intro_3661027 = "家具，可設置於巨像的房間。\n來！一起為歌爾蒂加油！讓她的歌聲傳播到大陸的每一處角落！",
  str_item_3000289 = "異賦經驗",
  str_item_3000290 = "異賦點",
  str_item_3661183 = "唱片騎師台",
  str_item_intro_3661183 = "家具，可設置於巨像的房間。\n內建擴音裝置的桌台，上面各種按鈕能讓操作者發出幾乎無限的各色音聲，加上節奏的變幻，只要一位操作者就能帶動氣氛，讓大家沉浸在熱烈的歡歌樂舞中。",
  str_item_3661184 = "夢想少女海報",
  str_item_intro_3661184 = "家具，可設置於巨像的房間。\n努力吧！你也可以成為像她一樣的少女。站上舞台，向整個大陸散播愛與希望！因此，任何時候都不能放棄夢想喔！",
  str_item_3661185 = "巡迴犬立偶",
  str_item_intro_3661185 = "家具，可設置於巨像的房間。\n永遠站在影鎮潮流的最前端！即使只是站立的玩偶，巡迴犬也展現了他那頗具眼光的審美。據說這玩偶在他的支持下十分受歡迎，因此一定要小心，不要被人偷偷拿走了~",
  str_item_3661186 = "猛士衝擊者",
  str_item_intro_3661186 = "家具，可設置於巨像的房間。\n能夠發揮強大聲動的樂器，據說只有最勇猛的人才敢演奏它，因為發出的聲音猛烈得足以衝擊軟弱之人。雖然吵了「一些」，然而在人山人海的演唱會上，它是再合適不過的了。",
  str_item_5259309 = "潛能吊墜",
  str_item_5259310 = "降咒之石",
  str_item_5259311 = "謎之鎖箱",
  str_item_5259410 = "混糅利刃",
  str_item_5259411 = "狂戰手甲",
  str_item_5259412 = "羈絆雕塑",
  str_item_5259505 = "蓄能腰帶",
  str_item_5259506 = "狂戰之魂",
  str_item_5259507 = "馭光大劍",
  str_item_5259513 = "狂戰之鎧",
  str_item_5259514 = "戰鬥女神像",
  str_item_intro_5259301 = "連線達到15格及以上時，連鎖技能傷害提升",
  str_item_intro_5259302 = "傷害計算時，我方無視屬性受剋制的負面影響",
  str_item_intro_5259303 = "對敵人施加中毒/灼燒/流血時，立即造成額外傷害",
  str_item_intro_5259304 = "永久提升我方生命值上限",
  str_item_intro_5259305 = "每當生命值降低至不足一半時，場上生成回復生命道具",
  str_item_intro_5259306 = "每波次開始時，回復生命",
  str_item_intro_5259307 = "每波次開始時，獲得護盾",
  str_item_intro_5259308 = "每回合對身邊的非首領敵人造成大量傷害",
  str_item_intro_5259309 = "空裔特別裝具主動效果冷卻回合-1",
  str_item_intro_5259310 = "每回合敵我全體按比例損失生命值",
  str_item_intro_5259311 = "隨機獲得一個額外的空裔特別裝具",
  str_item_intro_5259401 = "負面狀態下的敵人受傷增加",
  str_item_intro_5259402 = "光靈溢出的治療量按比例轉化為護盾",
  str_item_intro_5259403 = "敵人死亡時全場所有人中毒；\n我方受到的中毒傷害降低",
  str_item_intro_5259404 = "異常狀態下，連鎖技能傷害提升",
  str_item_intro_5259405 = "極低機率秒殺非首領敵人",
  str_item_intro_5259406 = "主動技能擊殺敵人時，我方回復生命",
  str_item_intro_5259407 = "生命值全滿時，我方所有傷害提升",
  str_item_intro_5259408 = "敵人毒傷觸發時，我方回復生命；\n我方受到的中毒傷害降低",
  str_item_intro_5259409 = "敵人對我方造成傷害時，對其反傷",
  str_item_intro_5259410 = "編隊至少3種不同主屬性的光靈時，我方傷害提高",
  str_item_intro_5259411 = "光靈的副屬性造成傷害時無衰減",
  str_item_intro_5259412 = "換隊長次數+5；\n本回合首次成為隊長的光靈，主動技能冷卻回合-1",
  str_item_intro_5259501 = "隊長在連線起點額外施展連鎖技能",
  str_item_intro_5259502 = "每5次普通攻擊產生爆炸效果",
  str_item_intro_5259503 = "每回合在周圍一圈產生少量彩色格",
  str_item_intro_5259504 = "秒殺生命值低於10%的敵人",
  str_item_intro_5259505 = "原地不動時，加快主動技能冷卻速度",
  str_item_intro_5259506 = "我方光靈防禦全部轉化為光靈攻擊",
  str_item_intro_5259507 = "連線的第一格可與之後的顏色不同，這兩種不同屬性都將觸發光靈出戰",
  str_item_intro_5259508 = "森屬性格子視為彩色",
  str_item_intro_5259509 = "水屬性格子視為彩色",
  str_item_intro_5259510 = "火屬性格子視為彩色",
  str_item_intro_5259511 = "雷屬性格子視為彩色",
  str_item_intro_5259512 = "我方傷害大幅提升，但是每次連線生成壞格子",
  str_item_intro_5259513 = "我方生命值越低，連鎖技能傷害越高",
  str_item_intro_5259514 = "換隊長次數+5；\n本回合當過隊長的光靈無視連線顏色均按主屬性出戰",
  str_item_rpintro_5259301 = "我方連線達到15格及以上時，連鎖技能傷害增加30%",
  str_item_rpintro_5259302 = "我方造成傷害時無視因屬性受剋制帶來的傷害降低效果；我方受傷時無視屬性因受剋制帶來的受傷增加效果",
  str_item_rpintro_5259303 = "對敵人成功施加中毒/灼燒/流血狀態時，目標立即損失自身50%攻擊力的生命值，每回合每個目標最多觸發1次",
  str_item_rpintro_5259304 = "隊伍中光靈生命值上限增加100%，目前生命值不變",
  str_item_rpintro_5259305 = "每當我方剩餘生命值降低至50%以下，會在場上隨機位置生成一個繃帶，我方經過時回復20%最大生命值",
  str_item_rpintro_5259306 = "每波次開始時，回復20%最大生命值",
  str_item_rpintro_5259307 = "每波次開始時，獲得40%最大生命值的護盾，持續1回合",
  str_item_rpintro_5259308 = "每回合開始時，對周圍一圈的非首領敵人造成50%最大生命值的傷害",
  str_item_rpintro_5259309 = "之後的戰鬥中，施放空裔特別裝具主動效果的冷卻回合-1",
  str_item_rpintro_5259310 = "每回合開始時，場上敵我所有人損失7%的目前生命值（包含首領類型的敵人）",
  str_item_rpintro_5259311 = "隨機獲得一個不同的空裔特別裝具，之後的戰鬥中可使用並單獨計算冷卻回合",
  str_item_rpintro_5259401 = "敵人處在異常狀態中或攜帶減益效果時，受到所有傷害增加20%",
  str_item_rpintro_5259402 = "光靈溢出的治療量的100%轉化為護盾，持續1回合",
  str_item_rpintro_5259403 = "每當敵人死亡時，對全場敵人和我方隊伍均附加1層中毒；我方受到的中毒傷害-50%",
  str_item_rpintro_5259404 = "當己方隊伍處在異常狀態中，連鎖技能造成傷害增加30%",
  str_item_rpintro_5259405 = "非首領敵人受到任何傷害時，均有3%機率立即死亡",
  str_item_rpintro_5259406 = "每次施展主動技能擊殺敵人時，我方回復等同於施展者最大生命值15%的生命",
  str_item_rpintro_5259407 = "我方隊伍生命值全滿時，造成的所有傷害均提高20%",
  str_item_rpintro_5259408 = "每當敵人受到中毒傷害時，為我方恢復毒傷量100%的生命值；我方受到的中毒傷害-50%",
  str_item_rpintro_5259409 = "敵人對我方造成傷害時，受到等同於我方所受傷害100%的反傷",
  str_item_rpintro_5259410 = "隊伍裡有至少3種不同主屬性的光靈時，我方造成的所有傷害均提高25%",
  str_item_rpintro_5259411 = "光靈副屬性造成傷害時，等同於主屬性倍率",
  str_item_rpintro_5259412 = "獲得時，換隊長次數+5；\n切換隊長時，新隊長主動技能剩餘冷卻回合-1，每回合每個光靈只能觸發1次",
  str_item_rpintro_5259501 = "隊長光靈在連線開始位置生成一個虛影，本回合同步施展連鎖技能",
  str_item_rpintro_5259502 = "普通攻擊Combo數為5的倍數時，對敵人產生一次爆炸效果",
  str_item_rpintro_5259503 = "每回合開始時，周圍一圈中3個格子轉為彩色",
  str_item_rpintro_5259504 = "立刻擊敗剩餘生命值低於10%的敵人",
  str_item_rpintro_5259505 = "本回合如果不進行連線移動，則所有處於冷卻中的光靈主動技能剩餘冷卻回合-1",
  str_item_rpintro_5259506 = "我方隊伍中每位光靈防禦降至0，自身攻擊上升防禦的降低值",
  str_item_rpintro_5259507 = "連線的第一格可與之後的顏色不同，這兩種不同屬性都將觸發光靈出戰",
  str_item_rpintro_5259508 = "以其他顏色連線時，也可連接森屬性格子",
  str_item_rpintro_5259509 = "以其他顏色連線時，也可連接水屬性格子",
  str_item_rpintro_5259510 = "以其他顏色連線時，也可連接火屬性格子",
  str_item_rpintro_5259511 = "以其他顏色連線時，也可連接雷屬性格子",
  str_item_rpintro_5259512 = "我方造成的所有傷害均提高25%，但是每次連線的起點將變成5回合無法行走的損壞格子",
  str_item_rpintro_5259513 = "根據我方已損失生命值百分比，提高連鎖技能傷害，最高提升80%",
  str_item_rpintro_5259514 = "換隊長次數+5；\n本回合當過隊長的光靈無視連線顏色均按主屬性出戰",
  str_item_intro_9994027 = "隊伍裡有至少3種不同主屬性的光靈時，我方造成的所有傷害均提高25%",
  str_item_intro_9994028 = "光靈的副屬性造成傷害時無衰減",
  str_item_intro_9994029 = "更換隊長次數+3；\n本回合首次成為隊長的光靈，主動技能冷卻回合-1",
  str_item_intro_9995019 = "原地雙擊不移動時，主動技能冷卻回合額外-1",
  str_item_intro_9995020 = "我方隊伍中每位光靈的防禦降至50%，自身提高等同於防禦降低值的攻擊",
  str_item_intro_9995021 = "根據我方已損失生命值百分比，提高連鎖技能傷害，最高提升80%",
  str_item_intro_9995022 = "更換隊長次數+3；\n本回合當過隊長的光靈無視連線顏色，均按主屬性出戰",
  str_item_rpintro_9994027 = "似乎能將光能完美融合的武器……實在很罕見。",
  str_item_rpintro_9994028 = "據說某位古代戰士在戰鬥中，因為非慣用手的力量不能完全發揮，從而落敗，後來他特別製造出這副手甲，果然在接下來一系列戰鬥中，無往不利。",
  str_item_rpintro_9994029 = "手可以連通心靈，因此握住的雙手就代表雙方達成心靈連接，彼此不分開。",
  str_item_rpintro_9995019 = "古代遺物，其中蘊含的力量可以令佩戴者更快施展各種強大的光能術，足以應付各種危險局面。",
  str_item_rpintro_9995020 = "古語有云「用劍者死於劍下」，它能擊倒極為強大的敵人，前提是已方的奮不顧身……",
  str_item_rpintro_9995021 = "在某些口耳相傳的故事中，這件鎧甲擁有強大又令人恐懼的力量，有人將其視為珍寶，有人則將其視為詛咒。",
  str_item_rpintro_9995022 = "有人說，這尊塑像雕刻的並不是神明，而是能協助戰鬥的傳奇女戰士。",
  str_item_3661187 = "龍洲祝福結",
  str_item_intro_3661187 = "家具，可設置於巨像的房間。\n似乎是用一根繩子巧妙地編成正方形的圖樣，展現了編織者的奇思妙想。據說是來自龍洲大陸上的一種裝飾，掛在家中可以保護人們平安。",
  str_item_3661188 = "高掛架燈籠",
  str_item_intro_3661188 = "家具，可設置於巨像的房間。\n來自龍洲大陸的一種燈架，獨特的木質結構配上紅色燈籠，似乎瞬間能讓人置身於另外一個世界之中。",
  str_item_3661028 = "星光月河飾板",
  str_item_intro_3661028 = "家具，可設置於巨像的房間。\n以各種燈串起來的裝飾板，亮起來後可以顯現出彷如銀河般的燈光景象，不僅可以掛在牆上用來欣賞，掛在野外的樹上或許也能在陰天時帶來星空的錯覺。",
  str_item_3010001 = "召集星標（限時）",
  str_item_intro_3010001 = "用於發射召集訊號的專用裝置，能夠引起光靈的注意力，使光靈回應召集的訊號，成為你的夥伴。\n此道具為限時道具，過期後道具消失，請注意及時使用。過期時間：2023年2月9日12:00",
  str_item_intro_3010002 = "用於發射召集訊號的專用裝置，能夠引起光靈的注意力，使光靈回應召集的訊號，成為你的夥伴。\n此道具為限時道具，過期後道具消失，請注意及時使用。過期時間：2023年3月9日12:00",
