  str_item_intro_3030001 = "外表方正的水晶盒，中心處閃著光芒，可以為稜鏡提供較多的能量。\n使用可獲得60稜鏡。\n此道具為限時道具，過期後道具消失，請注意及時使用。過期時間：2023年2月9日12:00",
