  str_item_intro_3030013 = "外表方正的水晶盒，中心處閃著光芒，可以為稜鏡提供較多的能量。\n使用可獲得60稜鏡。\n此道具為限時道具，過期後道具消失，請注意及時使用。過期時間：2023年12月20日12:00",
  str_item_intro_3010014 = "用於發射召集訊號的專用裝置，能夠引起光靈的注意，使光靈回應召集的訊號，成為你的夥伴。\n此道具為限時道具，過期後道具消失，請注意及時使用。過期時間：2024年01月10日12:00",
