  str_item_intro_3020028 = "用於發射有特殊圖案訊號的專用裝置，能夠吸引某些光靈的注意。\n此道具為限時道具，過期後道具消失，請把握時間使用。過期時間：2024年11月27日12:00",
  str_item_intro_3030028 = "外表方正的水晶盒，中心處閃著光芒，可以為稜鏡提供更多能量。\n使用可獲得60稜鏡。\n此道具為限時道具，過期後道具消失，請把握時間使用。過期時間：2024年11月27日12:00",
  str_item_3000301 = "食材包",
  str_item_intro_3000301 = "一包堆在一起的食材，裡面有各種不同的種類。\n可用於製作美食。",
  str_item_3000302 = "稀見彩羽",
  str_item_intro_3000302 = "不知道什麼神祕飛鳥留下的羽毛，由於色彩豔麗因此是某些信使公會成員的喜好，說不定可以換點東西。",
  str_item_3661189 = "薔薇燭架",
  str_item_intro_3661189 = "家具。可設置於巨像的房間。\n可使花不凋謝、燭光不熄滅。可望使這一刻的美好與回憶長久留存於心。",
  str_item_3661190 = "傾訴信箱",
  str_item_intro_3661190 = "家具。可設置於巨像的房間。\n不敢說出心中的祕密嗎？不敢傾訴特定心境嗎？這個信箱正是最好幫手。它極富耐心、安全可靠，是絕佳的傾訴對象。",
  str_item_3661191 = "明意玩偶熊",
  str_item_intro_3661191 = "家具。可設置於巨像的房間。\n誰會忍心拒絕這麼可愛的小熊呢？更別提它還帶著一顆「心」呢。若有人送出這件禮物，想必雙方已經心意相通。",
  str_item_3661192 = "表白玫瑰束",
  str_item_intro_3661192 = "家具。可設置於巨像的房間。\n紅色與白色的花朵，飽含強烈感情的同時也代言著純潔之心。當將這束花被交到那個人面前，就等於公開說出了那三個字。",
  str_item_3661029 = "心上沙發",
  str_item_intro_3661029 = "家具。可設置於巨像的房間。\n寬大舒適的沙發，很適合情投意合的兩人窩在一起。單人享受也沒問題，陷在柔軟墊子的包裹感也彷彿心上人就在身邊……",
  str_item_3661193 = "潔白之翼",
  str_item_intro_3661193 = "家具，可設置於巨像的房間。\n據說某些天使是愛情的守護者，因此將白色羽翼掛在牆上，說不定愛情很快就會到來哦～",
  str_item_3661194 = "天鵝蛋糕塔",
  str_item_intro_3661194 = "家具，可設置於巨像的房間。\n擁有精美天鵝雕飾的蛋糕塔，與其說是食物，不如說是藝術品……真的捨得吃掉它嗎？",
  str_item_3661030 = "間星浮球",
  str_item_intro_3661030 = "家具，可設置於巨像的房間。\n感覺更適合出現在遊樂場的氣球，放在家中作為裝點，卻也有別樣的感覺。但要是不掛起來的話，應該會到處亂飄吧。",
  str_item_3000308 = "通緝搜證紀錄",
  str_item_intro_3000308 = "記下了犯人某些「特徵」的紀錄，看看能不能用它來找出真相吧……",
  str_item_3661195 = "法古留聲機",
  str_item_intro_3661195 = "家具，可設置於巨像的房間。\n頗為經典的留聲機，據說在幾十年前的影鎮中頗為風行，是富商們的必備收藏品。製作者看來多半是當年的工匠，或者是下了苦工研究如何還原當時的風格，無論是音色還是裝飾，都能讓老一輩的人沉浸於過去的樂聲和歲月。",
  str_item_3661196 = "線索記錄圖板",
  str_item_intro_3661196 = "家具，可設置於巨像的房間。\n不僅能用來繪製各式分析案情用的推理關係圖，也能將重要線索、證人證物照片和蒐集而來的情報貼在上面，隨時供人查閱、歸納和總結，以更快地找出真相與犯人。",
  str_item_3661197 = "證報茶几",
  str_item_intro_3661197 = "家具，可設置於巨像的房間。\n原本是用來喝下午茶和打牌的茶几，現在上面放了一疊與案情有關的書報，加上旁邊擺著放大鏡、煙斗和提燈，此家具的主人八成是位名偵探，否則至少也是名「偵探愛好者」。",
  str_item_3661198 = "巡訪衣帽架",
  str_item_intro_3661198 = "家具，可設置於巨像的房間。\n外出尋訪自然不能沒有一些裝扮——大衣足以用來抵禦夜晚的寒冷，也能裝下不少巡防所用的道具，例如筆記本、放大鏡和防身用的小型武器；而那頂帽子，嗯，不僅可以防風，也能讓穿戴者的樣子看起來更像偵探吧。",
  str_item_3661031 = "沉思推理沙發",
  str_item_intro_3661031 = "家具，可設置於巨像的房間。\n據說某些偵探只要坐在沙發上，依靠他人蒐集來的大小線索就能推理出案件的真相，看來這沙發不僅能讓人休息，說不定還能加快腦袋運轉的速度呢～",
  str_item_3661199 = "鬥客掛架",
  str_item_intro_3661199 = "家具，可設置於巨像的房間。\n掛滿菸斗的架子。雖然菸草的氣味並非人人愛，但是那些造型精巧的菸斗還是頗具收藏價值。",
  str_item_3661200 = "落地望遠鏡",
  str_item_intro_3661200 = "家具，可設置於巨像的房間。\n將遠處的風景收納眼底，無疑是它最大的作用。鏡頭十分清晰，但全金屬製成的鏡筒令其略顯沉重，必須放在專用的三腳架上才能穩定使用。",
  str_item_3661032 = "牢固保險箱",
  str_item_intro_3661032 = "家具，可設置於巨像的房間。\n「這將是大陸上最安全、最牢固的物品監獄」，商人們如是說。確實，那大大的鎖柄光看就很牢固，厚重的箱身也能抵抗大部分的破壞行為。",
  str_item_3661033 = "冠軍榮譽獎品鴨",
  str_item_intro_3661033 = "家具，可設置於巨像的房間。\n貢露精心設計的鴨子，頒發給遊戲的優勝者！不僅外表可愛，那金光閃閃的外表也象徵著冠軍的榮譽。",
  str_item_3661207 = "秩高之毯",
  str_item_intro_3661207 = "家具，可設置於巨像的房間。\n位處雲巔的城市，天空中的不落之都‵．作為艾斯特拉大陸的文明之光，這張地毯不僅代表著身分與地位，也代表秩序與禮儀。",
  str_item_3661208 = "不落旗幟",
  str_item_intro_3661208 = "家具，可設置於巨像的房間。\n作為「最後的不落之都」的標誌，每當它出現在大陸之上，便代表白夜城的文明之光正照耀於此。",
  str_item_3661201 = "典頌豎琴",
  str_item_intro_3661201 = "家具，可設置於巨像的房間。\n只有在白夜城舉行盛大慶典時才會使用的豎琴，因為有著特殊的光能術加以保護，音色永遠不會失準，只有最好的樂師才能使用它彈奏那些讚頌的曲聲。",
  str_item_3661202 = "光籌落間沙漏",
  str_item_intro_3661202 = "家具，可設置於巨像的房間。\n「在光與夜的漲落期間，只有它能精確計算時刻。」據說這種沙漏內存放了大陸上最細的沙粒，加上特殊光能術的調整，其精確度堪比最好的鐘錶。",
  str_item_3661203 = "庭雲上之泉源",
  str_item_intro_3661203 = "家具，可設置於巨像的房間。\n在雲上的庭院間，能聽到流水之聲？不要驚訝，這正是來自那白夜城的泉源之台。在奇妙光能術的加持下，水似乎憑空生成，又逐級而下，讓人們在天空之上，也能欣賞這落泉之景。",
  str_item_3661204 = "最後的劍與盾",
  str_item_intro_3661204 = "家具，可設置於巨像的房間。\n作為永不陷落之都，白夜城無疑代表了文明的最後防線。而這劍與盾，則是這最後防線的最後依仗……它代表了戰鬥到最後一刻的責任、勇氣與堅持。",
  str_item_3661034 = "憶響日水晶球",
  str_item_intro_3661034 = "家具，可設置於巨像的房間。\n若匆匆望向那水晶之中，只能一瞥自身倒影，若細細望看那水晶之中，卻可見昔日之景。回憶的聲音遊蕩在眼前，如果想要抓住它，就要沉浸其間……",
  str_item_3000325 = "靈犀露珠",
  str_item_intro_3000325 = "據說，它是這個世界的「眼淚」……只在「那一天」才可獲得，其中或許包含了這個世界的真相。\n用途：在【追憶之間】中追憶物資。\n獲取途徑：完成消耗稜鏡的主線或資源整備關卡。",
  str_item_3661205 = "懸雙燭臺",
  str_item_intro_3661205 = "家具，可設置於巨像的房間。\n「即使在黑夜中也要散發光芒，讓人們得以尋找方向。」這支燭臺擁有白夜城特殊的光能術，沒有掛勾也能自動貼在牆壁上，還能防止燭火被風吹熄。",
  str_item_3661206 = "瑰雅邸瓶",
  str_item_intro_3661206 = "家具，可設置於巨像的房間。\n白夜城貴族使用的巨大花瓶，以造型優雅著稱，光是一支花瓶的價值就足以讓平民們吃香喝辣好幾年，在上層豪宅中則是隨處可見的裝飾。",
  str_item_3661035 = "儀曜禮服",
  str_item_intro_3661035 = "家具，可設置於巨像的房間。\n即使是最重禮儀的白夜城，這件禮服也足以出席任何盛大的場合——無論是典禮、節慶和貴族舞會。若穿著者姿容出眾，儀態大方，便足以吸引眾人目光，成為人群中的焦點。",
  str_item_3661209 = "度假地遮陽傘椅",
  str_item_intro_3661209 = "家具，可設置於巨像的房間。\n度假勝地自然少不了這種能用來休息又能防曬的家具了。雖然是兩件家具，但總覺得缺了其中任何一件，都少了很多假日氣息。",
  str_item_3661210 = "遊樂園廣告牆",
  str_item_intro_3661210 = "家具，可設置於巨像的房間。\n似乎每座遊樂園都看得到，巨大、亮眼，有著令人迷惑的各色圖案，彷彿在說「快來看呀！千萬別錯過！」",
  str_item_3661211 = "度假地冰淇淋車",
  str_item_intro_3661211 = "家具，可設置於巨像的房間。\n能夠在炎炎夏日中提供冰爽甜品的手推車，在遊樂園中相當於一處補給點，總有小孩在冰淇淋車周圍流連忘返。",
  str_item_3661212 = "度假地彈簧小馬",
  str_item_intro_3661212 = "家具，可設置於巨像的房間。\n頗受小孩歡迎的遊樂設施，下方的彈簧能為騎乘者帶來顛簸感，讓孩子尖叫聲接連不斷。",
  str_item_3661213 = "綠洲河上摩托艇",
  str_item_intro_3661213 = "家具，可設置於巨像的房間。\n沙漠中也能來場水上競速！沒想到吧！這都要多虧那一大片綠洲帶來的豐沛水流，才讓摩托艇有了用武之地，不至於廢置到天荒地老。",
  str_item_3661214 = "沙漠仙人掌盆栽",
  str_item_intro_3661214 = "家具，可設置於巨像的房間。\n沙漠中最常見的植物，極為耐旱，因此有人認為仙人掌象徵了堅韌，而將仙人掌移植到盆栽內，放在家中欣賞。請勿太過頻繁澆水，否則會讓仙人掌掛掉。",
  str_item_level_2905111 = "鏈場",
  str_item_10000100 = "水系光靈擇選箱",
  str_item_10000101 = "火系光靈擇選箱",
  str_item_10000102 = "森系光靈擇選箱",
  str_item_10000103 = "雷系光靈擇選箱",
  str_item_intro_10000100 = "使用後可選擇一位特定5星光靈加入你的冒險。（<color=#ffffff>諾爾、修拉德、巴頓、克萊肯、菲莉詩、渡</color>）",
  str_item_intro_10000101 = "使用後可選擇一位特定5星光靈加入你的冒險。（<color=#ffffff>浮士德、蕾吉娜、紅與黑、莉奧娜、伊斯塔萬、瑪姬、芭芭拉</color>）",
  str_item_intro_10000102 = "使用後可選擇一位特定5星光靈加入你的冒險。（<color=#ffffff>露易絲、知更、歐緹、契法、艾蕾雅、希卡蕾、庫絲庫塔</color>）",
  str_item_intro_10000103 = "使用後可選擇一位特定5星光靈加入你的冒險。（<color=#ffffff>蜜雅、涅墨西斯、舒瓦茲、薇薇安、基汀、烈雀、貝芙麗</color>）",
  str_item_3000327 = "抓抓樂代幣",
  str_item_intro_3000327 = "在抓抓樂娃娃機以及其他諸多遊戲設施中使用的代幣，上面印有萊蕾的笑容，像是在祝願每一位遊客都能玩得盡興。",
  str_item_3000328 = "德諾奧通行幣",
  str_item_intro_3000328 = "德諾奧峽谷度假村內使用的貨幣，製作精良、成色飽滿，因此能夠兌換其他勢力發行的貨幣。\n在經營模式中用於升級建築。",
  str_item_intro_3410627 = "包括：黃色中級訂購箱*15、黃色初級訂購箱*25、二階瑩玉·雷*5、一階瑩玉·雷*8、白夜幣*35000、聯軍初級訂購箱*8",
  str_item_intro_3410628 = "包括：黃色高級訂購箱*15、黃色中級訂購箱*25、二階瑩玉·雷*30、一階瑩玉·雷*7、白夜幣*121000、聯軍中級訂購箱*8",
