  str_item_intro_3410632 = "包括：紅色特級訂購箱*15、紅色高級訂購箱*25、三階瑩玉·火*25、二階瑩玉·火*10、一階瑩玉·火*6、白夜幣*331000、聯軍高級訂購箱*8",
  str_item_intro_3410633 = "包括：綠色中級訂購箱*20，綠色初級訂購箱*30，二階瑩玉*森*5，一階瑩玉*森*10，白夜幣*42,000，聯軍初級訂購箱*10",
