  str_item_intro_3410635 = "包括：綠色特級訂購箱*20，綠色高級訂購箱*30，三階瑩玉*森*25，二階瑩玉*森*25，一階瑩玉*森*5，白夜幣*427,000，聯軍高級訂購箱*10",
