  str_item_intro_34106161 = "包括：二階瑩玉·共通*15，白夜幣*50,000，聯軍初級訂購箱*10，低級訂購合成箱*30，中級訂購合成箱*20。",
  str_item_intro_34106171 = "包括：二階瑩玉·共通*55，白夜幣*150,000，聯軍中級訂購箱*10，中級訂購合成箱*30，高級訂購合成箱*20。",
  str_item_intro_34106181 = "包括：三階瑩玉·共通*50，白夜幣*450,000，聯軍高級訂購箱*10，高級訂購合成箱*30，特級訂購合成箱*20。",
  str_item_3410642 = "愛麗絲特別支援·覺醒1",
  str_item_3410643 = "愛麗絲特別支援·覺醒2",
  str_item_3410644 = "愛麗絲特別支援·覺醒3",
  str_item_3410645 = "卡夫卡特別支援·覺醒1",
  str_item_3410646 = "卡夫卡特別支援·覺醒2",
  str_item_3410647 = "卡夫卡特別支援·覺醒3",
  str_item_intro_3410642 = "包括：紅色中級訂購箱*15、紅色初級訂購箱*25、二階瑩玉·火*5、一階瑩玉·火*8、白夜幣*35000、聯軍初級訂購箱*8",
  str_item_intro_3410643 = "包括：紅色高級訂購箱*15、紅色中級訂購箱*25、二階瑩玉·火*30、一階瑩玉·火*7、白夜幣*121000、聯軍中級訂購箱*8",
  str_item_intro_3410644 = "包括：紅色特級訂購箱*15、紅色高級訂購箱*25、三階瑩玉·火*25、二階瑩玉·火*10、一階瑩玉·火*6、白夜幣*331000、聯軍高級訂購箱*8",
  str_item_intro_3410645 = "包括：黃色中級訂購箱*15、黃色初級訂購箱*25、二階瑩玉·雷*5、一階瑩玉·雷*8、白夜幣*35000、聯軍初級訂購箱*8",
  str_item_intro_3410646 = "包括：黃色高級訂購箱*15、黃色中級訂購箱*25、二階瑩玉·雷*30、一階瑩玉·雷*7、白夜幣*121000、聯軍中級訂購箱*8",
  str_item_intro_3410647 = "包括：黃色特級訂購箱*15、黃色高級訂購箱*25、三階瑩玉·雷*25、二階瑩玉·雷*10、一階瑩玉·雷*6、白夜幣*331000、聯軍高級訂購箱*8",
  str_item_intro_3000900 = "質地柔軟的棉花，通常可以當作填充物，或是製成華麗的裝飾物。",
  str_item_intro_3000901 = "艾斯特拉大陸常見的製衣材料，結實耐用、易於染色。",
  str_item_intro_3000902 = "染料，醒山只拿了這一桶給你看，他說實際上還有很多桶其他顏色的顏料。",
  str_item_intro_3000903 = "在製衣時常用的鈕扣，摸起來涼涼的，小孩子也許會誤認為是錢幣。",
  str_item_intro_3000904 = "看起來很普通的線團，醒山同樣只拿了黑色給你看，他說怕你亂玩弄亂了顏色順序。",
  str_item_7000100 = "殘缺的繪本",
  str_item_7000101 = "繪本碎片·醫生",
  str_item_7000102 = "繪本碎片·空盆",
  str_item_7000103 = "診斷書",
  str_item_7000104 = "紅茶茶杯",
  str_item_7000105 = "白色「蟾蜍」",
  str_item_7000106 = "粗糙的玩具",
  str_item_7000107 = "悔過書",
  str_item_7000108 = "破損的帳本",
  str_item_7000109 = "研究員的筆記",
  str_item_7000110 = "可愛扳手",
  str_item_7000111 = "迷你髮帶",
  str_item_7000112 = "指引青蛙",
  str_item_7000113 = "花種",
  str_item_7000114 = "繪本碎片·黎明之花",
  str_item_7000115 = "繪本碎片·扳手",
  str_item_7000116 = "繪本碎片·紅油之首",
  str_item_7000117 = "繪本碎片·巨像",
  str_item_7000118 = "繪本碎片·白蛙王子",
  str_item_7000119 = "完整的繪本",
  str_item_intro_7000100 = "一本簡筆畫繪本，攤開的頁面上畫著少女與身邊三人開心坐在一起的場景。奇怪的是，畫中的人頭部都被撕掉了。",
  str_item_intro_7000101 = "似乎是從殘缺的繪本上撕下來的紙片，紙片上依稀可見一名身穿白褂的神祕女性頭像。",
  str_item_intro_7000102 = "繪有陶盆的紙片，盆裡裝著一撮泥土。",
  str_item_intro_7000103 = "微微泛黃的紙張，看上去像是一份診斷書。",
  str_item_intro_7000104 = "一個製作精美的紅茶茶杯，看上去價值不菲。",
  str_item_intro_7000105 = "一隻神祕的白色小生物，沒有人知道牠從何而來，也許很喜歡蒲公英。",
  str_item_intro_7000106 = "一隻外形奇特的玩具布偶。品味不怎麼樣，但做工很精緻。",
  str_item_intro_7000107 = "一張皺巴巴的紙上寫滿了歪歪扭扭的字跡，雖然字很潦草，但能看出寫字的人很真誠。",
  str_item_intro_7000108 = "一本古老的帳本，但可以看出持有者並沒有記帳的習慣。比起記錄收支，她更需要一個能記錄其天賦才思的載體。",
  str_item_intro_7000109 = "有年代感的筆記本，持有者似乎上了年紀。",
  str_item_intro_7000110 = "一把巨型扳手，上面貼著可愛的貼紙。",
  str_item_intro_7000111 = "一條小到只有玩偶大小的生物能夠佩戴的花紋髮帶。",
  str_item_intro_7000112 = "把髮帶當領巾戴著的白色青蛙，看起來更有風度了。",
  str_item_intro_7000113 = "一顆孤獨的種子，像一個約定，在角落裡等待發掘。",
  str_item_intro_7000114 = "與迎接黎明的鮮花同名的少女，像花一樣小而燦爛。",
  str_item_intro_7000115 = "繪著超大扳手的紙片，這麼大的扳手，肯定屬於一個高大帥氣的人。",
  str_item_intro_7000116 = "紅油的魁首，踏破風暴、直面陰謀、笑看絕境，而鐵骨之下仍有溫柔。",
  str_item_intro_7000117 = "一座傳說中的龍形巨像，可愛的筆觸將他描繪成了一位優雅人士，但仍然可以欣賞到他淨白的翅膀。",
  str_item_intro_7000118 = "白色的使者，從外面的世界前來。",
  str_item_intro_7000119 = "畫風可愛的繪本，上面的幾個人笑得很開心。",
  str_item_sub_intro_7000100 = "「明明是快樂的記憶，卻到處都是洞……當初的我，究竟在上面畫了誰呢？」",
  str_item_sub_intro_7000101 = "「喂，誰這麼過分，把醫生的臉撕下來了？……是小動物啃的？那、那我就沒辦法了。」",
  str_item_sub_intro_7000102 = "「這種陶盆伊芙家也有！有好多！因為我很喜歡嘛，就收集了不少……只是想不起喜歡的理由了。」",
  str_item_sub_intro_7000103 = "「恐懼、憤怒、痛苦……一切影響你生理和心理狀態的負面因素都已經成功消除。恭喜你，現在是個健康的孩子了。」",
  str_item_sub_intro_7000104 = "「除了我之外，醫生還有別的病人要照顧。有位白夜城來的貴族小姐很愛喝紅茶，走到哪裡都帶著小茶杯……她現在一定也痊癒了吧？」",
  str_item_sub_intro_7000105 = "「蟾蜍有什麼不好？我最喜歡蟾蜍了！……嗯？你不叫蟾蜍？」",
  str_item_sub_intro_7000106 = "「給摯愛的■■，當我們不能陪在她身邊的時候，願這些小東西能帶給她快樂……」",
  str_item_sub_intro_7000107 = "「不能在■■面前說髒話，請大家互相監督。違反者要生吃十八瓶辣醬，我也不例外。」",
  str_item_sub_intro_7000108 = "「我承認，我被它的強大所震撼。我一度以為■■的程度已經是種子能達到的極限，■■■■應以精神面為突破口尋求種子對人格的影響。但這個■■■■原始、狂暴、超乎想像的強大，我被深深吸引，很驚訝種子還能做到這種事，這樣的力量、這樣的強大，才符合■■的需求。我迫切地需要■■改變世界的力量。」",
  str_item_sub_intro_7000109 = "「到達現場時，我們完全被毀滅性的破壞痕跡所震撼。我們猜測有某個個體釋放了巨大的能量，徹底摧毀了從地下到地表的所有設施與建築……難以想像，這是什麼怪物……」",
  str_item_sub_intro_7000110 = "「看上去好眼熟，這些花朵樣式的貼紙……也是我貼上去的嗎？」",
  str_item_sub_intro_7000111 = "「白色髮帶……黑色條紋……似乎在哪裡見過……」",
  str_item_sub_intro_7000112 = "「你想對我說什麼嗎？你要為迷茫的我指引道路嗎？」",
  str_item_sub_intro_7000113 = "「如果把花從我的世界裡拿走，我的心也會陷入更深的深淵裡吧。」",
  str_item_sub_intro_7000114 = "「我想回到赤眼谷，在那裡種滿鮮花。」",
  str_item_sub_intro_7000115 = "「就憑這樣的畫技，真的能畫出這把扳手的厲害之處嗎……呃，如果敢說這張圖畫得不好的話，倒是真有可能體驗到扳手的厲害……」",
  str_item_sub_intro_7000116 = "「他總能找到我！」",
  str_item_sub_intro_7000117 = "「猜猜看，能掌控這具漂亮巨像的人，會是個什麼樣的傢伙呢？……你們開什麼玩笑！我才沒有嘲諷陸行者號呢！冤枉啊啊啊啊——」",
  str_item_sub_intro_7000118 = "「活下去，我們會再相見。」",
  str_item_sub_intro_7000119 = "「真實的世界，和真實的幸福。」",
  str_item_get_7000100 = "「夢境-遺忘甦醒之日」中獲得",
