  str_item_7000200 = "放大鏡",
  str_item_7000201 = "羽毛筆",
  str_item_7000202 = "成績單",
  str_item_7000203 = "教鞭",
  str_item_7000204 = "判例（一）",
  str_item_7000205 = "祕密調查報告",
  str_item_7000206 = "判例（二）",
  str_item_intro_7000200 = "造型和配色都很獨特的放大鏡，查案時的必備工具。\n\n",
  str_item_intro_7000201 = "金燦燦的羽毛筆，掂在手裡分量十足。\n\n",
  str_item_intro_7000202 = "一份滿分的黎明學院成績單。\n\n",
  str_item_intro_7000203 = "放在角落、毫不起眼的教鞭，勾起了伊倫汀的童年回憶。\n\n",
  str_item_intro_7000204 = "名為「羅德爾·諾貝古」的審判官留下的一份判例，判決內容如同他本人一樣，冰冷無情。\n\n",
  str_item_intro_7000205 = "一份由伊倫汀的父親所撰寫的祕密報告，他早在審判遺囑案之前，就知道男爵的遺囑其實另有意圖。\n\n",
  str_item_intro_7000206 = "名為「羅德爾·諾貝古」的審判官留下的一份判例，他的判決將導致一個家族遭到抹去。\n\n",
  str_item_sub_intro_7000200 = "「是錯覺嗎，這把放大鏡好像在呼喚我的名字？咳，這怎麼可能。不過，放大鏡好眼熟……難道這是我的？我這是怎麼了，連這種事都忘記了。」",
  str_item_sub_intro_7000201 = "「為什麼無論做什麼，都無法贏得他們的認同？無論是父親，還是同齡人……」",
  str_item_sub_intro_7000202 = "「我，真的沒有用盡全力嗎……」",
  str_item_sub_intro_7000203 = "「要多麼努力，才能忘記哪些黯淡的童年時光？」",
  str_item_sub_intro_7000204 = "「我應該延續這份判決的思路嗎……」",
  str_item_sub_intro_7000205 = "「我、都做了些什麼……」",
  str_item_sub_intro_7000206 = "「我想……我有我自己的答案。」",
  str_item_7000300 = "獲得證據",
  str_item_7000301 = "獲得證言",
  str_item_7000302 = "獲得證據",
  str_item_7000303 = "獲得證言",
  str_item_7000304 = "獲得法條",
  str_item_7000305 = "獲得法條",
  str_item_7000306 = "獲得證據",
  str_item_7000307 = "獲得證據",
  str_item_7000308 = "獲得證言",
  str_item_7000309 = "獲得證言",
  str_item_7000310 = "獲得法條",
  str_item_7000311 = "獲得法條",
  str_item_7000312 = "獲得證據",
  str_item_7000313 = "獲得證據",
  str_item_7000314 = "獲得證言",
  str_item_7000315 = "獲得證言",
  str_item_7000316 = "獲得法條",
  str_item_7000317 = "獲得法條",
  str_item_7000318 = "金色砝碼",
  str_item_7000319 = "金色砝碼",
  str_item_7000320 = "金色砝碼",
  str_item_intro_7000300 = "諾蒂莉身上沒有徽章的蹤影",
  str_item_intro_7000301 = "學生會成員的證言：小普家中很缺錢",
  str_item_intro_7000302 = "諾蒂莉和小普彼此互相競爭",
  str_item_intro_7000303 = "老門衛的證言：諾蒂莉曾經去過自習室",
  str_item_intro_7000304 = "侵犯財產罪",
  str_item_intro_7000305 = "妨礙公共秩序罪",
  str_item_intro_7000306 = "祖父的遺囑經證實屬實",
  str_item_intro_7000307 = "祖父自盡的刀具上有傑瑞的指紋",
  str_item_intro_7000308 = "鄰居的證言：祖父說過要把一切都傳給孫女",
  str_item_intro_7000309 = "見證人的證言：祖父立遺囑時沒有異樣",
  str_item_intro_7000310 = "偽造文書罪",
  str_item_intro_7000311 = "遺囑繼承法",
  str_item_intro_7000312 = "戈蒂埃房中的皮洛斯家族徽章",
  str_item_intro_7000313 = "米倫·戈蒂埃在速寫本上的咒駡",
  str_item_intro_7000314 = "戈蒂埃家族抓走皮洛斯家族的人做實驗",
  str_item_intro_7000315 = "皮洛斯家族仍然在研究血色晶石",
  str_item_intro_7000316 = "謀反罪",
  str_item_intro_7000317 = "散布謠言罪",
  str_item_intro_7000318 = "「黎明徽章失竊案」搜證成功！",
  str_item_intro_7000319 = "「祖父的遺囑案」搜證成功！",
  str_item_intro_7000320 = "「戈蒂埃家族謀反案」搜證成功！",
  str_item_sub_intro_7000300 = "聽了小普對案件的描述，諾蒂莉看起來非常氣憤，她靠近小普，不停質問小普為什麼要污蔑自己。為了證實自己的清白，諾蒂莉主動讓伊倫汀搜身，而伊倫汀在她的身上果然什麼都沒有發現。",
  str_item_sub_intro_7000301 = "前往自習室的路上，伊倫汀被一位學生會的成員悄悄拉住。他慷慨激昂，向伊倫汀發表了一番見解：「小普家裡本來就不是什麼大貴族，父母也沒有擔任正式的公職，她家最近好像還因為某些原因很缺錢！」",
  str_item_sub_intro_7000302 = "伊倫汀在校園的公告欄上看見了一則來自神殿的公告：今年他們招收了兩名見習修女，分別是小普和諾蒂莉，而兩人之中最後只會有一人有機會留在神殿。",
  str_item_sub_intro_7000303 = "伊倫汀來到自習室附近，發現一位上了年紀的門衛正在附近打盹。門衛爺爺顯然沒有忘記伊倫汀，因為伊倫汀在校時曾幫過他不少忙。據門衛所說，今天除了小普，只有諾蒂莉走進過自習室，當時他還覺得奇怪，為什麼諾蒂莉要隔著手帕開門。「也許是潔癖吧，我當時也沒多想。」",
  str_item_sub_intro_7000304 = "偷竊他人財產且金額巨大，將判處監禁三至十年，併科罰金。",
  str_item_sub_intro_7000305 = "公然侮辱他人或故意誹謗他人且情節重大，將判處三年以下監禁，併科罰金。",
  str_item_sub_intro_7000306 = "傑瑞向伊倫汀出示了手上的遺囑，經過比對分析，伊倫汀確認這份遺囑確實是小普的祖父親筆所書。祖父把爵位和財產都留給了傑瑞，「我活夠了，已經沒什麼遺憾了」——伊倫汀很在意這句話，看樣子，祖父在寫遺書時已經透露了輕生的念頭。",
  str_item_sub_intro_7000307 = "伊倫汀來到祖父家中，發現祖父是用一把水果刀自盡身亡的。但仔細勘驗水果刀後，伊倫汀發現刀上留有傑瑞的指紋。傑瑞解釋表示，他平時要準備餐食，所以餐具上有他的指紋並不奇怪。伊倫汀再次勘驗了現場，確認祖父的確是自盡而亡。",
  str_item_sub_intro_7000308 = "伊倫汀詢問了祖父的鄰居，鄰居告訴伊倫汀，祖父生前雖然經常感嘆自己的兒子不爭氣，卻也經常向鄰居炫耀自己的孫女。祖父曾經當著眾人的面說，要把爵位和財產都傳給孫女，什麼都不會留給兒子。",
  str_item_sub_intro_7000309 = "遺囑的公證人是一位上過學的老僕人。老僕人說自己能得到祖父邀請擔任公證人實在是萬分榮幸，話剛說出口，老僕人忽然覺得自己好像說錯話了。一臉不好意思繼續解釋，祖父立遺囑的時候沒有異樣，老僕人也曾經反覆確認過這是不是祖父的真實想法。",
  str_item_sub_intro_7000310 = "偽造公私文書且利用文書詐騙者，判處監禁三至十年，併科罰金。",
  str_item_sub_intro_7000311 = "經判定合法有效的遺囑，應當遵從遺囑內容分配財產。",
  str_item_sub_intro_7000312 = "伊倫汀悄悄潛入戈蒂埃家族在下城流放地的房間，她仔細翻找，竟在角落發現一枚皮洛斯家族的家族徽章。戈蒂埃家族和皮洛斯家族因為血色晶石一案被一同流放下城，難道兩個家族要一起合作謀反？伊倫汀不敢繼續想下去。「小普也是皮洛斯家族的一員……」",
  str_item_sub_intro_7000313 = "伊倫汀又找到一處破爛的房屋，裡面有一本落款為「米倫·戈蒂埃」的速寫本。本子中畫著一些伊倫汀難以理解的抽象圖案，伊倫汀眯起眼睛，在圖案與圖案之間發現了一行小字：「你們憑什麼這樣對我……憑什麼憑什麼憑什麼？！我一定會重新掌控屬於自己的命運……哪怕是借助他們的力量。」",
  str_item_sub_intro_7000314 = "街邊忽然出現了一隻身形奇特的暗鬼，伊倫汀沒有猶豫，上前刺穿了暗鬼的胸膛。暗鬼嗚咽著倒下，似乎忽然恢復了清醒一般，向著人群的方向舉起手，彷彿有什麼話想說。伊倫汀靠近暗鬼，聽到了暗鬼的呢喃，「戈蒂埃……在報復……皮洛斯……我們……被戈蒂埃……抓走……當成……實驗品……他們要……謀反！」",
  str_item_sub_intro_7000315 = "伊倫汀正思考下一步的搜查方向時，一位衣衫襤褸的路人悄悄走了過來。他聲稱自己掌握了下城的所有消息，爆料最近皮洛斯家族仍然在研究血色晶石。伊倫汀問那人為何要透露消息給自己，路人張開嘴露出黑壓壓的牙齒，「你可以把我帶回中庭嗎？」",
  str_item_sub_intro_7000316 = "蓄意謀劃或試圖推翻白夜城現有統治，將判處終身監禁，情節嚴重者可處極刑。",
  str_item_sub_intro_7000317 = "故意散佈他人謠言，將判處一年以下監禁，併科罰金。",
  str_item_sub_intro_7000318 = "伊倫汀根據證據和證言，順利推斷出諾蒂莉便是偷走黎明徽章的罪魁禍首。",
  str_item_sub_intro_7000319 = "你認定遺囑有效，僕人傑瑞將繼承小普祖父的爵位和所有財產……",
  str_item_sub_intro_7000320 = "你搜集了最完整的證據和證言，證實了米倫·戈蒂埃拐來皮洛斯族人進行人體實驗及意圖謀反的事實。",
  str_item_7000400 = "陳舊鑰匙",
  str_item_7000401 = "烈雀的餅乾",
  str_item_7000402 = "新家的藍圖",
  str_item_7000403 = "莊嚴長號",
  str_item_7000404 = "新的樂譜",
  str_item_7000405 = "烈雀肖像",
  str_item_7000406 = "知更肖像",
  str_item_7000407 = "壺中女士肖像",
  str_item_7000408 = "白海豚肖像",
  str_item_intro_7000400 = "姑姑給克娜莉的閣樓鑰匙。要小心使用，以免讓陳年老鎖的聲音吵到其他人。\n",
  str_item_intro_7000401 = "克娜莉幫烈雀帶的餅乾，後來被魚人衛兵們偷走了。按照烈雀的要求，裡面沒有加糖。\n",
  str_item_intro_7000402 = "為水形之主而建造的城堡草圖。祂說的好像不是這個，但克娜莉女王擁有解釋權。\n",
  str_item_intro_7000403 = "小鎮居民為克娜莉尋來的新樂器，能吹出更嘹亮、更富威力的聲音，表達憤怒。\n",
  str_item_intro_7000404 = "克娜莉在老舊的閣樓裡找到的水形之譜，如今上面已經簽署了新的名字。\n",
  str_item_intro_7000405 = "海底小鎮的藝術家為侍衛烈雀繪製的肖像，如今被克娜莉女王拿出來置於觀眾席上，作為練習演講的道具。\n",
  str_item_intro_7000406 = "海底小鎮的藝術家為侍衛知更繪製的肖像，如今被克娜莉女王拿出來置於觀眾席上，作為練習演講的道具。\n",
  str_item_intro_7000407 = "海底小鎮的藝術家為神祕顧問繪製的肖像，如今被克娜莉女王拿出來置於觀眾席上，作為練習演講的道具。\n",
  str_item_intro_7000408 = "海底小鎮的藝術家為女王英俊的友魚繪製的肖像，如今被克娜莉女王拿出來置於觀眾席上，作為練習演講的道具。\n",
  str_item_sub_intro_7000400 = "「她睡在閣樓裡，吃別人不要的東西～說話聲音小小，躲在遠遠角落～白天打掃房間，晚上拿出樂器～音樂慰藉孤獨的心～」",
  str_item_sub_intro_7000401 = "「我的小餅乾！那是克娜莉送給我的！……這群沒長眼睛的臭狗腿，怎麼連小餅乾也不留給我！」",
  str_item_sub_intro_7000402 = "「芭呼喚爾梅神……達威……源賜咿葳！」",
  str_item_sub_intro_7000403 = "「痛苦與悲傷……終將在音樂中獲得救贖！」",
  str_item_sub_intro_7000404 = "「祂曾經說過，想要我幫祂取一個新名字，我想了很多，魯賓斯坦、薩列里、利奧波德、德沃夏克……都是祂喜歡的聲音……咦？要更親切一點的比較好？」",
  str_item_sub_intro_7000405 = "「什麼，說我太尖銳？要替手足出頭，不尖銳怎麼能行啊？」",
  str_item_sub_intro_7000406 = "「嗯……的確有魚說過我很扁平，沒有存在感什麼的……可這就是，我的生存之道……」",
  str_item_sub_intro_7000407 = "「想要我出來再開始畫？呵，那可是要付錢的。」",
  str_item_sub_intro_7000408 = "「你問我和克娜莉女王的關係？呼呼～保密～」",
  str_item_7000801 = "古玩舊物",
  str_item_intro_7000801 = "從雙榭城各個角落尋得的古玩。龍洲出產的文玩器物，在異國也備受珍視，只不過有些是透過酬金正當交易而來，有些是經由不法之徒輾轉偷渡而來。",
  str_item_6030101 = "迷你繪本",
  str_item_6030102 = "微笑溫度",
  str_item_6030103 = "伊芙之黎",
  str_item_6030104 = "白夜神殿",
  str_item_6030105 = "保持平衡",
  str_item_6030106 = "天真祈願",
  str_item_6030107 = "水形暗號",
  str_item_6030108 = "愛之獨奏",
  str_item_6030109 = "華美之家",
  str_item_6030110 = "紫藤之夢",
  str_item_6030111 = "花與魔劍",
  str_item_6030112 = "載夢扁舟",
  str_item_6030113 = "他的守望",
  str_item_6030114 = "她的誓言",
  str_item_6030115 = "戒衛之劍",
  str_item_6030116 = "甜蜜火車頭",
  str_item_6030117 = "獵石的新裝",
  str_item_6030118 = "奶油森林",
  str_item_6030119 = "士兵名牌",
  str_item_6030120 = "星火之光",
  str_item_6030121 = "啟光旗幟",
  str_item_6030122 = "娜席里絲之思",
  str_item_6030123 = "尼珀里絲之願",
  str_item_6030124 = "北國之鏡",
  str_item_intro_6030101 = "偕行紀念章。\n繪本迷你、圖案稚氣，然而難掩繪本中的不舍牽絆與難以割捨的情感。",
  str_item_intro_6030102 = "偕行紀念章。\n即使末日來臨，他還是會為妹妹準備好溫度合適的水。",
  str_item_intro_6030103 = "偕行紀念章。\n在那段黑暗的歲月中，這朵花就是她的黎明。",
  str_item_intro_6030104 = "偕行紀念章。\n來自白夜城神殿的肯定。",
  str_item_intro_6030105 = "偕行紀念章。\n沒有一個傾斜的天平可以逃過伊倫汀的雙眼。",
  str_item_intro_6030106 = "偕行紀念章。\n那時的普律瑪，還願意相信……",
  str_item_intro_6030107 = "偕行紀念章。\n這可是偉大的水形之主的示好！凡俗之物快快遞出肢體承接恩澤！",
  str_item_intro_6030108 = "偕行紀念章。\n這場演奏中有家人的願望，有夥伴們的關懷，還有……愛與勇氣。",
  str_item_intro_6030109 = "偕行紀念章。\n明明只是想尋找一個暫歸之處，結果卻意外地成就了一個很棒的居所。",
  str_item_intro_6030110 = "偕行紀念章。\n此刻感受到的暖意，是晨曦的暉光，還是你越過尖刺的溫度？",
  str_item_intro_6030111 = "偕行紀念章。\n很多人不知道，牡荊也是會開花的，只是比藤蘿花小，多為淡紫色，就像劍客的裙擺。",
  str_item_intro_6030112 = "偕行紀念章。\n某一天當她路過潺潺金河，她會想起夢裡乘船的經歷，並期待能與某人再度同舟。",
  str_item_intro_6030113 = "偕行紀念章。\n「因為有妳，這個世界才值得我去守護。」",
  str_item_intro_6030114 = "偕行紀念章。\n「因為有妳，我才想要守護這個世界。」",
  str_item_intro_6030115 = "偕行紀念章。\n由於灌注了戒衛座的愛意而得到非凡的強化，也許，她才因此能以另一種方式陪伴在他身邊……",
  str_item_intro_6030116 = "偕行紀念章。\n離開時，只覺得它是冰冷無情的機器；回來時，才發覺它的甜蜜。",
  str_item_intro_6030117 = "偕行紀念章。\n走到哪裡都沒辦法甩開……既然這樣，就當它是獨一無二的時尚單品吧。",
  str_item_intro_6030118 = "偕行紀念章。\n流著綿密奶油的樹木，結出清甜果實的小花……如果還有機會，多想在這裡野餐。",
  str_item_intro_6030119 = "偕行紀念章。\n每一塊名牌，每一條生命；每個璀璨的靈魂啊，願您得以安息。",
  str_item_intro_6030120 = "偕行紀念章。\n那是誰的父母？誰的孩子？誰的手足？銘刻於碑上的名字沉默著，映出前路。",
  str_item_intro_6030121 = "偕行紀念章。\n號聲響起，旌旗獵獵。艾斯特拉最無私的防軍堅守不退，將黑暗斥於一線之外。",
  str_item_intro_6030122 = "偕行紀念章。\n「想和姐姐在一起……」",
  str_item_intro_6030123 = "偕行紀念章。\n「想要妹妹活下去……」",
  str_item_intro_6030124 = "偕行紀念章。\n鏡面記錄過太多崩毀之刻，偶爾也該記點別的東西。",
  str_item_6130101 = "偕行銘忘板",
  str_item_6130102 = "偕行凝鏡板",
  str_item_6130103 = "偕行海奏板",
  str_item_6130104 = "偕行憧夢板",
  str_item_6130105 = "偕行相望板",
  str_item_6130106 = "偕行歸途板",
  str_item_6130107 = "偕行軍旅板",
  str_item_6130108 = "偕行鏡詩板",
  str_item_intro_6130101 = "偕行紀念板。\n結束了，舊日已經過去，我們回家吧。",
  str_item_intro_6130102 = "偕行紀念板。\n鏡中人，一起醒來吧。",
  str_item_intro_6130103 = "偕行紀念板。\n我的心從未如此強大，我的聲音從未如此動聽。",
  str_item_intro_6130104 = "偕行紀念板。\n每天醒來都要和詛咒抗爭，但她的夢很明亮：在一座整潔熱鬧的城市裡，迎來晨曦微光。",
  str_item_intro_6130105 = "偕行紀念板。\n縱使千年歲月如塵土一般消散如空，我心依舊。",
  str_item_intro_6130106 = "偕行紀念板。\n「嗚——叩隆叩隆——」火車擒著鐵軌，在明亮的夢中奔馳。奔過奶油森林，奔過蜂蜜泉眼，奔過旅人發酵的遺憾……",
  str_item_intro_6130107 = "偕行紀念板。\n「我願受萬萬遍打磨，篤信千淬啟光，百煉成鋼。削尖的全金屬彈，包裹我等義無反顧的大願。」",
  str_item_intro_6130108 = "偕行紀念板。\n「她的身體被雪掩埋，她的靈魂被鏡子禁錮，她的面孔落滿殘花，但她的愛不會消逝。」",
  str_item_3001000 = "夢智之碎",
  str_item_intro_3001000 = "從虛實難辨的故事中獲得的碎片，訴說著現實的痕跡。可以在【夢跡如實】商店兌換道具獎勵。",
  str_item_get_3001000 = "夢境-主題商店代幣過期轉化",
  str_item_3001001 = "蛻變之蕊",
  str_item_intro_3001001 = "在迎接挑戰、獲得成長後留下的紀念。可在「夢境-遺忘甦醒之日-記憶工坊」中兌換道具獎勵。",
  str_item_get_3001001 = "夢境-遺忘甦醒之日關卡",
  str_item_3001002 = "沉澱之片",
  str_item_intro_3001002 = "在迎接挑戰、獲得成長的過程中獲得的碎片。可在「夢境-遺忘甦醒之日-記憶工坊」中兌換道具獎勵。",
  str_item_get_3001002 = "夢境-遺忘甦醒之日關卡",
  str_item_3001003 = "心智",
  str_item_intro_3001003 = "伊芙保持理性與清醒的要素。可用於挑戰「夢境-遺忘甦醒之日」關卡，並在每日13:00恢復3點（已達上限則不會恢復）。",
  str_item_get_3001003 = "隨時間自動恢復",
  str_item_3001004 = "微笑之水",
  str_item_intro_3001004 = "伊芙愛用的水杯，雖然只是普通的水，卻能讓伊芙獲得源源不絕的力量。累積水量可提升「微笑指引著幸福」等級。",
  str_item_get_3001004 = "三星首通夢境潛夢難度關卡獲取",
  str_item_3001005 = "度量之砣",
  str_item_intro_3001005 = "尋找真我時獲得的砝碼，用來搭配名為人生的天平。可在「夢境-金波之下的審判-審判拍賣」中兌換道具獎勵。",
  str_item_get_3001005 = "「夢境-金波之下的審判」關卡",
  str_item_3001006 = "正義之燭",
  str_item_intro_3001006 = "為了心中的理想，在追求正義的路途上留下的星星燭火。可在「夢境-金波之下的審判-審判拍賣」中兌換道具獎勵。",
  str_item_get_3001006 = "「夢境-金波之下的審判」關卡",
  str_item_3001007 = "心智",
  str_item_intro_3001007 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001007 = "隨時間自動恢復",
  str_item_3001008 = "正義之光",
  str_item_intro_3001008 = "伊倫汀依靠自己的力量尋回的正義光芒。累積後可提升「真相聚焦」等級。",
  str_item_get_3001008 = "三星首通夢境潛夢難度關卡獲取",
  str_item_3001010 = "循聲海螺",
  str_item_intro_3001010 = "飄蕩著音樂聲的海螺，其腹中記錄了古老樂章的殘片。可在夢境-克娜莉夢遊水之仙境-海飲小店中兌換道具獎勵。",
  str_item_get_3001010 = "夢境-克娜莉夢遊水之仙境關卡",
  str_item_3001011 = "可口螢藻",
  str_item_intro_3001011 = "生長在海床角落的螢光藻，可用於製作某種大受歡迎的深海飲料。可在夢境-克娜莉夢遊水之仙境-海飲小店中兌換道具獎勵。",
  str_item_get_3001011 = "夢境-克娜莉夢遊水之仙境關卡",
  str_item_3001012 = "心智",
  str_item_intro_3001012 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001012 = "夢境-克娜莉夢遊水之仙境關卡",
  str_item_3001013 = "契約研習",
  str_item_intro_3001013 = "克娜莉試圖理解水形之主所描述的一切，連接上祂神祕的頭足類思維。累積後可提升「水形之觸」等級。",
  str_item_get_3001013 = "三星首通夢境潛夢難度關卡獲取",
  str_item_3001014 = "紫藤花簪",
  str_item_intro_3001014 = "細小但堅韌的花朵製成的髮簪。可在「夢境-夢隔重簾渡劍歌-花徑拾遺」中兌換道具獎勵。",
  str_item_get_3001014 = "夢境-夢隔重簾渡劍歌關卡",
  str_item_3001015 = "銅製古錢",
  str_item_intro_3001015 = "鏽跡斑駁的東方古錢，隨著歷史更迭，已失去了原本的貨幣功能。可在「夢境-夢隔重簾渡劍歌-花徑拾遺」中兌換道具獎勵。",
  str_item_get_3001015 = "夢境-夢隔重簾渡劍歌關卡",
  str_item_3001016 = "心智",
  str_item_intro_3001016 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001016 = "夢境-夢隔重簾渡劍歌關卡",
  str_item_3001017 = "鍛劍之念",
  str_item_intro_3001017 = "每次戰鬥，都是對俠士劍術的磨煉。不斷積累，終會引發質變。累積可提升「劍心」等級。",
  str_item_get_3001017 = "三星首通夢境潛夢難度關卡獲取",
  str_item_3001018 = "營運資金",
  str_item_intro_3001018 = "用影鎮人習慣的術語來說，紫蘊商會一開始只是個空殼商會罷了。但有錢不賺也不是建立者的作風，那何不「假戲真做」一番呢？",
  str_item_3001019 = "吉氣",
  str_item_intro_3001019 = "經商中透過金錢財務流轉所獲得的吉兆之氣，用於改善風水，促進斬邪。",
  str_item_3001021 = "銀白枝環",
  str_item_intro_3001021 = "象徵勝利與和平的橄欖枝花環。可在夢境-沉睡千年的守望-北風市集中兌換道具獎勵。",
  str_item_get_3001021 = "夢境-沉睡千年的守望關卡",
  str_item_3001022 = "守望銅幣",
  str_item_intro_3001022 = "為了紀念北風守望軍團凱旋而發行的青銅紀念幣。可在夢境-沉睡千年的守望-北風市集中兌換道具獎勵。",
  str_item_get_3001022 = "夢境-沉睡千年的守望關卡",
  str_item_3001023 = "心智",
  str_item_intro_3001023 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001023 = "隨時間自動恢復",
  str_item_3001024 = "芬香麥穗",
  str_item_intro_3001024 = "令人安心的麥香，是誓言裡對未來生活的期許，這不斷提醒著劍中魂——不要離去。累積後可提升「劍中魂」等級。",
  str_item_3001025 = "神殿之碎",
  str_item_intro_3001025 = "神殿一側轟然倒塌，那些雕刻精美的磚石和殿內呈貢的珍貴器皿也隨之化作一地碎片。而這些碎片，尚未失去價值。",
  str_item_3001026 = "跳跳糖果",
  str_item_intro_3001026 = "一種名為「跳跳糖」的稀有植物所結出的果實。可在夢境-怪誕美食鎮-美味速遞中兌換道具獎勵。",
  str_item_get_3001026 = "夢境-怪誕美食鎮關卡",
  str_item_3001027 = "奶油原木",
  str_item_intro_3001027 = "奶油森林中生長的茁壯樹木所製成的原木木材。可在夢境-怪誕美食鎮-美味速遞中兌換道具獎勵。",
  str_item_get_3001027 = "夢境-怪誕美食鎮關卡",
  str_item_3001028 = "心智",
  str_item_intro_3001028 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001028 = "隨時間自動恢復",
  str_item_3001029 = "珍心",
  str_item_intro_3001029 = "來自契法不加掩飾的關切與呼喚……獵石從不奢求。累積可提升「獵石」等級。",
  str_item_3001030 = "精品食器",
  str_item_intro_3001030 = "出自大師之手的精美傳世之作，能幫助頂級的食材更具吸引力。",
  str_item_3001031 = "啟明星勳章",
  str_item_intro_3001031 = "啟光舊時的勳章，如今已絕版，意義深刻。勳章本身並不值錢，只因英雄的光輝而承此榮幸，變為無價之寶。贈予英雄的勳章，不過是千恩萬謝中的些許還禮。可在夢境-璨星破曉之夜-夢幻配售部中兌換道具獎勵。",
  str_item_get_3001031 = "夢境-璨星破曉之夜",
  str_item_3001032 = "啟光兌換券",
  str_item_intro_3001032 = "啟光內部通行的票券，根據勞動與服役的時數配發，用以兌換物資。可在夢境-璨星破曉之夜-夢幻配售部中兌換道具獎勵獎勵。",
  str_item_get_3001032 = "夢境-璨星破曉之夜",
  str_item_3001033 = "心智",
  str_item_intro_3001033 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001033 = "隨時間自動恢復",
  str_item_3001034 = "哨子",
  str_item_intro_3001034 = "哨聲是那麼尖銳，總牽動著士兵的神經。但離開它，還有哪裡比這安心？累積後可提升「削尖彈頭」等級。",
  str_item_3001035 = "兵棋",
  str_item_intro_3001035 = "啟光難得的娛樂方式，但仍保留著戰鬥特性。精美的兵棋中，寄託製作者的心意。",
  str_item_3001036 = "乾花書籤",
  str_item_intro_3001036 = "少女閱讀時使用的自製書籤。在花兒的陪伴下，她翻閱了許多寓言集，去求證那一點零碎的過往。可在夢境-鏡中世界·雪中詩篇-無名市集中兌換道具獎勵。",
  str_item_get_3001036 = "夢境-鏡中世界·雪中詩篇關卡",
  str_item_3001037 = "鏡子碎片",
  str_item_intro_3001037 = "這些碎片不僅是魔鏡力量的延伸，也包含著鏡中世界的構成根基，每一片都是一個小小的裂境。可在夢境-鏡中世界·雪中詩篇-無名市集中兌換道具獎勵。",
  str_item_get_3001037 = "夢境-鏡中世界·雪中詩篇關卡",
  str_item_3001038 = "心智",
  str_item_intro_3001038 = "保持理性與清醒的要素。在探索中將會消耗，並隨時間經過恢復。",
  str_item_get_3001038 = "隨時間自動恢復",
  str_item_3001039 = "鏡界之花",
  str_item_intro_3001039 = "娜席里絲的力量常以花的形式出現，在境界的倒影中也沒有例外。",
  str_item_3001040 = "北境寓言集",
  str_item_intro_3001040 = "娜席里絲想要找回她的記憶，在求助他人的同時，也從未放棄自己身上的線索。",
  str_item_not_enough_plm = "黑荊白花之蕾道具不足",
  str_item_3751396 = "黑墨鏡的黑眼圈",
  str_item_3751397 = "黃昏鎮的教女",
  str_item_3751551 = "新元帥的煩惱",
  str_item_intro_3751396 = "希望光明能籠罩黃昏鎮，驅散那裡的暗霾。",
  str_item_intro_3751397 = "黑眼圈？才沒有。",
  str_item_intro_3751551 = "除了彙報工作以外，你們就不能聊點別的事嗎？",
  str_item_3000131 = "黃昏交響特召星標",
  str_item_intro_3000131 = "可於【黃昏交響】限定召集中使用，召集一次。\n此為限時道具，請在 【黃昏交響】限定召集結束前使用，逾期將消失，不轉化為其他物品。",
  str_item_10000992 = "克萊肯協力箱",
  str_item_intro_10000992 = "使用後光靈克萊肯將加入你的冒險。",
  str_item_1000099 = "克萊肯協力箱",
  str_item_intro_1000099 = "使用後光靈克萊肯將加入你的冒險。",
  str_item_3755023 = "狗狗布偶乖乖",
  str_item_3755024 = "青蛙？",
  str_item_3755025 = "黎明之花",
  str_item_intro_3755023 = "獲得後可解鎖對應頭像。\n嗚嚶……嗚嚶……你喜歡嗎？",
  str_item_intro_3755024 = "獲得後可解鎖對應頭像。\n蒲公英？不要跑～",
  str_item_intro_3755025 = "獲得後可解鎖對應頭像框。\n小小的白花，代表著黎明……",
  str_item_3661219 = "燦星騎士肖像",
  str_item_intro_3661219 = "家具，可設置於巨像的房間。\n以騎士時期的伊倫汀為原型製作的肖像，似乎是某位少女未能送出的禮物。\n「伊倫汀大人，衷心感謝您一直以來對我的幫助與關照。希望您能繼續秉持正義與仁愛的信念，引領白夜城走向更加光明的未來。」",
  str_item_3661220 = "天真修女肖像",
  str_item_intro_3661220 = "家具，可擺放在巨像的房間中。\n以修女時期的普律瑪為原型製作的肖像，似乎是某位父親未能送出的禮物。\n「小普，希望妳永遠純真善良，希望我們一家人永遠幸福快樂。」",
  str_item_3751039 = "堅毅如山",
  str_item_3751040 = "光明盡頭",
  str_item_3751041 = "長久勝歌",
  str_item_3751398 = "求知若渴",
  str_item_3751399 = "守護之力",
  str_item_3751400 = "你說什麼？",
  str_item_intro_3751039 = "獲得後可解鎖對應頭像。\n「德尼耶爾、萊因哈特……無論發生什麼，希望我們都能找到屬於自己的道路。」",
  str_item_intro_3751040 = "獲得後可解鎖對應頭像。\n「我無意與任何人為敵，我對這事可不感興趣。他們只是擋住了我的路而已。」",
  str_item_intro_3751041 = "獲得後可解鎖對應頭像。\n「啟明之光可以是任何人。只要能帶領光靈背負重任前行，啟明之光可以是你，也可以是我。」",
  str_item_intro_3751398 = "獲得後可解鎖對應頭像。\n「星空啊……就像一座無垠的圖書館，收藏著世上所有祕密。」",
  str_item_intro_3751399 = "獲得後可解鎖對應頭像。\n「說不定真的有一天，我也能妥善掌握這份命運賜給我的力量。」",
  str_item_intro_3751400 = "獲得後可解鎖對應頭像。\n「啊？」",
  str_item_3751552 = "禁忌話題",
  str_item_intro_3751552 = "獲得後可解鎖對應頭像。\n「你不准再說那個冰棒笑話！」",
  str_item_3751553 = "快樂的塔塔",
  str_item_intro_3751553 = "獲得後可解鎖對應頭像。\n「馬上要放假啦，塔塔已經想好假期要如何度過，她的計畫是什麼呢？」",
  str_item_3763034 = "暖心禮物",
  str_item_intro_3763034 = "獲得後可解鎖對應頭像框。\n札莉雅擔心你受不了北境的天氣，所以給了你自己的帽子。",
  str_item_3661215 = "書桌",
  str_item_intro_3661215 = "家具，可設置於巨像的房間。\n頗具品味的木製書桌，用來工作能令人心情平靜。",
  str_item_3661216 = "小茶几",
  str_item_intro_3661216 = "家具，可設置於巨像的房間。\n木製的小茶几，檯面有一部分是大理石製成，看起來非常講究。",
  str_item_3661217 = "貓頭鷹茶几",
  str_item_intro_3661217 = "家具，可設置於巨像的房間。\n一隻貓頭鷹站在小桌子上，似乎在凝視遠處。",
  str_item_3661218 = "魔法掃帚",
  str_item_intro_3661218 = "家具，可設置於巨像的房間。\n據說某些傳說中，騎上魔法掃帚就可以飛行。不知道靈感來自哪裡？",
  str_item_5234055 = "小船擺飾",
  str_item_intro_5234055 = "一艘色彩鮮豔的小船，被架起來當作擺飾使用。看到它是否會激起人遠航的衝動呢？",
  str_item_3661052 = "浮游螢盞",
  str_item_intro_3661052 = "家具，可設置於巨像的房間。\n只會浮起來，不能四處移動……要用它來做什麼呢？比如說掛點東西？還是當扶手？",
  str_item_3000338 = "遺跡碎片",
  str_item_intro_3000338 = "應該是古代遺跡的碎片，在漫長的歲月中已經四散各地。如果有人願意承認其價值，應該還是願意付出一定報酬來收購它們。",
  str_item_3751401 = "黑潮的籃球",
  str_item_3751402 = "桌球新人薇絲",
  str_item_3751403 = "電競選手貢露",
  str_item_3751404 = "射擊王者卡戎",
  str_item_intro_3751401 = "獲得後可解鎖對應頭像。\n看我三步上籃！ 啊，球怎麼被籃板彈回來了！",
  str_item_intro_3751402 = "獲得後可解鎖對應頭像。\n生命在於運動！ 雖然是新人，打桌球也一樣會全力以赴喔！",
  str_item_intro_3751403 = "獲得後可解鎖對應頭像。\n說到打遊戲，我絕對不輸人！看我在電競比賽上大顯身手吧！",
  str_item_intro_3751404 = "獲得後可解鎖對應頭像。\n射擊場上我也會華麗地演出！",
  str_item_3440011 = "光之寶箱",
  str_item_intro_3440011 = "打開後從以下內容中隨機獲得1份：白夜幣*10,000、白夜幣*5,000、二階瑩玉·共通*2、一階瑩玉·共通*3、靈質*100、靈質*50。",
  str_item_3440012 = "啟迪之匣",
  str_item_intro_3440012 = "打開後從以下內容中隨機獲得1份：白夜幣*5,000、白夜幣*2,000、白夜幣*1,000、二階瑩玉·共通*1、一階瑩玉·共通*2、靈質*30。",
  str_item_3440013 = "幽海寶匣",
  str_item_intro_3440013 = "打開後從以下內容中隨機獲得1份：匿名禮包*1、聯軍高級訂購箱*2、白夜幣*20,000、二階瑩玉·共通*4。",
  str_item_3440019 = "海靈寶匣",
  str_item_intro_3440019 = "打開後從以下內容中隨機獲得1份：匿名禮包*1、聯軍高級訂購箱*2、白夜幣*20,000、二階瑩玉·共通*4。",
  str_item_3755036 = "審判騎士伊倫汀",
  str_item_intro_3755036 = "獲得後可解鎖對應頭像。\n「不能放過任何蛛絲馬跡！」",
  str_item_3755037 = "小普的料理",
  str_item_intro_3755037 = "獲得後可解鎖對應頭像。\n「雖然賣相不太好，但我保證會很好吃喔！」",
  str_item_6110001 = "偕行薰風板",
  str_item_intro_6110001 = "偕行紀念板。\n看著上面的圖案，就想起了隨著海風而來的遠客，以及琵琶的微聲、旌幡的呼響……",
  str_item_3661221 = "紀念火車模型",
  str_item_intro_3661221 = "著名演員卡戎送給參與電影首映觀眾的禮物。雄偉的火車頭造型，就像卡戎本人極富衝擊力的表演一般，讓觀眾留下了深刻的印象。\n「記得這份感動吧！」",
  str_item_3000027 = "心意券",
  str_item_3000028 = "心意氣球",
  str_item_intro_3000027 = "用於在時裝投票活動中，為心儀的光靈投票。\n「這份心意，能順利傳達到嗎？」",
  str_item_intro_3000028 = "用於在時裝投票活動中，為鍾意的時裝投票。\n「請好好交到對方手中，不要讓心意飛走啦～」",
  str_item_3661222 = "黑管少女肖像",
  str_item_3661223 = "水形女王肖像",
  str_item_intro_3661222 = "家具，可設置於巨像的房間\n原本被製為咖啡館的特殊茶壺，但從嘴部出水的設計並沒有讓它獲得太好的評價。\n「別、別用我的形象做這種事啊！」",
  str_item_intro_3661223 = "家具，可設置於巨像的房間\n精緻的女王肖像，為了減輕重量而採用了空心設計。有人提議這種設計適合開發成容納螢藻汁的器皿，但被女王嚴正拒絕了。\n「嗚，為什麼……總是我遇到這樣的事……」",
  str_item_3661224 = "醫用儲物櫃",
  str_item_3661225 = "病床",
  str_item_3661226 = "手推車",
  str_item_3661227 = "聯排座椅",
  str_item_intro_3661224 = "家具，可設置於巨像的房間\n木質置物櫃，上面擺放著各種瓶瓶罐罐。希望這些藥液能緩解別人的痛苦。",
  str_item_intro_3661225 = "家具，可設置於巨像的房間\n專門為患者準備的床鋪。如果身體感到不舒服的話，不妨來這裡休息一下吧。",
  str_item_intro_3661226 = "家具，可設置於巨像的房間\n簡易的醫療推車。雖承載的物品有限，但也相當重要。",
  str_item_intro_3661227 = "家具，可設置於巨像的房間\n聯排座椅。與周圍的同伴聊聊天，或許能緩解焦慮的心情。",
  str_item_5234056 = "靜謐亭院",
  str_item_intro_5234056 = "很適合乘涼休息的地方。遇到煩心事的話，就來這裡吧。",
  str_item_3000344 = "收納瓶",
  str_item_intro_3000344 = "到底要收集多少，才能結束呢……",
  str_item_3000345 = "遊玩券",
  str_item_intro_3000345 = "由影鎮商會製作而成的遊玩券，外觀普通，是「盲盒」熱潮這款遊戲的指定貨幣。",
  str_item_3661228 = "築爐巧蟹",
  str_item_3661229 = "福船模型",
  str_item_intro_3661228 = "家具，可設置於巨像的房間。\n原本是璇極親手製作，用於協助匠人機巧鍛造的龍洲機關獸，在多年使用後已失去運動功能，但還是很適合作為另類擺設來欣賞。",
  str_item_intro_3661229 = "家具，可設置於巨像的房間。\n龍洲人在出海的福船上寄託許多心願，例如在榫合處嵌入銅錢和銅鏡，擺出七星伴月的陣勢，寓意吉祥好運、一帆風順。雖然這條船是璇極製作的船模，但該有的細節和心意卻一樣不少。",
  str_item_3763035 = "治療藥液",
  str_item_intro_3763035 = "獲得後可解鎖對應頭像框。\n別擔心，祂不會傷害你的……",
  str_item_3751554 = "虛弱",
  str_item_intro_3751554 = "獲得後可解鎖對應頭像。\n「咳咳……我、我沒事……調養一下就好了。」",
  str_item_3751555 = "感恩有你",
  str_item_intro_3751555 = "獲得後可解鎖對應頭像。\n「今天我請客～」",
  str_item_3751405 = "心繫患者",
  str_item_intro_3751405 = "獲得後可解鎖對應頭像。\n「請坐下來，我來幫您看看。」",
  str_item_3751406 = "以武服人",
  str_item_intro_3751406 = "獲得後可解鎖對應頭像。\n「我看誰敢欠你的錢！」",
  str_item_3751407 = "海底舊物",
  str_item_intro_3751407 = "獲得後可解鎖對應頭像。\n埋藏在深海中的寶物。\n抵抗著磨損，抵抗著來自海水的沖刷，只為有一天能重回陸地。",
  str_item_3751408 = "璇極的邀請",
  str_item_intro_3751408 = "獲得後可解鎖對應頭像。\n「我聽聞空裔所信奉之理和我的宗族有類似之處，怎麼樣，願意來我鄴國宗門交流一番嗎？」",
  str_item_3751556 = "銅造機物",
  str_item_intro_3751556 = "獲得後可解鎖對應頭像。\n「無實際功能的機關術造物。若你覺得它好看，那就值得了。」",
  str_item_3751409 = "漫天金幣",
  str_item_intro_3751409 = "獲得後可解鎖對應頭像。\n「雖不及我財產的百分之一，但白來的財富沒有不拿的道理。」",
  str_item_3751410 = "影主的休息時間",
  str_item_intro_3751410 = "獲得後可解鎖對應頭像。\n「節日很快就到了，那就放鬆一點吧。」",
  str_item_3751557 = "將軍",
  str_item_intro_3751557 = "獲得後可解鎖對應頭像。\n「不要猶豫，要出奇制勝。」",
  str_item_3751558 = "幸運金幣",
  str_item_intro_3751558 = "獲得後可解鎖對應頭像。\n「幸運金幣，送給來年一定會得到好運的你。」",
  str_item_3763036 = "霧氣之蛇",
  str_item_intro_3763036 = "獲得後可解鎖對應頭像框。\n盤繞形成的霧蛇，終將吞噬一切。",
  str_item_3751411 = "來飲茶",
  str_item_intro_3751411 = "獲得後可解鎖對應頭像。\n「 三點了，飲茶否？」",
  str_item_3751559 = "山櫻盡染",
  str_item_intro_3751559 = "獲得後可解鎖對應頭像。\n「 也許是何處山櫻早開的暈染，在緋的面龐上映出一縷暖流。」",
  str_item_3751560 = "極客快樂餅",
  str_item_intro_3751560 = "獲得後可解鎖對應頭像。\n「 滿足我的不是食物，而是智慧。」",
  str_item_3751412 = "智慧司令",
  str_item_intro_3751412 = "獲得後可解鎖對應頭像。\n「 光靈的敵人是光靈。」",
  str_item_3763037 = "櫻華之禮",
  str_item_intro_3763037 = "獲得後可解鎖對應頭像框。\n櫻華一族的血脈，代替族人一直默默守護著緋。",
  str_item_3751561 = "小虎貼貼",
  str_item_3751562 = "不辣",
  str_item_3751563 = "微辣",
  str_item_3751564 = "中辣",
  str_item_3751565 = "哎斯特辣",
  str_item_intro_3751561 = "獲得後可解鎖對應頭像。\n「這麼可愛又有美味力量的小老虎，誰能忍住貼貼的衝動呢～」",
  str_item_intro_3751562 = "獲得後可解鎖對應頭像。\n「對於紅油扳手來說，這種辣度小CASE啦！」",
  str_item_intro_3751563 = "獲得後可解鎖對應頭像。\n「鄴國喜微辣，雖然魔鬼辣對丹棠來說太辣了，但廚藝超群的她能理解這味道的妙處所在。」",
  str_item_intro_3751564 = "獲得後可解鎖對應頭像。\n「『用餐要優雅！』卡蓮反覆告訴自己。可不能因為嘴裡的激辣而丟了白夜騎士的用餐禮儀呀！」",
  str_item_intro_3751565 = "獲得後可解鎖對應頭像。\n「『啊～啊～啊～哎斯特辣！』這是八哥吃完辣醬後良久說出的第一句話。」",
  str_item_9997004 = "急救繃帶",
  str_item_9997005 = "銀月盾牌",
  str_item_9997008 = "治癒女神雕像",
  str_item_9997009 = "降咒之石",
  str_item_9997010 = "死亡信件",
  str_item_9997011 = "狂戰之鎧",
  str_item_9997012 = "太陽榮光",
  str_item_9997013 = "雷擊者",
  str_item_9997014 = "萬色寶石",
  str_item_9997015 = "馭光大劍",
  str_item_9997016 = "銀月獵刀",
  str_item_9997017 = "銀月長弓",
  str_item_9997018 = "鋒利短劍",
  str_item_9997019 = "耀光目鏡",
  str_item_9997020 = "消光漆",
  str_item_9997021 = "櫻之落",
  str_item_9997023 = "瓦解面具",
  str_item_9997024 = "神裁之手",
  str_item_9997025 = "寂滅女神像",
  str_item_9997026 = "蓄能腰帶",
  str_item_9997027 = "光能力盾",
  str_item_9997028 = "死神凝視",
  str_item_9997029 = "鏈介護符",
  str_item_9997030 = "羈絆雕塑",
  str_item_9997031 = "潛能吊墜",
  str_item_9997033 = "行動能源器",
  str_item_9997035 = "攝魂斬刀",
  str_item_9997003 = "光療蠟燭",
  str_item_9997006 = "虔心之證",
  str_item_9997007 = "太陽之盾",
  str_item_9997032 = "共鳴勳章",
  str_item_9997022 = "摺疊睡袋",
  str_item_9997036 = "舊學手稿",
  str_item_9997037 = "瘟疫遺作",
  str_item_9997038 = "混糅利刃",
  str_item_9997034 = "爆裂靴",
  str_item_9997039 = "幸運幣",
  str_item_9997040 = "雙聲蘭",
  str_item_9997041 = "「冰原」浮游器",
  str_item_9997042 = "「烈陽」浮游器",
  str_item_9997043 = "「葉植」浮游器",
  str_item_9997044 = "「雷霆」浮游器",
  str_item_9997045 = "黎明之碟",
  str_item_9997046 = "裂解水晶",
  str_item_9997047 = "光能魔盒",
  str_item_intro_9997004 = "戰鬥開始時，戰場中生成一個繃帶",
  str_item_intro_9997005 = "戰鬥開始時，獲得最大生命值20%的護盾，持續2回合",
  str_item_intro_9997008 = "戰鬥開始時，如果目前生命值低於30%，則回復至30%",
  str_item_intro_9997009 = "每回合開始時，損失7%目前生命值，之後對周圍2圈範圍內敵人造成隊伍平均攻擊力150%的傷害",
  str_item_intro_9997010 = "光靈主動技能傷害提高50%，每次施放主動技能損失8%目前生命值",
  str_item_intro_9997011 = "根據我方已損失生命值百分比，提高連鎖技能傷害，最高提升40%",
  str_item_intro_9997012 = "目前生命值在70%以上時，光靈造成的傷害提升20%",
  str_item_intro_9997013 = "光靈同時攻擊至少3個敵人時，施放落雷攻擊全場敵人，造成隊伍平均攻擊力100%的傷害",
  str_item_intro_9997014 = "每回合開始時時，場上隨機更新1個彩色格子",
  str_item_intro_9997015 = "一次性點選消除至少15個格子時，光靈連鎖技能傷害提升30%；消除格子數不足8時，無法施放連鎖技能",
  str_item_intro_9997016 = "距離敵人越近，光靈連鎖技能傷害越高，最高提升20%",
  str_item_intro_9997017 = "距離敵人越遠，光靈連鎖技能傷害越高，最高提升30%",
  str_item_intro_9997018 = "職業為「爆破」的光靈，有30%機率額外施放一次連鎖技能",
  str_item_intro_9997019 = "職業為「狙擊手」的光靈，連鎖技能目標+1",
  str_item_intro_9997020 = "職業為「輔助」的光靈戰鬥時，連鎖技和主動技能帶來的恢復效果提升25%",
  str_item_intro_9997021 = "戰鬥開始時，職業為「變化」的光靈主動技能冷卻回合-1",
  str_item_intro_9997023 = "光靈施放主動技能或連鎖技能造成傷害時，有30%機率立刻結算一次目標的中毒/灼燒/流血效果",
  str_item_intro_9997024 = "敵人處在異常狀態中或攜帶減益效果時，受到所有傷害增加20%",
  str_item_intro_9997025 = "召喚死亡的氣息，秒殺生命值低於7%的敵人",
  str_item_intro_9997026 = "點選消除後，若本回合光靈未施放連鎖技能，所有光靈主動技能冷卻回合-1",
  str_item_intro_9997027 = "光靈溢出的治療量，將按比例轉化為一層護盾，持續一回合",
  str_item_intro_9997028 = "當攜帶中毒/灼燒/流血效果的敵人死亡時，為場上另一個隨機敵人附加一層中毒效果",
  str_item_intro_9997029 = "陣營支援技能觸發需要消除的格子數量降低5",
  str_item_intro_9997030 = "光靈施放主動技能時，其羈絆光靈的主動技能冷卻回合-1",
  str_item_intro_9997031 = "戰鬥開始時施放的第一個主動技能，施放後冷卻回合-2",
  str_item_intro_9997033 = "每回合開始時，戰場中隨機更新一個指示物，消除指示物後，本回合內連鎖技能傷害提升25%",
  str_item_intro_9997035 = "光靈造成傷害時，擁有2%吸血率，每回合開始時，損失15%目前生命值",
  str_item_intro_9997003 = "戰鬥勝利後，回復10%最大生命值",
  str_item_intro_9997006 = "戰鬥勝利後，所有光靈的最大生命值提升3%",
  str_item_intro_9997007 = "戰鬥勝利後，所有光靈的防禦力提升1.5%",
  str_item_intro_9997032 = "戰鬥勝利後，所有光靈的攻擊力提升1%",
  str_item_intro_9997022 = "獲取時，總回合數+10 ",
  str_item_intro_9997036 = "點選消除格子時，有25%機率額外增加1次消除次數",
  str_item_intro_9997037 = "點選消除格子時，對消除範圍內的敵人隨機附加1層中毒/流血/灼燒效果",
  str_item_intro_9997038 = "點選消除格子時，對消除範圍內的敵人造成隊伍平均攻擊力120%的傷害",
  str_item_intro_9997034 = "敵人在本回合點選消除的區域內每移動一格，受到一次隊伍平均攻擊力150%的傷害",
  str_item_intro_9997039 = "戰鬥開始時，隨機1個空裔特別裝具獲得1次使用次數",
  str_item_intro_9997040 = "獲得空裔特別裝具：任選2個格子轉為彩色格子，每消除60個格子獲得1次使用次數",
  str_item_intro_9997041 = "獲得空裔特別裝具：選擇3*3範圍，消除其中的水屬性格子，每消除50個格子獲得1次使用次數",
  str_item_intro_9997042 = "獲得空裔特別裝具：選擇3*3範圍，消除其中的火屬性格子，每消除50個格子獲得1次使用次數",
  str_item_intro_9997043 = "獲得空裔特別裝具：選擇3*3範圍，消除其中的森屬性格子，每消除50個格子獲得1次使用次數",
  str_item_intro_9997044 = "獲得空裔特別裝具：選擇3*3範圍，消除其中的雷屬性格子，每消除50個格子獲得1次使用次數",
  str_item_intro_9997045 = "獲得空裔特別裝具：重設全場格子，每消除80個格子獲得1次使用次數",
  str_item_intro_9997046 = "獲得空裔特別裝具：任選1個屬性，重設全場該屬性格子，每消除80個格子獲得1次使用次數",
  str_item_intro_9997047 = "獲得空裔特別裝具：任選1個格子，將距離其最近的4個同屬性格子消除，每消除60個格子獲得1次使用次數",
  str_item_rpintro_9997004 = "恢復藥水的輔助品，方便為戰鬥人員恢復傷勢。",
  str_item_rpintro_9997005 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。",
  str_item_rpintro_9997008 = "保存良好的塑像，會為佩戴者提供治癒之力。",
  str_item_rpintro_9997009 = "舊時代的產物，它會詛咒使用者，同時也給予你相應的力量。",
  str_item_rpintro_9997010 = "據說是上一次毀滅性戰爭時出現的神祕物品，帶有強大的詛咒之力，足以重傷對手。",
  str_item_rpintro_9997011 = "穿上它，你的傷痛將化為力量，最終指引你走向勝利。",
  str_item_rpintro_9997012 = "帶著她就能擁有勝利女神的庇護，在戰鬥中將會無往不利。",
  str_item_rpintro_9997013 = "舊時代的名刃，其中封印了雷霆的力量，只要拔出來就會瞬間爆發，消滅敵人。",
  str_item_rpintro_9997014 = "蘊含所有顏色的寶石，擁有絢爛的多變光芒。",
  str_item_rpintro_9997015 = "舊時代的大劍，當你握緊它時，你能感受到體內的力量正在增加。",
  str_item_rpintro_9997016 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。",
  str_item_rpintro_9997017 = "舊日士兵使用的經典武器，上面還附著來自過去的祝福，對付靈活的敵人時效果卓越。",
  str_item_rpintro_9997018 = "古老的短劍，使用了舊時代的高強度合金，十分鋒利。",
  str_item_rpintro_9997019 = "鏡片會在戰鬥時發出炫目的光芒致盲對手，並會保護佩戴者免疫此種光芒，屬於輔助性質的裝備。",
  str_item_rpintro_9997020 = "舊時代的塗料，吸收光能的效果很好。",
  str_item_rpintro_9997021 = "舊時代的產物，雖然外表美麗，卻帶有可怕的力量，會讓敵人宛如落花般死於爆炸之中。",
  str_item_rpintro_9997023 = "舊時代的遺物，似乎附有強烈的詛咒術，佩戴者若用毒液作戰，足以令人致命。",
  str_item_rpintro_9997024 = "來自於舊時代的名刃，執刀者會感受到媲美神的力量。",
  str_item_rpintro_9997025 = "從這尊小雕像裡，能感受到敵人的生命氣息，攜帶在身邊，足以立刻殺死搖搖欲墜的殘敵。",
  str_item_rpintro_9997026 = "非常合身的腰帶，在符合啟動條件的情況下，可為佩戴者提供所需的光能。",
  str_item_rpintro_9997027 = "舊時代的一種神祕裝置，可以感應溢出的光能，並轉化為保護佩戴者的力場。",
  str_item_rpintro_9997028 = "據說是強大戰士親手製作的詛咒物品，足以使敵人無法逃離死亡的命運。",
  str_item_rpintro_9997029 = "舊時代的護符，能夠在微觀層面進行光能連結，在戰鬥時大幅傷害敵人。",
  str_item_rpintro_9997030 = "舊時代的產物，可為羈絆光靈恢復一定的光能。",
  str_item_rpintro_9997031 = "舊時代的產物，使用該物品後，可迅速補充失去的部分光能。",
  str_item_rpintro_9997033 = "用來儲存光能的裝置，釋放後可以補充失去的光能。",
  str_item_rpintro_9997035 = "泛有一絲邪惡氣息的斬刀，似乎是上古時代專門用於惡戰的武器，出刀必須見血。",
  str_item_rpintro_9997003 = "這根蠟燭散發的溫暖光芒，擁有能夠治癒光靈傷口的力量。",
  str_item_rpintro_9997006 = "舊時代流傳下來的小雕像，以高強度材料製成，堅固又輕便，還會賜福於攜帶者。",
  str_item_rpintro_9997007 = "舊時代的古老盾牌……擁有完美的弧形，據說更注入了太陽的力量，光能的力量會擋開一切致命的攻擊。",
  str_item_rpintro_9997032 = "舊時代的勳章，構造神祕，能夠在微觀層面進行光能連結，增加戰鬥力。",
  str_item_rpintro_9997022 = "不知是誰遺落的摺疊睡袋，能夠恢復體力。",
  str_item_rpintro_9997036 = "似乎是古代的學者手稿，上面記載了相性之間的奇妙關係，能指導戰鬥人員如何針對相性進行作戰。",
  str_item_rpintro_9997037 = "一位佚名作者很久以前繪製的古老畫作，描繪瘟疫橫行的慘狀，作者本人也死於這場瘟疫，隨後它就擁有了可怕的力量。",
  str_item_rpintro_9997038 = "似乎能將光能完美融合的武器……實在很罕見。",
  str_item_rpintro_9997034 = "舊時代的產物，專門用於對付追兵。蘊含的光能之力會殘留在經過的路線上，並在一段時間後爆發，殺傷追擊的敵人。",
  str_item_rpintro_9997039 = "古老而神祕的錢幣，擁有它的光靈偶爾會獲得力量增益、行動更敏捷",
  str_item_rpintro_9997040 = "一種稀有的紅色蘭花，是舊時代特別培育出的產物，必定成對出現、成對開放、成對凋零，能使佩戴者擁有神祕感應，協力作戰時更順利。",
  str_item_rpintro_9997041 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。",
  str_item_rpintro_9997042 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。",
  str_item_rpintro_9997043 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。",
  str_item_rpintro_9997044 = "舊時代的產物，長得有點像微縮版的巨像，戰鬥時會協助主人作戰。",
  str_item_rpintro_9997045 = "舊時代的產物，會在兩名戰鬥者之間產生神祕的感應作用。",
  str_item_rpintro_9997046 = "表面佈滿細微裂紋的粗糙水晶，這表示其中蘊含過多光能，只要輕輕觸碰就會釋放，足以在戰鬥中使敵人暈眩。",
  str_item_rpintro_9997047 = "舊時代的技術，雖然只是個小小的盒子，但能儲存大量光能。",
  str_item_3000349 = "浮空兌換幣",
  str_item_intro_3000349 = "浮空商會的福利兌換幣，只有熟客才有機會獲得。",
  str_item_3000134 = "貪婪之蛇特召星標",
  str_item_intro_3000134 = "可在【貪婪之蛇】限定召集中使用，進行一次召集。\n此道具是限時道具，請您在【貪婪之蛇】限定召集結束之前使用，逾期則道具將消失，不另外轉化為其他內容。",
  str_item_3420133 = "2.5週年特選召集箱",
  str_item_intro_3420133 = "從指定6星光靈名單中選擇一位光靈與你並肩作戰，人選包含：<color=#ffffff>丹棠/札莉雅/安頓/萊蕾/希南/約書亞/舒瓦茲·錚鳴/鶯歌/李奧/哈提/蒂娜/零恩/耶利亞/木月白/仲胥/維克/阿克希亞/莉莉卡/米洛斯/珀拉珂/傑諾/菲雅/卡蓮·煜魂/妮娜/巴頓·芒刃/賈爾斯/蓮/青瞳/瑤/雨森/凜音/芙洛琳/露比/希諾普/諾維亞/海蒂/貝菲爾/路克/普律瑪/克/雷文頓/斯莫奇/弗勞爾/拜里厄/緋/醒山/伊芙/烏列爾/卡蓮/希羅娜/沙利葉/拉斐爾/克娜莉/卡戎/艾希/維多利亞/約娜/娜席里絲/加百列/彌加德/米迦勒/貢露/伊倫汀/雷霆</color>。\n注意：2.5週年特選召集箱有期限，過期將轉化為3,000光珀，經由郵件發放給您。請記得在期限內使用：2024年2月28日17:00",
  str_item_3661231 = "影之座",
  str_item_intro_3661231 = "家具，可設置於巨像的房間。\n皮革硬挺、造型霸氣，這是浮空商會專為伊斯塔萬打造的豪華座椅。因為有此噱頭，同款座椅的價格雖然昂貴，但還是賣得很好。",
  str_item_3661232 = "浮空飛艇模型",
  str_item_intro_3661232 = "家具，可設置於巨像的房間。\n由浮空商會打造的「浮空飛艇」，集旅遊、購物、休閒、度假於一體，當然也少不了各種規格的模型供顧客選購。這款模型的規格雖不是最大，但做工卻最為精細。",
  str_item_3661233 = "微光彩燈",
  str_item_intro_3661233 = "家具，可設置於巨像的房間。\n一排排的彩燈照亮了漆黑的空間。在這值得慶祝的日子裡，希望彩燈的微光能為你帶來一些溫暖。",
  str_item_3661234 = "聖夜禮盒",
  str_item_intro_3661234 = "家具，可設置於巨像的房間。\n光靈們送你這份心意作為禮物。雖為薄禮，卻飽含他們的心血與努力。願來年，這份禮物依舊為你帶來好運。",
  str_item_5234057 = "冰晶車",
  str_item_intro_5234057 = "由寒冰打造的觀賞車。其晶瑩剔透的外表讓人看著就能放鬆心情。",
  str_item_3661236 = "變裝劍士肖像",
  str_item_3661237 = "行舟劍士肖像",
  str_item_3661241 = "布林風扇",
  str_item_3661242 = "植物小夜燈",
  str_item_intro_3661236 = "家具，可設置於巨像的房間。\n某位機巧師所做的換裝機關玩偶，按下按鈕玩偶便會隨機換裝。據說靈感來源於龍洲的某種表演藝術。\n「想要扮演龍洲人的話……也必須要學會這種瞬間變裝技術嗎？」",
  str_item_intro_3661237 = "家具，可設置於巨像的房間。\n機巧師為了紀念與劍士成功合作，以劍士執行任務時的姿態為原型製作了肖像。\n「你說想在船的另一邊留個空位？好喔，哪天想好要放誰上去，就告訴我一聲吧。」",
  str_item_intro_3661241 = "家具，可設置於巨像的房間。\n啟光科學家實驗室內的專用風扇，支架有靈活的彎曲、黏貼功能。據說，這款風扇的設計靈感源自一個名為「布林」的機械體。",
  str_item_intro_3661242 = "家具，可設置於巨像的房間。\n一款設計精巧的燈具，不僅能為室內植物提供必要的生長光，還能為室內營造溫馨自然的氛圍。",
  str_item_3000352 = "空裔之羽",
  str_item_intro_3000352 = "樣貌獨特的羽毛，據說在空裔一族中具有極高的價值。",
  str_item_3661243 = "餃子沙發",
  str_item_3661244 = "年畫·辰",
  str_item_3661238 = "鞭炮掛飾",
  str_item_3661239 = "迎新掛飾",
  str_item_3661240 = "古典置物櫃",
  str_item_intro_3661243 = "家具，可設置於巨像的房間。\n餃子形狀的懶人沙發，本來內建揚聲器，會播放台詞：\n「餃子、餃子、餃餃子！」\n「大家一起包餃子！」\n現在裝置已經被嫌吵的某些光靈拆掉，巨像內終於恢復寧靜。",
  str_item_intro_3661244 = "家具，可設置於巨像的房間。\n印著龍女的年畫，是濟國吉祥年貨的熱門品項。只不過展示龍女真實形象的，只有這一張辰霓送的「藝術照」。",
  str_item_intro_3661238 = "家具，可設置於巨像的房間。\n龍洲的傳統節日馬上要到了，為了能讓巨像上的龍洲友人感受到節日的氛圍，大夥拿出了共同製作的鞭炮掛飾。希望這掛飾能掃清所有不幸的遭遇，讓新的一年好運連連。",
  str_item_intro_3661239 = "家具，可設置於巨像的房間。\n雙榭城商鋪熱賣中的商品，是龍洲大陸逢年過節家家戶戶必掛的擺飾，象徵對未來的美好期望。",
  str_item_intro_3661240 = "家具，可設置於巨像的房間。\n雙榭城工匠的得意之作，精木雕刻，設計上佳。可用於收納用不到的小東西和觀賞其獨特的構造。若將其擺放在巨像中，想必能增加室內的古典氛圍。",
  str_item_intro_3763039 = "獲得後可解鎖對應頭像框。\n桃之夭夭，灼灼其華。桃花正印，好運到來。",
  str_item_intro_3751417 = "獲得後可解鎖對應頭像。\n「空裔收到一頂特殊的帽子作為新年禮物，他很開心地戴上了呢！」",
  str_item_intro_3751566 = "獲得後可解鎖對應頭像。\n「阿霓賜佑，百祿多福！」\n百姓視為「海神」的龍女，真的能賜予俗世幸福嗎？阿霓不知道，但阿霓會努力！",
  str_item_intro_3751567 = "獲得後可解鎖對應頭像。\n「我的嘴就是尺！」\n身為艾斯特拉大使的導航員，在美食品鑑方面也是經驗老到，品味不凡。",
  str_item_intro_3763038 = "獲得後可解鎖對應頭像框。\n「集齊所有福卡就能召喚神龍！」\n雖然不知傳言是不是真的，但這股集卡風潮確實為龍洲新年帶來新鮮歡快的體驗。",
  str_item_intro_3751413 = "獲得後可解鎖對應頭像。\n「阿霓想要去看浮空島上的巨大機關盔甲、沙漠裡超級吵的歌舞表演、地下室的鬥士切磋比武……」\n新的一年，連菩薩也會有很多願望呢。",
  str_item_intro_3751414 = "獲得後可解鎖對應頭像。\n會吃人的長角猛獸，影鎮也有自己的年獸！驚嚇電影《禁入廟會》，影鎮好夢塢出品，春朔檔期震撼上映！\n「所以……我到底演了些什麼……？」",
  str_item_intro_3751415 = "獲得後可解鎖對應頭像。\n「拿去，我隨手做的……我也會做冰棒以外的東西啦！」\n札莉雅失敗無數次後唯一成功的成品，為了表達心意而特意調高了甜度。",
  str_item_intro_3751416 = "獲得後可解鎖對應頭像。\n今天的團圓，希望能讓你感受到「家」的力量。無論身在何處，我們都能看到同一片天空。",
  str_item_intro_3751568 = "獲得後可解鎖對應頭像。\n「雖然有很多人說喜歡我，但我覺得導航員對我還是最特別。我們真的心有靈犀！」",
  str_item_intro_3751569 = "獲得後可解鎖對應頭像。\n「要、要比心？！……好嘛，你就心懷感激地收下我的心意吧……可別得意忘形喔！」",
  str_item_3763039 = "桃花運",
  str_item_3751417 = "龍帽子與空裔",
  str_item_3751566 = "龍年、龍洲、龍女",
  str_item_3751567 = "美食大使",
  str_item_3763038 = "龍游新春",
  str_item_3751413 = "新年新願",
  str_item_3751414 = "賀歲群演",
  str_item_3751415 = "甜甜的",
  str_item_3751416 = "團圓大家族",
  str_item_3751568 = "弗勞爾的心意",
  str_item_3751569 = "札莉雅的心意",
  str_item_3763041 = "千日之冠",
  str_item_3751420 = "冠月騎士之日",
  str_item_3751419 = "跨越千個晝夜",
  str_item_3751570 = "燃燒的淨界",
  str_item_3763040 = "最後的火光",
  str_item_3751421 = "千日之心",
  str_item_3751422 = "戀心射落之日",
  str_item_intro_3751421 = "獲得後可解鎖對應頭像。\n「導航員，看這裡！」\n航程千日，愛常相隨，以後也請帶著眾人的祝福繼續前行吧！",
  str_item_intro_3751422 = "獲得後可解鎖對應頭像。\n「行動起來吧，也許今天就是決定命運的時刻呢！」",
  str_item_intro_3763041 = "獲得後可解鎖對應頭像框。\n「予堅定者以榮耀！」\n千日堅持，千日相伴，感謝你的指引與守護，期待未來繼續攜手同行。",
  str_item_intro_3751420 = "獲得後可解鎖對應頭像。\n「要來參加嗎？冠月節的特殊審判。」",
  str_item_intro_3751419 = "獲得後可解鎖對應頭像。\n「感謝在這片天空下與我們相伴千日時光的你。導航員，以後也請多指教！」",
  str_item_intro_3751570 = "獲得後可解鎖對應頭像。\n「你、你願意和我一起陷入淨界？那……拉起我的手，一起燃燒希望吧！」",
  str_item_intro_3763040 = "獲得後可解鎖對應頭像框。\n「等魔藥的時效結束，這身衣服也會化作火焰……你會循著最後一縷火光來追尋我嗎？」",
  str_item_3751042 = "同行寄語",
  str_item_3751043 = "鍛煉的成果",
  str_item_3751044 = "真理同在",
  str_item_3751045 = "旅途隨護",
  str_item_3751046 = "茶會常客",
  str_item_3751047 = "我的故事",
  str_item_3751048 = "戰友兄弟",
  str_item_3751573 = "躲狐狐",
  str_item_3763042 = "頂呱呱",
  str_item_intro_3751042 = "獲得後可解鎖對應頭像。\n「我知道的，導航員一路走來很不容易，繼續加油吧。」",
  str_item_intro_3751043 = "獲得後可解鎖對應頭像。\n「堅持這麼久真了不起，以後也要一起鍛煉啊！」",
  str_item_intro_3751044 = "獲得後可解鎖對應頭像。\n「您須謹記，無論時光變遷，真理永遠同在。」",
  str_item_intro_3751045 = "獲得後可解鎖對應頭像。\n「今後的旅途，我也會護您周全。」",
  str_item_intro_3751046 = "獲得後可解鎖對應頭像。\n「本小姐已經招待你多少次下午茶了？」",
  str_item_intro_3751047 = "獲得後可解鎖對應頭像。\n「我的故事已經講給你聽了，你的呢？」",
  str_item_intro_3751048 = "獲得後可解鎖對應頭像。\n「經過了這麼久的相處，我們早就是親密的兄弟了！」",
  str_item_intro_3751573 = "獲得後可解鎖對應頭像。\n「藏好了嗎？還沒有唷。」",
  str_item_intro_3763042 = "獲得後可解鎖對應頭像框。\n「看起來很眼熟的形象。」",
  str_item_intro_3751423 = "獲得後可解鎖對應頭像。\n「呱↗呱↘呱↗呱—」",
  str_item_intro_3751424 = "獲得後可解鎖對應頭像。\n「該怎麼做……答案一直就在我心裡？」",
  str_item_3751423 = "白蛙王子",
  str_item_3751424 = "燈塔下的答案",
  str_item_3440014 = "嗚哇一口奇趣袋",
  str_item_intro_3440014 = "「我」只是隻可憐的青蛙，把一生的積蓄都給你了。",
  str_item_intro_3440015 = "超值好運福袋的獎勵通常是巨大的騙局。",
  str_item_intro_3440016 = "好運呈階梯式上升，就像我的人生。",
  str_item_intro_3440017 = "再抽一次吧，感覺快要保底了。",
  str_item_intro_3440018 = "抽完這個奇趣袋，我就關閉頁面，退出遊戲。",
  str_item_3751574 = "我推的歌爾蒂",
  str_item_intro_3751574 = "獲得後可解鎖對應頭像。\n「她是完美又閃亮的偶像，奪走全場眾人的目光。」",
  str_item_3751425 = "偶像的倦意",
  str_item_intro_3751425 = "獲得後可解鎖對應頭像。\n「呵啊～穿上睡衣就想睡起來了。」",
  str_item_3763043 = "我推的棉花糖",
  str_item_intro_3763043 = "獲得後可解鎖對應頭像框。\n「靈動的身影可愛滿點，蓬鬆絨毛，又讓一人為你淪陷。」",
  str_item_3751572 = "爸爸去哪",
  str_item_intro_3751572 = "獲得後可解鎖對應頭像。\n「父親，請告知本機您的去向。」",
  str_item_3751571 = "微笑祝福",
  str_item_intro_3751571 = "獲得後可解鎖對應頭像。\n「本機將該部件贈予父親，希望父親的表情能與螢幕上的顯示一致。」",
  str_item_3751429 = "你好狗蛋",
  str_item_intro_3751429 = "獲得後可解鎖對應頭像。\n「你好呀狗蛋！溫暖巨像收留每一位心碎的打工族。」",
  str_item_3751430 = "勳章與榮譽",
  str_item_3751577 = "鷹眼小隊，集合！",
  str_item_3751578 = "狂歡撒花",
  str_item_3751579 = "伴君千春",
  str_item_3763046 = "予君彩縷",
  str_item_3763047 = "鯉魚旗",
  str_item_intro_3751430 = "獲得後可解鎖對應頭像。\n「很好，今天也沒有讓榮譽蒙羞。」",
  str_item_intro_3751577 = "獲得後可解鎖對應頭像。\n「目光銳如鷹眼，攻擊凜如利爪，行動迅如振翅。」",
  str_item_intro_3751578 = "獲得後可解鎖對應頭像。\n「狂歡快樂！來，一起說！」",
  str_item_intro_3751579 = "獲得後可解鎖對應頭像。\n「願從今往後，天地萬物，上下四方，所遇所行，皆能如你所願，直至百歲千春。」",
  str_item_intro_3763046 = "獲得後可解鎖對應頭像框。\n「願你春風得意，願你所向披靡，願你有志竟成，願你百折不撓；願你能和阿霓一起，體驗更多有趣的瞬間。」",
  str_item_intro_3763047 = "獲得後可解鎖對應頭像框。\n流行於雲島的圖騰旗幟，是成長與勇氣的象徵。",
  str_item_3751581 = "感動的滋味",
  str_item_3751582 = "美味蛋糕",
  str_item_3751580 = "「祕密獠牙」的領主",
  str_item_intro_3751581 = "獲得後可解鎖對應頭像。\n「啵～這就是……被愛著的滋味啵？」",
  str_item_intro_3751582 = "獲得後可解鎖對應頭像。\n「嚐一口……嗯嗯，再嚐一口！」",
  str_item_intro_3751580 = "獲得後可解鎖對應頭像。\n「影鎮遊戲廳『祕密獠牙』的領主，歡迎來到遊戲的世界。」",
  str_item_3751436 = "堅毅的眼神",
  str_item_3751583 = "反叛之焰",
  str_item_3751584 = "來者上賓",
  str_item_3751585 = "為我們的友誼乾杯",
  str_item_3763048 = "向啟光的未來展望",
  str_item_3763049 = "祕陵之鑰",
  str_item_intro_3751436 = "獲得後可解鎖對應頭像。\n「有你們在，真好！」",
  str_item_intro_3751583 = "獲得後可解鎖對應頭像。\n「必須變得更強，比站在最頂點的光靈都強。」",
  str_item_intro_3751584 = "獲得後可解鎖對應頭像。\n「哪怕我今天葬身於此，也要看看你的真面目。」",
  str_item_intro_3751585 = "獲得後可解鎖對應頭像。\n「想與他交際當然可以，但請你們拿出尊重的態度。畢竟，他是我萊因哈特的客人。」",
  str_item_intro_3763048 = "獲得後可解鎖對應頭像框。\n「別擔心，萬事萬物都會變化。有點變化令人唏噓，但至少在我看來——還是令人振奮的變化比較多。」",
  str_item_intro_3763049 = "獲得後可解鎖對應頭像框。\n「藉著幽微的燭光，能否一窺黑盒所守護的祕密？」",
  str_item_3751438 = "洞悉真理",
  str_item_3751586 = "神聖的受召者",
  str_item_3763050 = "璀璨路途",
  str_item_intro_3751438 = "獲得後可解鎖對應頭像。\n「真理的探索者如同追著那遙遠的星光，需要心靈的眼睛才能洞察。」",
  str_item_intro_3751586 = "獲得後可解鎖對應頭像。\n「我懺悔！我贖罪！我——是受到真理祝福之人。」",
  str_item_intro_3763050 = "獲得後可解鎖對應頭像框。\n「願真理祝福你，此後的人生熠熠生輝。」",
  str_item_3751426 = "萊莎的靈光",
  str_item_3751427 = "科洛蒂婭的微笑",
  str_item_3751428 = "派翠夏的倔強",
  str_item_3751575 = "向著新的冒險",
  str_item_3751576 = "燦然夏花",
  str_item_3751587 = "雄心海軍王",
  str_item_3751588 = "水上無人機",
  str_item_3763044 = "閃耀夢想",
  str_item_3763045 = "海風熠耀",
  str_item_3763051 = "圈住夏天",
  str_item_3763052 = "富貴逼人",
  str_item_3763053 = "守誓者",
  str_item_3751444 = "請享受比賽",
  str_item_3751443 = "海上精靈",
  str_item_3751589 = "童話公主",
  str_item_3751594 = "冥河獵神",
  str_item_3751593 = "輝金之蛇",
  str_item_3751592 = "誓約讀者",
  str_item_3751591 = "祭劍座",
  str_item_intro_3751594 = "獲得後可解鎖對應頭像。\n「黑色的羽翼是劃過冥河上空的利刃。」",
  str_item_intro_3751593 = "獲得後可解鎖對應頭像。\n「不論談生意還是找樂子，只要金幣準備到位，我都能滿足您的要求！」",
  str_item_intro_3751592 = "獲得後可解鎖對應頭像。\n「千年的誓約必須銘記，朗基努斯一族的心意，只獻給完成英雄之路的人。」",
  str_item_intro_3751591 = "獲得後可解鎖對應頭像。\n「見敵必殺，用我的劍守護星辰的故事。」",
  str_item_intro_3763052 = "獲得後可解鎖對應頭像框。\n「富貴晃人眼！」",
  str_item_intro_3763053 = "獲得後可解鎖對應頭像框。\n「黑色羽翼守護著千年的誓約。」",
  str_item_intro_3751444 = "獲得後可解鎖對應頭像。\n「看那競賽選手投入其中，努力爭取名次。盡情享受比賽，為選手加油打氣吧！」",
  str_item_intro_3751443 = "獲得後可解鎖對應頭像。\n「摩耶喜歡水，喜歡游泳的樂趣，要不要去參加比賽呢？和大家一起享受快樂～」",
  str_item_intro_3751589 = "獲得後可解鎖對應頭像。\n「摩耶想要做個美夢。希望這個世界沒有悲傷，永遠快樂。」",
  str_item_intro_3751426 = "獲得後可解鎖對應頭像。\n「這是什麼？有點心動……」",
  str_item_intro_3751427 = "獲得後可解鎖對應頭像。\n「歡迎回來，今天的冒險如何？有沒有趣事要跟我分享呢？」",
  str_item_intro_3751428 = "獲得後可解鎖對應頭像。\n「啊，不好意思，讓您看到我失態的樣子了。且讓我重整姿勢，再來一次。」",
  str_item_intro_3751575 = "獲得後可解鎖對應頭像。\n「向著新的冒險，出發！」",
  str_item_intro_3751576 = "獲得後可解鎖對應頭像。\n「有朋友陪伴的夏天，果然最棒了～」",
  str_item_intro_3751587 = "獲得後可解鎖對應頭像。\n「既然這份桀驁能夠征服陸地，那面對大海也沒關係……吧？」",
  str_item_intro_3751588 = "獲得後可解鎖對應頭像。\n「嗶嗶，切換為水上航行模式。」",
  str_item_intro_3763044 = "獲得後可解鎖對應頭像框。\n「沐浴在這道光芒中，連四周的人都會感覺內心變得光明。」",
  str_item_intro_3763045 = "獲得後可解鎖對應頭像框。\n「來到艾斯特拉，是這個夏天最驚喜的意外！」",
  str_item_intro_3763051 = "獲得後可解鎖對應頭像框。\n「讓人一看就想帶著它擁抱大海的時尚泳圈。不要錯過短暫的暑期，馬上動起來，用它圈住夏天吧！」",
  str_item_3661248 = "古代英雄肖像",
  str_item_3661249 = "古代軍官肖像",
  str_item_intro_3661248 = "家具，可設置於巨像的房間。\n最近出土的古代塑像，根據衣著和頭飾來判斷，塑像是一位古時受到嘉勉的平民戰士。考古學家指出，在同時期，通常只有貴族才有製造塑像的權利。由此可見，這位戰士必定是立下了赫赫戰功，人民才主動為其製作此尊塑像。\n「她所愛的世界，由我來守護！」",
  str_item_intro_3661249 = "家具，可設置於巨像的房間。\n最近出土的古代塑像，根據衣著和頭飾來判斷，塑像是一位在軍隊裡位高權重的官員。考古學家指出，在同時期，軍隊官員幾乎都出身貴族，這尊塑像與另一尊平民戰士塑像不同，很可能出自專為貴族服務的雕塑家之手。\n「接下來，就交給我吧。」",
  str_item_3661250 = "雪狐雕塑",
  str_item_3661251 = "松木燭台",
  str_item_3661252 = "知更的書架",
  str_item_3661253 = "典藏音響",
  str_item_3661254 = "休閒矮桌",
  str_item_intro_3661250 = "家具，可設置於巨像的房間。\n深受北境人喜愛的雕塑。據說，雕塑的原型是一名北境護衛，為了紀念在一場戰爭中犧牲的重要同伴而造。",
  str_item_intro_3661251 = "家具，可設置於巨像的房間。\n選用上好松木製成的氛圍燭台，散發的淡雅松香有助眠的效果。",
  str_item_intro_3661252 = "家具，可設置於巨像的房間。\n造型簡約的書架，優質木材散發出淡淡香氣。",
  str_item_intro_3661253 = "家具，可設置於巨像的房間。\n適合莊重場合使用的典雅音響，從中飄出的音符往往屬於儀仗行伍，而非安希雅熟悉的爆裂金屬樂。",
  str_item_intro_3661254 = "家具，可設置於巨像的房間。\n美觀又實惠的休閒桌，足以擱置城市居民一天的安閒，無論在哪裡都會成為暢銷款式。",
  str_item_3661256 = "復古掛鐘",
  str_item_3661257 = "裝飾畫「月夜」",
  str_item_3661258 = "獵兔犬玩偶",
  str_item_3661260 = "紅油燒烤架",
  str_item_intro_3661256 = "家具，可設置於巨像的房間。\n鐘錶的邊框由精緻的金屬材質製成，表面經過特殊處理，呈現出歲月沉澱的古銅色澤。",
  str_item_intro_3661257 = "家具，可設置於巨像的房間。\n美麗的裝飾畫。月亮以深邃的夜空為背景，佔據在畫面中央，散發出柔和的光輝。",
  str_item_intro_3661258 = "家具，可設置於巨像的房間。\n獵兔犬造型的玩偶。玩偶的眼神彷彿在說：「寶看見，寶想要，寶得到。」",
  str_item_intro_3661260 = "家具，可設置於巨像的房間。\n紅油扳手營地中最常見的燒烤架。雖然是用廢銅爛鐵拼接而成，但烤出的食物卻額外焦香——至少紅油扳手的人們是這樣認為的。",
  str_item_3661265 = "優雅旅人肖像",
  str_item_3661266 = "怪誕胡蘿蔔像",
  str_item_intro_3661265 = "家具，可設置於巨像的房間。\n傳說有位旅人在一片甜蜜的土地上，建造了一座名為「福德」的小鎮。那裡有吃不完的蜂蜜，喝不完的牛奶……\n「這座小鎮到底在哪裡？難道是……在另一個世界？」",
  str_item_intro_3661266 = "家具，可設置於巨像的房間。\n在討厭胡蘿蔔的孩子心中，胡蘿蔔張牙舞爪、青眼獠牙……似乎比暗鬼還可怕？\n「蔔……我只是一隻可憐的胡蘿蔔蔔……」",
  str_item_3661267 = "復古街機",
  str_item_intro_3661267 = "家具，可設置於巨像的房間。\n「要搬進巨像上住的話，這台一定要帶……不然我可活不下去。」\n既然是同伴的請求，導航員當然要親自幫忙搬，即使代價是肌肉拉傷。",
  str_item_3661268 = "像素墨鏡掛飾",
  str_item_intro_3661268 = "家具，可設置於巨像的房間。\n「鶯歌，妳輸了，戰利品拿來吧。」\n從鶯歌手上贏來的戰利品，似乎是某款遊戲的周邊。",
  str_item_3661271 = "玩偶收納盒",
  str_item_intro_3661271 = "家具，可設置於巨像的房間。\n對於那些丟三落四的玩偶收藏家而言，這是世界上最偉大的發明。",
  str_item_3661272 = "貓爪掛鐘",
  str_item_intro_3661272 = "家具，可設置於巨像的房間。\n萬夢至尊貓咪肉墊掛鐘！摸起來是軟軟糯糯的喲！至於需要掛在墻上這種缺點當然是可以忽略的啦……",
  str_item_3661273 = "新生演講台",
  str_item_intro_3661273 = "家具，可設置於巨像的房間。\n啟光流傳著這樣一句話：入學時在演講台上大聲說出夢想的新生，後來都成為了令人敬仰的英雄。",
  str_item_3661274 = "鑄鐵壁爐",
  str_item_intro_3661274 = "家具，可設置於巨像的房間。\n啟光生產的鑄鐵壁爐，除了保暖性良好以外，其低調沉穩的外觀和溫暖的火苗，總會讓房間顯得格外溫馨。",
  str_item_3661275 = "獲召之席",
  str_item_intro_3661275 = "家具，可設置於巨像的房間。\n來自瓦拉吉鎮的高檔床具。溫馨舒適，具有獨特的古典風情。真理結社的信徒奉其為天啟降臨的臥榻。",
  str_item_3661276 = "照見未來鏡",
  str_item_intro_3661276 = "家具，可設置於巨像的房間。\n「探索真理之人，會從古老的木鏡中窺見未來。」究竟是誰想出來的宣傳語……",
  str_item_3661277 = "英勇士兵肖像",
  str_item_intro_3661277 = "家具，可設置於巨像的房間。\n在鋪天蓋地的暗鬼進攻下，連衝鋒的軍號也被咆哮聲淹沒。混戰中，一位英勇士兵扛著軍旗前進，千千萬萬個士兵便緊隨其後。\n「獻給英勇無畏、敢於犧牲之人。」",
  str_item_3661278 = "滅日暮鐘之像",
  str_item_intro_3661278 = "家具，可設置於巨像的房間。\n一尊醜惡的雕像，猙獰的模樣令人不禁認為它生來便與世界為敵。\n據說當它邁步前進，身上的金屬盔甲就會互相碰撞形成悶響，那是憎惡生命的暮鐘之聲。",
  str_item_3661262 = "遺跡守衛模型",
  str_item_intro_3661262 = "家具，可設置於巨像的房間。\n對遺跡守衛念念不忘的弗勞爾製作的模型。\n「這應該也算是一種機甲吧！」",
  str_item_3661263 = "鍊金釜",
  str_item_intro_3661263 = "家具，可設置於巨像的房間。\n有了它，「萊莎的鍊金工房」就能在巨像上開張啦！",
  str_item_3661264 = "冒險留影",
  str_item_intro_3661264 = "家具，可設置於巨像的房間。\n等到夏天過去，再來懷念這個夏天吧！",
  str_item_3661279 = "夏風圓舵",
  str_item_intro_3661279 = "家具，可設置於巨像的房間。\n雙手置於其上，彷彿就能感受到海風的輕拂，完美捕捉到夏日海洋的清新氣息，絕對是一款航海愛好者的必備家具。",
  str_item_3661280 = "夏風泳圈",
  str_item_intro_3661280 = "家具，可設置於巨像的房間。\n色調經典，材質耐用。無論置於家中或是在航海中投入實用，都能成為一抹亮麗的風景。",
  str_item_3661281 = "夏風旗幟",
  str_item_intro_3661281 = "家具，可設置於巨像的房間。\n簡潔而不失優雅的裝飾旗幟，適合擺在任何需要增添航海氛圍的空間。",
  str_item_3661282 = "留住海鳥大螺號",
  str_item_intro_3661282 = "家具，可設置於巨像的房間。\n「大螺號，嗶嗶吹，海鷗聽了不會飛～」\n也不知道是誰，居然在巨像上開始傳播這種歌謠。",
  str_item_3661283 = "優遊自如泡泡機",
  str_item_intro_3661283 = "家具，可設置於巨像的房間。\n固定在底座的泡泡槍，按一下就會噴出泡泡。\n「真是悠哉的道具呢，希望它不會讓人陷入夢境～」",
  str_item_3661284 = "白之水仙肖像",
  str_item_intro_3661284 = "家具，可設置於巨像的房間。\n娜席里絲喜愛栽種水仙。她很重視她的花，還會把隨意踐踏的傢伙丟入鏡湖。",
  str_item_3661285 = "純潔百合肖像",
  str_item_intro_3661285 = "家具，可設置於巨像的房間。\n尼珀里絲喜愛栽種百合。她會摘下鮮花贈予他人，只留香氣久久不散。",
  str_item_3661286 = "星辰閃耀時",
  str_item_intro_3661286 = "家具，可設置於巨像的房間。\n蜜特拉的畫作，描繪了阿克琉斯刹那的笑容。\n不屈的流星，請與你的夥伴再次閃耀吧。",
  str_item_3661287 = "雙劍",
  str_item_intro_3661287 = "家具，可設置於巨像的房間。\n寂靜獵兵正副隊長武器的仿製品。\n見證吧！此乃開闢的極意，以及守護的決心！這正是寂靜獵兵的真諦。",
  str_item_3661288 = "猛禽攀架",
  str_item_intro_3661288 = "家具，可設置於巨像的房間。\n蜜特拉替猛禽準備的落腳點。\n別看牠們在這上面乖乖的，爪子可厲害了呢。",
  str_item_3661289 = "群星",
  str_item_intro_3661289 = "家具，可設置於巨像的房間。\n經巧手復原的舊作。\n如果劃過天空的星辰，有朝一日能在歲月的溫柔中抵達歸宿……\n願你們得到遲來的幸福。",
  str_item_3661290 = "幽月之聲",
  str_item_intro_3661290 = "家具，可設置於巨像的房間。\n名為路德維希的空裔所譜的曲子。\n如同月光般高潔、優雅，又透露著難以平息的悲傷。願你們得到遲來的幸福。",
  str_item_9998002 = "毒醫面具",
  str_item_9998003 = "叛亂迴聲",
  str_item_9998004 = "神裁之手",
  str_item_9998005 = "死神凝視",
  str_item_9998006 = "瓦解面具",
  str_item_9998007 = "瘟疫遺作",
  str_item_9998008 = "破壁者",
  str_item_9998009 = "狂戰手甲",
  str_item_9998010 = "狂戰之魂",
  str_item_9998011 = "領隊雕像",
  str_item_9998012 = "雙聲蘭",
  str_item_9998013 = "鏈介護符",
  str_item_9998014 = "命運骰盒",
  str_item_9998015 = "全息透鏡",
  str_item_9998016 = "共鳴勳章",
  str_item_9998017 = "戰鬥女神像",
  str_item_9998018 = "替身稻草人",
  str_item_9998019 = "光療蠟燭",
  str_item_9998020 = "急救繃帶",
