  str_item_9998076 = "消光漆",
  str_item_intro_9998002 = "每回合開始時，全場所有敵人隨機附加1層中毒/流血/灼燒狀態，效果重複4次；光靈造成的傷害降低15%",
  str_item_intro_9998003 = "敵人處在異常狀態中或攜帶減益效果時，受到所有傷害增加20%",
  str_item_intro_9998004 = "消除格子時，對消除範圍內的怪物隨機附加1層中毒/流血/灼燒狀態，效果重複5次",
  str_item_intro_9998005 = "當攜帶中毒/灼燒/流血的敵人死亡時，為場上剩餘所有敵人附加1層中毒、灼燒和流血狀態",
  str_item_intro_9998006 = "敵人受到的中毒/流血/灼燒傷害提高100%",
  str_item_intro_9998007 = "對敵人成功施加中毒/灼燒/流血狀態時，目標立即損失1%生命值",
  str_item_intro_9998008 = "獲得空裔特別裝具：消耗2回合，立即施放1次等級2的陣營支援技能，每回合只能使用1次",
  str_item_intro_9998009 = "與敵人距離越近，光靈連鎖技能傷害越高，最高提升30%",
  str_item_intro_9998010 = "「爆破」職業的光靈有30%機率多施放1次連鎖技能，本回合每消除1格，觸發機率增加1%",
  str_item_intro_9998011 = "隊長只按自己屬性出戰，但造成的傷害提高100%",
  str_item_intro_9998012 = "隊長施放連鎖技能時，在消除前位置生成一道虛影，同時施放連鎖技能",
  str_item_intro_9998013 = "下次戰鬥勝利後，可額外選擇2次啟迪裝具，生效1次",
  str_item_intro_9998014 = "選擇啟迪裝具時可以重骰，可使用8次",
  str_item_intro_9998015 = "刪除初始空裔特別裝具，然後立即再進行2次啟迪裝具選擇",
  str_item_intro_9998016 = "光靈主動技能同時攻擊至少3名敵人時，施放落雷攻擊全場敵人，造成隊伍平均攻擊力200%的傷害",
  str_item_intro_9998017 = "更換隊長後，新隊長主動技能冷卻回合-1，同一光靈每回合最多觸發1次",
  str_item_intro_9998018 = "隊伍生命值降低到1%時鎖血1回合，然後生命值恢復20%（每場戰鬥最多觸發1次，總共最多觸發2次）",
  str_item_intro_9998019 = "戰鬥勝利後，隊伍已損失生命值恢復35%",
  str_item_intro_9998020 = "戰鬥開始時，在戰場上生成1個繃帶",
  str_item_intro_9998021 = "隊伍生命值在90%以上時，光靈造成的傷害提高15%",
  str_item_intro_9998022 = "每波次開始時，獲得最大生命值40%的護盾，持續2回合",
  str_item_intro_9998023 = "戰鬥開始時，如果當下生命值低於50%，則恢復至50%",
  str_item_intro_9998024 = "「輔助」職業的光靈戰鬥時，連鎖技能、主動技能帶來的恢復效果提升40%",
  str_item_intro_9998025 = "隊伍中光靈每有1種主屬性，光靈造成的傷害提高6%，最多提高24%",
  str_item_intro_9998026 = "光靈造成傷害時可無視屬性剋制帶來的傷害降低效果；受傷時可無視屬性剋制帶來的受傷增加效果",
  str_item_intro_9998027 = "光靈副屬性造成傷害時，傷害倍率等同於主屬性",
  str_item_intro_9998028 = "羈絆光靈可以無視消除的格子屬性施放連鎖技能",
  str_item_intro_9998029 = "每有1組羈絆光靈，每回合開始時隊伍生命值恢復5%",
  str_item_intro_9998030 = "每有1組羈絆光靈，消除格子時有40%機率額外增加1點空裔特別裝具充能，存在多組羈絆獨立觸發",
  str_item_intro_9998031 = "羈絆光靈相互繼承20%的基礎攻擊力",
  str_item_intro_9998032 = "光靈施放主動技能時，其羈絆光靈的主動技能冷卻回合-1，每場戰鬥最多觸發5次",
  str_item_intro_9998033 = "每場戰鬥施放的第1次主動技能，施放後技能冷卻回合立即-2",
  str_item_intro_9998034 = "點選消除後，若本回合光靈未施放連鎖技能，所有光靈主動技能冷卻回合-1",
  str_item_intro_9998035 = "光靈距離敵人越遠，連鎖技能傷害越高，最高提升50%",
  str_item_intro_9998036 = "「狙擊手」職業的光靈連鎖技能目標+2",
  str_item_intro_9998037 = "光靈造成傷害時有3%吸血率，但每回合開始時損失10%生命值",
  str_item_intro_9998038 = "生命值越低，光靈連鎖技能傷害越高，最高提升50%",
  str_item_intro_9998039 = "每回合開始時，場上敵我所有單位均損失7%生命值",
  str_item_intro_9998040 = "當下生命值處於50%時，光靈造成的傷害提高30%；生命值每差1%，該加成衰減5%",
  str_item_intro_9998041 = "每回合開始時，損失7%目前生命值，之後對周圍2圈範圍內敵人造成隊伍平均攻擊力150%的傷害",
  str_item_intro_9998042 = "戰鬥開始時損失70%生命值，對全場敵人造成該損失值300%的傷害",
  str_item_intro_9998043 = "光靈主動技能傷害提高80%，每次施放主動技能會損失8%生命值",
  str_item_intro_9998044 = "無視點選消除的格子數量，每次消除後必定施放光靈最高階段連鎖技能",
  str_item_intro_9998045 = "戰鬥開始時，所有空裔特別裝具獲得1次使用次數",
  str_item_intro_9998046 = "每次使用空裔特別裝具時，立即觸發1次等級1的陣營支援技能，每場戰鬥生效2次",
  str_item_intro_9998047 = "初始空裔特別裝具生效範圍提升至5*5，累積40點充能後獲得1次使用次數",
  str_item_intro_9998048 = "空裔特別裝具使用次數充能效率提高50%",
  str_item_intro_9998049 = "召喚死亡的氣息，秒殺生命值低於9%的敵人",
  str_item_intro_9998050 = "光靈造成的傷害提高20%，經過回合消耗數提升1倍",
  str_item_intro_9998051 = "隊伍中所有光靈的防禦力歸零，但將其基礎防禦力的50%轉換為攻擊力",
  str_item_intro_9998052 = "每擁有1個啟迪裝具，所有光靈的最大生命值提高2%",
  str_item_intro_9998053 = "每擁有1個啟迪裝具，所有光靈的防禦力提高1.5%",
  str_item_intro_9998054 = "每擁有1個啟迪裝具，所有光靈的攻擊力提高1%",
  str_item_intro_9998055 = "每回合開始時，戰場中隨機生成1個增傷機關，將其消除後，本回合內連鎖技能傷害提升35%",
  str_item_intro_9998056 = "每波次開始時，戰場中隨機生成1個充能糖罐，將其消除後，隨機1個空裔特別裝具獲得1次使用次數",
  str_item_intro_9998057 = "場上所有可消除道具生成時數量變為2個",
  str_item_intro_9998058 = "每波次開始時，戰場中隨機生成1個行動能源器，將其消除後，獲得3點總回合數",
  str_item_intro_9998059 = "每回合開始時，震碎腳下格子，光靈造成的傷害提高15%",
  str_item_intro_9998060 = "將所有啟迪裝具生效次數恢復至初始值",
  str_item_intro_9998061 = "獲得空裔特別裝具：將場上所有格子轉為彩色格子，獲得時自帶2次使用次數",
  str_item_intro_9998062 = "對消除範圍內的敵人造成的連鎖技能傷害提高35%",
  str_item_intro_9998063 = "點選消除格子時，對消除範圍內的敵人造成隊伍平均攻擊力150%的傷害",
  str_item_intro_9998064 = "每點選消除1個格子，獲得最大生命值0.5%的護盾，持續1回合",
  str_item_intro_9998065 = "一次性點選消除至少15個格子時，光靈連鎖技能傷害提升30%；但消除格子數若不足7格，則無法施放連鎖技能",
  str_item_intro_9998066 = "隊伍中攻擊力最低的光靈，其基礎攻擊力提高60%",
  str_item_intro_9998067 = "陣營支援技能觸發所需消除的格子數減少，等級1減少5格 / 等級2減少10格",
  str_item_intro_9998068 = "陣營支援技能附加將敵人擊退1格的效果",
  str_item_intro_9998069 = "每回合開始時，隊伍中每有1名光靈的陣營與陣營支援技能相同，所有空裔特別裝具獲得3點充能",
  str_item_intro_9998070 = "陣營支援技能附加吸血效果，隊伍中每有1名該陣營的光靈，獲得5%吸血率",
  str_item_intro_9998071 = "點選消除格子時，每消除1格，本回合陣營支援技能的最終傷害提高5%",
  str_item_intro_9998072 = "隊伍中每有1名光靈的陣營與陣營支援技能相同，陣營支援技能的最終傷害提高25%",
  str_item_intro_9998073 = "隊伍中每有1名光靈的陣營與陣營支援技能相同，所有光靈的基礎防禦力、生命值上限提高3%",
  str_item_intro_9998074 = "光靈主動技能傷害提高100%，連鎖技能只能施放1階",
  str_item_intro_9998075 = "每回合開始時，將場上隨機2名敵人腳下的1個格子轉為彩色格子",
  str_item_intro_9998076 = "敵人死亡時，將腳下1個格子顏色轉為隊長的屬性",
  str_item_4090264 = "魔法藥之夜",
  str_item_intro_4090264 = "「導航員，我不做光靈了。」\n無法忍受虛無的烏列爾，想用魔藥把自己轉化成其他存在。然而喝下魔藥的她並未如願，反而陷入奇妙的酩酊狀態。原本頹喪疏離的她，突然變得積極主動，拉著你一起嘗試各種亂七八糟的事情。接下來一整天，你將如何應對呢？",
  str_item_3400132 = "意識連結，呱",
  str_item_intro_3400132 = "獲得後可解鎖背景圖-意識連結，呱。\n感應萬物的意識是蛙的奇異能力，而蛙也將因此天賦承擔起療癒夥伴的重擔……",
