  str_item_intro_9011001 = "回合開始時，對全場敵人造成4444點固定傷害，並消滅生命值低於6%的敵人。",
  str_item_intro_9011002 = "每回合在身邊生成彩色格子，數量等同於隊伍中光靈的主屬性種類數。開場時額外執行2次。",
  str_item_intro_9011003 = "在戰鬥的第3回合將所有格子轉為彩色，連線結束後清除所有彩色格子。",
  str_item_intro_9011004 = "生命值全滿的光靈，造成的所有傷害提高15%。",
  str_item_intro_9011005 = "完成「噬夢暗影」關卡後，獲得持有夢境金幣數30%的利息。",
  str_item_intro_9011006 = "一次性：獲得2顆爆夢彈。",
  str_item_intro_9011007 = "持有的夢境金幣越多，普通攻擊傷害越高。",
  str_item_intro_9011008 = "連線的第1格可以和之後的屬性不同，且兩種屬性的光靈都會出戰。",
  str_item_intro_9011009 = "將所有未裝配的幻珠重骰為新的幻珠（新幻珠等級不低於重骰前），並且每顆幻珠有30%機率提升星級。",
  str_item_intro_9011010 = "連線經過的格子顏色是隊長屬性時，每連線2格幻珠蓄能+1。",
  str_item_intro_9011011 = "幻珠技能造成傷害時，在隨機區間內重骰2次並取較高值，傷害浮動區間擴大10%。",
  str_item_intro_9011012 = "獲得後，後續獲得的幻珠預設為1星星級。",
  str_item_intro_9011013 = "選擇卜夢卡時，可供選擇的卜夢卡少1張，但是透過卜夢牌獲得的獎勵效果加倍。",
  str_item_intro_9011014 = "進入戰鬥後，全體光靈生命值上限降低20%。行動時，可供選擇的卜夢卡多1張。",
  str_item_intro_9011015 = "連線開始前，每當光靈位移後，在落點造成1次平均攻擊力150%的菱形傷害，且每位移1圈，幻珠蓄能+1。",
  str_item_intro_9011016 = "職業為「變化」及「輔助」的光靈以連鎖技能造成傷害時，對目標隨機附加1層中毒／流血／灼燒狀態。",
  str_item_intro_9011017 = "對中毒／流血／灼燒狀態的敵人造成傷害時，每種效果的傷害提升。",
  str_item_intro_9011018 = "對目標附加中毒／流血／灼燒其中一種狀態後，有機率再隨機附加1層。此效果可重複觸發，每次觸發後機率減半。",
  str_item_intro_9011019 = "敵人死亡時，對全場敵人隨機附加1層中毒／流血／灼燒狀態。",
  str_item_intro_9011020 = "隊長普通攻擊時，額外造成1次全隊攻擊力50%的火屬性傷害。",
  str_item_intro_9011021 = "隊長普通攻擊時，額外造成1次全隊攻擊力50%的雷屬性傷害。",
  str_item_intro_9011022 = "隊長普通攻擊時，額外造成1次全隊攻擊力50%的森屬性傷害。",
  str_item_intro_9011023 = "隊長普通攻擊時，額外造成1次全隊攻擊力50%的水屬性傷害。",
  str_item_intro_9011024 = "每回合開始時，將最靠近的3個火屬性格子轉為彩色格子。",
  str_item_intro_9011025 = "每回合開始時，將最靠近的3個雷屬性格子轉為彩色格子。",
  str_item_intro_9011026 = "每回合開始時，將最靠近的3個森屬性格子轉為彩色格子。",
  str_item_intro_9011027 = "每回合開始時，將最靠近的3個水屬性格子轉為彩色格子。",
  str_item_intro_9011028 = "每回合開始時，將所有敵人腳下至多1個格子轉為彩色格子。",
  str_item_intro_9011029 = "受到傷害時，將周圍2圈內的3個格子轉為彩色格子。",
  str_item_intro_9011030 = "每回合開始，生命值較低的光靈根據已損失生命值的比例回復生命值。",
  str_item_intro_9011031 = "戰鬥勝利後，所有光靈恢復20%生命值。",
  str_item_intro_9011032 = "本回合若獲得過深色格子，獲得1層鬥志。",
  str_item_intro_9011033 = "「輔助」職業光靈施放主動／連鎖技能治療隊伍時，獲得1層鬥志。",
  str_item_intro_9011034 = "光靈以主動技能造成擊退／牽引時，根據目標的數量獲得鬥志，每回合最多觸發3次。",
  str_item_intro_9011035 = "每當怪物被附加中毒／流血／灼燒狀態時，獲得1層鬥志，每回合最多觸發4次。",
  str_item_intro_9011036 = "每當夢境等級提高時，獲得相當於等級4倍的夢境金幣。",
  str_item_intro_9011037 = "每當夢境利息提高時，立即獲得相當於提高值7倍的夢境金幣。",
  str_item_intro_9011038 = "在戰鬥中每擊敗1隻暗鬼，獲得4夢境金幣。",
  str_item_intro_9011039 = "一次性：從擁有的卜夢卡抽取5張，獲得等同於其步數之和的夢境利息。",
  str_item_intro_9011040 = "在祕寶夢域中，可以同時獲得兩項獎勵。",
  str_item_intro_9011041 = "每當經過危險夢域後，獲得30夢境經驗。",
  str_item_intro_9011042 = "代購中貨品價格降低，且重骰夢境裝具、光靈、貨品的花費降低35%。",
  str_item_intro_9011043 = "獲得後，派遣至「待墾夢域」的光靈會立即歸隊，且派遣的夢境金幣和夢境利息收益翻倍。",
  str_item_intro_9011044 = "每次經過營地後，獲得40夢境經驗。",
  str_item_intro_9011045 = "一次性：所有光靈損失70%當下生命值；每有1名光靈損失生命值，獲得25夢境經驗。",
  str_item_intro_9011046 = "一次性：消耗擁有數量一半的夢境金幣，每消耗1夢境金幣，獲得2夢境經驗。",
  str_item_intro_9011047 = "光靈主動技能傷害大幅提高，若造成傷害，自身損失生命值。",
  str_item_9011048 = "轟擊者",
  str_item_9011049 = "踏碎者",
  str_item_9011050 = "弒君者",
  str_item_9011051 = "破壁者",
  str_item_9011052 = "麻痺者",
  str_item_9011053 = "雷擊者",
  str_item_intro_9011048 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；場上敵人數量越少，最終傷害越高。",
  str_item_intro_9011049 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；隊長普通攻擊時，獲得3點<link=\"1006\"><color=#98500f><u>超載值</u></color></link>。",
  str_item_intro_9011050 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；光靈主動技能每命中1名敵人，產生4點<link=\"1006\"><color=#98500f><u>超載值</u></color></link>。",
  str_item_intro_9011051 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；回合開始時隊伍生命值越少，獲得越多<link=\"1006\"><color=#98500f><u>超載值</u></color></link>能量。",
  str_item_intro_9011052 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；每次受傷獲得8點<link=\"1006\"><color=#98500f><u>超載值</u></color></link>。",
  str_item_intro_9011053 = "啟動<link=\"1005\"><color=#98500f><u>演算法升級模組</u></color></link>；「資料轟炸」增為120點<link=\"1006\"><color=#98500f><u>超載值</u></color></link>觸發，對大體型敵人的傷害提升。",
  str_item_intro_9011054 = "不再進入極光時刻，改為每當進極光時刻時+1ms值，並獲得5金（波次跟戰鬥勝利時吞掉的極光時刻也計入效果）。",
  str_item_intro_9011055 = "敵人死亡時，將其腳下至多1個格子轉為深色格子。",
  str_item_intro_9011056 = "回合開始時，將與隊長同屬性的2個最靠近格子轉為深色格子。",
  str_item_intro_9011057 = "每次選擇夢境裝具時，可選數量+1。",
  str_item_intro_9011058 = "每次選擇夢境裝具時，第一次重骰免費。",
  str_item_intro_9011059 = "每擁有1件夢境裝具，「爆破」和「狙擊手」職業的光靈攻擊力提高0.5%。",
  str_item_intro_9011060 = "每擁有1件夢境裝具，「變化」和「輔助」職業的光靈防禦力提高2%。",
  str_item_intro_9011061 = "每擁有1件夢境裝具，所有光靈最大生命值提高1.5%。",
  str_item_intro_9011062 = "每回合開始時生成1個時鐘（最多存在1個），獲得時令技能冷卻最高的光靈技能冷卻-1。",
  str_item_intro_9011063 = "對造成傷害的目標附加<link=\"1010\"><color=#98500f><u>致盲</u></color></link>效果。",
  str_item_intro_9011064 = "每次受到傷害時，全體光靈都會獲得5%的傷害加成，最大30%（戰鬥結束後重設）。",
  str_item_intro_9011065 = "普通攻擊傷害提高30%，受到傷害後該效果消失。",
  str_item_intro_9011066 = "全體光靈防禦力減半，根據防禦力減少的值提升自身攻擊力。",
  str_item_intro_9011067 = "隊長光靈在連線開始位置生成一個虛影，本回合同步施展連鎖技能",
  str_item_intro_9011068 = "隊伍裡每有一種主屬性的光靈，傷害提高3.5%。",
  str_item_intro_9011069 = "副屬性可按主屬性的倍率造成傷害，主副屬性相同時倍率額外提高。",
  str_item_intro_9011070 = "之前的隊長可無視連線屬性出戰。",
  str_item_intro_9011071 = "每場戰鬥的換隊長次數+2；\n切換隊長時，新隊長主動技能剩餘冷卻回合-1，每位光靈每回合只能觸發1次。",
  str_item_intro_9011072 = "每次連線或位移後，起點格子必定與隊長屬性相同。",
  str_item_intro_9011073 = "我方造成的所有傷害均提高15%，但是每次連線的起點將變成8回合無法行走的損壞格子。",
  str_item_intro_9011074 = "光靈主動技能造成敵人擊退／牽引時，每移動一格造成3000固定傷害。",
  str_item_intro_9011075 = "所有光靈的突破等級+1（滿突破光靈不生效）。",
  str_item_intro_9011076 = "一次性：任選1名光靈加入隊伍，該光靈的突破等級為最大值。",
  str_item_intro_9011077 = "「爆破」職業的光靈，連鎖技能會對命中的目標附加1層<link=\"1003\"><color=#98500f><u>熔化</u></color></link>效果。",
  str_item_intro_9011078 = "「爆破」職業的光靈，主動技能有40%機率對目標附加<link=\"1011\"><color=#98500f><u>麻痺</u></color></link>效果。",
  str_item_intro_9011079 = "「爆破」職業光靈的最高階連鎖技能範圍擴大到2圈。",
  str_item_intro_9011080 = "「爆破」職業的光靈普通攻擊附加無視防禦的傷害，對目標造成光靈已損失生命值10%的傷害。",
  str_item_intro_9011081 = "「爆破」職業的光靈普通攻擊有30%機率造成1.5倍傷害。",
  str_item_intro_9011082 = "每上陣1名「爆破」職業的光靈，所有「爆破」光靈造成的連鎖技能傷害提高4%。",
  str_item_intro_9011083 = "「狙擊手」職業的光靈，普通攻擊對目標附加自身攻擊力20%的<link=\"1004\"><color=#98500f><u>聖決值</u></color></link>。",
  str_item_intro_9011084 = "「狙擊手」職業的光靈連鎖技能對多格怪傷害提高。",
  str_item_intro_9011085 = "「狙擊手」職業的光靈單體連鎖技能範圍擴大2圈，且目標數+1。",
  str_item_intro_9011086 = "「狙擊手」職業的光靈連鎖技能傷害隨自身損失生命值提高，最高提升50%。",
  str_item_intro_9011087 = "「狙擊手」職業的光靈，主動技能有30%機率對目標附加<link=\"1012\"><color=#98500f><u>恐懼</u></color></link>效果。",
  str_item_intro_9011088 = "每指派1名「狙擊手」職業的光靈上陣，所有「狙擊手」光靈造成的普通攻擊傷害提高5%。",
  str_item_9810702 = "演算法升級 夢境裝具套裝2",
  str_item_9810704 = "演算法升級 夢境裝具套裝4",
  str_item_9810706 = "演算法升級 夢境裝具套裝6",
  str_item_intro_9810702 = "「資料轟炸」對全場敵人造成隊伍平均攻擊力300%的單體傷害。",
  str_item_intro_9810704 = "「資料轟炸」對全場敵人造成隊伍平均攻擊力400%的單體傷害。",
  str_item_intro_9810706 = "「資料轟炸」對全場敵人造成隊伍平均攻擊力500%的單體傷害；目標生命值百分比越高此傷害越高，最高可翻倍。",
