  str_item_8800421 = "「銅掛飾」鍊金配方",
  str_item_intro_8800103 = "取自雪松之巔的冷冽露水，清澈到彷彿能淨化心靈。",
  str_item_intro_8800102 = "綻放於寒冷之中的花朵，散發出淡淡幽香。",
  str_item_intro_8800101 = "隨處可見的冰塊，大量聚集時會產生寒氣。",
  str_item_intro_8800203 = "火辣的高級油脂，能從中感受到紅油的激情與活力。",
  str_item_intro_8800202 = "岩石表面流淌著熾熱的油液。",
  str_item_intro_8800201 = "粗糙的橙色沙粒，保留著沙漠的餘溫。",
  str_item_intro_8800303 = "繁茂的樹枝，能感受到不可思議的生命力在其中流淌。",
  str_item_intro_8800302 = "輕飄飄的絨毛，會攜帶希望的種子隨風傳播。",
  str_item_intro_8800301 = "樸素的綠色種子，等待破土而出。",
  str_item_intro_8800403 = "貴重又稀少的晶石，散發著晨曦般璀璨的光芒。",
  str_item_intro_8800402 = "黃色寶石，雷鳴之力在其中閃爍。",
  str_item_intro_8800401 = "不起眼的礦石，比普通的石材更重一點。",
  str_item_intro_8800113 = "滋補精華，為動植物注入活力與健康。",
  str_item_intro_8800213 = "香甜滑嫩，每一口都是幸福的滋味。",
  str_item_intro_8800313 = "兼顧美觀與觸感的彩偶，有機會成為潮流禮品。",
  str_item_intro_8800413 = "折射出迷人光芒的水晶球，適合裝飾室內空間。",
  str_item_intro_8800112 = "見效極快的跌打損傷膏，居家旅行必備良藥。",
  str_item_intro_8800212 = "用於潤滑、減少摩擦，可以用在各種場合。",
  str_item_intro_8800312 = "綠意盎然的生態盆景，放在陽光充足的地方很好養。",
  str_item_intro_8800412 = "銳利無比，切割無憂，工匠之選。",
  str_item_intro_8800111 = "可用來替其他東西降溫，也可以直接飲用。",
  str_item_intro_8800211 = "強力炸藥，要謹慎使用喔。",
  str_item_intro_8800311 = "堅韌質樸的麻布，用途廣泛。",
  str_item_intro_8800411 = "簡約的掛飾，低調的美感。",
  str_item_intro_8800123 = "記載著「營養補劑」鍊製要求的配方。",
  str_item_intro_8800223 = "記載著「美味蛋糕」鍊製要求的配方。",
  str_item_intro_8800323 = "記載著「華麗彩偶」鍊製要求的配方。",
  str_item_intro_8800423 = "記載著「水晶擺飾」鍊製要求的配方。",
  str_item_intro_8800122 = "記載著「外用藥膏」鍊製要求的配方。",
  str_item_intro_8800222 = "記載著「潤滑靈液」鍊製要求的配方。",
  str_item_intro_8800322 = "記載著「儲水盆景」鍊製要求的配方。",
  str_item_intro_8800422 = "記載著「鋒利刀具」鍊製要求的配方。",
  str_item_intro_8800121 = "記載著「冷卻水」鍊製要求的配方。",
  str_item_intro_8800221 = "記載著「炸藥塊」鍊製要求的配方。",
  str_item_intro_8800321 = "記載著「麻布條」鍊製要求的配方。",
  str_item_intro_8800421 = "記載著「銅掛飾」鍊製要求的配方。",
  str_item_8800005 = "遺跡殘片",
  str_item_intro_8800005 = "本來是遺跡一部分的石片，能看出千百年歲月留下的滄桑痕跡。",
  str_item_8800006 = "採集攜行者",
